library/std/archive/ar.sn:
// Generic System V/BSD Unix ar container header decoding. Archive symbol
// selection, thin member resolution and object/link policy stay with consumers.
عام نوع حقيقة_عضو_حاوية_أرشيف = {
    موضع_الرأس: غير_موقع,
    موضع_المحتوى: غير_موقع,
    الحجم: غير_موقع,
    موضع_الرأس_التالي: غير_موقع
};

عام عرف ضمن_حدود_حاوية_أرشيف(
    البايتات: &متجه غ8,
    الموضع: غير_موقع,
    الحجم: غير_موقع
): منطقي {
    دع حجم_الأرشيف: غير_موقع = الطول(*البايتات) مثل غير_موقع;
    لو (الموضع > حجم_الأرشيف) {
        أرجع خطأ;
    };
    أرجع الحجم <= (حجم_الأرشيف - الموضع);
}

عام عرف اقرأ_بايت_حاوية_أرشيف(
    البايتات: &متجه غ8,
    الموضع: غير_موقع
): غ8 {
    أرجع (*البايتات)[الموضع];
}

عام عرف تحقق_توقيع_حاوية_أرشيف(البايتات: &متجه غ8): منطقي {
    لو (!ضمن_حدود_حاوية_أرشيف(البايتات, 0, 8)) {
        أرجع خطأ;
    };
    أرجع اقرأ_بايت_حاوية_أرشيف(البايتات, 0) == 0x21
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 1) == 0x3C
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 2) == 0x61
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 3) == 0x72
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 4) == 0x63
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 5) == 0x68
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 6) == 0x3E
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 7) == 0x0A;
}

عام عرف تحقق_توقيع_حاوية_أرشيف_رفيع(البايتات: &متجه غ8): منطقي {
    لو (!ضمن_حدود_حاوية_أرشيف(البايتات, 0, 8)) {
        أرجع خطأ;
    };
    أرجع اقرأ_بايت_حاوية_أرشيف(البايتات, 0) == 0x21
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 1) == 0x3C
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 2) == 0x74
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 3) == 0x68
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 4) == 0x69
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 5) == 0x6E
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 6) == 0x3E
        && اقرأ_بايت_حاوية_أرشيف(البايتات, 7) == 0x0A;
}

عام عرف تحقق_أي_توقيع_حاوية_أرشيف(البايتات: &متجه غ8): منطقي {
    أرجع تحقق_توقيع_حاوية_أرشيف(البايتات)
        || تحقق_توقيع_حاوية_أرشيف_رفيع(البايتات);
}

عام عرف اقرأ_عدد_عشري_من_حقل_أرشيف(
    البايتات: &متجه غ8,
    الموضع: غير_موقع,
    الحجم: غير_موقع
): اختيار غير_موقع {
    لو (!ضمن_حدود_حاوية_أرشيف(البايتات, الموضع, الحجم)) {
        أرجع اختيار.لا_شيء();
    };
    دع القيمة: متغير غير_موقع = 0;
    دع وجد_رقما: متغير منطقي = خطأ;
    دع وصل_إلى_فراغ: متغير منطقي = خطأ;
    دع فهرس_البايت: متغير غير_موقع = 0;
    بينما (فهرس_البايت < الحجم) {
        دع البايت: غ8 = اقرأ_بايت_حاوية_أرشيف(البايتات, الموضع + فهرس_البايت);
        لو (البايت == 0x20) {
            وصل_إلى_فراغ := صواب;
        } وإلا {
            لو (وصل_إلى_فراغ || البايت < 0x30 || البايت > 0x39) {
                أرجع اختيار.لا_شيء();
            };
            وجد_رقما := صواب;
            القيمة := القيمة * 10 + ((البايت - 0x30) مثل غير_موقع);
        };
        فهرس_البايت := فهرس_البايت + 1;
    }
    لو (!وجد_رقما) {
        أرجع اختيار.لا_شيء();
    };
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_رأس_عضو_حاوية_أرشيف(
    البايتات: &متجه غ8,
    موضع_الرأس: غير_موقع
): اختيار حقيقة_عضو_حاوية_أرشيف {
    لو (!ضمن_حدود_حاوية_أرشيف(البايتات, موضع_الرأس, 60)) {
        أرجع اختيار.لا_شيء();
    };
    لو (اقرأ_بايت_حاوية_أرشيف(البايتات, موضع_الرأس + 58) != 0x60
        || اقرأ_بايت_حاوية_أرشيف(البايتات, موضع_الرأس + 59) != 0x0A) {
        أرجع اختيار.لا_شيء();
    };
    دع حجم_المحتوى: غير_موقع;
    طابق اقرأ_عدد_عشري_من_حقل_أرشيف(
        البايتات,
        موضع_الرأس + 48,
        10
    ) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الحجم) -> { حجم_المحتوى := الحجم; };
    دع موضع_المحتوى: غير_موقع = موضع_الرأس + 60;
    دع الحقيقة: حقيقة_عضو_حاوية_أرشيف = {
        موضع_الرأس: موضع_الرأس,
        موضع_المحتوى: موضع_المحتوى,
        الحجم: حجم_المحتوى,
        موضع_الرأس_التالي: موضع_المحتوى
    };
    أرجع اختيار.بعض(الحقيقة);
}

عام عرف اقرأ_حقيقة_عضو_حاوية_أرشيف(
    البايتات: &متجه غ8,
    موضع_الرأس: غير_موقع
): اختيار حقيقة_عضو_حاوية_أرشيف {
    لو (!ضمن_حدود_حاوية_أرشيف(البايتات, موضع_الرأس, 60)) {
        أرجع اختيار.لا_شيء();
    };
    لو (اقرأ_بايت_حاوية_أرشيف(البايتات, موضع_الرأس + 58) != 0x60
        || اقرأ_بايت_حاوية_أرشيف(البايتات, موضع_الرأس + 59) != 0x0A) {
        أرجع اختيار.لا_شيء();
    };
    دع حجم_المحتوى: غير_موقع;
    طابق اقرأ_عدد_عشري_من_حقل_أرشيف(
        البايتات,
        موضع_الرأس + 48,
        10
    ) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الحجم) -> { حجم_المحتوى := الحجم; };
    دع موضع_المحتوى: غير_موقع = موضع_الرأس + 60;
    لو (!ضمن_حدود_حاوية_أرشيف(
        البايتات,
        موضع_المحتوى,
        حجم_المحتوى
    )) {
        أرجع اختيار.لا_شيء();
    };
    دع الموضع_بعد_المحتوى: غير_موقع = موضع_المحتوى + حجم_المحتوى;
    دع الحقيقة: حقيقة_عضو_حاوية_أرشيف = {
        موضع_الرأس: موضع_الرأس,
        موضع_المحتوى: موضع_المحتوى,
        الحجم: حجم_المحتوى,
        موضع_الرأس_التالي:
            الموضع_بعد_المحتوى + (الموضع_بعد_المحتوى % 2)
    };
    أرجع اختيار.بعض(الحقيقة);
}

// English spellings point to the same generic ar declarations.
عام مرادف ar_member_header = حقيقة_عضو_حاوية_أرشيف;
عام مرادف ar_magic_valid = تحقق_توقيع_حاوية_أرشيف;
عام مرادف ar_thin_magic_valid = تحقق_توقيع_حاوية_أرشيف_رفيع;
عام مرادف ar_read_member_header = اقرأ_حقيقة_عضو_حاوية_أرشيف;
عام مرادف ar_read_thin_header = اقرأ_رأس_عضو_حاوية_أرشيف;

library/std/archive/tar.sn:
استورد bytes.range;
استورد math.integer;
استورد text.from_bytes;

عرف بايت_تار_عند(المصدر: &متجه غ8, الموضع: غير_موقع): غ8 { أرجع (*المصدر)[الموضع]; }
عرف بايت_نص_تار_عند(النص: &نص, الموضع: غير_موقع): غ8 { أرجع (*النص)[الموضع]; }
عرف اكتب_بايت_تار(الوجهة: &متغير متجه غ8, الموضع: غير_موقع, القيمة: غ8): فراغ { (*الوجهة)[الموضع] := القيمة; }

// POSIX ustar archive reader/writer. The writer emits 512-byte ustar records
// and the required two zero end records. The reader validates header checksums
// and bounds before materializing entry data. Filesystem extraction is
// intentionally outside this module.

عام نوع نوع_مدخل_تار =
    | ملف_عادي
    | دليل
    | رابط_رمزي
    | رابط_صلب
    | جهاز_محرف
    | جهاز_كتلة
    | فيفو
    | آخر بنوع غ8
;

عام نوع مدخل_تار = {
    المسار: نص,
    النوع: نوع_مدخل_تار,
    البيانات: متجه غ8,
    الرابط: نص,
    النمط: غير_موقع,
    معرف_المستخدم: غير_موقع,
    معرف_المجموعة: غير_موقع,
    وقت_التعديل: غير_موقع
};

عام نوع خطأ_تار =
    | نهاية_غير_متوقعة
    | ترويسة_غير_صالحة
    | مجموع_تحقق_غير_صالح
    | رقم_ثماني_غير_صالح
    | رقم_أكبر_من_الحقل
    | مسار_أطول_من_يوستار
    | رابط_أطول_من_يوستار
    | بيانات_مدخل_ناقصة
;

نوع تقسيم_مسار_تار = {
    بداية_الاسم: غير_موقع,
    طول_الاسم: غير_موقع,
    طول_البادئة: غير_موقع
};

عرف ابن_أصفار_تار(العدد: غير_موقع): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        ألحق(الناتج, 0);
        ف := ف + 1;
    }
    أرجع الناتج;
}

عرف كتلة_صفرية_تار(المصدر: &متجه غ8, البداية: غير_موقع): منطقي {
    لو (!متاح_في_البايتات(المصدر, البداية, 512)) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 512) {
        لو (بايت_تار_عند(المصدر, البداية + ف) != 0) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف انسخ_حقل_نص_تار(
    الترويسة: &متغير متجه غ8,
    البداية: غير_موقع,
    العرض: غير_موقع,
    النص: &نص,
    بداية_النص: غير_موقع,
    طول_النص: غير_موقع
): منطقي {
    لو (طول_النص > العرض) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < طول_النص) {
        اكتب_بايت_تار(الترويسة, البداية + ف, بايت_نص_تار_عند(النص, بداية_النص + ف));
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف اكتب_ثمانيا_تار(
    الترويسة: &متغير متجه غ8,
    البداية: غير_موقع,
    العرض: غير_موقع,
    القيمة: غير_موقع
): منطقي {
    لو (العرض < 2) { أرجع خطأ; };
    دع الحالي: متغير غير_موقع = القيمة;
    دع الموضع: متغير غير_موقع = البداية + العرض - 1;
    اكتب_بايت_تار(الترويسة, الموضع, 0);
    دع ف: متغير غير_موقع = الموضع;
    بينما (ف > البداية) {
        ف := ف - 1;
        اكتب_بايت_تار(الترويسة, ف, (0x30 + (الحالي & 7)) مثل غ8);
        الحالي := الحالي >> 3;
    }
    أرجع الحالي == 0;
}

عرف اقرأ_ثمانيا_تار(
    المصدر: &متجه غ8,
    البداية: غير_موقع,
    العرض: غير_موقع
): نتيجة غير_موقع, خطأ_تار {
    لو (!متاح_في_البايتات(المصدر, البداية, العرض)) {
        أرجع نتيجة.خطأ(خطأ_تار.نهاية_غير_متوقعة());
    };
    لو ((العرض > 0) && ((بايت_تار_عند(المصدر, البداية) & 0x80) != 0)) {
        أرجع نتيجة.خطأ(خطأ_تار.رقم_ثماني_غير_صالح());
    };
    دع القيمة: متغير غير_موقع = 0;
    دع رأى_رقما: متغير منطقي = خطأ;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العرض) {
        دع ب: غ8 = بايت_تار_عند(المصدر, البداية + ف);
        لو ((ب == 0) || (ب == 0x20)) {
            // Leading and trailing NUL/space are allowed by common ustar writers.
        } وإلا لو ((ب >= 0x30) && (ب <= 0x37)) {
            رأى_رقما := صواب;
            دع الرقم: غير_موقع = (ب - 0x30) مثل غير_موقع;
            دع المضاعف: متغير غير_موقع = 0;
            طابق ضرب_غير_موقع_متحقق(القيمة, 8) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_تار.رقم_أكبر_من_الحقل()); }
            | اختيار.بعض(ق) -> { المضاعف := ق; };
            طابق جمع_غير_موقع_متحقق(المضاعف, الرقم) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_تار.رقم_أكبر_من_الحقل()); }
            | اختيار.بعض(ق) -> { القيمة := ق; };
        } وإلا {
            أرجع نتيجة.خطأ(خطأ_تار.رقم_ثماني_غير_صالح());
        };
        ف := ف + 1;
    }
    لو (!رأى_رقما) { أرجع نتيجة.نجح(0); };
    أرجع نتيجة.نجح(القيمة);
}

عرف اقرأ_نص_حقل_تار(
    المصدر: &متجه غ8,
    البداية: غير_موقع,
    العرض: غير_موقع
): نتيجة نص, خطأ_تار {
    لو (!متاح_في_البايتات(المصدر, البداية, العرض)) {
        أرجع نتيجة.خطأ(خطأ_تار.نهاية_غير_متوقعة());
    };
    دع نهاية_الحقل: غير_موقع = البداية + العرض;
    دع النهاية: متغير غير_موقع = البداية;
    بينما ((النهاية < نهاية_الحقل) && (بايت_تار_عند(المصدر, النهاية) != 0)) {
        النهاية := النهاية + 1;
    }
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) {
        ألحق(البايتات, بايت_تار_عند(المصدر, ف));
        ف := ف + 1;
    }
    أرجع نتيجة.نجح(من_بايتات(&البايتات));
}

عرف اجمع_ترويسة_تار(المصدر: &متجه غ8, البداية: غير_موقع): غير_موقع {
    دع المجموع: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 512) {
        لو ((ف >= 148) && (ف < 156)) { المجموع := المجموع + 0x20; }
        وإلا { المجموع := المجموع + (بايت_تار_عند(المصدر, البداية + ف) مثل غير_موقع); };
        ف := ف + 1;
    }
    أرجع المجموع;
}

عرف قسم_مسار_يوستار(المسار: &نص): نتيجة تقسيم_مسار_تار, خطأ_تار {
    دع العدد: غير_موقع = الطول(*المسار) مثل غير_موقع;
    لو (العدد <= 100) {
        دع الناتج: تقسيم_مسار_تار = { بداية_الاسم: 0, طول_الاسم: العدد, طول_البادئة: 0 };
        أرجع نتيجة.نجح(الناتج);
    };
    دع ف: متغير غير_موقع = العدد;
    بينما (ف > 0) {
        ف := ف - 1;
        لو ((*المسار)[ف] == 0x2F) {
            دع طول_البادئة: غير_موقع = ف;
            دع طول_الاسم: غير_موقع = العدد - ف - 1;
            لو ((طول_البادئة <= 155) && (طول_الاسم > 0) && (طول_الاسم <= 100)) {
                دع الناتج: تقسيم_مسار_تار = {
                    بداية_الاسم: ف + 1,
                    طول_الاسم: طول_الاسم,
                    طول_البادئة: طول_البادئة
                };
                أرجع نتيجة.نجح(الناتج);
            };
        };
    }
    أرجع نتيجة.خطأ(خطأ_تار.مسار_أطول_من_يوستار());
}

عرف علم_نوع_تار(النوع: &نوع_مدخل_تار): غ8 {
    طابق *النوع مع
    | نوع_مدخل_تار.ملف_عادي -> { أرجع 0x30; }
    | نوع_مدخل_تار.دليل -> { أرجع 0x35; }
    | نوع_مدخل_تار.رابط_رمزي -> { أرجع 0x32; }
    | نوع_مدخل_تار.رابط_صلب -> { أرجع 0x31; }
    | نوع_مدخل_تار.جهاز_محرف -> { أرجع 0x33; }
    | نوع_مدخل_تار.جهاز_كتلة -> { أرجع 0x34; }
    | نوع_مدخل_تار.فيفو -> { أرجع 0x36; }
    | نوع_مدخل_تار.آخر(العلم) -> { أرجع العلم; };
}

عرف نوع_من_علم_تار(العلم: غ8): نوع_مدخل_تار {
    لو ((العلم == 0) || (العلم == 0x30)) { أرجع نوع_مدخل_تار.ملف_عادي(); };
    لو (العلم == 0x35) { أرجع نوع_مدخل_تار.دليل(); };
    لو (العلم == 0x32) { أرجع نوع_مدخل_تار.رابط_رمزي(); };
    لو (العلم == 0x31) { أرجع نوع_مدخل_تار.رابط_صلب(); };
    لو (العلم == 0x33) { أرجع نوع_مدخل_تار.جهاز_محرف(); };
    لو (العلم == 0x34) { أرجع نوع_مدخل_تار.جهاز_كتلة(); };
    لو (العلم == 0x36) { أرجع نوع_مدخل_تار.فيفو(); };
    أرجع نوع_مدخل_تار.آخر(العلم);
}

