library/std/bytes/compare.sn:
// مساواة عامة لمتجهي بايتات دون أي سياسة هوية أو ترميز أعلى.
عام عرف متجها_بايتات_متساويان(
    الأول: &متجه غ8,
    الثاني: &متجه غ8
): منطقي {
    دع عدد_أ: غير_موقع = الطول(*الأول) مثل غير_موقع;
    دع عدد_ب: غير_موقع = الطول(*الثاني) مثل غير_موقع;

    لو (عدد_أ != عدد_ب) {
        أرجع خطأ;
    };

    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < عدد_أ) {
        لو ((*الأول)[الفهرس] != (*الثاني)[الفهرس]) {
            أرجع خطأ;
        };
        الفهرس := الفهرس + 1;
    }
    أرجع صواب;
}

// مقارنة معجمية عامة بالبايتات: -1 إن كان الأول أصغر، 0 إن تساويا، 1 إن كان أكبر.
عام عرف قارن_متجهي_بايتات_معجميا(
    الأول: &متجه غ8,
    الثاني: &متجه غ8
): عدد {
    دع عدد_أ: غير_موقع = الطول(*الأول) مثل غير_موقع;
    دع عدد_ب: غير_موقع = الطول(*الثاني) مثل غير_موقع;
    دع الحد: متغير غير_موقع = عدد_أ;

    لو (عدد_ب < الحد) {
        الحد := عدد_ب;
    };

    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < الحد) {
        لو ((*الأول)[الفهرس] < (*الثاني)[الفهرس]) {
            أرجع -1;
        };
        لو ((*الأول)[الفهرس] > (*الثاني)[الفهرس]) {
            أرجع 1;
        };
        الفهرس := الفهرس + 1;
    }

    لو (عدد_أ < عدد_ب) {
        أرجع -1;
    };
    لو (عدد_أ > عدد_ب) {
        أرجع 1;
    };
    أرجع 0;
}
// الأسماء العامة الإنجليزية ترتبط بالتصريحات العربية نفسها.
عام مرادف byte_vectors_equal = متجها_بايتات_متساويان;
عام مرادف compare_byte_vectors_lexicographically = قارن_متجهي_بايتات_معجميا;

عام عرف تبدأ_البايتات_بـ(القيمة: &متجه غ8, المطلوب: &متجه غ8): منطقي {
    دع عدد_المصدر: غير_موقع = الطول(*القيمة) مثل غير_موقع;
    دع عدد_النمط: غير_موقع = الطول(*المطلوب) مثل غير_موقع;
    لو (عدد_النمط > عدد_المصدر) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < عدد_النمط) {
        لو ((*القيمة)[ف] != (*المطلوب)[ف]) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

عام عرف تنتهي_البايتات_بـ(القيمة: &متجه غ8, المطلوب: &متجه غ8): منطقي {
    دع عدد_المصدر: غير_موقع = الطول(*القيمة) مثل غير_موقع;
    دع عدد_النمط: غير_موقع = الطول(*المطلوب) مثل غير_موقع;
    لو (عدد_النمط > عدد_المصدر) { أرجع خطأ; };
    دع البداية: غير_موقع = عدد_المصدر - عدد_النمط;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < عدد_النمط) {
        دع موضع: غير_موقع = البداية + ف;
        لو ((*القيمة)[موضع] != (*المطلوب)[ف]) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

عام عرف ابحث_بايتات_من(القيمة: &متجه غ8, المطلوب: &متجه غ8, البداية: غير_موقع): اختيار غير_موقع {
    دع عدد_المصدر: غير_موقع = الطول(*القيمة) مثل غير_موقع;
    دع عدد_النمط: غير_موقع = الطول(*المطلوب) مثل غير_موقع;
    لو (البداية > عدد_المصدر) { أرجع اختيار.لا_شيء(); };
    لو (عدد_النمط == 0) { أرجع اختيار.بعض(البداية); };
    لو (عدد_النمط > (عدد_المصدر - البداية)) { أرجع اختيار.لا_شيء(); };
    دع الحد: غير_موقع = عدد_المصدر - عدد_النمط;
    دع ف: متغير غير_موقع = البداية;
    بينما (ف <= الحد) {
        دع ع: متغير غير_موقع = 0;
        دع يطابق: متغير منطقي = صواب;
        بينما (يطابق && (ع < عدد_النمط)) {
            دع موضع: غير_موقع = ف + ع;
            لو ((*القيمة)[موضع] != (*المطلوب)[ع]) { يطابق := خطأ; };
            ع := ع + 1;
        }
        لو (يطابق) { أرجع اختيار.بعض(ف); };
        ف := ف + 1;
    }
    أرجع اختيار.لا_شيء();
}

عام عرف ابحث_بايتات(القيمة: &متجه غ8, المطلوب: &متجه غ8): اختيار غير_موقع {
    أرجع ابحث_بايتات_من(القيمة, المطلوب, 0);
}

عام عرف تحتوي_البايتات(القيمة: &متجه غ8, المطلوب: &متجه غ8): منطقي {
    طابق ابحث_بايتات(القيمة, المطلوب) مع
    | اختيار.بعض(_) -> { أرجع صواب; }
    | اختيار.لا_شيء -> { أرجع خطأ; };
}

عام مرادف bytes_starts_with = تبدأ_البايتات_بـ;
عام مرادف bytes_ends_with = تنتهي_البايتات_بـ;
عام مرادف bytes_find_from = ابحث_بايتات_من;
عام مرادف bytes_find = ابحث_بايتات;
عام مرادف bytes_contains = تحتوي_البايتات;

library/std/bytes/cursor.sn:
استورد text.from_bytes;
// Bounds-checked byte cursor for binary protocols and parsers. It owns no I/O;
// callers provide an already available byte vector.
عام نوع مؤشر_بايتات = {
    البايتات: متجه غ8,
    الموضع: غير_موقع
};

عام عرف أنشئ_مؤشر_بايتات(البايتات: &متجه غ8): مؤشر_بايتات {
    // The cursor owns its bytes: an independent copy of the borrowed input.
    دع الناتج: مؤشر_بايتات = { البايتات: انسخ_بايتات(البايتات), الموضع: 0 };
    أرجع الناتج;
}

عام عرف موضع_مؤشر_بايتات(المؤشر: &مؤشر_بايتات): غير_موقع {
    أرجع (*المؤشر).الموضع;
}

عام عرف متبقي_مؤشر_بايتات(المؤشر: &مؤشر_بايتات): غير_موقع {
    دع العدد: غير_موقع = الطول((*المؤشر).البايتات) مثل غير_موقع;
    لو ((*المؤشر).الموضع >= العدد) { أرجع 0; };
    أرجع العدد - (*المؤشر).الموضع;
}

عام عرف اقرأ_غ8(المؤشر: &متغير مؤشر_بايتات): اختيار غ8 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < 1) { أرجع اختيار.لا_شيء(); };
    دع القيمة: غ8 = (*المؤشر).البايتات[(*المؤشر).الموضع];
    (*المؤشر).الموضع := (*المؤشر).الموضع + 1;
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_غ16_صغير(المؤشر: &متغير مؤشر_بايتات): اختيار غ16 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < 2) { أرجع اختيار.لا_شيء(); };
    دع م: غير_موقع = (*المؤشر).الموضع;
    دع م1: غير_موقع = م + 1;
    دع القيمة: غ16 = (((*المؤشر).البايتات[م] مثل غ16) | (((*المؤشر).البايتات[م1] مثل غ16) << 8));
    (*المؤشر).الموضع := م + 2;
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_غ16_كبير(المؤشر: &متغير مؤشر_بايتات): اختيار غ16 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < 2) { أرجع اختيار.لا_شيء(); };
    دع م: غير_موقع = (*المؤشر).الموضع;
    دع م1: غير_موقع = م + 1;
    دع القيمة: غ16 = ((((*المؤشر).البايتات[م] مثل غ16) << 8) | ((*المؤشر).البايتات[م1] مثل غ16));
    (*المؤشر).الموضع := م + 2;
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_غ32_صغير(المؤشر: &متغير مؤشر_بايتات): اختيار غ32 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < 4) { أرجع اختيار.لا_شيء(); };
    دع م: غير_موقع = (*المؤشر).الموضع;
    دع م1: غير_موقع = م + 1;
    دع م2: غير_موقع = م + 2;
    دع م3: غير_موقع = م + 3;
    دع ب0: غ32 = (*المؤشر).البايتات[م] مثل غ32;
    دع ب1: غ32 = (*المؤشر).البايتات[م1] مثل غ32;
    دع ب2: غ32 = (*المؤشر).البايتات[م2] مثل غ32;
    دع ب3: غ32 = (*المؤشر).البايتات[م3] مثل غ32;
    دع القيمة: متغير غ32 = ب0;
    القيمة := القيمة | (ب1 << 8);
    القيمة := القيمة | (ب2 << 16);
    القيمة := القيمة | (ب3 << 24);
    (*المؤشر).الموضع := م + 4;
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_غ32_كبير(المؤشر: &متغير مؤشر_بايتات): اختيار غ32 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < 4) { أرجع اختيار.لا_شيء(); };
    دع م: غير_موقع = (*المؤشر).الموضع;
    دع م1: غير_موقع = م + 1;
    دع م2: غير_موقع = م + 2;
    دع م3: غير_موقع = م + 3;
    دع ب0: غ32 = (*المؤشر).البايتات[م] مثل غ32;
    دع ب1: غ32 = (*المؤشر).البايتات[م1] مثل غ32;
    دع ب2: غ32 = (*المؤشر).البايتات[م2] مثل غ32;
    دع ب3: غ32 = (*المؤشر).البايتات[م3] مثل غ32;
    دع القيمة: متغير غ32 = ب0 << 24;
    القيمة := القيمة | (ب1 << 16);
    القيمة := القيمة | (ب2 << 8);
    القيمة := القيمة | ب3;
    (*المؤشر).الموضع := م + 4;
    أرجع اختيار.بعض(القيمة);
}

عام عرف اقرأ_بايتات(المؤشر: &متغير مؤشر_بايتات, العدد: غير_موقع): اختيار متجه غ8 {
    لو (متبقي_مؤشر_بايتات(المؤشر) < العدد) { أرجع اختيار.لا_شيء(); };
    دع الناتج: متغير متجه غ8 = [];
    دع النهاية: غير_موقع = (*المؤشر).الموضع + العدد;
    دع ف: متغير غير_موقع = (*المؤشر).الموضع;
    بينما (ف < النهاية) {
        ألحق(الناتج, (*المؤشر).البايتات[ف]);
        ف := ف + 1;
    }
    (*المؤشر).الموضع := النهاية;
    أرجع اختيار.بعض(الناتج);
}

عام عرف تخط_بايتات(المؤشر: &متغير مؤشر_بايتات, العدد: غير_موقع): منطقي {
    لو (متبقي_مؤشر_بايتات(المؤشر) < العدد) { أرجع خطأ; };
    (*المؤشر).الموضع := (*المؤشر).الموضع + العدد;
    أرجع صواب;
}

عام نوع byte_cursor = مؤشر_بايتات;
عام مرادف new_byte_cursor = أنشئ_مؤشر_بايتات;
عام مرادف byte_cursor_position = موضع_مؤشر_بايتات;
عام مرادف byte_cursor_remaining = متبقي_مؤشر_بايتات;
عام مرادف byte_cursor_read_u8 = اقرأ_غ8;
عام مرادف byte_cursor_read_u16_le = اقرأ_غ16_صغير;
عام مرادف byte_cursor_read_u16_be = اقرأ_غ16_كبير;
عام مرادف byte_cursor_read_u32_le = اقرأ_غ32_صغير;
عام مرادف byte_cursor_read_u32_be = اقرأ_غ32_كبير;
عام مرادف byte_cursor_read_bytes = اقرأ_بايتات;
عام مرادف byte_cursor_skip = تخط_بايتات;

library/std/bytes/range.sn:
// التحقق العام من حدود نطاق داخل متجه بايتات.
عام عرف متاح_في_البايتات(
    القيمة: &متجه غ8,
    الموضع: غير_موقع,
    العدد: غير_موقع
): منطقي {
    دع الطول_الكلي: غير_موقع = الطول(*القيمة) مثل غير_موقع;

    لو (الموضع > الطول_الكلي) {
        أرجع خطأ;
    };

    أرجع العدد <= (الطول_الكلي - الموضع);
}

// ينسخ نطاق بايتات صالحا إلى متجه مستقل؛ النطاق غير الصالح لا يُقص أو يُمدد ضمنيا.
عام عرف انسخ_نطاق_بايتات(
    القيمة: &متجه غ8,
    الموضع: غير_موقع,
    العدد: غير_موقع
): اختيار متجه غ8 {
    لو (!متاح_في_البايتات(القيمة, الموضع, العدد)) {
        أرجع اختيار.لا_شيء();
    };

    دع الناتج: متغير متجه غ8 = [];
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < العدد) {
        دع موضع_الحالي: غير_موقع = الموضع + الفهرس;
        ألحق(الناتج, (*القيمة)[موضع_الحالي]);
        الفهرس := الفهرس + 1;
    }

    أرجع اختيار.بعض(الناتج);
}
// الأسماء العامة الإنجليزية ترتبط بالتصريحات العربية نفسها.
عام مرادف byte_range_available = متاح_في_البايتات;
عام مرادف copy_byte_range = انسخ_نطاق_بايتات;

library/std/chars/ascii.sn:
// خصائص ASCII العامة على مستوى البايت.
عام عرف رقم_عشري(البايت: غ8): منطقي {
    أرجع (البايت >= 0x30) && (البايت <= 0x39);
}

عام عرف رقم_سداسي(البايت: غ8): منطقي {
    أرجع رقم_عشري(البايت)
        || ((البايت >= 0x41) && (البايت <= 0x46))
        || ((البايت >= 0x61) && (البايت <= 0x66));
}

عام عرف قيمة_سداسية(البايت: غ8): عدد {
    لو ((البايت >= 0x30) && (البايت <= 0x39)) {
        أرجع (البايت - 0x30) مثل عدد;
    };
    لو ((البايت >= 0x41) && (البايت <= 0x46)) {
        أرجع ((البايت - 0x41) + 10) مثل عدد;
    };
    لو ((البايت >= 0x61) && (البايت <= 0x66)) {
        أرجع ((البايت - 0x61) + 10) مثل عدد;
    };
    أرجع -1;
}

عام عرف حرف_لاتيني(البايت: غ8): منطقي {
    أرجع ((البايت >= 0x41) && (البايت <= 0x5A))
        || ((البايت >= 0x61) && (البايت <= 0x7A));
}

عام عرف فاصل_أسكي(البايت: غ8): منطقي {
    أرجع (البايت == 0x20)
        || (البايت == 0x09)
        || (البايت == 0x0D)
        || (البايت == 0x0A);
}
// الأسماء العامة الإنجليزية ترتبط بالتصريحات العربية نفسها.
عام مرادف is_decimal_digit = رقم_عشري;
عام مرادف is_hex_digit = رقم_سداسي;
عام مرادف hex_digit_value = قيمة_سداسية;
عام مرادف is_latin_letter = حرف_لاتيني;
عام مرادف is_ascii_separator = فاصل_أسكي;

عام عرف محرف_أسكي(البايت: غ8): منطقي {
    أرجع البايت <= 0x7F;
}

عام عرف حرف_لاتيني_صغير(البايت: غ8): منطقي {
    أرجع (البايت >= 0x61) && (البايت <= 0x7A);
}

عام عرف حرف_لاتيني_كبير(البايت: غ8): منطقي {
    أرجع (البايت >= 0x41) && (البايت <= 0x5A);
}

عام عرف حرف_أو_رقم_أسكي(البايت: غ8): منطقي {
    أرجع حرف_لاتيني(البايت) || رقم_عشري(البايت);
}

عام عرف فراغ_أسكي(البايت: غ8): منطقي {
    أرجع (البايت == 0x20) || ((البايت >= 0x09) && (البايت <= 0x0D));
}

عام عرف تحكم_أسكي(البايت: غ8): منطقي {
    أرجع (البايت <= 0x1F) || (البايت == 0x7F);
}

عام عرف قابل_للطباعة_أسكي(البايت: غ8): منطقي {
    أرجع (البايت >= 0x20) && (البايت <= 0x7E);
}

عام عرف إلى_صغير_أسكي(البايت: غ8): غ8 {
    لو (حرف_لاتيني_كبير(البايت)) { أرجع (البايت + 0x20) مثل غ8; };
    أرجع البايت;
}

عام عرف إلى_كبير_أسكي(البايت: غ8): غ8 {
    لو (حرف_لاتيني_صغير(البايت)) { أرجع (البايت - 0x20) مثل غ8; };
    أرجع البايت;
}

// قيمة رقم ASCII لقواعد 2..36؛ -1 لغير الرقم/الحرف اللاتيني.
عام عرف قيمة_رقم_أسكي(البايت: غ8): عدد {
    لو (رقم_عشري(البايت)) { أرجع (البايت - 0x30) مثل عدد; };
    لو (حرف_لاتيني_كبير(البايت)) { أرجع ((البايت - 0x41) + 10) مثل عدد; };
    لو (حرف_لاتيني_صغير(البايت)) { أرجع ((البايت - 0x61) + 10) مثل عدد; };
    أرجع -1;
}

عام مرادف is_ascii = محرف_أسكي;
عام مرادف is_ascii_lowercase = حرف_لاتيني_صغير;
عام مرادف is_ascii_uppercase = حرف_لاتيني_كبير;
عام مرادف is_ascii_alphanumeric = حرف_أو_رقم_أسكي;
عام مرادف is_ascii_whitespace = فراغ_أسكي;
عام مرادف is_ascii_control = تحكم_أسكي;
عام مرادف is_ascii_printable = قابل_للطباعة_أسكي;
