library/std/collections/btree_map.sn:
// Ordered generic B-tree map. Minimum degree 8 gives up to 15 keys and
// 16 children per node. Optional slots let structural operations move owning
// generic keys/values without copying them.
// The caller comparator must define a stable total ordering: zero exactly for
// equivalent keys, and a consistent sign for each ordered pair of keys.

عام نوع مدخل_خريطة_شجرة_بي<م, ق> = {
    المفتاح: م,
    القيمة: ق
};

نوع مدخل_منقول_شجرة_بي<م, ق> = {
    المفتاح: اختيار م,
    القيمة: اختيار ق
};

نوع عقدة_خريطة_شجرة_بي<م, ق> = {
    المفاتيح: متجه اختيار م,
    القيم: متجه اختيار ق,
    الأبناء: متجه غير_موقع,
    العدد: غير_موقع,
    ورقة: منطقي,
    فعالة: منطقي
};

نوع موضع_خريطة_شجرة_بي = {
    العقدة: غير_موقع,
    الموضع: غير_موقع
};

عام نوع خريطة_شجرة_بي<م, ق> = {
    العقد: متجه عقدة_خريطة_شجرة_بي<م, ق>,
    الجذر: غير_موقع,
    العدد: غير_موقع,
    المقارنة: دالة(&م, &م): عدد,
    العقد_الحرة: متجه غير_موقع,
    عدد_العقد_الحرة: غير_موقع
};

عرف درجة_خريطة_شجرة_بي(): غير_موقع { أرجع 8; }
عرف أقصى_مفاتيح_خريطة_شجرة_بي(): غير_موقع { أرجع 15; }
عرف أقصى_أبناء_خريطة_شجرة_بي(): غير_موقع { أرجع 16; }

عرف ابن_عقدة_خريطة_شجرة_بي<م, ق>(ورقة: منطقي): عقدة_خريطة_شجرة_بي<م, ق> {
    دع المفاتيح: متغير متجه اختيار م = [];
    دع القيم: متغير متجه اختيار ق = [];
    دع الأبناء: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < أقصى_مفاتيح_خريطة_شجرة_بي()) {
        ألحق(المفاتيح, اختيار.لا_شيء());
        ألحق(القيم, اختيار.لا_شيء());
        ف := ف + 1;
    }
    ف := 0;
    بينما (ف < أقصى_أبناء_خريطة_شجرة_بي()) {
        ألحق(الأبناء, 0);
        ف := ف + 1;
    }
    دع الناتج: عقدة_خريطة_شجرة_بي<م, ق> = {
        المفاتيح: المفاتيح,
        القيم: القيم,
        الأبناء: الأبناء,
        العدد: 0,
        ورقة: ورقة,
        فعالة: صواب
    };
    أرجع الناتج;
}

عرف فرغ_عقدة_خريطة_شجرة_بي<م, ق>(
    الخريطة: &متغير خريطة_شجرة_بي<م, ق>,
    الفهرس: غير_موقع,
    ورقة: منطقي
): فراغ {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < أقصى_مفاتيح_خريطة_شجرة_بي()) {
        دع مفتاح_مزال: متغير اختيار م = اختيار.لا_شيء();
        دع قيمة_مزالة: متغير اختيار ق = اختيار.لا_شيء();
        بدّل((*الخريطة).العقد[الفهرس].المفاتيح[ف], مفتاح_مزال);
        بدّل((*الخريطة).العقد[الفهرس].القيم[ف], قيمة_مزالة);
        ف := ف + 1;
    }
    ف := 0;
    بينما (ف < أقصى_أبناء_خريطة_شجرة_بي()) {
        (*الخريطة).العقد[الفهرس].الأبناء[ف] := 0;
        ف := ف + 1;
    }
    (*الخريطة).العقد[الفهرس].العدد := 0;
    (*الخريطة).العقد[الفهرس].ورقة := ورقة;
    (*الخريطة).العقد[الفهرس].فعالة := صواب;
}

عرف خصص_عقدة_خريطة_شجرة_بي<م, ق>(
    الخريطة: &متغير خريطة_شجرة_بي<م, ق>,
    ورقة: منطقي
): غير_موقع {
    لو ((*الخريطة).عدد_العقد_الحرة > 0) {
        دع الموضع: غير_موقع = (*الخريطة).عدد_العقد_الحرة - 1;
        دع الفهرس: غير_موقع = (*الخريطة).العقد_الحرة[الموضع];
        (*الخريطة).عدد_العقد_الحرة := الموضع;
        فرغ_عقدة_خريطة_شجرة_بي(الخريطة, الفهرس, ورقة);
        أرجع الفهرس;
    };
    دع الفهرس: غير_موقع = الطول((*الخريطة).العقد) مثل غير_موقع;
    دع العقدة: عقدة_خريطة_شجرة_بي<م, ق> = ابن_عقدة_خريطة_شجرة_بي(ورقة);
    ألحق((*الخريطة).العقد, العقدة);
    أرجع الفهرس;
}

عرف حرر_عقدة_خريطة_شجرة_بي<م, ق>(
    الخريطة: &متغير خريطة_شجرة_بي<م, ق>,
    الفهرس: غير_موقع
): فراغ {
    (*الخريطة).العقد[الفهرس].العدد := 0;
    (*الخريطة).العقد[الفهرس].ورقة := صواب;
    (*الخريطة).العقد[الفهرس].فعالة := خطأ;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < أقصى_أبناء_خريطة_شجرة_بي()) {
        (*الخريطة).العقد[الفهرس].الأبناء[ف] := 0;
        ف := ف + 1;
    }
    دع الموضع: غير_موقع = (*الخريطة).عدد_العقد_الحرة;
    لو (الموضع < (الطول((*الخريطة).العقد_الحرة) مثل غير_موقع)) {
        (*الخريطة).العقد_الحرة[الموضع] := الفهرس;
    } وإلا {
        ألحق((*الخريطة).العقد_الحرة, الفهرس);
    };
    (*الخريطة).عدد_العقد_الحرة := الموضع + 1;
}

عام عرف أنشئ_خريطة_شجرة_بي<م, ق>(المقارنة: دالة(&م, &م): عدد): خريطة_شجرة_بي<م, ق> {
    دع العقد: متجه عقدة_خريطة_شجرة_بي<م, ق> = [];
    دع الحرة: متجه غير_موقع = [];
    دع الناتج: متغير خريطة_شجرة_بي<م, ق> = {
        العقد: العقد,
        الجذر: 0,
        العدد: 0,
        المقارنة: المقارنة,
        العقد_الحرة: الحرة,
        عدد_العقد_الحرة: 0
    };
    دع الجذر: غير_موقع = خصص_عقدة_خريطة_شجرة_بي(&متغير الناتج, صواب);
    الناتج.الجذر := الجذر;
    أرجع الناتج;
}

عام عرف طول_خريطة_شجرة_بي<م, ق>(الخريطة: &خريطة_شجرة_بي<م, ق>): غير_موقع {
