عام عرف امسح_خريطة_شجرة_بي<م, ق>(الخريطة: &متغير خريطة_شجرة_بي<م, ق>): فراغ {
    دع عدد_العقد: غير_موقع = الطول((*الخريطة).العقد) مثل غير_موقع;
    دع الجذر: غير_موقع = (*الخريطة).الجذر;
    دع الحرة: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < عدد_العقد) {
        فرغ_عقدة_خريطة_شجرة_بي(الخريطة, ف, صواب);
        لو (ف != الجذر) {
            (*الخريطة).العقد[ف].فعالة := خطأ;
            ألحق(الحرة, ف);
        };
        ف := ف + 1;
    }
    (*الخريطة).العقد[الجذر].فعالة := صواب;
    (*الخريطة).العقد[الجذر].ورقة := صواب;
    (*الخريطة).العقد[الجذر].العدد := 0;
    (*الخريطة).العقد_الحرة := الحرة;
    (*الخريطة).عدد_العقد_الحرة := الطول((*الخريطة).العقد_الحرة) مثل غير_موقع;
    (*الخريطة).العدد := 0;
}

