// Comparator-driven binary max-heap. A positive comparator result means the
// first value has higher priority than the second value.
عام نوع الكومة<ق> = {
    العناصر: متجه اختيار ق,
    العدد: غير_موقع,
    المقارنة: دالة(&ق, &ق): عدد
};

عرف سعة_نمو_الكومة(الحالية: غير_موقع, المطلوبة: غير_موقع): غير_موقع {
    دع السعة: متغير غير_موقع = الحالية;
    لو (السعة < 8) { السعة := 8; };
    دع الحد: غير_موقع = ~((0 مثل غير_موقع));
    بينما (السعة < المطلوبة) {
        // Do not wrap on the last doubling. An exact large capacity is valid.
        لو (السعة > (الحد / 2)) { أرجع المطلوبة; };
        السعة := السعة * 2;
    }
    أرجع السعة;
}

عرف ابن_خانات_الكومة<ق>(السعة: غير_موقع): متجه اختيار ق {
    دع الناتج: متغير متجه اختيار ق = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < السعة) {
        ألحق(الناتج, اختيار.لا_شيء());
        ف := ف + 1;
    }
    أرجع الناتج;
}

عام عرف أنشئ_الكومة_بسعة<ق>(السعة: غير_موقع, المقارنة: دالة(&ق, &ق): عدد): الكومة<ق> {
    دع العناصر: متجه اختيار ق = ابن_خانات_الكومة(السعة);
    دع الناتج: الكومة<ق> = { العناصر: العناصر, العدد: 0, المقارنة: المقارنة };
    أرجع الناتج;
}

عام عرف أنشئ_الكومة<ق>(المقارنة: دالة(&ق, &ق): عدد): الكومة<ق> {
    أرجع أنشئ_الكومة_بسعة(0, المقارنة);
}

عام عرف طول_الكومة<ق>(الكومة: &الكومة<ق>): غير_موقع {
    أرجع (*الكومة).العدد;
}

عام عرف سعة_الكومة<ق>(الكومة: &الكومة<ق>): غير_موقع {
    أرجع الطول((*الكومة).العناصر) مثل غير_موقع;
}

عام عرف الكومة_فارغة<ق>(الكومة: &الكومة<ق>): منطقي {
    أرجع (*الكومة).العدد == 0;
}

// False indicates unsigned count overflow; no slots or elements are changed.
// Allocation failure remains the backing vector's responsibility.
عام عرف احجز_للكومة<ق>(الكومة: &متغير الكومة<ق>, إضافي: غير_موقع): منطقي {
    دع الحد: غير_موقع = ~((0 مثل غير_موقع));
    لو (إضافي > (الحد - (*الكومة).العدد)) { أرجع خطأ; };
    دع المطلوبة: غير_موقع = (*الكومة).العدد + إضافي;
    دع الحالية: غير_موقع = الطول((*الكومة).العناصر) مثل غير_موقع;
    لو (المطلوبة <= الحالية) { أرجع صواب; };
    دع الجديدة: غير_موقع = سعة_نمو_الكومة(الحالية, المطلوبة);
    دع ف: متغير غير_موقع = الحالية;
    بينما (ف < الجديدة) {
        ألحق((*الكومة).العناصر, اختيار.لا_شيء());
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف عنصر_الكومة_أعلى<ق>(الكومة: &الكومة<ق>, الأول: غير_موقع, الثاني: غير_موقع): منطقي {
    دع المقارنة: دالة(&ق, &ق): عدد = (*الكومة).المقارنة;
    طابق (*الكومة).العناصر[الأول] مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(أ) -> {
        طابق (*الكومة).العناصر[الثاني] مع
        | اختيار.لا_شيء -> { أرجع صواب; }
        | اختيار.بعض(ب) -> { أرجع المقارنة(&أ, &ب) > 0; };
    };
}

عرف اصعد_في_الكومة<ق>(الكومة: &متغير الكومة<ق>, الموضع_الأولي: غير_موقع): فراغ {
    دع الموضع: متغير غير_موقع = الموضع_الأولي;
    بينما (الموضع > 0) {
        دع الأب: غير_موقع = (الموضع - 1) / 2;
        لو (!عنصر_الكومة_أعلى(الكومة, الموضع, الأب)) { أرجع; };
        بدّل((*الكومة).العناصر[الموضع], (*الكومة).العناصر[الأب]);
        الموضع := الأب;
    }
}

عرف انزل_في_الكومة<ق>(الكومة: &متغير الكومة<ق>, الموضع_الأولي: غير_موقع): فراغ {
    دع الموضع: متغير غير_موقع = الموضع_الأولي;
    بينما (صواب) {
        // No child exists beyond this bound; avoid overflowing 2 * index + 1.
        لو (الموضع >= ((*الكومة).العدد / 2)) { أرجع; };
        دع اليسار: غير_موقع = الموضع * 2 + 1;
        دع الأفضل: متغير غير_موقع = اليسار;
        دع اليمين: غير_موقع = اليسار + 1;
        لو ((اليمين < (*الكومة).العدد) && عنصر_الكومة_أعلى(الكومة, اليمين, اليسار)) {
            الأفضل := اليمين;
        };
        لو (!عنصر_الكومة_أعلى(الكومة, الأفضل, الموضع)) { أرجع; };
        بدّل((*الكومة).العناصر[الموضع], (*الكومة).العناصر[الأفضل]);
        الموضع := الأفضل;
    }
}

// False means no insertion occurred because the requested count overflowed.
عام عرف أضف_إلى_الكومة<ق>(الكومة: &متغير الكومة<ق>, القيمة: ق): منطقي {
    لو (!احجز_للكومة(الكومة, 1)) { أرجع خطأ; };
    دع الموضع: غير_موقع = (*الكومة).العدد;
    دع الجديدة: متغير اختيار ق = اختيار.بعض(القيمة);
    بدّل((*الكومة).العناصر[الموضع], الجديدة);
    (*الكومة).العدد := الموضع + 1;
    اصعد_في_الكومة(الكومة, الموضع);
    أرجع صواب;
}

عام عرف قمة_الكومة<ق>(الكومة: &الكومة<ق>): اختيار ق {
    لو ((*الكومة).العدد == 0) { أرجع اختيار.لا_شيء(); };
    طابق (*الكومة).العناصر[0] مع
    | اختيار.بعض(القيمة) -> { أرجع اختيار.بعض(القيمة); }
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); };
}

عام عرف خذ_قمة_الكومة<ق>(الكومة: &متغير الكومة<ق>): اختيار ق {
    لو ((*الكومة).العدد == 0) { أرجع اختيار.لا_شيء(); };
    دع الأخير: غير_موقع = (*الكومة).العدد - 1;
    لو (الأخير > 0) {
        بدّل((*الكومة).العناصر[0], (*الكومة).العناصر[الأخير]);
    };
    دع الناتج: متغير اختيار ق = اختيار.لا_شيء();
    بدّل((*الكومة).العناصر[الأخير], الناتج);
    (*الكومة).العدد := الأخير;
    لو (الأخير > 0) { انزل_في_الكومة(الكومة, 0); };
    أرجع الناتج;
}

عام عرف امسح_الكومة<ق>(الكومة: &متغير الكومة<ق>): فراغ {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (*الكومة).العدد) {
        دع المزال: متغير اختيار ق = اختيار.لا_شيء();
        بدّل((*الكومة).العناصر[ف], المزال);
        ف := ف + 1;
    }
    (*الكومة).العدد := 0;
}

عام عرف أعد_ضبط_الكومة<ق>(الكومة: &متغير الكومة<ق>): فراغ {
    دع الفارغة: متجه اختيار ق = [];
    (*الكومة).العناصر := الفارغة;
    (*الكومة).العدد := 0;
}

عام نوع heap<T> = الكومة<T>;
عام مرادف new_heap = أنشئ_الكومة;
عام مرادف new_heap_with_capacity = أنشئ_الكومة_بسعة;
عام مرادف heap_reserve = احجز_للكومة;
عام مرادف heap_push = أضف_إلى_الكومة;
عام مرادف heap_peek = قمة_الكومة;
عام مرادف heap_pop = خذ_قمة_الكومة;
عام مرادف heap_length = طول_الكومة;
عام مرادف heap_capacity = سعة_الكومة;
عام مرادف heap_is_empty = الكومة_فارغة;
عام مرادف heap_clear = امسح_الكومة;
عام مرادف heap_reset = أعد_ضبط_الكومة;

library/std/collections/map.sn:
// Canonical generic open-addressed hash map. Hash and equality policy are supplied
// by the caller; this module owns storage, probing, capacity, and tombstones.
//
// Buckets intentionally contain only cached hash/index metadata. Generic keys and
// values live in side storage so probing can compare a borrowed stored key without
// copying arbitrary generic payloads on every collision.
// Equal keys must have equal hashes, and neither hash nor equality may change
// while a key is stored. Violating that caller contract invalidates lookup.
عام نوع خانة_الخريطة<م, ق> =
    | فارغة
    | محذوفة
    | مشغولة بنوع (غير_موقع, غير_موقع)
;

عام نوع مدخل_الخريطة<م, ق> = { المفتاح: م, القيمة: ق };

عام نوع الخريطة<م, ق> = {
    الخانات: متجه خانة_الخريطة<م, ق>,
    المداخل: متجه مدخل_الخريطة<اختيار م, اختيار ق>,
    المداخل_الحرة: متجه غير_موقع,
    عدد_المداخل_الحرة: غير_موقع,
    العدد: غير_موقع,
    المحذوف: غير_موقع,
    الهاش: دالة(&م): غير_موقع,
    التساوي: دالة(&م, &م): منطقي
};

نوع نتيجة_مسبار_الخريطة = {
    الموضع: غير_موقع,
    فهرس_المدخل: غير_موقع,
    موجود: منطقي,
    يعيد_استخدام_محذوف: منطقي
};

نوع موضع_الخريطة = {
    الموضع: غير_موقع,
    فهرس_المدخل: غير_موقع
};

عرف سعة_خانات_للعدد(العدد: غير_موقع): غير_موقع {
    دع السعة: متغير غير_موقع = 8;
    // Divide first for a non-overflowing 3/4 threshold. The final capacity
    // may stop being a power of two if doubling cannot represent it; probing
    // uses modulo and remains valid for any nonzero bucket count.
    دع الحد: غير_موقع = ~((0 مثل غير_موقع));
    بينما (العدد > ((السعة / 4) * 3)) {
        لو (السعة > (الحد / 2)) { أرجع الحد; };
        السعة := السعة * 2;
    }
    أرجع السعة;
}

عرف ابن_خانات_الخريطة<م, ق>(السعة: غير_موقع): متجه خانة_الخريطة<م, ق> {
    دع الناتج: متغير متجه خانة_الخريطة<م, ق> = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < السعة) {
        ألحق(الناتج, خانة_الخريطة.فارغة());
        ف := ف + 1;
    }
    أرجع الناتج;
}

عام عرف أنشئ_الخريطة_بسعة<م, ق>(
    السعة_المتوقعة: غير_موقع,
    الهاش: دالة(&م): غير_موقع,
    التساوي: دالة(&م, &م): منطقي
): الخريطة<م, ق> {
    دع سعة_الخانات: غير_موقع = سعة_خانات_للعدد(السعة_المتوقعة);
    دع الخانات: متجه خانة_الخريطة<م, ق> = ابن_خانات_الخريطة(سعة_الخانات);
    دع المداخل: متجه مدخل_الخريطة<اختيار م, اختيار ق> = [];
    دع الحرة: متجه غير_موقع = [];
    دع الناتج: الخريطة<م, ق> = {
        الخانات: الخانات,
        المداخل: المداخل,
        المداخل_الحرة: الحرة,
        عدد_المداخل_الحرة: 0,
        العدد: 0,
        المحذوف: 0,
        الهاش: الهاش,
        التساوي: التساوي
    };
    أرجع الناتج;
}

عام عرف أنشئ_الخريطة<م, ق>(
    الهاش: دالة(&م): غير_موقع,
    التساوي: دالة(&م, &م): منطقي
): الخريطة<م, ق> {
    أرجع أنشئ_الخريطة_بسعة(0, الهاش, التساوي);
}

عرف ابحث_عن_موضع_الخريطة<م, ق>(
    الخريطة: &الخريطة<م, ق>,
    المفتاح: &م,
    الهاش: غير_موقع
): اختيار موضع_الخريطة {
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    لو (السعة == 0) { أرجع اختيار.لا_شيء(); };
    دع التساوي: دالة(&م, &م): منطقي = (*الخريطة).التساوي;
    دع الموضع: متغير غير_موقع = الهاش % السعة;
    دع المفحوص: متغير غير_موقع = 0;
    بينما (المفحوص < السعة) {
        طابق (*الخريطة).الخانات[الموضع] مع
        | خانة_الخريطة.فارغة -> { أرجع اختيار.لا_شيء(); }
        | خانة_الخريطة.محذوفة -> { }
        | خانة_الخريطة.مشغولة(هاش_الخانة, فهرس_المدخل) -> {
            لو (هاش_الخانة == الهاش) {
                دع مرجع_المفتاح: &اختيار م = &(*الخريطة).المداخل[فهرس_المدخل].المفتاح;
                طابق *مرجع_المفتاح مع
                | اختيار.بعض(المفتاح_المخزن) -> {
                    لو (التساوي(&المفتاح_المخزن, المفتاح)) {
                        دع الناتج: موضع_الخريطة = {
                            الموضع: الموضع,
                            فهرس_المدخل: فهرس_المدخل
                        };
                        أرجع اختيار.بعض(الناتج);
                    };
                }
                | اختيار.لا_شيء -> { };
            };
        };
        الموضع := (الموضع + 1) % السعة;
        المفحوص := المفحوص + 1;
    }
    أرجع اختيار.لا_شيء();
}

عرف مسبار_إدخال_الخريطة<م, ق>(
    الخريطة: &الخريطة<م, ق>,
    المفتاح: &م,
    الهاش: غير_موقع
): نتيجة_مسبار_الخريطة {
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    دع التساوي: دالة(&م, &م): منطقي = (*الخريطة).التساوي;
    دع الموضع: متغير غير_موقع = الهاش % السعة;
    دع أول_محذوف: متغير اختيار غير_موقع = اختيار.لا_شيء();
    دع المفحوص: متغير غير_موقع = 0;
    بينما (المفحوص < السعة) {
        طابق (*الخريطة).الخانات[الموضع] مع
        | خانة_الخريطة.فارغة -> {
            طابق أول_محذوف مع
            | اختيار.بعض(موضع_محذوف) -> {
                دع الناتج: نتيجة_مسبار_الخريطة = {
                    الموضع: موضع_محذوف,
                    فهرس_المدخل: 0,
                    موجود: خطأ,
                    يعيد_استخدام_محذوف: صواب
                };
                أرجع الناتج;
            }
            | اختيار.لا_شيء -> {
                دع الناتج: نتيجة_مسبار_الخريطة = {
                    الموضع: الموضع,
                    فهرس_المدخل: 0,
                    موجود: خطأ,
                    يعيد_استخدام_محذوف: خطأ
                };
                أرجع الناتج;
            };
        }
        | خانة_الخريطة.محذوفة -> {
            طابق أول_محذوف مع
            | اختيار.لا_شيء -> { أول_محذوف := اختيار.بعض(الموضع); }
            | اختيار.بعض(_) -> { };
        }
        | خانة_الخريطة.مشغولة(هاش_الخانة, فهرس_المدخل) -> {
            لو (هاش_الخانة == الهاش) {
                دع مرجع_المفتاح: &اختيار م = &(*الخريطة).المداخل[فهرس_المدخل].المفتاح;
                طابق *مرجع_المفتاح مع
                | اختيار.بعض(المفتاح_المخزن) -> {
                    لو (التساوي(&المفتاح_المخزن, المفتاح)) {
                        دع الناتج: نتيجة_مسبار_الخريطة = {
                            الموضع: الموضع,
                            فهرس_المدخل: فهرس_المدخل,
                            موجود: صواب,
                            يعيد_استخدام_محذوف: خطأ
                        };
                        أرجع الناتج;
                    };
                }
                | اختيار.لا_شيء -> { };
            };
        };
        الموضع := (الموضع + 1) % السعة;
        المفحوص := المفحوص + 1;
    }
    طابق أول_محذوف مع
    | اختيار.بعض(موضع_محذوف) -> {
        دع الناتج: نتيجة_مسبار_الخريطة = {
            الموضع: موضع_محذوف,
            فهرس_المدخل: 0,
            موجود: خطأ,
            يعيد_استخدام_محذوف: صواب
        };
        أرجع الناتج;
    }
    | اختيار.لا_شيء -> {
        دع الناتج: نتيجة_مسبار_الخريطة = {
            الموضع: 0,
            فهرس_المدخل: 0,
            موجود: خطأ,
            يعيد_استخدام_محذوف: خطأ
        };
        أرجع الناتج;
    };
}

عرف أدرج_فهرس_في_خانات<م, ق>(
    الخانات: &متغير متجه خانة_الخريطة<م, ق>,
    الهاش: غير_موقع,
    فهرس_المدخل: غير_موقع
): فراغ {
    دع السعة: غير_موقع = الطول(*الخانات) مثل غير_موقع;
    دع الموضع: متغير غير_موقع = الهاش % السعة;
    دع المفحوص: متغير غير_موقع = 0;
    بينما (المفحوص < السعة) {
        طابق (*الخانات)[الموضع] مع
        | خانة_الخريطة.فارغة -> {
            (*الخانات)[الموضع] := خانة_الخريطة.مشغولة(الهاش, فهرس_المدخل);
            أرجع;
        }
        | _ -> { };
        الموضع := (الموضع + 1) % السعة;
        المفحوص := المفحوص + 1;
    }
}

عرف أعد_تجزئة_الخريطة<م, ق>(الخريطة: &متغير الخريطة<م, ق>, السعة_المطلوبة: غير_موقع): فراغ {
    دع السعة: متغير غير_موقع = السعة_المطلوبة;
    لو (السعة < 8) { السعة := 8; };
    دع الجديدة: متغير متجه خانة_الخريطة<م, ق> = ابن_خانات_الخريطة(السعة);
    دع القديمة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < القديمة) {
        طابق (*الخريطة).الخانات[ف] مع
        | خانة_الخريطة.مشغولة(هاش_الخانة, فهرس_المدخل) -> {
            أدرج_فهرس_في_خانات(&متغير الجديدة, هاش_الخانة, فهرس_المدخل);
        }
        | _ -> { };
        ف := ف + 1;
    }
    (*الخريطة).الخانات := الجديدة;
    (*الخريطة).المحذوف := 0;
}

عرف سجل_مدخلا_حرا<م, ق>(الخريطة: &متغير الخريطة<م, ق>, فهرس_المدخل: غير_موقع): فراغ {
    دع الموضع: غير_موقع = (*الخريطة).عدد_المداخل_الحرة;
    لو (الموضع < (الطول((*الخريطة).المداخل_الحرة) مثل غير_موقع)) {
        (*الخريطة).المداخل_الحرة[الموضع] := فهرس_المدخل;
    } وإلا {
        ألحق((*الخريطة).المداخل_الحرة, فهرس_المدخل);
    };
    (*الخريطة).عدد_المداخل_الحرة := الموضع + 1;
}

عرف خذ_مدخلا_حرا<م, ق>(الخريطة: &متغير الخريطة<م, ق>): اختيار غير_موقع {
    لو ((*الخريطة).عدد_المداخل_الحرة == 0) { أرجع اختيار.لا_شيء(); };
    دع الموضع: غير_موقع = (*الخريطة).عدد_المداخل_الحرة - 1;
    (*الخريطة).عدد_المداخل_الحرة := الموضع;
    أرجع اختيار.بعض((*الخريطة).المداخل_الحرة[الموضع]);
}

// False means the requested live count exceeds the maximum representable
// 3/4-load bucket capacity. The map is unchanged on that failure.
// Allocation failure remains the backing vector's responsibility.
عام عرف احجز_للخريطة<م, ق>(الخريطة: &متغير الخريطة<م, ق>, إضافي: غير_موقع): منطقي {
    دع الحد_الأقصى: غير_موقع = (~((0 مثل غير_موقع)) / 4) * 3;
    لو ((*الخريطة).العدد > الحد_الأقصى) { أرجع خطأ; };
    لو (إضافي > (الحد_الأقصى - (*الخريطة).العدد)) { أرجع خطأ; };
    دع المطلوب_من_المداخل: غير_موقع = (*الخريطة).العدد + إضافي;
    دع المطلوبة: غير_موقع = سعة_خانات_للعدد(المطلوب_من_المداخل);
    دع الحالية: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    لو (المطلوبة > الحالية) {
        أعد_تجزئة_الخريطة(الخريطة, المطلوبة);
        أرجع صواب;
    };
    لو ((*الخريطة).المحذوف > 0) {
        دع المساحة_الحرة: غير_موقع = ((الحالية / 4) * 3) - (*الخريطة).العدد;
        لو ((*الخريطة).المحذوف > المساحة_الحرة) {
            أعد_تجزئة_الخريطة(الخريطة, الحالية);
        } وإلا لو (إضافي > (المساحة_الحرة - (*الخريطة).المحذوف)) {
            أعد_تجزئة_الخريطة(الخريطة, الحالية);
        };
    };
    أرجع صواب;
}

عام عرف سعة_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>): غير_موقع {
    دع سعة_الخانات: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    أرجع (سعة_الخانات / 4) * 3;
}

// An inserted key returns نجح(لا_شيء); a replaced key returns its old value.
// A capacity failure returns خطأ without modifying buckets or owned entries.
// The old اختيار-only insertion return could not represent this failure.
عام نوع خطأ_إدراج_الخريطة =
    | سعة_غير_قابلة_للتمثيل
;

عام عرف أدرج_في_الخريطة<م, ق>(
    الخريطة: &متغير الخريطة<م, ق>,
    المفتاح: م,
    القيمة: ق
): نتيجة اختيار ق, خطأ_إدراج_الخريطة {
    دع دالة_الهاش: دالة(&م): غير_موقع = (*الخريطة).الهاش;
    دع الهاش: غير_موقع = دالة_الهاش(&المفتاح);
    دع المسبار: نتيجة_مسبار_الخريطة = مسبار_إدخال_الخريطة(الخريطة, &المفتاح, الهاش);

    // Replacing an existing key does not require an additional slot.
    لو (المسبار.موجود) {
        دع الجديدة: متغير اختيار ق = اختيار.بعض(القيمة);
        بدّل((*الخريطة).المداخل[المسبار.فهرس_المدخل].القيمة, الجديدة);
        أرجع نتيجة.نجح(الجديدة);
    };

    // Reservation is the sole capacity/overflow check. Failure happens before
    // taking a free entry or writing keys, values, buckets, or the live count.
    لو (!احجز_للخريطة(الخريطة, 1)) {
        أرجع نتيجة.خطأ(خطأ_إدراج_الخريطة.سعة_غير_قابلة_للتمثيل());
    };

    // Reservation may rehash (including compacting tombstones). The original
    // probe is therefore stale; resolve the new bucket before changing storage.
    دع موضع_الإدراج: نتيجة_مسبار_الخريطة = مسبار_إدخال_الخريطة(
        الخريطة, &المفتاح, الهاش
    );

    دع فهرس_المدخل: متغير غير_موقع = 0;
    طابق خذ_مدخلا_حرا(الخريطة) مع
    | اختيار.بعض(الفهرس) -> {
        فهرس_المدخل := الفهرس;
        دع المفتاح_الجديد: متغير اختيار م = اختيار.بعض(المفتاح);
        دع القيمة_الجديدة: متغير اختيار ق = اختيار.بعض(القيمة);
        بدّل((*الخريطة).المداخل[الفهرس].المفتاح, المفتاح_الجديد);
        بدّل((*الخريطة).المداخل[الفهرس].القيمة, القيمة_الجديدة);
    }
    | اختيار.لا_شيء -> {
        فهرس_المدخل := الطول((*الخريطة).المداخل) مثل غير_موقع;
        دع المدخل: مدخل_الخريطة<اختيار م, اختيار ق> = {
            المفتاح: اختيار.بعض(المفتاح),
            القيمة: اختيار.بعض(القيمة)
        };
        ألحق((*الخريطة).المداخل, المدخل);
    };

    (*الخريطة).الخانات[موضع_الإدراج.الموضع] := خانة_الخريطة.مشغولة(
        الهاش, فهرس_المدخل
    );
    لو (موضع_الإدراج.يعيد_استخدام_محذوف) {
        (*الخريطة).المحذوف := (*الخريطة).المحذوف - 1;
    };
    // The checked reservation guarantees that increasing the count fits.
    (*الخريطة).العدد := (*الخريطة).العدد + 1;
    أرجع نتيجة.نجح(اختيار.لا_شيء());
}

عام عرف ابحث_في_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>, المفتاح: &م): اختيار ق {
    دع دالة_الهاش: دالة(&م): غير_موقع = (*الخريطة).الهاش;
    دع الهاش: غير_موقع = دالة_الهاش(المفتاح);
    طابق ابحث_عن_موضع_الخريطة(الخريطة, المفتاح, الهاش) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الموجود) -> {
        طابق (*الخريطة).المداخل[الموجود.فهرس_المدخل].القيمة مع
        | اختيار.بعض(القيمة) -> { أرجع اختيار.بعض(القيمة); }
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); };
    };
}

عام عرف تحتوي_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>, المفتاح: &م): منطقي {
    دع دالة_الهاش: دالة(&م): غير_موقع = (*الخريطة).الهاش;
    دع الهاش: غير_موقع = دالة_الهاش(المفتاح);
    طابق ابحث_عن_موضع_الخريطة(الخريطة, المفتاح, الهاش) مع
    | اختيار.بعض(_) -> { أرجع صواب; }
    | اختيار.لا_شيء -> { أرجع خطأ; };
}

عام عرف احذف_من_الخريطة<م, ق>(الخريطة: &متغير الخريطة<م, ق>, المفتاح: &م): اختيار ق {
    دع دالة_الهاش: دالة(&م): غير_موقع = (*الخريطة).الهاش;
    دع الهاش: غير_موقع = دالة_الهاش(المفتاح);
    طابق ابحث_عن_موضع_الخريطة(الخريطة, المفتاح, الهاش) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الموجود) -> {
        دع المفتاح_المحذوف: متغير اختيار م = اختيار.لا_شيء();
        دع القيمة_المحذوفة: متغير اختيار ق = اختيار.لا_شيء();
        بدّل((*الخريطة).المداخل[الموجود.فهرس_المدخل].المفتاح, المفتاح_المحذوف);
        بدّل((*الخريطة).المداخل[الموجود.فهرس_المدخل].القيمة, القيمة_المحذوفة);
        (*الخريطة).الخانات[الموجود.الموضع] := خانة_الخريطة.محذوفة();
        (*الخريطة).العدد := (*الخريطة).العدد - 1;
        (*الخريطة).المحذوف := (*الخريطة).المحذوف + 1;
        سجل_مدخلا_حرا(الخريطة, الموجود.فهرس_المدخل);
        أرجع القيمة_المحذوفة;
    };
}

عام عرف طول_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>): غير_موقع {
    أرجع (*الخريطة).العدد;
}

// Clear releases every live generic payload while retaining reusable bucket
// and side-entry storage. Every side slot becomes owner-empty and reusable.
عام عرف امسح_الخريطة<م, ق>(الخريطة: &متغير الخريطة<م, ق>): فراغ {
    دع ف: متغير غير_موقع = 0;
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    بينما (ف < السعة) {
        (*الخريطة).الخانات[ف] := خانة_الخريطة.فارغة();
        ف := ف + 1;
    }

    (*الخريطة).عدد_المداخل_الحرة := 0;
    ف := 0;
    دع عدد_المداخل: غير_موقع = الطول((*الخريطة).المداخل) مثل غير_موقع;
    بينما (ف < عدد_المداخل) {
        دع المفتاح_المزال: متغير اختيار م = اختيار.لا_شيء();
        دع القيمة_المزالة: متغير اختيار ق = اختيار.لا_شيء();
        بدّل((*الخريطة).المداخل[ف].المفتاح, المفتاح_المزال);
        بدّل((*الخريطة).المداخل[ف].القيمة, القيمة_المزالة);
        سجل_مدخلا_حرا(الخريطة, ف);
        ف := ف + 1;
    }
    (*الخريطة).العدد := 0;
    (*الخريطة).المحذوف := 0;
}

عام عرف أعد_ضبط_الخريطة<م, ق>(الخريطة: &متغير الخريطة<م, ق>): فراغ {
    دع الهاش: دالة(&م): غير_موقع = (*الخريطة).الهاش;
    دع التساوي: دالة(&م, &م): منطقي = (*الخريطة).التساوي;
    دع الجديدة: الخريطة<م, ق> = أنشئ_الخريطة(الهاش, التساوي);
    *الخريطة := الجديدة;
}

عام عرف مداخل_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>): متجه مدخل_الخريطة<م, ق> {
    دع الناتج: متغير متجه مدخل_الخريطة<م, ق> = [];
    دع ف: متغير غير_موقع = 0;
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    بينما (ف < السعة) {
        طابق (*الخريطة).الخانات[ف] مع
        | خانة_الخريطة.مشغولة(_, فهرس_المدخل) -> {
            طابق (*الخريطة).المداخل[فهرس_المدخل].المفتاح مع
            | اختيار.بعض(المفتاح) -> {
                طابق (*الخريطة).المداخل[فهرس_المدخل].القيمة مع
                | اختيار.بعض(القيمة) -> {
                    دع المدخل: مدخل_الخريطة<م, ق> = { المفتاح: المفتاح, القيمة: القيمة };
                    ألحق(الناتج, المدخل);
                }
                | اختيار.لا_شيء -> { };
            }
            | اختيار.لا_شيء -> { };
        }
        | _ -> { };
        ف := ف + 1;
    }
    أرجع الناتج;
}

// Materialize live keys directly from the canonical bucket/index owner.
// No intermediate key/value entry vector is needed by set-values callers.
عام عرف مفاتيح_الخريطة<م, ق>(الخريطة: &الخريطة<م, ق>): متجه م {
    دع الناتج: متغير متجه م = [];
    دع ف: متغير غير_موقع = 0;
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    بينما (ف < السعة) {
        طابق (*الخريطة).الخانات[ف] مع
        | خانة_الخريطة.مشغولة(_, فهرس_المدخل) -> {
            طابق (*الخريطة).المداخل[فهرس_المدخل].المفتاح مع
            | اختيار.بعض(المفتاح) -> { ألحق(الناتج, المفتاح); }
            | اختيار.لا_شيء -> { };
        }
        | _ -> { };
        ف := ف + 1;
    }
    أرجع الناتج;
}

// English compatibility surface.
عام نوع map_bucket<K, V> = خانة_الخريطة<K, V>;
عام نوع map<K, V> = الخريطة<K, V>;
عام نوع map_entry<K, V> = مدخل_الخريطة<K, V>;
عام مرادف new_map = أنشئ_الخريطة;
عام مرادف new_map_with_capacity = أنشئ_الخريطة_بسعة;
عام مرادف map_insert = أدرج_في_الخريطة;
عام مرادف map_get = ابحث_في_الخريطة;
عام مرادف map_contains = تحتوي_الخريطة;
عام مرادف map_remove = احذف_من_الخريطة;
عام مرادف map_length = طول_الخريطة;
عام مرادف map_capacity = سعة_الخريطة;
عام مرادف map_reserve = احجز_للخريطة;
عام مرادف map_clear = امسح_الخريطة;
عام مرادف map_clear_retain_capacity = امسح_الخريطة;
عام مرادف map_reset = أعد_ضبط_الخريطة;
عام مرادف map_entries = مداخل_الخريطة;
عام مرادف map_keys = مفاتيح_الخريطة;

library/std/collections/set.sn:
استورد collections.map;

عام نوع مجموعة<T> = { الخريطة: الخريطة<T, منطقي> };

عام عرف أنشئ_مجموعة<T>(الهاش: دالة(&T): غير_موقع, التساوي: دالة(&T, &T): منطقي): مجموعة<T> {
    دع الخريطة: الخريطة<T, منطقي> = أنشئ_الخريطة(الهاش, التساوي);
    دع الناتج: مجموعة<T> = { الخريطة: الخريطة };
    أرجع الناتج;
}

// نجح(صواب) adds a new element; نجح(خطأ) means it was already present.
// Capacity failure is distinct from both outcomes and leaves the set unchanged.
عام عرف أضف_إلى_مجموعة<T>(
    المجموعة: &متغير مجموعة<T>,
    القيمة: T
): نتيجة منطقي, خطأ_إدراج_الخريطة {
    طابق أدرج_في_الخريطة(&متغير (*المجموعة).الخريطة, القيمة, صواب) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(اختيار.لا_شيء) -> { أرجع نتيجة.نجح(صواب); }
    | نتيجة.نجح(اختيار.بعض(_)) -> { أرجع نتيجة.نجح(خطأ); };
}

عام عرف تحتوي_مجموعة<T>(المجموعة: &مجموعة<T>, القيمة: &T): منطقي {
    أرجع تحتوي_الخريطة(&(*المجموعة).الخريطة, القيمة);
}

عام عرف احذف_من_مجموعة<T>(المجموعة: &متغير مجموعة<T>, القيمة: &T): منطقي {
    طابق احذف_من_الخريطة(&متغير (*المجموعة).الخريطة, القيمة) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(_) -> { أرجع صواب; };
}

عام عرف طول_مجموعة<T>(المجموعة: &مجموعة<T>): غير_موقع {
    أرجع طول_الخريطة(&(*المجموعة).الخريطة);
}

عام عرف امسح_مجموعة<T>(المجموعة: &متغير مجموعة<T>): فراغ {
    امسح_الخريطة(&متغير (*المجموعة).الخريطة);
}

// The canonical map materializes live keys without an intermediate entry copy.
عام عرف قيم_مجموعة<T>(المجموعة: &مجموعة<T>): متجه T {
    أرجع مفاتيح_الخريطة(&(*المجموعة).الخريطة);
}

عام نوع set<T> = مجموعة<T>;
عام مرادف new_set = أنشئ_مجموعة;
عام مرادف set_insert = أضف_إلى_مجموعة;
عام مرادف set_contains = تحتوي_مجموعة;
عام مرادف set_remove = احذف_من_مجموعة;
عام مرادف set_length = طول_مجموعة;
عام مرادف set_clear = امسح_مجموعة;
عام مرادف set_values = قيم_مجموعة;

library/std/collections/sort.sn:
استورد text.compare;

// Comparator-driven in-place heap sort. A negative comparator result means
// the first value sorts before the second value. The implementation swaps
// vector slots directly so arbitrary generic values are not copied merely
// to reorder them. The comparator must define a consistent total order.
عام عرف رتب_بالمقارنة<ق>(القيم: &متغير متجه ق, المقارنة: دالة(&ق, &ق): عدد): فراغ {
    دع العدد: غير_موقع = الطول(*القيم) مثل غير_موقع;
    لو (العدد < 2) { أرجع; };

    دع البداية: متغير غير_موقع = العدد / 2;
    بينما (البداية > 0) {
        البداية := البداية - 1;
        دع الجذر: متغير غير_موقع = البداية;
        دع مستمر: متغير منطقي = صواب;
        بينما (مستمر) {
            لو (الجذر >= (العدد / 2)) { اخرج_من_حلقة; };
            دع الأكبر: متغير غير_موقع = الجذر;
            دع اليسار: غير_موقع = الجذر * 2 + 1;
            لو ((اليسار < العدد) && (المقارنة(&(*القيم)[اليسار], &(*القيم)[الأكبر]) > 0)) { الأكبر := اليسار; };
            دع اليمين: غير_موقع = اليسار + 1;
            لو ((اليمين < العدد) && (المقارنة(&(*القيم)[اليمين], &(*القيم)[الأكبر]) > 0)) { الأكبر := اليمين; };
            لو (الأكبر == الجذر) { مستمر := خطأ; }
            وإلا {
                بدّل((*القيم)[الجذر], (*القيم)[الأكبر]);
                الجذر := الأكبر;
            };
        }
    }

    دع الحد: متغير غير_موقع = العدد;
    بينما (الحد > 1) {
        الحد := الحد - 1;
        بدّل((*القيم)[0], (*القيم)[الحد]);
        دع الجذر: متغير غير_موقع = 0;
        دع مستمر: متغير منطقي = صواب;
        بينما (مستمر) {
            لو (الجذر >= (الحد / 2)) { اخرج_من_حلقة; };
            دع الأكبر: متغير غير_موقع = الجذر;
            دع اليسار: غير_موقع = الجذر * 2 + 1;
            لو ((اليسار < الحد) && (المقارنة(&(*القيم)[اليسار], &(*القيم)[الأكبر]) > 0)) { الأكبر := اليسار; };
            دع اليمين: غير_موقع = اليسار + 1;
            لو ((اليمين < الحد) && (المقارنة(&(*القيم)[اليمين], &(*القيم)[الأكبر]) > 0)) { الأكبر := اليمين; };
            لو (الأكبر == الجذر) { مستمر := خطأ; }
            وإلا {
                بدّل((*القيم)[الجذر], (*القيم)[الأكبر]);
                الجذر := الأكبر;
            };
        }
    }
}

// Returns one matching position in an already-sorted vector.
عام عرف بحث_ثنائي_بالمقارنة<ق>(
    القيم: &متجه ق,
    المطلوب: &ق,
    المقارنة: دالة(&ق, &ق): عدد
): اختيار غير_موقع {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = الطول(*القيم) مثل غير_موقع;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + ((النهاية - البداية) / 2);
        دع نتيجة_المقارنة: عدد = المقارنة(&(*القيم)[الوسط], المطلوب);
        لو (نتيجة_المقارنة < 0) { البداية := الوسط + 1; }
        وإلا لو (نتيجة_المقارنة > 0) { النهاية := الوسط; }
        وإلا { أرجع اختيار.بعض(الوسط); };
    }
    أرجع اختيار.لا_شيء();
}

// First position at which value can be inserted without violating ordering.
عام عرف موضع_الحد_الأدنى_بالمقارنة<ق>(
    القيم: &متجه ق,
    المطلوب: &ق,
    المقارنة: دالة(&ق, &ق): عدد
): غير_موقع {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = الطول(*القيم) مثل غير_موقع;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + ((النهاية - البداية) / 2);
        لو (المقارنة(&(*القيم)[الوسط], المطلوب) < 0) { البداية := الوسط + 1; }
        وإلا { النهاية := الوسط; };
    }
    أرجع البداية;
}

// First position strictly after all values equal to the requested value.
عام عرف موضع_الحد_الأعلى_بالمقارنة<ق>(
    القيم: &متجه ق,
    المطلوب: &ق,
    المقارنة: دالة(&ق, &ق): عدد
): غير_موقع {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = الطول(*القيم) مثل غير_موقع;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + ((النهاية - البداية) / 2);
        لو (المقارنة(&(*القيم)[الوسط], المطلوب) <= 0) { البداية := الوسط + 1; }
        وإلا { النهاية := الوسط; };
    }
    أرجع البداية;
}

عرف قارن_غير_موقع_للفرز(أ: &غير_موقع, ب: &غير_موقع): عدد {
    لو (*أ < *ب) { أرجع -1; };
    لو (*أ > *ب) { أرجع 1; };
    أرجع 0;
}

عرف قارن_عدد_للفرز(أ: &عدد, ب: &عدد): عدد {
    لو (*أ < *ب) { أرجع -1; };
    لو (*أ > *ب) { أرجع 1; };
    أرجع 0;
}

عام عرف رتب_غير_موقع(القيم: &متغير متجه غير_موقع): فراغ { رتب_بالمقارنة(القيم, قارن_غير_موقع_للفرز); }
عام عرف رتب_عدد(القيم: &متغير متجه عدد): فراغ { رتب_بالمقارنة(القيم, قارن_عدد_للفرز); }
عام عرف رتب_نصوص(القيم: &متغير متجه نص): فراغ { رتب_بالمقارنة(القيم, قارن_نصين_معجميا); }

عام عرف بحث_ثنائي_غير_موقع(القيم: &متجه غير_موقع, المطلوب: غير_موقع): اختيار غير_موقع {
    أرجع بحث_ثنائي_بالمقارنة(القيم, &المطلوب, قارن_غير_موقع_للفرز);
}
عام عرف بحث_ثنائي_عدد(القيم: &متجه عدد, المطلوب: عدد): اختيار غير_موقع {
    أرجع بحث_ثنائي_بالمقارنة(القيم, &المطلوب, قارن_عدد_للفرز);
}
عام عرف بحث_ثنائي_نص(القيم: &متجه نص, المطلوب: &نص): اختيار غير_موقع {
    أرجع بحث_ثنائي_بالمقارنة(القيم, المطلوب, قارن_نصين_معجميا);
}

