): اختيار غير_موقع {
    أرجع احذف_من_الخريطة(الخريطة, المفتاح);
}

عام عرف طول_خريطة_نص_فهرس(الخريطة: &خريطة_نص_فهرس): غير_موقع {
    أرجع طول_الخريطة(الخريطة);
}

عام عرف امسح_خريطة_نص_فهرس(الخريطة: &متغير خريطة_نص_فهرس): فراغ {
    امسح_الخريطة(الخريطة);
}

// Generic entry materialization copies keys by reading them, which text keys
// do not allow; each live key is copied into independent text here.
عام عرف مداخل_خريطة_نص_فهرس(الخريطة: &خريطة_نص_فهرس): متجه مدخل_خريطة_نص_فهرس {
    دع الناتج: متغير متجه مدخل_خريطة_نص_فهرس = [];
    دع ف: متغير غير_موقع = 0;
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    بينما (ف < السعة) {
        طابق (*الخريطة).الخانات[ف] مع
        | خانة_الخريطة.مشغولة(_, فهرس_المدخل) -> {
            طابق (*الخريطة).المداخل[فهرس_المدخل].المفتاح مع
            | اختيار.بعض(المفتاح) -> {
                طابق (*الخريطة).المداخل[فهرس_المدخل].القيمة مع
                | اختيار.بعض(القيمة) -> {
                    دع المدخل: مدخل_خريطة_نص_فهرس = { المفتاح: انسخ_نص(&المفتاح), القيمة: القيمة };
                    ألحق(الناتج, المدخل);
                }
                | اختيار.لا_شيء -> { };
            }
            | اختيار.لا_شيء -> { };
        }
        | _ -> { };
        ف := ف + 1;
    }
    أرجع الناتج;
}

