عام عرف قيم_مجموعة_نص(المجموعة: &مجموعة_نص): متجه نص {
    دع الخريطة: &الخريطة<نص, منطقي> = &(*المجموعة).الخريطة;
    دع الناتج: متغير متجه نص = [];
    دع ف: متغير غير_موقع = 0;
    دع السعة: غير_موقع = الطول((*الخريطة).الخانات) مثل غير_موقع;
    بينما (ف < السعة) {
        طابق (*الخريطة).الخانات[ف] مع
        | خانة_الخريطة.مشغولة(_, فهرس_المدخل) -> {
            طابق (*الخريطة).المداخل[فهرس_المدخل].المفتاح مع
            | اختيار.بعض(المفتاح) -> { ألحق(الناتج, انسخ_نص(&المفتاح)); }
            | اختيار.لا_شيء -> { };
        }
        | _ -> { };
        ف := ف + 1;
    }
    أرجع الناتج;
}

