عرف اقرأ_بت_ديفليت(المصدر: &متجه غ8, القارئ: &متغير قارئ_بتات_ديفليت): اختيار غير_موقع {
    دع العدد: غير_موقع = الطول(*المصدر) مثل غير_موقع;
    لو ((*القارئ).موضع_البايت >= العدد) { أرجع اختيار.لا_شيء(); };
    دع البايت: غ8 = (*المصدر)[(*القارئ).موضع_البايت];
    دع البت: غير_موقع = ((البايت >> ((*القارئ).موضع_البت مثل غ8)) & 1) مثل غير_موقع;
    (*القارئ).موضع_البت := (*القارئ).موضع_البت + 1;
    لو ((*القارئ).موضع_البت == 8) {
        (*القارئ).موضع_البت := 0;
        (*القارئ).موضع_البايت := (*القارئ).موضع_البايت + 1;
    };
    أرجع اختيار.بعض(البت);
}

عرف اقرأ_بتات_صغيرة_ديفليت(
    المصدر: &متجه غ8,
    القارئ: &متغير قارئ_بتات_ديفليت,
    العدد: غير_موقع
): اختيار غير_موقع {
    دع القيمة: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        طابق اقرأ_بت_ديفليت(المصدر, القارئ) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(البت) -> { القيمة := القيمة | (البت << ف); };
        ف := ف + 1;
    }
    أرجع اختيار.بعض(القيمة);
}

عرف حاذ_قارئ_ديفليت(القارئ: &متغير قارئ_بتات_ديفليت): فراغ {
    لو ((*القارئ).موضع_البت != 0) {
        (*القارئ).موضع_البت := 0;
        (*القارئ).موضع_البايت := (*القارئ).موضع_البايت + 1;
    };
}

عرف أنشئ_كاتب_بتات_ديفليت(): كاتب_بتات_ديفليت {
    دع البايتات: متجه غ8 = [];
    دع الناتج: كاتب_بتات_ديفليت = { البايتات: البايتات, الحالي: 0, عدد_البتات: 0 };
    أرجع الناتج;
}

عرف اكتب_بت_ديفليت(الكاتب: &متغير كاتب_بتات_ديفليت, البت: غير_موقع): فراغ {
    لو ((البت & 1) != 0) {
        دع القناع: غ8 = (1 << ((*الكاتب).عدد_البتات مثل غ8)) مثل غ8;
        (*الكاتب).الحالي := (*الكاتب).الحالي | القناع;
    };
    (*الكاتب).عدد_البتات := (*الكاتب).عدد_البتات + 1;
    لو ((*الكاتب).عدد_البتات == 8) {
        ألحق((*الكاتب).البايتات, (*الكاتب).الحالي);
        (*الكاتب).الحالي := 0;
        (*الكاتب).عدد_البتات := 0;
    };
}

عرف اكتب_بتات_صغيرة_ديفليت(
    الكاتب: &متغير كاتب_بتات_ديفليت,
    القيمة: غير_موقع,
    العدد: غير_موقع
): فراغ {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        اكتب_بت_ديفليت(الكاتب, (القيمة >> ف) & 1);
        ف := ف + 1;
    }
}

عرف اكتب_شفرة_هوفمان_ديفليت(
    الكاتب: &متغير كاتب_بتات_ديفليت,
    الشفرة: غير_موقع,
    الطول: غير_موقع
): فراغ {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الطول) {
        دع الإزاحة: غير_موقع = الطول - 1 - ف;
        اكتب_بت_ديفليت(الكاتب, (الشفرة >> الإزاحة) & 1);
        ف := ف + 1;
    }
}

عرف أنه_كاتب_بتات_ديفليت(الكاتب: كاتب_بتات_ديفليت): متجه غ8 {
    // Consumes the writer so its byte buffer can move to the caller.
    دع الحالة: متغير كاتب_بتات_ديفليت = الكاتب;
    لو (الحالة.عدد_البتات != 0) {
        ألحق(الحالة.البايتات, الحالة.الحالي);
        الحالة.الحالي := 0;
        الحالة.عدد_البتات := 0;
    };
    طابق الحالة مع
    | { البايتات: البايتات, الحالي: _, عدد_البتات: _ } -> { أرجع البايتات; };
}

عرف ابن_شجرة_هوفمان_ديفليت(الأطوال: &متجه غير_موقع): نتيجة شجرة_هوفمان_ديفليت, خطأ_ديفليت {
    دع الأعداد: متغير متجه غير_موقع = متجه_أصفار_ديفليت(16);
    دع أقصى: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*الأطوال) مثل غير_موقع)) {
        دع طول_الرمز: غير_موقع = (*الأطوال)[ف];
        لو (طول_الرمز > 15) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };
        لو (طول_الرمز > 0) {
            الأعداد[طول_الرمز] := الأعداد[طول_الرمز] + 1;
            لو (طول_الرمز > أقصى) { أقصى := طول_الرمز; };
        };
        ف := ف + 1;
    }

    دع المتبقي: متغير عدد = 1;
    دع ب: متغير غير_موقع = 1;
    بينما (ب <= 15) {
        المتبقي := (المتبقي * 2) - (الأعداد[ب] مثل عدد);
        لو (المتبقي < 0) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };
        ب := ب + 1;
    }

    دع أول_شفرة: متغير متجه غير_موقع = متجه_أصفار_ديفليت(16);
    دع أول_رمز: متغير متجه غير_موقع = متجه_أصفار_ديفليت(16);
    دع الشفرة: متغير غير_موقع = 0;
    دع تراكم: متغير غير_موقع = 0;
    ب := 1;
    بينما (ب <= 15) {
        الشفرة := (الشفرة + الأعداد[ب - 1]) << 1;
        أول_شفرة[ب] := الشفرة;
        أول_رمز[ب] := تراكم;
        تراكم := تراكم + الأعداد[ب];
        ب := ب + 1;
    }

    دع الرموز: متغير متجه غير_موقع = [];
    ب := 1;
    بينما (ب <= 15) {
        ف := 0;
        بينما (ف < (الطول(*الأطوال) مثل غير_موقع)) {
            لو ((*الأطوال)[ف] == ب) { ألحق(الرموز, ف); };
            ف := ف + 1;
        }
        ب := ب + 1;
    }

    دع الناتج: شجرة_هوفمان_ديفليت = {
        الأعداد: الأعداد,
        أول_شفرة: أول_شفرة,
        أول_رمز: أول_رمز,
        الرموز: الرموز,
        أقصى_طول: أقصى
    };
    أرجع نتيجة.نجح(الناتج);
}

عرف فك_رمز_هوفمان_ديفليت(
    المصدر: &متجه غ8,
    القارئ: &متغير قارئ_بتات_ديفليت,
    الشجرة: &شجرة_هوفمان_ديفليت
): نتيجة غير_موقع, خطأ_ديفليت {
    لو ((*الشجرة).أقصى_طول == 0) { أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_هوفمان_غير_صالح()); };
    دع الشفرة: متغير غير_موقع = 0;
    دع الطول_الحالي: متغير غير_موقع = 1;
    بينما (الطول_الحالي <= (*الشجرة).أقصى_طول) {
        طابق اقرأ_بت_ديفليت(المصدر, القارئ) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
        | اختيار.بعض(البت) -> { الشفرة := (الشفرة << 1) | البت; };
        دع العدد: غير_موقع = (*الشجرة).الأعداد[الطول_الحالي];
        دع الأول: غير_موقع = (*الشجرة).أول_شفرة[الطول_الحالي];
        لو ((العدد > 0) && (الشفرة >= الأول) && (الشفرة < (الأول + العدد))) {
            دع الفهرس: غير_موقع = (*الشجرة).أول_رمز[الطول_الحالي] + (الشفرة - الأول);
            لو (الفهرس >= (الطول((*الشجرة).الرموز) مثل غير_موقع)) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_هوفمان_غير_صالح());
            };
            أرجع نتيجة.نجح((*الشجرة).الرموز[الفهرس]);
        };
        الطول_الحالي := الطول_الحالي + 1;
    }
    أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_هوفمان_غير_صالح());
}

عرف أطوال_هوفمان_الثابتة_للحروف(): متجه غير_موقع {
    دع الأطوال: متغير متجه غير_موقع = متجه_أصفار_ديفليت(288);
    دع ف: متغير غير_موقع = 0;
    بينما (ف <= 143) { الأطوال[ف] := 8; ف := ف + 1; }
    بينما (ف <= 255) { الأطوال[ف] := 9; ف := ف + 1; }
    بينما (ف <= 279) { الأطوال[ف] := 7; ف := ف + 1; }
    بينما (ف <= 287) { الأطوال[ف] := 8; ف := ف + 1; }
    أرجع الأطوال;
}

عرف أطوال_هوفمان_الثابتة_للمسافات(): متجه غير_موقع {
    دع الأطوال: متغير متجه غير_موقع = متجه_أصفار_ديفليت(32);
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 32) { الأطوال[ف] := 5; ف := ف + 1; }
    أرجع الأطوال;
}

عرف ابن_شجرتي_ديفليت_الديناميكيتين(
    المصدر: &متجه غ8,
    القارئ: &متغير قارئ_بتات_ديفليت
): نتيجة متجه شجرة_هوفمان_ديفليت, خطأ_ديفليت {
    دع هليت: متغير غير_موقع = 0;
    دع هديست: متغير غير_موقع = 0;
    دع هكلن: متغير غير_موقع = 0;
    طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 5) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
    | اختيار.بعض(ق) -> { هليت := ق + 257; };
    طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 5) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
    | اختيار.بعض(ق) -> { هديست := ق + 1; };
    طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 4) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
    | اختيار.بعض(ق) -> { هكلن := ق + 4; };

    دع ترتيب: متجه غير_موقع = [16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15];
    دع أطوال_الترميز: متغير متجه غير_موقع = متجه_أصفار_ديفليت(19);
    دع ف: متغير غير_موقع = 0;
    بينما (ف < هكلن) {
        طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 3) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
        | اختيار.بعض(ق) -> { أطوال_الترميز[ترتيب[ف]] := ق; };
        ف := ف + 1;
    }

    دع شجرة_الترميز: متغير شجرة_هوفمان_ديفليت = شجرة_هوفمان_ديفليت_فارغة();
    طابق ابن_شجرة_هوفمان_ديفليت(&أطوال_الترميز) مع
    | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
    | نتيجة.نجح(ش) -> { شجرة_الترميز := ش; };
    لو (شجرة_الترميز.أقصى_طول == 0) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };

    دع المطلوب: غير_موقع = هليت + هديست;
    دع الأطوال: متغير متجه غير_موقع = [];
    بينما ((الطول(الأطوال) مثل غير_موقع) < المطلوب) {
        دع الرمز: متغير غير_موقع = 0;
        طابق فك_رمز_هوفمان_ديفليت(المصدر, القارئ, &شجرة_الترميز) مع
        | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
        | نتيجة.نجح(ق) -> { الرمز := ق; };

        لو (الرمز <= 15) {
            ألحق(الأطوال, الرمز);
        } وإلا لو (الرمز == 16) {
            دع الحالي: غير_موقع = الطول(الأطوال) مثل غير_موقع;
            لو (الحالي == 0) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };
            دع السابق: غير_موقع = الأطوال[الحالي - 1];
            دع التكرار: متغير غير_موقع = 0;
            طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 2) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
            | اختيار.بعض(ق) -> { التكرار := ق + 3; };
            لو (الحالي + التكرار > المطلوب) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };
            دع ت: متغير غير_موقع = 0;
            بينما (ت < التكرار) { ألحق(الأطوال, السابق); ت := ت + 1; }
        } وإلا لو (الرمز == 17) {
            دع التكرار: متغير غير_موقع = 0;
            طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 3) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
            | اختيار.بعض(ق) -> { التكرار := ق + 3; };
            لو ((الطول(الأطوال) مثل غير_موقع) + التكرار > المطلوب) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة());
            };
            دع ت: متغير غير_موقع = 0;
            بينما (ت < التكرار) { ألحق(الأطوال, 0); ت := ت + 1; }
        } وإلا لو (الرمز == 18) {
            دع التكرار: متغير غير_موقع = 0;
            طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, 7) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
            | اختيار.بعض(ق) -> { التكرار := ق + 11; };
            لو ((الطول(الأطوال) مثل غير_موقع) + التكرار > المطلوب) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة());
            };
            دع ت: متغير غير_موقع = 0;
            بينما (ت < التكرار) { ألحق(الأطوال, 0); ت := ت + 1; }
        } وإلا {
            أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة());
        };
    }

    دع أطوال_الحروف: متغير متجه غير_موقع = [];
    دع أطوال_المسافات: متغير متجه غير_موقع = [];
    ف := 0;
    بينما (ف < هليت) { ألحق(أطوال_الحروف, الأطوال[ف]); ف := ف + 1; }
    بينما (ف < المطلوب) { ألحق(أطوال_المسافات, الأطوال[ف]); ف := ف + 1; }
    لو ((الطول(أطوال_الحروف) مثل غير_موقع) <= 256) {
        أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة());
    };
    لو (أطوال_الحروف[256] == 0) { أرجع نتيجة.خطأ(خطأ_ديفليت.شجرة_هوفمان_غير_صالحة()); };

    دع شجرة_الحروف: متغير شجرة_هوفمان_ديفليت = شجرة_هوفمان_ديفليت_فارغة();
    دع شجرة_المسافات: متغير شجرة_هوفمان_ديفليت = شجرة_هوفمان_ديفليت_فارغة();
    طابق ابن_شجرة_هوفمان_ديفليت(&أطوال_الحروف) مع
    | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
    | نتيجة.نجح(ش) -> { شجرة_الحروف := ش; };
    طابق ابن_شجرة_هوفمان_ديفليت(&أطوال_المسافات) مع
    | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
    | نتيجة.نجح(ش) -> { شجرة_المسافات := ش; };

    دع الناتج: متجه شجرة_هوفمان_ديفليت = [شجرة_الحروف, شجرة_المسافات];
    أرجع نتيجة.نجح(الناتج);
}

عرف يسمح_إخراج_ديفليت(الحالي: غير_موقع, الإضافة: غير_موقع, الحد: غير_موقع): منطقي {
    لو (الحد == 0) { أرجع صواب; };
    لو (الحالي > الحد) { أرجع خطأ; };
    أرجع الإضافة <= (الحد - الحالي);
}

عرف فك_كتلة_هوفمان_ديفليت(
    المصدر: &متجه غ8,
    القارئ: &متغير قارئ_بتات_ديفليت,
    الناتج: &متغير متجه غ8,
    الحروف: &شجرة_هوفمان_ديفليت,
    المسافات: &شجرة_هوفمان_ديفليت,
    الجداول: &جداول_ديفليت,
    الحد: غير_موقع
): نتيجة منطقي, خطأ_ديفليت {
    بينما (صواب) {
        دع الرمز: متغير غير_موقع = 0;
        طابق فك_رمز_هوفمان_ديفليت(المصدر, القارئ, الحروف) مع
        | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
        | نتيجة.نجح(ق) -> { الرمز := ق; };

        لو (الرمز < 256) {
            لو (!يسمح_إخراج_ديفليت(الطول(*الناتج) مثل غير_موقع, 1, الحد)) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.تجاوز_حد_الإخراج());
            };
            ألحق(*الناتج, الرمز مثل غ8);
        } وإلا لو (الرمز == 256) {
            أرجع نتيجة.نجح(صواب);
        } وإلا لو ((الرمز >= 257) && (الرمز <= 285)) {
            دع فهرس_الطول: غير_موقع = الرمز - 257;
            دع طول_التطابق: متغير غير_موقع = (*الجداول).قواعد_الطول[فهرس_الطول];
            دع بتات_الطول: غير_موقع = (*الجداول).إضافيات_الطول[فهرس_الطول];
            لو (بتات_الطول > 0) {
                طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, بتات_الطول) مع
                | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
                | اختيار.بعض(ق) -> { طول_التطابق := طول_التطابق + ق; };
            };

            دع رمز_المسافة: متغير غير_موقع = 0;
            طابق فك_رمز_هوفمان_ديفليت(المصدر, القارئ, المسافات) مع
            | نتيجة.خطأ(_) -> { أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_مسافة_غير_صالح()); }
            | نتيجة.نجح(ق) -> { رمز_المسافة := ق; };
            لو (رمز_المسافة >= 30) { أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_مسافة_غير_صالح()); };
            دع المسافة: متغير غير_موقع = (*الجداول).قواعد_المسافة[رمز_المسافة];
            دع بتات_المسافة: غير_موقع = (*الجداول).إضافيات_المسافة[رمز_المسافة];
            لو (بتات_المسافة > 0) {
                طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, القارئ, بتات_المسافة) مع
                | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
                | اختيار.بعض(ق) -> { المسافة := المسافة + ق; };
            };
            دع طول_الناتج: غير_موقع = الطول(*الناتج) مثل غير_موقع;
            لو ((المسافة == 0) || (المسافة > 32768) || (المسافة > طول_الناتج)) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.مسافة_غير_صالحة());
            };
            لو (!يسمح_إخراج_ديفليت(طول_الناتج, طول_التطابق, الحد)) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.تجاوز_حد_الإخراج());
            };
            دع ت: متغير غير_موقع = 0;
            بينما (ت < طول_التطابق) {
                دع الموضع: غير_موقع = (الطول(*الناتج) مثل غير_موقع) - المسافة;
                دع البايت: غ8 = (*الناتج)[الموضع];
                ألحق(*الناتج, البايت);
                ت := ت + 1;
            }
        } وإلا {
            أرجع نتيجة.خطأ(خطأ_ديفليت.رمز_طول_غير_صالح());
        };
    }
}

عام عرف فك_ضغط_ديفليت_من_موضع_بحد(
    المصدر: &متجه غ8,
    البداية: غير_موقع,
    الحد_الأقصى_للإخراج: غير_موقع
): نتيجة ناتج_فك_ديفليت, خطأ_ديفليت {
    لو (البداية > (الطول(*المصدر) مثل غير_موقع)) {
        أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة());
    };
    دع القارئ: متغير قارئ_بتات_ديفليت = أنشئ_قارئ_بتات_ديفليت(البداية);
    دع الناتج: متغير متجه غ8 = [];
    دع الجداول: جداول_ديفليت = جداول_ديفليت_القياسية();
    دع انتهى: متغير منطقي = خطأ;

    بينما (!انتهى) {
        دع نهائية: متغير غير_موقع = 0;
        دع النوع: متغير غير_موقع = 0;
        طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, &متغير القارئ, 1) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
        | اختيار.بعض(ق) -> { نهائية := ق; };
        طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, &متغير القارئ, 2) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
        | اختيار.بعض(ق) -> { النوع := ق; };

        لو (النوع == 0) {
            حاذ_قارئ_ديفليت(&متغير القارئ);
            دع الطول_المخزن: متغير غير_موقع = 0;
            دع المتمم: متغير غير_موقع = 0;
            طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, &متغير القارئ, 16) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
            | اختيار.بعض(ق) -> { الطول_المخزن := ق; };
            طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, &متغير القارئ, 16) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
            | اختيار.بعض(ق) -> { المتمم := ق; };
            لو (((الطول_المخزن ^ 0xFFFF) & 0xFFFF) != المتمم) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.كتلة_مخزنة_غير_صالحة());
            };
            لو (!يسمح_إخراج_ديفليت(الطول(الناتج) مثل غير_موقع, الطول_المخزن, الحد_الأقصى_للإخراج)) {
                أرجع نتيجة.خطأ(خطأ_ديفليت.تجاوز_حد_الإخراج());
            };
            دع ت: متغير غير_موقع = 0;
            بينما (ت < الطول_المخزن) {
                طابق اقرأ_بتات_صغيرة_ديفليت(المصدر, &متغير القارئ, 8) مع
                | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ديفليت.نهاية_غير_متوقعة()); }
                | اختيار.بعض(ق) -> { ألحق(الناتج, ق مثل غ8); };
                ت := ت + 1;
            }
        } وإلا لو (النوع == 1) {
            دع أطوال_الحروف: متجه غير_موقع = أطوال_هوفمان_الثابتة_للحروف();
            دع أطوال_المسافات: متجه غير_موقع = أطوال_هوفمان_الثابتة_للمسافات();
            دع شجرة_الحروف: متغير شجرة_هوفمان_ديفليت = شجرة_هوفمان_ديفليت_فارغة();
            دع شجرة_المسافات: متغير شجرة_هوفمان_ديفليت = شجرة_هوفمان_ديفليت_فارغة();
            طابق ابن_شجرة_هوفمان_ديفليت(&أطوال_الحروف) مع
            | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
            | نتيجة.نجح(ش) -> { شجرة_الحروف := ش; };
            طابق ابن_شجرة_هوفمان_ديفليت(&أطوال_المسافات) مع
            | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
            | نتيجة.نجح(ش) -> { شجرة_المسافات := ش; };
            طابق فك_كتلة_هوفمان_ديفليت(
                المصدر, &متغير القارئ, &متغير الناتج,
                &شجرة_الحروف, &شجرة_المسافات, &الجداول, الحد_الأقصى_للإخراج
            ) مع
            | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
            | نتيجة.نجح(_) -> { };
        } وإلا لو (النوع == 2) {
            دع الشجرتان: متغير متجه شجرة_هوفمان_ديفليت = [];
            طابق ابن_شجرتي_ديفليت_الديناميكيتين(المصدر, &متغير القارئ) مع
            | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
            | نتيجة.نجح(ش) -> { الشجرتان := ش; };
            طابق فك_كتلة_هوفمان_ديفليت(
                المصدر, &متغير القارئ, &متغير الناتج,
                &الشجرتان[0], &الشجرتان[1], &الجداول, الحد_الأقصى_للإخراج
            ) مع
            | نتيجة.خطأ(خ) -> { أرجع نتيجة.خطأ(خ); }
            | نتيجة.نجح(_) -> { };
        } وإلا {
            أرجع نتيجة.خطأ(خطأ_ديفليت.نوع_كتلة_محجوز());
        };

        لو (نهائية != 0) { انتهى := صواب; };
    }

    حاذ_قارئ_ديفليت(&متغير القارئ);
    دع المستهلك: غير_موقع = القارئ.موضع_البايت - البداية;
    دع النتيجة: ناتج_فك_ديفليت = { البايتات: الناتج, المستهلك: المستهلك };
    أرجع نتيجة.نجح(النتيجة);
}

