عرف شفرة_هوفمان_ثابتة_للحرف(الرمز: غير_موقع): متجه غير_موقع {
    دع الناتج: متغير متجه غير_موقع = [];
    لو (الرمز <= 143) {
        ألحق(الناتج, 0x30 + الرمز);
        ألحق(الناتج, 8);
    } وإلا لو (الرمز <= 255) {
        ألحق(الناتج, 0x190 + (الرمز - 144));
        ألحق(الناتج, 9);
    } وإلا لو (الرمز <= 279) {
        ألحق(الناتج, الرمز - 256);
        ألحق(الناتج, 7);
    } وإلا {
        ألحق(الناتج, 0xC0 + (الرمز - 280));
        ألحق(الناتج, 8);
    };
    أرجع الناتج;
}

