عرف هاش_ثلاثي_ديفليت(المصدر: &متجه غ8, الموضع: غير_موقع): غير_موقع {
    دع أ: غير_موقع = (*المصدر)[الموضع] مثل غير_موقع;
    دع ب: غير_موقع = (*المصدر)[الموضع + 1] مثل غير_موقع;
    دع ج: غير_موقع = (*المصدر)[الموضع + 2] مثل غير_موقع;
    أرجع (((أ * 251) + ب) * 251 + ج) & 4095;
}

عرف سجل_موضع_ديفليت(
    المصدر: &متجه غ8,
    الموضع: غير_موقع,
    الرؤوس: &متغير متجه عدد,
    السابق: &متغير متجه عدد
): فراغ {
    دع العدد: غير_موقع = الطول(*المصدر) مثل غير_موقع;
    لو (الموضع + 2 >= العدد) { أرجع; };
    دع ه: غير_موقع = هاش_ثلاثي_ديفليت(المصدر, الموضع);
    (*السابق)[الموضع] := (*الرؤوس)[ه];
