عرف ابحث_عن_تطابق_ديفليت(
    المصدر: &متجه غ8,
    الموضع: غير_موقع,
    الرؤوس: &متجه عدد,
    السابق: &متجه عدد
): تطابق_ديفليت {
    دع العدد: غير_موقع = الطول(*المصدر) مثل غير_موقع;
    دع لا_شيء: تطابق_ديفليت = { الطول: 0, المسافة: 0 };
    لو (الموضع + 2 >= العدد) { أرجع لا_شيء; };
    دع ه: غير_موقع = هاش_ثلاثي_ديفليت(المصدر, الموضع);
    دع المرشح: متغير عدد = (*الرؤوس)[ه];
    دع أفضل_طول: متغير غير_موقع = 0;
    دع أفضل_مسافة: متغير غير_موقع = 0;
    دع المحاولات: متغير غير_موقع = 0;
    دع أقصى_طول: متغير غير_موقع = العدد - الموضع;
    لو (أقصى_طول > 258) { أقصى_طول := 258; };

    بينما ((المرشح >= 0) && (المحاولات < 64)) {
        دع م: غير_موقع = المرشح مثل غير_موقع;
        لو (م >= الموضع) { أرجع لا_شيء; };
        دع المسافة: غير_موقع = الموضع - م;
        لو (المسافة > 32768) {
            المرشح := -1;
        } وإلا {
            دع طول_الحالي: متغير غير_موقع = 0;
            بينما ((طول_الحالي < أقصى_طول)
                && ((*المصدر)[م + طول_الحالي] == (*المصدر)[الموضع + طول_الحالي])) {
                طول_الحالي := طول_الحالي + 1;
            }
            لو ((طول_الحالي >= 3) && (طول_الحالي > أفضل_طول)) {
                أفضل_طول := طول_الحالي;
                أفضل_مسافة := المسافة;
                لو (أفضل_طول == 258) {
                    دع الناتج: تطابق_ديفليت = { الطول: أفضل_طول, المسافة: أفضل_مسافة };
                    أرجع الناتج;
                };
            };
            المرشح := (*السابق)[م];
            المحاولات := المحاولات + 1;
        };
    }
    دع الناتج: تطابق_ديفليت = { الطول: أفضل_طول, المسافة: أفضل_مسافة };
    أرجع الناتج;
}

عرف اكتب_طول_ومسافة_ديفليت(
    الكاتب: &متغير كاتب_بتات_ديفليت,
    التطابق: &تطابق_ديفليت,
    الجداول: &جداول_ديفليت
): فراغ {
    دع فهرس_الطول: متغير غير_موقع = 0;
