عام عرف جزئ_تشفير(الخوارزمية: خوارزمية_تجزئة, البيانات: &متجه غ8): متجه غ8 {
    طابق الخوارزمية مع
    | خوارزمية_تجزئة.تجزئة_شا1 -> { أرجع شا1(البيانات); }
    | خوارزمية_تجزئة.تجزئة_شا256 -> { أرجع شا256(البيانات); }
    | خوارزمية_تجزئة.تجزئة_شا384 -> { أرجع شا384(البيانات); }
    | خوارزمية_تجزئة.تجزئة_شا512 -> { أرجع شا512(البيانات); };
}

عام عرف حجم_ملخص_تجزئة(الخوارزمية: خوارزمية_تجزئة): غير_موقع {
    طابق الخوارزمية مع
    | خوارزمية_تجزئة.تجزئة_شا1 -> { أرجع 20; }
    | خوارزمية_تجزئة.تجزئة_شا256 -> { أرجع 32; }
    | خوارزمية_تجزئة.تجزئة_شا384 -> { أرجع 48; }
    | خوارزمية_تجزئة.تجزئة_شا512 -> { أرجع 64; };
}

عام عرف حجم_كتلة_تجزئة(الخوارزمية: خوارزمية_تجزئة): غير_موقع {
    طابق الخوارزمية مع
    | خوارزمية_تجزئة.تجزئة_شا1 -> { أرجع 64; }
    | خوارزمية_تجزئة.تجزئة_شا256 -> { أرجع 64; }
    | خوارزمية_تجزئة.تجزئة_شا384 -> { أرجع 128; }
    | خوارزمية_تجزئة.تجزئة_شا512 -> { أرجع 128; };
}

عام عرف هماك_تشفير(الخوارزمية: خوارزمية_تجزئة, المفتاح: &متجه غ8, الرسالة: &متجه غ8): متجه غ8 {
    دع الكتلة: غير_موقع = حجم_كتلة_تجزئة(الخوارزمية);
    دع ك: متغير متجه غ8 = [];
    لو ((الطول(*المفتاح) مثل غير_موقع) > الكتلة) {
        ك := جزئ_تشفير(الخوارزمية, المفتاح);
    } وإلا {
        ألحق_بايتات_تشفير(&متغير ك, المفتاح);
    };
    بينما ((الطول(ك) مثل غير_موقع) < الكتلة) { ألحق(ك, 0 مثل غ8); }

    دع داخلي: متغير متجه غ8 = [];
    دع وسادة_خارجية: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الكتلة) {
        ألحق(داخلي, ((ك[ف] مثل غير_موقع) ^ 0x36) مثل غ8);
        ألحق(وسادة_خارجية, ((ك[ف] مثل غير_موقع) ^ 0x5C) مثل غ8);
        ف := ف + 1;
    }
    ألحق_بايتات_تشفير(&متغير داخلي, الرسالة);
    دع ملخص_داخلي: متجه غ8 = جزئ_تشفير(الخوارزمية, &داخلي);
    ألحق_بايتات_تشفير(&متغير وسادة_خارجية, &ملخص_داخلي);
    امسح_بايتات_تشفير(&متغير ك);
    امسح_بايتات_تشفير(&متغير داخلي);
    أرجع جزئ_تشفير(الخوارزمية, &وسادة_خارجية);
}

// HKDF-Extract. An empty salt is a string of HashLen zero bytes (RFC 5869 2.2).
عام عرف هكدف_استخرج_تشفير(الخوارزمية: خوارزمية_تجزئة, الملح: &متجه غ8, المادة: &متجه غ8): متجه غ8 {
    لو ((الطول(*الملح) مثل غير_موقع) == 0) {
        دع أصفار: متجه غ8 = أصفار_تشفير(حجم_ملخص_تجزئة(الخوارزمية));
        أرجع هماك_تشفير(الخوارزمية, &أصفار, المادة);
    };
    أرجع هماك_تشفير(الخوارزمية, الملح, المادة);
}

// HKDF-Expand; none when the length exceeds 255 * HashLen.
عام عرف هكدف_وسع_تشفير(
    الخوارزمية: خوارزمية_تجزئة,
    المفتاح_الكاذب: &متجه غ8,
    المعلومات: &متجه غ8,
    الطول_المطلوب: غير_موقع
): اختيار متجه غ8 {
    لو (الطول_المطلوب > 255 * حجم_ملخص_تجزئة(الخوارزمية)) { أرجع اختيار.لا_شيء(); };
    دع الناتج: متغير متجه غ8 = [];
    دع السابق: متغير متجه غ8 = [];
    دع العداد: متغير غير_موقع = 1;
    بينما ((الطول(الناتج) مثل غير_موقع) < الطول_المطلوب) {
        دع الرسالة: متغير متجه غ8 = [];
        ألحق_بايتات_تشفير(&متغير الرسالة, &السابق);
        ألحق_بايتات_تشفير(&متغير الرسالة, المعلومات);
        ألحق(الرسالة, العداد مثل غ8);
        السابق := هماك_تشفير(الخوارزمية, المفتاح_الكاذب, &الرسالة);
        دع ف: متغير غير_موقع = 0;
        بينما ((ف < (الطول(السابق) مثل غير_موقع)) && ((الطول(الناتج) مثل غير_موقع) < الطول_المطلوب)) {
            ألحق(الناتج, السابق[ف]);
            ف := ف + 1;
        }
        العداد := العداد + 1;
    }
    أرجع اختيار.بعض(الناتج);
}

عام مرادف hash_algorithm = خوارزمية_تجزئة;
عام مرادف hash_digest = جزئ_تشفير;
عام مرادف hash_digest_size = حجم_ملخص_تجزئة;
عام مرادف hmac = هماك_تشفير;
عام مرادف hkdf_extract = هكدف_استخرج_تشفير;
عام مرادف hkdf_expand = هكدف_وسع_تشفير;

// PBKDF2 (RFC 8018 5.2) with HMAC over the selected digest. Callers own the
// password/salt policy; zero iterations and oversized output are rejected.
عام عرف ببدف2_تشفير(
    الخوارزمية: خوارزمية_تجزئة,
    كلمة_المرور: &متجه غ8,
    الملح: &متجه غ8,
    التكرارات: غير_موقع,
    الطول_المطلوب: غير_موقع
): اختيار متجه غ8 {
    لو (التكرارات == 0) { أرجع اختيار.لا_شيء(); };
    دع الملخص: غير_موقع = حجم_ملخص_تجزئة(الخوارزمية);
    لو (الطول_المطلوب > 4294967295 * الملخص) { أرجع اختيار.لا_شيء(); };
    دع الناتج: متغير متجه غ8 = [];
    دع رقم_الكتلة: متغير غير_موقع = 1;
    بينما ((الطول(الناتج) مثل غير_موقع) < الطول_المطلوب) {
        دع الرسالة: متغير متجه غ8 = [];
        ألحق_بايتات_تشفير(&متغير الرسالة, الملح);
        ألحق_كبير32_تشفير(&متغير الرسالة, رقم_الكتلة);
        دع يو: متغير متجه غ8 = هماك_تشفير(الخوارزمية, كلمة_المرور, &الرسالة);
        دع الكتلة: متغير متجه غ8 = [];
        ألحق_بايتات_تشفير(&متغير الكتلة, &يو);
        دع الجولة: متغير غير_موقع = 1;
        بينما (الجولة < التكرارات) {
            يو := هماك_تشفير(الخوارزمية, كلمة_المرور, &يو);
            دع ف: متغير غير_موقع = 0;
            بينما (ف < الملخص) {
                الكتلة[ف] := الكتلة[ف] ^ يو[ف];
                ف := ف + 1;
            }
            الجولة := الجولة + 1;
        }
        دع م: متغير غير_موقع = 0;
        بينما ((م < الملخص) && ((الطول(الناتج) مثل غير_موقع) < الطول_المطلوب)) {
            ألحق(الناتج, الكتلة[م]);
            م := م + 1;
        }
        رقم_الكتلة := رقم_الكتلة + 1;
    }
    أرجع اختيار.بعض(الناتج);
}

عام مرادف pbkdf2 = ببدف2_تشفير;

// SHA-256 forms of the generic constructions (the previous std.crypto API).
عام عرف هماك_شا256(المفتاح: &متجه غ8, الرسالة: &متجه غ8): متجه غ8 {
    أرجع هماك_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), المفتاح, الرسالة);
}

عام عرف هكدف_شا256_استخرج(الملح: &متجه غ8, مادة_المفتاح: &متجه غ8): متجه غ8 {
    أرجع هكدف_استخرج_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), الملح, مادة_المفتاح);
}

عام عرف هكدف_شا256_وسع(المفتاح_الكاذب: &متجه غ8, المعلومات: &متجه غ8, الطول_المطلوب: غير_موقع): اختيار متجه غ8 {
    أرجع هكدف_وسع_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), المفتاح_الكاذب, المعلومات, الطول_المطلوب);
}

عام عرف هكدف_شا256(الملح: &متجه غ8, مادة_المفتاح: &متجه غ8, المعلومات: &متجه غ8, الطول_المطلوب: غير_موقع): اختيار متجه غ8 {
    دع المفتاح_الكاذب: متجه غ8 = هكدف_شا256_استخرج(الملح, مادة_المفتاح);
    أرجع هكدف_شا256_وسع(&المفتاح_الكاذب, المعلومات, الطول_المطلوب);
}

عام عرف ببدف2_هماك_شا256(
    كلمة_المرور: &متجه غ8,
    الملح: &متجه غ8,
    التكرارات: غير_موقع,
    الطول_المطلوب: غير_موقع
): اختيار متجه غ8 {
    لو (الطول_المطلوب == 0 && التكرارات != 0) {
        دع فارغ: متجه غ8 = [];
        أرجع اختيار.بعض(فارغ);
    };
    أرجع ببدف2_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), كلمة_المرور, الملح, التكرارات, الطول_المطلوب);
}

عام مرادف hmac_sha256 = هماك_شا256;
عام مرادف hkdf_sha256_extract = هكدف_شا256_استخرج;
عام مرادف hkdf_sha256_expand = هكدف_شا256_وسع;
عام مرادف hkdf_sha256 = هكدف_شا256;
عام مرادف pbkdf2_hmac_sha256 = ببدف2_هماك_شا256;

library/std/crypto/ecdsa.sn:
// ECDSA (FIPS 186-5 6.4) and ECDH (SEC 1 3.3.1) on NIST P-256 and P-384, for
// X.509, TLS 1.3 CertificateVerify and the secp256r1/secp384r1 key shares.
// Field and scalar arithmetic use crypto.bignum Montgomery contexts. Public
// keys are SEC 1 uncompressed points and must lie on the curve; signatures
// are the DER Ecdsa-Sig-Value.
// - Verification handles public data only: its double-and-add scalar
//   multiplication is variable time.
// - Signing and key agreement handle secrets: their scalar multiplication
//   uses the complete projective addition law of Renes, Costello and Batina
//   (2016, Algorithm 4, a = -3), which has no exceptional cases, in a fixed
//   double-and-add-always ladder over every bit of the field size with masked
//   selection. Signing nonces are deterministic (RFC 6979 3.2, HMAC with the
//   curve's hash); the nonce inverse uses the fixed-window exponentiation.

استورد crypto.bignum;
استورد crypto.digest;
استورد crypto.words;
استورد encoding.der;
استورد encoding.hex;

عام نوع منحنى_إهليلجي =
    | منحنى_بي256
    | منحنى_بي384
;

نوع معاملات_منحنى_إهليلجي = {
    الحقل: سياق_مونتغمري,
    الرتبة: سياق_مونتغمري,
    ب_م: متجه غير_موقع,
    س_المولد: متجه غ8,
    ص_المولد: متجه غ8,
    البايتات: غير_موقع
};

نوع نقطة_يعقوبية = {
    س: متجه غير_موقع,
    ص: متجه غير_موقع,
    ع: متجه غير_موقع,
    لانهائية: منطقي
};

عرف سداسي_منحنى(النص: نص): متجه غ8 {
    طابق فك_سداسي(&النص) مع
    | نتيجة.نجح(القيمة) -> { أرجع القيمة; }
    | نتيجة.خطأ(_) -> {
        دع فارغ: متجه غ8 = [];
        أرجع فارغ;
    };
}

// Domain parameters from FIPS 186-5 / SEC 2 (a = -3 for both curves).
عرف معاملات_منحنى_إهليلجي_محدد(المنحنى: منحنى_إهليلجي): اختيار معاملات_منحنى_إهليلجي {
    دع الأولي: متغير متجه غ8 = [];
    دع ب: متغير متجه غ8 = [];
    دع الرتبة: متغير متجه غ8 = [];
    دع س: متغير متجه غ8 = [];
    دع ص: متغير متجه غ8 = [];
    دع البايتات: متغير غير_موقع = 0;
    طابق المنحنى مع
    | منحنى_إهليلجي.منحنى_بي256 -> {
        الأولي := سداسي_منحنى(«ffffffff00000001000000000000000000000000ffffffffffffffffffffffff»);
        ب := سداسي_منحنى(«5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b»);
        الرتبة := سداسي_منحنى(«ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551»);
        س := سداسي_منحنى(«6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296»);
        ص := سداسي_منحنى(«4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5»);
        البايتات := 32;
    }
    | منحنى_إهليلجي.منحنى_بي384 -> {
        الأولي := سداسي_منحنى(«fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeffffffff0000000000000000ffffffff»);
        ب := سداسي_منحنى(«b3312fa7e23ee7e4988e056be3f82d19181d9c6efe8141120314088f5013875ac656398d8a2ed19d2a85c8edd3ec2aef»);
        الرتبة := سداسي_منحنى(«ffffffffffffffffffffffffffffffffffffffffffffffffc7634d81f4372ddf581a0db248b0a77aecec196accc52973»);
        س := سداسي_منحنى(«aa87ca22be8b05378eb1c71ef320ad746e1d3b628ba79b9859f741e082542a385502f25dbf55296c3a545e3872760ab7»);
        ص := سداسي_منحنى(«3617de4a96262c6f5d9e98bf9292dc29f8f41dbd289a147ce9da3113b5f0b8c00a60b1ce1d7e819d7a431d7c90ea0e5f»);
        البايتات := 48;
    };
    طابق أنشئ_سياق_مونتغمري(&الأولي) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الحقل) -> {
        طابق أنشئ_سياق_مونتغمري(&الرتبة) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(سياق_الرتبة) -> {
            طابق عدد_كبير_من_بايتات(&ب, الحقل.العدد) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(ب_عادي) -> {
                دع ب_م: متجه غير_موقع = إلى_مونتغمري(&ب_عادي, &الحقل);
                دع المعاملات: معاملات_منحنى_إهليلجي = {
                    الحقل: الحقل,
                    الرتبة: سياق_الرتبة,
                    ب_م: ب_م,
                    س_المولد: س,
                    ص_المولد: ص,
                    البايتات: البايتات
                };
                أرجع اختيار.بعض(المعاملات);
            };
        };
    };
}

عرف ضرب_حقل(أ: &متجه غير_موقع, ب: &متجه غير_موقع, ح: &معاملات_منحنى_إهليلجي): متجه غير_موقع {
    أرجع اضرب_مونتغمري(أ, ب, &(*ح).الحقل);
}

عرف جمع_حقل(أ: &متجه غير_موقع, ب: &متجه غير_موقع, ح: &معاملات_منحنى_إهليلجي): متجه غير_موقع {
    أرجع اجمع_معياري_كبير(أ, ب, &(*ح).الحقل);
}

عرف طرح_حقل(أ: &متجه غير_موقع, ب: &متجه غير_موقع, ح: &معاملات_منحنى_إهليلجي): متجه غير_موقع {
    أرجع اطرح_معياري_كبير(أ, ب, &(*ح).الحقل);
}

عرف نقطة_لانهائية(ح: &معاملات_منحنى_إهليلجي): نقطة_يعقوبية {
    دع العدد: غير_موقع = (*ح).الحقل.العدد;
    دع النقطة: نقطة_يعقوبية = {
        س: أطراف_صفرية_كبير(العدد),
        ص: أطراف_صفرية_كبير(العدد),
        ع: أطراف_صفرية_كبير(العدد),
        لانهائية: صواب
    };
    أرجع النقطة;
}

// dbl-2001-b (Bernstein-Lange EFD) for a = -3.
عرف ضاعف_نقطة_إهليلجية(ن: &نقطة_يعقوبية, ح: &معاملات_منحنى_إهليلجي): نقطة_يعقوبية {
    لو ((*ن).لانهائية || هل_صفر_كبير(&(*ن).ص)) { أرجع نقطة_لانهائية(ح); };
    دع دلتا: متجه غير_موقع = ضرب_حقل(&(*ن).ع, &(*ن).ع, ح);
    دع جاما: متجه غير_موقع = ضرب_حقل(&(*ن).ص, &(*ن).ص, ح);
    دع بيتا: متجه غير_موقع = ضرب_حقل(&(*ن).س, &جاما, ح);
    دع ت1: متجه غير_موقع = طرح_حقل(&(*ن).س, &دلتا, ح);
    دع ت2: متجه غير_موقع = جمع_حقل(&(*ن).س, &دلتا, ح);
    دع ت3: متجه غير_موقع = ضرب_حقل(&ت1, &ت2, ح);
    دع ت3_2: متجه غير_موقع = جمع_حقل(&ت3, &ت3, ح);
    دع ألفا: متجه غير_موقع = جمع_حقل(&ت3_2, &ت3, ح);
    دع بيتا2: متجه غير_موقع = جمع_حقل(&بيتا, &بيتا, ح);
    دع بيتا4: متجه غير_موقع = جمع_حقل(&بيتا2, &بيتا2, ح);
    دع بيتا8: متجه غير_موقع = جمع_حقل(&بيتا4, &بيتا4, ح);
    دع ألفا2: متجه غير_موقع = ضرب_حقل(&ألفا, &ألفا, ح);
    دع س3: متجه غير_موقع = طرح_حقل(&ألفا2, &بيتا8, ح);
    دع ص_ع: متجه غير_موقع = جمع_حقل(&(*ن).ص, &(*ن).ع, ح);
    دع ص_ع2: متجه غير_موقع = ضرب_حقل(&ص_ع, &ص_ع, ح);
    دع ع3_أ: متجه غير_موقع = طرح_حقل(&ص_ع2, &جاما, ح);
    دع ع3: متجه غير_موقع = طرح_حقل(&ع3_أ, &دلتا, ح);
    دع جاما2: متجه غير_موقع = ضرب_حقل(&جاما, &جاما, ح);
    دع جاما2_2: متجه غير_موقع = جمع_حقل(&جاما2, &جاما2, ح);
    دع جاما2_4: متجه غير_موقع = جمع_حقل(&جاما2_2, &جاما2_2, ح);
    دع جاما2_8: متجه غير_موقع = جمع_حقل(&جاما2_4, &جاما2_4, ح);
    دع فرق_بيتا: متجه غير_موقع = طرح_حقل(&بيتا4, &س3, ح);
    دع ص3_أ: متجه غير_موقع = ضرب_حقل(&ألفا, &فرق_بيتا, ح);
    دع ص3: متجه غير_موقع = طرح_حقل(&ص3_أ, &جاما2_8, ح);
    دع لانهائية: منطقي = هل_صفر_كبير(&ع3);
    دع الناتج: نقطة_يعقوبية = { س: س3, ص: ص3, ع: ع3, لانهائية: لانهائية };
    أرجع الناتج;
}

// Independent copies: points own their coordinate limbs.
عرف انسخ_أطراف_إهليلجية(القيمة: &متجه غير_موقع): متجه غير_موقع {
    دع الناتج: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*القيمة) مثل غير_موقع)) {
        ألحق(الناتج, (*القيمة)[ف]);
        ف := ف + 1;
    }
    أرجع الناتج;
}

عرف انسخ_نقطة_يعقوبية(النقطة: &نقطة_يعقوبية): نقطة_يعقوبية {
    دع الناتج: نقطة_يعقوبية = {
        س: انسخ_أطراف_إهليلجية(&(*النقطة).س),
        ص: انسخ_أطراف_إهليلجية(&(*النقطة).ص),
        ع: انسخ_أطراف_إهليلجية(&(*النقطة).ع),
        لانهائية: (*النقطة).لانهائية
    };
    أرجع الناتج;
}

// add-2007-bl (Bernstein-Lange EFD), with the doubling and inverse cases.
عرف اجمع_نقطتين_إهليلجيتين(أ: &نقطة_يعقوبية, ب: &نقطة_يعقوبية, ح: &معاملات_منحنى_إهليلجي): نقطة_يعقوبية {
    لو ((*أ).لانهائية) { أرجع انسخ_نقطة_يعقوبية(ب); };
    لو ((*ب).لانهائية) { أرجع انسخ_نقطة_يعقوبية(أ); };
    دع ع1ع1: متجه غير_موقع = ضرب_حقل(&(*أ).ع, &(*أ).ع, ح);
    دع ع2ع2: متجه غير_موقع = ضرب_حقل(&(*ب).ع, &(*ب).ع, ح);
    دع يو1: متجه غير_موقع = ضرب_حقل(&(*أ).س, &ع2ع2, ح);
    دع يو2: متجه غير_موقع = ضرب_حقل(&(*ب).س, &ع1ع1, ح);
    دع ع2_ع2ع2: متجه غير_موقع = ضرب_حقل(&(*ب).ع, &ع2ع2, ح);
    دع س1: متجه غير_موقع = ضرب_حقل(&(*أ).ص, &ع2_ع2ع2, ح);
    دع ع1_ع1ع1: متجه غير_موقع = ضرب_حقل(&(*أ).ع, &ع1ع1, ح);
    دع س2: متجه غير_موقع = ضرب_حقل(&(*ب).ص, &ع1_ع1ع1, ح);
    دع هاء: متجه غير_موقع = طرح_حقل(&يو2, &يو1, ح);
    دع ر_أ: متجه غير_موقع = طرح_حقل(&س2, &س1, ح);
    لو (هل_صفر_كبير(&هاء)) {
        لو (هل_صفر_كبير(&ر_أ)) { أرجع ضاعف_نقطة_إهليلجية(أ, ح); };
        أرجع نقطة_لانهائية(ح);
    };
    دع هاء2: متجه غير_موقع = جمع_حقل(&هاء, &هاء, ح);
    دع مربع_الفرق: متجه غير_موقع = ضرب_حقل(&هاء2, &هاء2, ح);
    دع جي: متجه غير_موقع = ضرب_حقل(&هاء, &مربع_الفرق, ح);
    دع ر: متجه غير_موقع = جمع_حقل(&ر_أ, &ر_أ, ح);
    دع في: متجه غير_موقع = ضرب_حقل(&يو1, &مربع_الفرق, ح);
    دع ر2: متجه غير_موقع = ضرب_حقل(&ر, &ر, ح);
    دع س3_أ: متجه غير_موقع = طرح_حقل(&ر2, &جي, ح);
    دع في2: متجه غير_موقع = جمع_حقل(&في, &في, ح);
    دع س3: متجه غير_موقع = طرح_حقل(&س3_أ, &في2, ح);
    دع في_س3: متجه غير_موقع = طرح_حقل(&في, &س3, ح);
    دع ص3_أ: متجه غير_موقع = ضرب_حقل(&ر, &في_س3, ح);
    دع س1_جي: متجه غير_موقع = ضرب_حقل(&س1, &جي, ح);
    دع س1_جي2: متجه غير_موقع = جمع_حقل(&س1_جي, &س1_جي, ح);
    دع ص3: متجه غير_موقع = طرح_حقل(&ص3_أ, &س1_جي2, ح);
    دع ع1_ع2: متجه غير_موقع = جمع_حقل(&(*أ).ع, &(*ب).ع, ح);
    دع ع1_ع2_2: متجه غير_موقع = ضرب_حقل(&ع1_ع2, &ع1_ع2, ح);
    دع ع3_أ: متجه غير_موقع = طرح_حقل(&ع1_ع2_2, &ع1ع1, ح);
    دع ع3_ب: متجه غير_موقع = طرح_حقل(&ع3_أ, &ع2ع2, ح);
    دع ع3: متجه غير_موقع = ضرب_حقل(&ع3_ب, &هاء, ح);
    دع لانهائية: منطقي = هل_صفر_كبير(&ع3);
    دع الناتج: نقطة_يعقوبية = { س: س3, ص: ص3, ع: ع3, لانهائية: لانهائية };
    أرجع الناتج;
}

// k * P for a public scalar k in normal form.
عرف اضرب_نقطة_إهليلجية(العددي: &متجه غير_موقع, النقطة: &نقطة_يعقوبية, ح: &معاملات_منحنى_إهليلجي): نقطة_يعقوبية {
    دع الناتج: متغير نقطة_يعقوبية = نقطة_لانهائية(ح);
    دع البتات: غير_موقع = طول_بتات_كبير(العددي);
    دع ف: متغير غير_موقع = البتات;
    بينما (ف > 0) {
        ف := ف - 1;
        الناتج := ضاعف_نقطة_إهليلجية(&الناتج, ح);
        لو (بت_كبير(العددي, ف) == 1) {
            الناتج := اجمع_نقطتين_إهليلجيتين(&الناتج, النقطة, ح);
        };
    }
    أرجع الناتج;
}

// An affine point (normal-form coordinates) as a Jacobian point, if it
// satisfies y^2 = x^3 - 3x + b with both coordinates below p.
عرف نقطة_من_إحداثيات(س_بايتات: &متجه غ8, ص_بايتات: &متجه غ8, ح: &معاملات_منحنى_إهليلجي): اختيار نقطة_يعقوبية {
    دع العدد: غير_موقع = (*ح).الحقل.العدد;
    طابق عدد_كبير_من_بايتات(س_بايتات, العدد) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(س) -> {
        طابق عدد_كبير_من_بايتات(ص_بايتات, العدد) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(ص) -> {
            لو (قارن_كبير(&س, &(*ح).الحقل.المعامل) >= 0 || قارن_كبير(&ص, &(*ح).الحقل.المعامل) >= 0) {
                أرجع اختيار.لا_شيء();
            };
            دع س_م: متجه غير_موقع = إلى_مونتغمري(&س, &(*ح).الحقل);
            دع ص_م: متجه غير_موقع = إلى_مونتغمري(&ص, &(*ح).الحقل);
            دع ص2: متجه غير_موقع = ضرب_حقل(&ص_م, &ص_م, ح);
            دع س2: متجه غير_موقع = ضرب_حقل(&س_م, &س_م, ح);
            دع س3: متجه غير_موقع = ضرب_حقل(&س2, &س_م, ح);
            دع س_2: متجه غير_موقع = جمع_حقل(&س_م, &س_م, ح);
            دع س_3: متجه غير_موقع = جمع_حقل(&س_2, &س_م, ح);
            دع الأيمن_أ: متجه غير_موقع = طرح_حقل(&س3, &س_3, ح);
            دع الأيمن: متجه غير_موقع = جمع_حقل(&الأيمن_أ, &(*ح).ب_م, ح);
            لو (قارن_كبير(&ص2, &الأيمن) != 0) { أرجع اختيار.لا_شيء(); };
            دع واحد: متغير متجه غير_موقع = أطراف_صفرية_كبير(العدد);
            واحد[0] := 1;
            دع النقطة: نقطة_يعقوبية = {
                س: س_م,
                ص: ص_م,
                ع: إلى_مونتغمري(&واحد, &(*ح).الحقل),
                لانهائية: خطأ
            };
            أرجع اختيار.بعض(النقطة);
        };
    };
}

// The affine x-coordinate in normal form; none for the point at infinity.
عرف إحداثي_س_أفيني(النقطة: &نقطة_يعقوبية, ح: &معاملات_منحنى_إهليلجي): اختيار متجه غير_موقع {
    لو ((*النقطة).لانهائية) { أرجع اختيار.لا_شيء(); };
    دع ع_عادي: متجه غير_موقع = من_مونتغمري(&(*النقطة).ع, &(*ح).الحقل);
    دع الأس: متجه غ8 = معامل_ناقص_كبير(&(*ح).الحقل, 2, (*ح).البايتات);
    دع معكوس_ع: متجه غير_موقع = أس_معياري_كبير(&ع_عادي, &الأس, &(*ح).الحقل);
    دع معكوس_ع_م: متجه غير_موقع = إلى_مونتغمري(&معكوس_ع, &(*ح).الحقل);
    دع معكوس_ع2: متجه غير_موقع = ضرب_حقل(&معكوس_ع_م, &معكوس_ع_م, ح);
    دع س_م: متجه غير_موقع = ضرب_حقل(&(*النقطة).س, &معكوس_ع2, ح);
    أرجع اختيار.بعض(من_مونتغمري(&س_م, &(*ح).الحقل));
}

عرف حجم_بايتات_منحنى(المنحنى: منحنى_إهليلجي): غير_موقع {
    طابق المنحنى مع
    | منحنى_إهليلجي.منحنى_بي256 -> { أرجع 32; }
    | منحنى_إهليلجي.منحنى_بي384 -> { أرجع 48; };
}

// Verifies a DER Ecdsa-Sig-Value over a message digest with a SEC 1
// uncompressed public key (0x04 || X || Y).
عام عرف تحقق_إي_سي_دي_إس_إيه(
    المنحنى: منحنى_إهليلجي,
    المفتاح_العام: &متجه غ8,
    الملخص: &متجه غ8,
    التوقيع: &متجه غ8
): منطقي {
    دع البايتات: غير_موقع = حجم_بايتات_منحنى(المنحنى);
    لو ((الطول(*المفتاح_العام) مثل غير_موقع) != 2 * البايتات + 1 || (*المفتاح_العام)[0] != 0x04) { أرجع خطأ; };
    دع ر_بايتات: متجه غ8;
    دع س_بايتات: متجه غ8;
    طابق اقرأ_جذر_دي_إي_آر(التوقيع) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(الجذر) -> {
        طابق أبناء_بوسم_دي_إي_آر(التوقيع, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(الأبناء) -> {
            لو ((الطول(الأبناء) مثل غير_موقع) != 2) { أرجع خطأ; };
            طابق عدد_صحيح_موجب_دي_إي_آر(التوقيع, &الأبناء[0]) مع
            | اختيار.لا_شيء -> { أرجع خطأ; }
            | اختيار.بعض(القيمة) -> { ر_بايتات := القيمة; };
            طابق عدد_صحيح_موجب_دي_إي_آر(التوقيع, &الأبناء[1]) مع
            | اختيار.لا_شيء -> { أرجع خطأ; }
            | اختيار.بعض(القيمة) -> { س_بايتات := القيمة; };
        };
    };
    طابق معاملات_منحنى_إهليلجي_محدد(المنحنى) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(ح) -> {
        دع ن: &سياق_مونتغمري = &ح.الرتبة;
        دع العدد: غير_موقع = (*ن).العدد;
        دع ر: متجه غير_موقع;
        دع س: متجه غير_موقع;
        طابق عدد_كبير_من_بايتات(&ر_بايتات, العدد) مع
        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(القيمة) -> { ر := القيمة; };
        طابق عدد_كبير_من_بايتات(&س_بايتات, العدد) مع
        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(القيمة) -> { س := القيمة; };
        لو (هل_صفر_كبير(&ر) || هل_صفر_كبير(&س)) { أرجع خطأ; };
        لو (قارن_كبير(&ر, &(*ن).المعامل) >= 0 || قارن_كبير(&س, &(*ن).المعامل) >= 0) { أرجع خطأ; };

        // e: the leftmost bits of the digest, reduced modulo n.
        دع طول_الملخص: متغير غير_موقع = الطول(*الملخص) مثل غير_موقع;
        لو (طول_الملخص > البايتات) { طول_الملخص := البايتات; };
        دع الملخص_المقطوع: متجه غ8 = شريحة_بايتات_تشفير(الملخص, 0, طول_الملخص);
        دع قيمة_الملخص: متجه غير_موقع;
        طابق عدد_كبير_من_بايتات(&الملخص_المقطوع, العدد) مع
        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(القيمة) -> { قيمة_الملخص := اختزل_أقل_من_ضعف_كبير(&القيمة, ن); };

        // w = s^-1 mod n (Fermat; n is prime), u1 = e w, u2 = r w.
        دع أس_ن: متجه غ8 = معامل_ناقص_كبير(ن, 2, البايتات);
        دع دبليو: متجه غير_موقع = أس_معياري_كبير(&س, &أس_ن, ن);
        دع دبليو_م: متجه غير_موقع = إلى_مونتغمري(&دبليو, ن);
        دع يو1: متجه غير_موقع = اضرب_مونتغمري(&دبليو_م, &قيمة_الملخص, ن);
        دع يو2: متجه غير_موقع = اضرب_مونتغمري(&دبليو_م, &ر, ن);

        دع س_ق: متجه غ8 = شريحة_بايتات_تشفير(المفتاح_العام, 1, البايتات);
        دع ص_ق: متجه غ8 = شريحة_بايتات_تشفير(المفتاح_العام, 1 + البايتات, البايتات);
        طابق نقطة_من_إحداثيات(&س_ق, &ص_ق, &ح) مع
        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(كيو) -> {
            طابق نقطة_من_إحداثيات(&ح.س_المولد, &ح.ص_المولد, &ح) مع
            | اختيار.لا_شيء -> { أرجع خطأ; }
            | اختيار.بعض(جي) -> {
                دع أ: نقطة_يعقوبية = اضرب_نقطة_إهليلجية(&يو1, &جي, &ح);
                دع ب: نقطة_يعقوبية = اضرب_نقطة_إهليلجية(&يو2, &كيو, &ح);
                دع المجموع: نقطة_يعقوبية = اجمع_نقطتين_إهليلجيتين(&أ, &ب, &ح);
                طابق إحداثي_س_أفيني(&المجموع, &ح) مع
                | اختيار.لا_شيء -> { أرجع خطأ; }
                | اختيار.بعض(إكس) -> {
                    // x < p < 2n for both curves, so one conditional subtraction reduces it.
                    دع في: متجه غير_موقع = اختزل_أقل_من_ضعف_كبير(&إكس, ن);
                    أرجع قارن_كبير(&في, &ر) == 0;
                };
            };
        };
    };
}

// ---- Constant-time arithmetic for secret scalars -------------------------

نوع نقطة_إسقاطية = {
    س: متجه غير_موقع,
    ص: متجه غير_موقع,
    ع: متجه غير_موقع
};

// The complete addition law (RCB 2016 Algorithm 4); also valid for doubling
// and for the identity (0 : 1 : 0). All coordinates are in Montgomery form.
عرف اجمع_إسقاطي_كامل(أ: &نقطة_إسقاطية, ب: &نقطة_إسقاطية, ح: &معاملات_منحنى_إهليلجي): نقطة_إسقاطية {
    دع ت0: متغير متجه غير_موقع = ضرب_حقل(&(*أ).س, &(*ب).س, ح);
    دع ت1: متغير متجه غير_موقع = ضرب_حقل(&(*أ).ص, &(*ب).ص, ح);
    دع ت2: متغير متجه غير_موقع = ضرب_حقل(&(*أ).ع, &(*ب).ع, ح);
    دع ت3: متغير متجه غير_موقع = جمع_حقل(&(*أ).س, &(*أ).ص, ح);
    دع ت4: متغير متجه غير_موقع = جمع_حقل(&(*ب).س, &(*ب).ص, ح);
    ت3 := ضرب_حقل(&ت3, &ت4, ح);
    ت4 := جمع_حقل(&ت0, &ت1, ح);
    ت3 := طرح_حقل(&ت3, &ت4, ح);
    ت4 := جمع_حقل(&(*أ).ص, &(*أ).ع, ح);
    دع س3: متغير متجه غير_موقع = جمع_حقل(&(*ب).ص, &(*ب).ع, ح);
    ت4 := ضرب_حقل(&ت4, &س3, ح);
    س3 := جمع_حقل(&ت1, &ت2, ح);
    ت4 := طرح_حقل(&ت4, &س3, ح);
    س3 := جمع_حقل(&(*أ).س, &(*أ).ع, ح);
    دع ص3: متغير متجه غير_موقع = جمع_حقل(&(*ب).س, &(*ب).ع, ح);
    س3 := ضرب_حقل(&س3, &ص3, ح);
    ص3 := جمع_حقل(&ت0, &ت2, ح);
    ص3 := طرح_حقل(&س3, &ص3, ح);
    دع ع3: متغير متجه غير_موقع = ضرب_حقل(&(*ح).ب_م, &ت2, ح);
    س3 := طرح_حقل(&ص3, &ع3, ح);
    ع3 := جمع_حقل(&س3, &س3, ح);
    س3 := جمع_حقل(&س3, &ع3, ح);
    ع3 := طرح_حقل(&ت1, &س3, ح);
    س3 := جمع_حقل(&ت1, &س3, ح);
    ص3 := ضرب_حقل(&(*ح).ب_م, &ص3, ح);
    ت1 := جمع_حقل(&ت2, &ت2, ح);
    ت2 := جمع_حقل(&ت1, &ت2, ح);
    ص3 := طرح_حقل(&ص3, &ت2, ح);
    ص3 := طرح_حقل(&ص3, &ت0, ح);
    ت1 := جمع_حقل(&ص3, &ص3, ح);
    ص3 := جمع_حقل(&ت1, &ص3, ح);
    ت1 := جمع_حقل(&ت0, &ت0, ح);
    ت0 := جمع_حقل(&ت1, &ت0, ح);
    ت0 := طرح_حقل(&ت0, &ت2, ح);
    ت1 := ضرب_حقل(&ت4, &ص3, ح);
    ت2 := ضرب_حقل(&ت0, &ص3, ح);
    ص3 := ضرب_حقل(&س3, &ع3, ح);
    ص3 := جمع_حقل(&ص3, &ت2, ح);
    س3 := ضرب_حقل(&ت3, &س3, ح);
    س3 := طرح_حقل(&س3, &ت1, ح);
    ع3 := ضرب_حقل(&ت4, &ع3, ح);
    ت1 := ضرب_حقل(&ت3, &ت0, ح);
    ع3 := جمع_حقل(&ع3, &ت1, ح);
    دع الناتج: نقطة_إسقاطية = { س: س3, ص: ص3, ع: ع3 };
    أرجع الناتج;
}

عرف اختر_نقطة_إسقاطية(الشرط: غير_موقع, أ: &نقطة_إسقاطية, ب: &نقطة_إسقاطية, ح: &معاملات_منحنى_إهليلجي): نقطة_إسقاطية {
    دع العدد: غير_موقع = (*ح).الحقل.العدد;
    دع الناتج: نقطة_إسقاطية = {
        س: اختر_أطراف_كبير(الشرط, &(*أ).س, &(*ب).س, العدد),
        ص: اختر_أطراف_كبير(الشرط, &(*أ).ص, &(*ب).ص, العدد),
        ع: اختر_أطراف_كبير(الشرط, &(*أ).ع, &(*ب).ع, العدد)
    };
    أرجع الناتج;
}

// k * P for a secret scalar k (normal form, below 2^(32 * limbs)): a fixed
// number of steps, each one doubling and one addition, with masked selection.
عرف اضرب_بزمن_ثابت_إهليلجي(العددي: &متجه غير_موقع, النقطة: &نقطة_إسقاطية, ح: &معاملات_منحنى_إهليلجي): نقطة_إسقاطية {
    دع العدد: غير_موقع = (*ح).الحقل.العدد;
    دع واحد: متغير متجه غير_موقع = أطراف_صفرية_كبير(العدد);
    واحد[0] := 1;
    دع الناتج: متغير نقطة_إسقاطية = {
        س: أطراف_صفرية_كبير(العدد),
        ص: إلى_مونتغمري(&واحد, &(*ح).الحقل),
        ع: أطراف_صفرية_كبير(العدد)
    };
    دع ف: متغير غير_موقع = 32 * العدد;
    بينما (ف > 0) {
        ف := ف - 1;
        الناتج := اجمع_إسقاطي_كامل(&الناتج, &الناتج, ح);
        دع المجموع: نقطة_إسقاطية = اجمع_إسقاطي_كامل(&الناتج, النقطة, ح);
        الناتج := اختر_نقطة_إسقاطية(بت_كبير(العددي, ف), &المجموع, &الناتج, ح);
    }
    أرجع الناتج;
}

// Affine (x, y) in normal form; none for the identity (Z = 0). The Fermat
// inverse uses the fixed-window exponentiation.
عرف إحداثيات_أفينية_إسقاطية(النقطة: &نقطة_إسقاطية, ح: &معاملات_منحنى_إهليلجي): اختيار متجه متجه غير_موقع {
    دع ع_عادي: متجه غير_موقع = من_مونتغمري(&(*النقطة).ع, &(*ح).الحقل);
    لو (هل_صفر_كبير(&ع_عادي)) { أرجع اختيار.لا_شيء(); };
    دع الأس: متجه غ8 = معامل_ناقص_كبير(&(*ح).الحقل, 2, (*ح).البايتات);
    دع المعكوس: متجه غير_موقع = أس_معياري_كبير(&ع_عادي, &الأس, &(*ح).الحقل);
    دع المعكوس_م: متجه غير_موقع = إلى_مونتغمري(&المعكوس, &(*ح).الحقل);
    دع س_م: متجه غير_موقع = ضرب_حقل(&(*النقطة).س, &المعكوس_م, ح);
    دع ص_م: متجه غير_موقع = ضرب_حقل(&(*النقطة).ص, &المعكوس_م, ح);
    دع الناتج: متجه متجه غير_موقع = [من_مونتغمري(&س_م, &(*ح).الحقل), من_مونتغمري(&ص_م, &(*ح).الحقل)];
    أرجع اختيار.بعض(الناتج);
}

عرف مولد_إسقاطي(ح: &معاملات_منحنى_إهليلجي): اختيار نقطة_إسقاطية {
    طابق نقطة_من_إحداثيات(&(*ح).س_المولد, &(*ح).ص_المولد, ح) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض({ س: س_جي, ص: ص_جي, ع: ع_جي, لانهائية: _ }) -> {
        دع النقطة: نقطة_إسقاطية = { س: س_جي, ص: ص_جي, ع: ع_جي };
        أرجع اختيار.بعض(النقطة);
    };
}

// A private scalar 1 <= d < n from exactly البايتات big-endian bytes.
عرف عددي_خاص_إهليلجي(الخاص: &متجه غ8, ح: &معاملات_منحنى_إهليلجي): اختيار متجه غير_موقع {
    لو ((الطول(*الخاص) مثل غير_موقع) != (*ح).البايتات) { أرجع اختيار.لا_شيء(); };
    طابق عدد_كبير_من_بايتات(الخاص, (*ح).الرتبة.العدد) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(د) -> {
        لو (هل_صفر_كبير(&د) || قارن_كبير(&د, &(*ح).الرتبة.المعامل) >= 0) { أرجع اختيار.لا_شيء(); };
        أرجع اختيار.بعض(د);
    };
}

عرف نقطة_مرمزة_إهليلجية(س: &متجه غير_موقع, ص: &متجه غير_موقع, البايتات: غير_موقع): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [0x04];
    دع س_بايتات: متجه غ8 = بايتات_من_عدد_كبير(س, البايتات);
    دع ص_بايتات: متجه غ8 = بايتات_من_عدد_كبير(ص, البايتات);
    ألحق_بايتات_تشفير(&متغير الناتج, &س_بايتات);
    ألحق_بايتات_تشفير(&متغير الناتج, &ص_بايتات);
    أرجع الناتج;
}

// The SEC 1 uncompressed public key of a private scalar (big-endian bytes of
// the curve size).
عام عرف مفتاح_عام_إي_سي_دي_إس_إيه(المنحنى: منحنى_إهليلجي, الخاص: &متجه غ8): اختيار متجه غ8 {
    طابق معاملات_منحنى_إهليلجي_محدد(المنحنى) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(ح) -> {
        طابق عددي_خاص_إهليلجي(الخاص, &ح) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(د) -> {
            طابق مولد_إسقاطي(&ح) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(جي) -> {
                دع النقطة: نقطة_إسقاطية = اضرب_بزمن_ثابت_إهليلجي(&د, &جي, &ح);
                طابق إحداثيات_أفينية_إسقاطية(&النقطة, &ح) مع
                | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                | اختيار.بعض(الإحداثيات) -> {
                    أرجع اختيار.بعض(نقطة_مرمزة_إهليلجية(&الإحداثيات[0], &الإحداثيات[1], ح.البايتات));
                };
            };
        };
    };
}

// ECDH (SEC 1 3.3.1): the x-coordinate of d * Q for a peer public key Q that
// must lie on the curve; none for an invalid key or the identity.
عام عرف اتفاق_إي_سي_دي_إتش(المنحنى: منحنى_إهليلجي, الخاص: &متجه غ8, العام_للنظير: &متجه غ8): اختيار متجه غ8 {
    طابق معاملات_منحنى_إهليلجي_محدد(المنحنى) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(ح) -> {
        دع البايتات: غير_موقع = ح.البايتات;
        لو ((الطول(*العام_للنظير) مثل غير_موقع) != 2 * البايتات + 1 || (*العام_للنظير)[0] != 0x04) {
            أرجع اختيار.لا_شيء();
        };
        طابق عددي_خاص_إهليلجي(الخاص, &ح) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(د) -> {
            دع س_ق: متجه غ8 = شريحة_بايتات_تشفير(العام_للنظير, 1, البايتات);
            دع ص_ق: متجه غ8 = شريحة_بايتات_تشفير(العام_للنظير, 1 + البايتات, البايتات);
            طابق نقطة_من_إحداثيات(&س_ق, &ص_ق, &ح) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض({ س: س_كيو, ص: ص_كيو, ع: ع_كيو, لانهائية: _ }) -> {
                دع النظير: نقطة_إسقاطية = { س: س_كيو, ص: ص_كيو, ع: ع_كيو };
                دع المشترك: نقطة_إسقاطية = اضرب_بزمن_ثابت_إهليلجي(&د, &النظير, &ح);
                طابق إحداثيات_أفينية_إسقاطية(&المشترك, &ح) مع
                | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                | اختيار.بعض(الإحداثيات) -> {
                    أرجع اختيار.بعض(بايتات_من_عدد_كبير(&الإحداثيات[0], البايتات));
                };
            };
        };
    };
}

// A DER INTEGER for a non-negative big-endian value.
عرف عدد_صحيح_دي_إي_آر_إهليلجي(القيمة: &متجه غ8): متجه غ8 {
    دع البداية: متغير غير_موقع = 0;
    دع الحجم: غير_موقع = الطول(*القيمة) مثل غير_موقع;
    بينما (البداية + 1 < الحجم && (*القيمة)[البداية] == 0) { البداية := البداية + 1; }
    دع المحتوى: متغير متجه غ8 = [];
    لو (البداية < الحجم && ((*القيمة)[البداية] مثل غير_موقع) >= 0x80) { ألحق(المحتوى, 0 مثل غ8); };
    دع الجزء: متجه غ8 = شريحة_بايتات_تشفير(القيمة, البداية, الحجم - البداية);
    ألحق_بايتات_تشفير(&متغير المحتوى, &الجزء);
    أرجع رمز_عنصر_دي_إي_آر(وسم_عدد_صحيح_دي_إي_آر(), &المحتوى);
}

// bits2octets (RFC 6979 2.3.4) for a curve whose order has a whole number of
// bytes: the leftmost البايتات digest bytes reduced modulo n.
عرف ملخص_مختزل_إهليلجي(الملخص: &متجه غ8, ح: &معاملات_منحنى_إهليلجي): اختيار متجه غير_موقع {
    دع البايتات: غير_موقع = (*ح).البايتات;
    دع طول_الملخص: متغير غير_موقع = الطول(*الملخص) مثل غير_موقع;
    لو (طول_الملخص > البايتات) { طول_الملخص := البايتات; };
    دع المقطوع: متجه غ8 = شريحة_بايتات_تشفير(الملخص, 0, طول_الملخص);
    طابق عدد_كبير_من_بايتات(&المقطوع, (*ح).الرتبة.العدد) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(القيمة) -> { أرجع اختيار.بعض(اختزل_أقل_من_ضعف_كبير(&القيمة, &(*ح).الرتبة)); };
}

عرف هماك_موصول_إهليلجي(
    الخوارزمية: خوارزمية_تجزئة,
    المفتاح: &متجه غ8,
    ف: &متجه غ8,
    الفاصل: اختيار غ8,
    الخاص: &متجه غ8,
    الملخص: &متجه غ8
): متجه غ8 {
    دع الرسالة: متغير متجه غ8 = شريحة_بايتات_تشفير(ف, 0, الطول(*ف) مثل غير_موقع);
    طابق الفاصل مع
    | اختيار.لا_شيء -> { }
    | اختيار.بعض(البايت) -> {
        ألحق(الرسالة, البايت);
        ألحق_بايتات_تشفير(&متغير الرسالة, الخاص);
        ألحق_بايتات_تشفير(&متغير الرسالة, الملخص);
    };
    دع الناتج: متجه غ8 = هماك_تشفير(الخوارزمية, المفتاح, &الرسالة);
    امسح_بايتات_تشفير(&متغير الرسالة);
    أرجع الناتج;
}

// Signs a message digest with a private scalar (big-endian bytes of the curve
// size): the DER Ecdsa-Sig-Value. The nonce is derived with HMAC-الخوارزمية
// (RFC 6979 3.2); the digest is used as given (truncated to the order size).
عام عرف وقع_إي_سي_دي_إس_إيه(
    المنحنى: منحنى_إهليلجي,
    الخوارزمية: خوارزمية_تجزئة,
    الخاص: &متجه غ8,
    الملخص: &متجه غ8
): اختيار متجه غ8 {
    طابق معاملات_منحنى_إهليلجي_محدد(المنحنى) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(ح) -> {
        دع البايتات: غير_موقع = ح.البايتات;
        دع ن: &سياق_مونتغمري = &ح.الرتبة;
        دع العدد: غير_موقع = (*ن).العدد;
        دع د: متغير متجه غير_موقع;
        طابق عددي_خاص_إهليلجي(الخاص, &ح) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(القيمة) -> { د := القيمة; };
        دع قيمة_الملخص_المختزلة: متجه غير_موقع;
        طابق ملخص_مختزل_إهليلجي(الملخص, &ح) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(القيمة) -> { قيمة_الملخص_المختزلة := القيمة; };
        دع جي: نقطة_إسقاطية;
        طابق مولد_إسقاطي(&ح) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(القيمة) -> { جي := القيمة; };

        // RFC 6979 3.2 b-f.
        دع حجم_الملخص: غير_موقع = حجم_ملخص_تجزئة(الخوارزمية);
        دع في: متغير متجه غ8 = [];
        دع كي: متغير متجه غ8 = أصفار_تشفير(حجم_الملخص);
        دع ف: متغير غير_موقع = 0;
        بينما (ف < حجم_الملخص) { ألحق(في, 1 مثل غ8); ف := ف + 1; }
        دع خاص_ثمانيات: متغير متجه غ8 = بايتات_من_عدد_كبير(&د, البايتات);
        دع ملخص_ثمانيات: متجه غ8 = بايتات_من_عدد_كبير(&قيمة_الملخص_المختزلة, البايتات);
        كي := هماك_موصول_إهليلجي(الخوارزمية, &كي, &في, اختيار.بعض(0 مثل غ8), &خاص_ثمانيات, &ملخص_ثمانيات);
        في := هماك_تشفير(الخوارزمية, &كي, &في);
        كي := هماك_موصول_إهليلجي(الخوارزمية, &كي, &في, اختيار.بعض(1 مثل غ8), &خاص_ثمانيات, &ملخص_ثمانيات);
        في := هماك_تشفير(الخوارزمية, &كي, &في);
        امسح_بايتات_تشفير(&متغير خاص_ثمانيات);
        دع المحاولة: متغير غير_موقع = 0;
        بينما (المحاولة < 64) {
            // h. T = V || V || ... until it holds the order's size.
            دع تي: متغير متجه غ8 = [];
            بينما ((الطول(تي) مثل غير_موقع) < البايتات) {
                في := هماك_تشفير(الخوارزمية, &كي, &في);
                ألحق_بايتات_تشفير(&متغير تي, &في);
            }
            دع تي_مقطوع: متغير متجه غ8 = شريحة_بايتات_تشفير(&تي, 0, البايتات);
            امسح_بايتات_تشفير(&متغير تي);
            طابق عدد_كبير_من_بايتات(&تي_مقطوع, العدد) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(ك) -> {
                امسح_بايتات_تشفير(&متغير تي_مقطوع);
                لو (!هل_صفر_كبير(&ك) && قارن_كبير(&ك, &(*ن).المعامل) < 0) {
                    دع النقطة: نقطة_إسقاطية = اضرب_بزمن_ثابت_إهليلجي(&ك, &جي, &ح);
                    طابق إحداثيات_أفينية_إسقاطية(&النقطة, &ح) مع
                    | اختيار.لا_شيء -> { }
                    | اختيار.بعض(الإحداثيات) -> {
                        // x < p < 2n for both curves: one conditional subtraction reduces it.
                        دع ر: متجه غير_موقع = اختزل_أقل_من_ضعف_كبير(&الإحداثيات[0], ن);
                        لو (!هل_صفر_كبير(&ر)) {
                            // s = k^-1 (e + r d) mod n.
                            دع ر_م: متجه غير_موقع = إلى_مونتغمري(&ر, ن);
                            دع ر_د: متجه غير_موقع = اضرب_مونتغمري(&ر_م, &د, ن);
                            دع المجموع: متجه غير_موقع = اجمع_معياري_كبير(&قيمة_الملخص_المختزلة, &ر_د, ن);
                            دع أس_ن: متجه غ8 = معامل_ناقص_كبير(ن, 2, البايتات);
                            دع ك_معكوس: متجه غير_موقع = أس_معياري_كبير(&ك, &أس_ن, ن);
                            دع ك_معكوس_م: متجه غير_موقع = إلى_مونتغمري(&ك_معكوس, ن);
                            دع س: متجه غير_موقع = اضرب_مونتغمري(&ك_معكوس_م, &المجموع, ن);
                            لو (!هل_صفر_كبير(&س)) {
                                دع ر_بايتات: متجه غ8 = بايتات_من_عدد_كبير(&ر, البايتات);
                                دع س_بايتات: متجه غ8 = بايتات_من_عدد_كبير(&س, البايتات);
                                دع المحتوى: متغير متجه غ8 = عدد_صحيح_دي_إي_آر_إهليلجي(&ر_بايتات);
                                دع س_مرمز: متجه غ8 = عدد_صحيح_دي_إي_آر_إهليلجي(&س_بايتات);
                                ألحق_بايتات_تشفير(&متغير المحتوى, &س_مرمز);
                                امسح_بايتات_تشفير(&متغير كي);
                                أرجع اختيار.بعض(رمز_عنصر_دي_إي_آر(وسم_تسلسل_دي_إي_آر(), &المحتوى));
                            };
                        };
                    };
                };
            };
            // k rejected: K = HMAC_K(V || 0x00), V = HMAC_K(V).
            دع مدخل_الرفض: متغير متجه غ8 = شريحة_بايتات_تشفير(&في, 0, الطول(في) مثل غير_موقع);
            ألحق(مدخل_الرفض, 0 مثل غ8);
            كي := هماك_تشفير(الخوارزمية, &كي, &مدخل_الرفض);
            في := هماك_تشفير(الخوارزمية, &كي, &في);
            المحاولة := المحاولة + 1;
        }
        امسح_بايتات_تشفير(&متغير كي);
        أرجع اختيار.لا_شيء();
    };
}

