            ف := ف + 1;
        }
        ه0 := اجمع_غ32(ه0, أ); ه1 := اجمع_غ32(ه1, ب);
        ه2 := اجمع_غ32(ه2, ج); ه3 := اجمع_غ32(ه3, د);
        ه4 := اجمع_غ32(ه4, هاء); ه5 := اجمع_غ32(ه5, و5);
        ه6 := اجمع_غ32(ه6, ز); ه7 := اجمع_غ32(ه7, ح);
        كتلة := كتلة + 64;
    }

    دع الخرج: متغير متجه غ8 = [];
    دع الحالات: متجه غير_موقع = [ه0,ه1,ه2,ه3,ه4,ه5,ه6,ه7];
    ف := 0;
    بينما (ف < 8) {
        ألحق_بايت_هاش(&متغير الخرج, الحالات[ف] / 16777216);
        ألحق_بايت_هاش(&متغير الخرج, الحالات[ف] / 65536);
        ألحق_بايت_هاش(&متغير الخرج, الحالات[ف] / 256);
        ألحق_بايت_هاش(&متغير الخرج, الحالات[ف]);
        ف := ف + 1;
    }
    أرجع الخرج;
}

// The subtraction check prevents overflow in start + length.
عام عرف شا256_لمدى(
    المصدر: &متجه غ8, البداية: غير_موقع, الحجم: غير_موقع
): اختيار متجه غ8 {
    دع طول_المصدر: غير_موقع = الطول(*المصدر) مثل غير_موقع;
    لو (البداية > طول_المصدر || الحجم > طول_المصدر - البداية) {
        أرجع اختيار.لا_شيء();
    };
    أرجع اختيار.بعض(شا256_المجال_المتحقق(المصدر, البداية, الحجم));
}

عام عرف شا256(المصدر: &متجه غ8): متجه غ8 {
    أرجع شا256_المجال_المتحقق(المصدر, 0, الطول(*المصدر) مثل غير_موقع);
}

عام عرف هاش_متساوي_بزمن_ثابت(أ: &متجه غ8, ب: &متجه غ8): منطقي {
    أرجع بايتات_متساوية_بزمن_ثابت_تشفير(أ, ب);
}

عام مرادف sha256 = شا256;
عام مرادف constant_time_digest_equal = هاش_متساوي_بزمن_ثابت;
عام مرادف sha256_range = شا256_لمدى;

