عام نوع مدخل_دليل = {
    الاسم: نص,
    النوع: نوع_مدخل_دليل
};

عرف ابن_مخزن_اسم_دليل(): متجه غ8 {
    دع المخزن: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 4096) {
        ألحق(المخزن, 0 مثل غ8);
        ف := ف + 1;
    }
    أرجع المخزن;
}

عرف نص_مدخل_من_مخزن(المخزن: &متجه غ8, العدد: غير_موقع): نص {
    دع القيمة: متجه غ8 = *المخزن;
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        ألحق(البايتات, القيمة[ف]);
        ف := ف + 1;
    }
    أرجع من_بايتات(&البايتات);
}

عرف مدخل_خاص_بالدليل(الاسم: &نص): منطقي {
    دع نقطة: نص = «.»;
    دع نقطتان: نص = «..»;
    لو (نصان_متساويان(الاسم, &نقطة)) { أرجع صواب; };
    أرجع نصان_متساويان(الاسم, &نقطتان);
}

// Native directory listing owns and closes its platform resource in std.os.
عرف نوع_مدخل_من_رمز(الرمز: عدد): نوع_مدخل_دليل {
    لو (الرمز == 1) { أرجع نوع_مدخل_دليل.ملف(); };
    لو (الرمز == 2) { أرجع نوع_مدخل_دليل.دليل(); };
    لو (الرمز == 3) { أرجع نوع_مدخل_دليل.وصلة_رمزية(); };
    أرجع نوع_مدخل_دليل.آخر();
}

عام عرف اقرأ_مدخلات_الدليل(المسار: &نص): نتيجة متجه مدخل_دليل, عدد {
    طابق اقرأ_مداخل_دليل_النظام(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(رمز_خطأ_حد_النظام(الخطأ)); }
    | نتيجة.نجح(المداخل) -> {
        دع الناتج: متغير متجه مدخل_دليل = [];
        دع الموضع: متغير غير_موقع = 0;
        بينما (الموضع < (الطول(المداخل) مثل غير_موقع)) {
            // Borrow the OS entry; its owned name bytes stay in المداخل.
            دع المصدر: &مدخل_نظام = &المداخل[الموضع];
            دع الاسم: نص = من_بايتات(&(*المصدر).الاسم);
            لو (!مدخل_خاص_بالدليل(&الاسم)) {
                دع المدخل: مدخل_دليل = {
                    الاسم: الاسم, النوع: نوع_مدخل_من_رمز((*المصدر).النوع)
                };
                ألحق(الناتج, المدخل);
            };
            الموضع := الموضع + 1;
        }
        أرجع نتيجة.نجح(الناتج);
    };
}

// Check the actual path, not a normalized spelling or the last directory
// entry. "link/.." and "file/" must reach the filesystem unchanged.
// Metadata is the single std owner of path-type queries; the OS layer owns
// whether its path-type primitive observes symbolic links or their targets.
عرف نوع_مدخل_من_نوع_مسار(النوع: نوع_مسار): نوع_مدخل_دليل {
    طابق النوع مع
    | نوع_مسار.ملف -> { أرجع نوع_مدخل_دليل.ملف(); }
    | نوع_مسار.دليل -> { أرجع نوع_مدخل_دليل.دليل(); }
    | نوع_مسار.وصلة_رمزية -> { أرجع نوع_مدخل_دليل.وصلة_رمزية(); }
    | نوع_مسار.آخر -> { أرجع نوع_مدخل_دليل.آخر(); };
}

عام عرف حاول_نوع_مدخل_المسار(المسار: &نص): نتيجة اختيار نوع_مدخل_دليل, عدد {
    طابق حاول_نوع_المسار(المسار) مع
    | نتيجة.نجح(النوع) -> {
        أرجع نتيجة.نجح(اختيار.بعض(نوع_مدخل_من_نوع_مسار(النوع)));
    }
    | نتيجة.خطأ(الخطأ) -> {
        لو (هل_خطأ_غير_موجود(الخطأ)) {
            أرجع نتيجة.نجح(اختيار.لا_شيء());
        };
        أرجع نتيجة.خطأ(الخطأ);
    };
}

عام عرف حاول_وجود_المسار(المسار: &نص): نتيجة منطقي, عدد {
    طابق حاول_نوع_مدخل_المسار(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الموجود) -> {
        طابق الموجود مع
        | اختيار.بعض(_) -> { أرجع نتيجة.نجح(صواب); }
        | اختيار.لا_شيء -> { أرجع نتيجة.نجح(خطأ); };
    };
}

عام عرف حاول_مسار_ملف(المسار: &نص): نتيجة منطقي, عدد {
    طابق حاول_نوع_مدخل_المسار(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الموجود) -> {
        طابق الموجود مع
        | اختيار.لا_شيء -> { أرجع نتيجة.نجح(خطأ); }
        | اختيار.بعض(النوع) -> {
            طابق النوع مع
            | نوع_مدخل_دليل.ملف -> { أرجع نتيجة.نجح(صواب); }
            | _ -> { أرجع نتيجة.نجح(خطأ); };
        };
    };
}

عام عرف حاول_مسار_دليل(المسار: &نص): نتيجة منطقي, عدد {
    طابق حاول_نوع_مدخل_المسار(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الموجود) -> {
        طابق الموجود مع
        | اختيار.لا_شيء -> { أرجع نتيجة.نجح(خطأ); }
        | اختيار.بعض(النوع) -> {
            طابق النوع مع
            | نوع_مدخل_دليل.دليل -> { أرجع نتيجة.نجح(صواب); }
            | _ -> { أرجع نتيجة.نجح(خطأ); };
        };
    };
}

عام عرف حاول_مسار_وصلة_رمزية(المسار: &نص): نتيجة منطقي, عدد {
    طابق حاول_نوع_مدخل_المسار(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الموجود) -> {
        طابق الموجود مع
        | اختيار.لا_شيء -> { أرجع نتيجة.نجح(خطأ); }
        | اختيار.بعض(النوع) -> {
            طابق النوع مع
            | نوع_مدخل_دليل.وصلة_رمزية -> { أرجع نتيجة.نجح(صواب); }
            | _ -> { أرجع نتيجة.نجح(خطأ); };
        };
    };
}

عام مرادف directory_entry_type = نوع_مدخل_دليل;
عام مرادف directory_entry = مدخل_دليل;
عام مرادف directory_entry_type.file = نوع_مدخل_دليل.ملف;
عام مرادف directory_entry_type.directory = نوع_مدخل_دليل.دليل;
عام مرادف directory_entry_type.symlink = نوع_مدخل_دليل.وصلة_رمزية;
عام مرادف directory_entry_type.other = نوع_مدخل_دليل.آخر;
عام مرادف list_directory = اقرأ_مدخلات_الدليل;
عام مرادف try_path_entry_type = حاول_نوع_مدخل_المسار;
عام مرادف try_exists = حاول_وجود_المسار;
عام مرادف try_is_file = حاول_مسار_ملف;
عام مرادف try_is_directory = حاول_مسار_دليل;
عام مرادف try_is_symlink = حاول_مسار_وصلة_رمزية;

library/std/fs/error.sn:
استورد os.error;
استورد os.error_translation;

عام نوع فئة_خطأ_نظام =
    | لا_خطأ
    | غير_موجود
    | مرفوض_الإذن
    | موجود_مسبقا
    | إدخال_غير_صالح
    | غير_مدعوم
    | هو_دليل
    | ليس_دليلا
    | مورد_منهك
    | مقاطعة
    | آخر
;

// Translate the file API's numeric error status through the target-selected
// OS error classifier. Socket error namespaces are deliberately excluded.
عام عرف صنف_خطأ_نظام(الخطأ: عدد): فئة_خطأ_نظام {
    لو (الخطأ == 0) { أرجع فئة_خطأ_نظام.لا_خطأ(); };
    طابق صنف_خطأ_ملفات_النظام(الخطأ) مع
    | صنف_خطأ_نظام.غير_موجود -> { أرجع فئة_خطأ_نظام.غير_موجود(); }
    | صنف_خطأ_نظام.وصول_مرفوض -> { أرجع فئة_خطأ_نظام.مرفوض_الإذن(); }
    | صنف_خطأ_نظام.موجود_مسبقا -> { أرجع فئة_خطأ_نظام.موجود_مسبقا(); }
    | صنف_خطأ_نظام.وسيط_غير_صالح -> { أرجع فئة_خطأ_نظام.إدخال_غير_صالح(); }
    | صنف_خطأ_نظام.غير_مدعوم -> { أرجع فئة_خطأ_نظام.غير_مدعوم(); }
    | صنف_خطأ_نظام.هو_دليل -> { أرجع فئة_خطأ_نظام.هو_دليل(); }
    | صنف_خطأ_نظام.ليس_دليلا -> { أرجع فئة_خطأ_نظام.ليس_دليلا(); }
    | صنف_خطأ_نظام.استنفاد_الموارد -> { أرجع فئة_خطأ_نظام.مورد_منهك(); }
    | صنف_خطأ_نظام.عملية_انقطعت -> { أرجع فئة_خطأ_نظام.مقاطعة(); }
    | _ -> { أرجع فئة_خطأ_نظام.آخر(); };
}

عام عرف هل_خطأ_غير_موجود(الخطأ: عدد): منطقي {
    طابق صنف_خطأ_نظام(الخطأ) مع
    | فئة_خطأ_نظام.غير_موجود -> { أرجع صواب; }
    | _ -> { أرجع خطأ; };
}

عام مرادف os_error_class = فئة_خطأ_نظام;
عام مرادف os_error_class.none = فئة_خطأ_نظام.لا_خطأ;
عام مرادف os_error_class.not_found = فئة_خطأ_نظام.غير_موجود;
عام مرادف os_error_class.permission_denied = فئة_خطأ_نظام.مرفوض_الإذن;
عام مرادف os_error_class.already_exists = فئة_خطأ_نظام.موجود_مسبقا;
عام مرادف os_error_class.invalid_input = فئة_خطأ_نظام.إدخال_غير_صالح;
عام مرادف os_error_class.unsupported = فئة_خطأ_نظام.غير_مدعوم;
عام مرادف os_error_class.is_directory = فئة_خطأ_نظام.هو_دليل;
عام مرادف os_error_class.not_directory = فئة_خطأ_نظام.ليس_دليلا;
عام مرادف os_error_class.resource_exhausted = فئة_خطأ_نظام.مورد_منهك;
عام مرادف os_error_class.interrupted = فئة_خطأ_نظام.مقاطعة;
عام مرادف os_error_class.other = فئة_خطأ_نظام.آخر;
عام مرادف classify_os_error = صنف_خطأ_نظام;
عام مرادف is_not_found_error = هل_خطأ_غير_موجود;

library/std/fs/handle.sn:
استورد os.file;
استورد os.error;

عرف نتيجة_مقبض_ملف_خام(النتيجة: نتيجة عدد, خطأ_حد_نظام): عدد {
    طابق النتيجة مع
    | نتيجة.خطأ(الخطأ) -> { أرجع رمز_خطأ_حد_النظام(الخطأ); }
    | نتيجة.نجح(القيمة) -> { أرجع القيمة; };
}
عرف مقبض_من_معرف_ملف(المعرف: عدد): مقبض_ملف_نظام {
    دع الناتج: مقبض_ملف_نظام = { القيمة: المعرف مثل غ64, مفتوح: صواب };
    أرجع الناتج;
}
عرف افتح_مقبض_ملف_خام_للقراءة(المسار: &نص): عدد {
    طابق افتح_مقبض_ملف_نظام(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع رمز_خطأ_حد_النظام(الخطأ); }
    | نتيجة.نجح(المقبض) -> { أرجع المقبض.القيمة مثل عدد; };
}
عرف أنشئ_مقبض_ملف_خام_للكتابة(المسار: &نص): عدد {
    طابق أنشئ_مقبض_ملف_نظام(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع رمز_خطأ_حد_النظام(الخطأ); }
    | نتيجة.نجح(المقبض) -> { أرجع المقبض.القيمة مثل عدد; };
}
عرف اقرأ_مقطع_مقبض_ملف_خام(
    المعرف: عدد, المخزن: &متغير متجه غ8, الإزاحة: عدد, العدد: عدد
): عدد {
    دع المقبض: مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(اقرأ_مقبض_ملف_نظام(&المقبض, المخزن, الإزاحة, العدد));
}
عرف اكتب_مقطع_مقبض_ملف_خام(
    المعرف: عدد, المحتوى: &متجه غ8, الإزاحة: عدد, العدد: عدد
): عدد {
    دع المقبض: مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(اكتب_مقبض_ملف_نظام(&المقبض, المحتوى, الإزاحة, العدد));
}
عرف أغلق_مقبض_ملف_خام(المعرف: عدد): عدد {
    دع المقبض: متغير مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(أغلق_مقبض_ملف_نظام(&متغير المقبض));
}
عرف أصل_موضع_مقبض_ملف(الرمز: عدد): أصل_تحريك_ملف_نظام {
    لو (الرمز == 1) { أرجع أصل_تحريك_ملف_نظام.الحالي(); };
    لو (الرمز == 2) { أرجع أصل_تحريك_ملف_نظام.النهاية(); };
    أرجع أصل_تحريك_ملف_نظام.البداية();
}
عرف حرك_مقبض_ملف_خام(المعرف: عدد, الإزاحة: عدد, الأصل: عدد): عدد {
    دع المقبض: مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(
        حرك_مقبض_ملف_نظام(&المقبض, الإزاحة, أصل_موضع_مقبض_ملف(الأصل))
    );
}
عرف موضع_مقبض_ملف_خام(المعرف: عدد): عدد {
    دع المقبض: مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(
        حرك_مقبض_ملف_نظام(&المقبض, 0, أصل_تحريك_ملف_نظام.الحالي())
    );
}
عرف زامن_مقبض_ملف_خام(المعرف: عدد): عدد {
    دع المقبض: مقبض_ملف_نظام = مقبض_من_معرف_ملف(المعرف);
    أرجع نتيجة_مقبض_ملف_خام(زامن_مقبض_ملف_نظام(&المقبض));
}

عام نوع مقبض_ملف = صندوق عدد;

عام نوع أصل_موضع_ملف =
    | البداية
    | الحالي
    | النهاية
;

عرف قيمة_أصل_موضع_ملف(الأصل: أصل_موضع_ملف): عدد {
    طابق الأصل مع
    | أصل_موضع_ملف.البداية -> { أرجع 0; }
    | أصل_موضع_ملف.الحالي -> { أرجع 1; }
    | أصل_موضع_ملف.النهاية -> { أرجع 2; };
}

عرف قيمة_مقبض_ملف(المقبض: &مقبض_ملف): عدد {
    أرجع **المقبض;
}

عام عرف افتح_مقبض_ملف_للقراءة(المسار: &نص): نتيجة مقبض_ملف, عدد {
    دع الخام: عدد = افتح_مقبض_ملف_خام_للقراءة(المسار);
    لو (الخام < 0) { أرجع نتيجة.خطأ(الخام); };
    دع المقبض: مقبض_ملف = صندوق الخام;
    أرجع نتيجة.نجح(المقبض);
}

عام عرف أنشئ_مقبض_ملف_للكتابة(المسار: &نص): نتيجة مقبض_ملف, عدد {
    دع الخام: عدد = أنشئ_مقبض_ملف_خام_للكتابة(المسار);
    لو (الخام < 0) { أرجع نتيجة.خطأ(الخام); };
    دع المقبض: مقبض_ملف = صندوق الخام;
    أرجع نتيجة.نجح(المقبض);
}

عام عرف اقرأ_من_مقبض_ملف(
    المقبض: &مقبض_ملف,
    المخزن: &متغير متجه غ8,
    الإزاحة: عدد,
    العدد: عدد
): نتيجة عدد, عدد {
    دع المقروء: عدد = اقرأ_مقطع_مقبض_ملف_خام(قيمة_مقبض_ملف(المقبض), المخزن, الإزاحة, العدد);
    لو (المقروء < 0) { أرجع نتيجة.خطأ(المقروء); };
    أرجع نتيجة.نجح(المقروء);
}

عام عرف اكتب_إلى_مقبض_ملف(
    المقبض: &مقبض_ملف,
    المحتوى: &متجه غ8,
    الإزاحة: عدد,
    العدد: عدد
): نتيجة عدد, عدد {
    دع الحالة: متجه غ8 = *المحتوى;
    دع المكتوب: عدد = اكتب_مقطع_مقبض_ملف_خام(قيمة_مقبض_ملف(المقبض), &الحالة, الإزاحة, العدد);
    لو (المكتوب < 0) { أرجع نتيجة.خطأ(المكتوب); };
    أرجع نتيجة.نجح(المكتوب);
}

عام عرف حرك_مقبض_ملف(
    المقبض: &مقبض_ملف,
    الإزاحة: عدد,
    الأصل: أصل_موضع_ملف
): نتيجة عدد, عدد {
    دع الموضع: عدد = حرك_مقبض_ملف_خام(
        قيمة_مقبض_ملف(المقبض), الإزاحة, قيمة_أصل_موضع_ملف(الأصل)
    );
    لو (الموضع < 0) { أرجع نتيجة.خطأ(الموضع); };
    أرجع نتيجة.نجح(الموضع);
}

عام عرف موضع_مقبض_ملف(المقبض: &مقبض_ملف): نتيجة عدد, عدد {
    دع الموضع: عدد = موضع_مقبض_ملف_خام(قيمة_مقبض_ملف(المقبض));
