عام عرف اكتب_الملف(المسار: &نص, المحتوى: &نص): نتيجة عدد, عدد {
    دع النص: نص = *المحتوى;
    دع البايتات: متغير متجه غ8 = [];
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < (الطول(النص) مثل غير_موقع)) {
        ألحق(البايتات, النص[الفهرس]);
        الفهرس := الفهرس + 1;
    }
    أرجع اكتب_البايتات(المسار, &البايتات);
}

