عام عرف يحتوي_رمز_اتصال_ويب1(الرؤوس: &متجه رأس_ويب, الرمز: &نص): منطقي {
    دع اسم_الاتصال: نص = «connection»;
    دع القيم: متجه نص = قيم_رأس_ويب(الرؤوس, &اسم_الاتصال);
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(القيم) مثل غير_موقع)) {
        دع القيمة: نص = *(&القيم[ف]);
        دع البداية: متغير غير_موقع = 0;
        دع م: متغير غير_موقع = 0;
        بينما (م <= (الطول(القيمة) مثل غير_موقع)) {
            دع نهاية: منطقي = م == (الطول(القيمة) مثل غير_موقع);
