    دع close: نص = «close»;
    دع keep_alive: نص = «keep-alive»;
    دع اسم_الاتصال: نص = «connection»;
    دع يبقى: متغير منطقي = طلب_ويب1_يبقي_الاتصال(الطلب);
    لو (يحتوي_رمز_اتصال_ويب1(&(*الاستجابة).الرؤوس, &close)) { يبقى := خطأ; };
    لو (((*الاستجابة).الحالة == 101)) { يبقى := خطأ; };
