        دع الباقي: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = المحلل.المستهلك;
        بينما (ف < (الطول((*المفكك).المخزن) مثل غير_موقع)) { ألحق(الباقي, (*المفكك).المخزن[ف]); ف := ف + 1; }
