عام نوع إعداد_خادم_ويب = {
    العنوان: نص,
    التراكم: عدد,
    الحدود: حدود_ويب,
    إعادة_استخدام_العنوان: منطقي
};

عام نوع خطأ_خادم_ويب =
    | عنوان_غير_صالح
    | شبكة بنوع عدد
    | بروتوكول بنوع خطأ_ويب
    | انتقال_بروتوكول_غير_مدعوم
;

عام عرف إعداد_خادم_ويب_افتراضي(العنوان: &نص): إعداد_خادم_ويب {
    دع الإعداد: إعداد_خادم_ويب = {
        العنوان: انسخ_نص(العنوان),
        التراكم: 128,
        الحدود: حدود_ويب_افتراضية(),
        إعادة_استخدام_العنوان: صواب
    };
    أرجع الإعداد;
}

عرف بايتات_مقروءة_خادم(المخزن: &متجه غ8, العدد: غير_موقع): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما ((ف < العدد) && (ف < (الطول(*المخزن) مثل غير_موقع))) { ألحق(الناتج, (*المخزن)[ف]); ف := ف + 1; }
    أرجع الناتج;
}

عرف حالة_خطأ_خادم_ويب(الخطأ: &خطأ_ويب): غير_موقع {
    طابق (*الخطأ).الصنف مع
    | صنف_خطأ_ويب.جسم_كبير -> { أرجع 413; }
    | صنف_خطأ_ويب.قسم_رؤوس_كبير -> { أرجع 431; }
    | صنف_خطأ_ويب.رؤوس_كثيرة -> { أرجع 431; }
    | صنف_خطأ_ويب.إصدار_غير_مدعوم -> { أرجع 505; }
    | _ -> { أرجع 400; };
}

عرف أرسل_خطأ_بروتوكول_خادم(التدفق: &تدفق_تي_سي_بي, الخطأ: &خطأ_ويب): فراغ {
    دع النص: نص = «Bad HTTP request\n»;
    دع الاستجابة: متغير استجابة_ويب_مخزنة = استجابة_نص_ويب(حالة_خطأ_خادم_ويب(الخطأ), &النص);
    دع اسم_الاتصال: نص = «connection»;
    دع close: نص = «close»;
    دع تجاهل_رأس: منطقي = ضع_رأس_ويب(&متغير الاستجابة.الرؤوس, &اسم_الاتصال, &close);
    طابق سلسل_استجابة_ويب1(&الاستجابة) مع
    | نتيجة.خطأ(_) -> { }
    | نتيجة.نجح(البايتات) -> { دع تجاهل_كتابة: نتيجة غير_موقع, عدد = اكتب_الكل(التدفق, اكتب_تي_سي_بي, &البايتات); };
}

// Sequential HTTP/1 connection owner. It consumes and closes the stream.
عرف خدم_اتصال_ويب1<S>(
    التدفق: تدفق_تي_سي_بي,
    الحدود: &حدود_ويب,
    الحالة: &S,
    الخدمة: خدمة_ويب<S, متجه غ8, متجه غ8>
): نتيجة عدد, خطأ_خادم_ويب {
    دع المفكك: متغير مفكك_ويب1 = مفكك_ويب1_جديد(*الحدود);
    دع مخزن_قراءة: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 8192) { ألحق(مخزن_قراءة, 0); ف := ف + 1; }
    دع عدد_الطلبات: متغير عدد = 0;
    دع مستمر: متغير منطقي = صواب;
    بينما (مستمر) {
        طابق التالي_من_مفكك_ويب1(&متغير المفكك) مع
        | نتيجة.خطأ(الخطأ) -> {
            أرسل_خطأ_بروتوكول_خادم(&التدفق, &الخطأ);
            دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
            أرجع نتيجة.خطأ(خطأ_خادم_ويب.بروتوكول(الخطأ));
        }
        | نتيجة.نجح(اختيار.بعض(المحلل)) -> {
            دع الطلب: طلب_ويب_مخزن = طلب_من_طلب_محلل(&المحلل);
            دع الاستجابة: متغير استجابة_ويب_مخزنة = الخدمة(الحالة, &الطلب);
            ضع_إصدار_استجابة_ويب(&متغير الاستجابة, الطلب.الإصدار);
            دع connect: نص = «CONNECT»;
            دع انتقال_اتصال: منطقي = نصان_متساويان(&الطلب.الطريقة, &connect)
                && (الاستجابة.الحالة >= 200) && (الاستجابة.الحالة < 300);
            لو ((الاستجابة.الحالة == 101) || انتقال_اتصال) {
                // The generic std.http server owns HTTP messages only; it cannot
                // transfer the live stream to an upgrade/tunnel handler.
                دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                أرجع نتيجة.خطأ(خطأ_خادم_ويب.انتقال_بروتوكول_غير_مدعوم());
            };
            دع يبقى: منطقي = طبق_سياسة_اتصال_خادم_ويب1(&الطلب, &متغير الاستجابة);
            دع المرسل: متغير متجه غ8 = [];
            طابق سلسل_استجابة_ويب1_لطلب(&الطلب, &الاستجابة) مع
            | نتيجة.خطأ(الخطأ) -> {
                دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                أرجع نتيجة.خطأ(خطأ_خادم_ويب.بروتوكول(الخطأ));
            }
            | نتيجة.نجح(القيمة) -> { المرسل := القيمة; };
            طابق اكتب_الكل(&التدفق, اكتب_تي_سي_بي, &المرسل) مع
            | نتيجة.خطأ(الخطأ) -> {
                دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                أرجع نتيجة.خطأ(خطأ_خادم_ويب.شبكة(الخطأ));
            }
            | نتيجة.نجح(_) -> { };
            عدد_الطلبات := عدد_الطلبات + 1;
            لو (!يبقى) {
                دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                أرجع نتيجة.نجح(عدد_الطلبات);
            };
        }
        | نتيجة.نجح(اختيار.لا_شيء) -> {
            طابق اقرأ_تي_سي_بي(&التدفق, &متغير مخزن_قراءة, 0, 8192) مع
            | نتيجة.خطأ(الخطأ) -> {
                دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                أرجع نتيجة.خطأ(خطأ_خادم_ويب.شبكة(الخطأ));
            }
            | نتيجة.نجح(المقروء) -> {
                لو (المقروء == 0) {
                    لو (بايتات_معلقة_في_مفكك_ويب1(&المفكك) > 0) {
                        دع خطأ_النهاية: خطأ_ويب = خطأ_ويب_عند(صنف_خطأ_ويب.غير_مكتمل(), بايتات_معلقة_في_مفكك_ويب1(&المفكك));
                        أرسل_خطأ_بروتوكول_خادم(&التدفق, &خطأ_النهاية);
                    };
                    دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
                    أرجع نتيجة.نجح(عدد_الطلبات);
                };
                دع الجزء: متجه غ8 = بايتات_مقروءة_خادم(&مخزن_قراءة, المقروء مثل غير_موقع);
                غذ_مفكك_ويب1(&متغير المفكك, &الجزء);
            };
        };
    }
    دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_سي_بي(التدفق);
    أرجع نتيجة.نجح(عدد_الطلبات);
}

عام عرف شغل_خادم_ويب<S>(
    الإعداد: &إعداد_خادم_ويب,
    الحالة: &S,
    الخدمة: خدمة_ويب<S, متجه غ8, متجه غ8>
): نتيجة عدد, خطأ_خادم_ويب {
    دع القيمة: إعداد_خادم_ويب = *الإعداد;
    دع العنوان: متغير عنوان_مقبس;
    طابق حلل_عنوان_مقبس(&القيمة.العنوان) مع
    | نتيجة.خطأ(_) -> { أرجع نتيجة.خطأ(خطأ_خادم_ويب.عنوان_غير_صالح()); }
    | نتيجة.نجح(قيمة_العنوان) -> { العنوان := قيمة_العنوان; };
    دع الخيارات: متغير متجه خيار_مقبس = [];
    لو (القيمة.إعادة_استخدام_العنوان) { ألحق(الخيارات, خيار_مقبس.إعادة_استخدام_العنوان(صواب)); };
    طابق اربط_مستمع_تي_سي_بي_بخيارات(&العنوان, القيمة.التراكم, &الخيارات) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_خادم_ويب.شبكة(الخطأ)); }
    | نتيجة.نجح(المستمع) -> {
        بينما (صواب) {
            طابق اقبل_تي_سي_بي(&المستمع) مع
            | نتيجة.خطأ(الخطأ) -> {
                دع تجاهل: نتيجة عدد, عدد = أغلق_مستمع_تي_سي_بي(المستمع);
                أرجع نتيجة.خطأ(خطأ_خادم_ويب.شبكة(الخطأ));
            }
            | نتيجة.نجح(التدفق) -> {
                // Per-connection failures are contained to that client. The
                // listener remains the server's long-lived owner.
                دع تجاهل_اتصال: نتيجة عدد, خطأ_خادم_ويب = خدم_اتصال_ويب1(التدفق, &القيمة.الحدود, الحالة, الخدمة);
            };
        }
    };
    أرجع نتيجة.نجح(0);
}

