    بينما ((الوحدة * 2.0) <= المطلق) { الوحدة := الوحدة * 2.0; }
    دع الباقي: متغير ع64 = المطلق;
    دع الصحيح: متغير ع64 = 0.0;
    بينما (الوحدة >= 1.0) {
