        أرجع نتيجة.نجح(الربط);
    }
    عرف خريطة_خام(الطول: عدد, الحماية: عدد): عدد {
        طابق اربط_ذاكرة_تشغيل_نظام(الطول, الحماية) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع رمز_خطأ_حد_النظام(الخطأ); }
        | نتيجة.نجح(المنطقة) -> {
