            };
            أرجع المنطقة.العنوان مثل عدد;
        };
    }
    عرف إلغاء_خريطة_خام(العنوان: عدد, الطول: عدد): عدد {
        طابق ربط_ذاكرة_من_أرقام(العنوان, الطول) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع الخطأ; }
        | نتيجة.نجح(المصدر) -> {
            دع المنطقة: متغير ربط_ذاكرة_نظام = المصدر;
            أرجع رقم_نتيجة_ذاكرة(الغ_ربط_ذاكرة_تشغيل_نظام(&متغير المنطقة));
        };
    }
    عرف حماية_خام(العنوان: عدد, الطول: عدد, الحماية: عدد): عدد {
        طابق ربط_ذاكرة_من_أرقام(العنوان, الطول) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع الخطأ; }
