        سجل_تحرير_كتلة_مخصص(الكتلة, الفئة);
    }

    عرف أعد_تخصيص_كتلة_مخصص(الكتلة: غ64, الحجم: غ64): غ64 {
        لو (الكتلة == 0) { أرجع خصص_كتلة_مخصص(الحجم); };
        دع الحالة: غ64 = حالة_المخصص();
        لو (الحالة == 0) { أرجع 0; };
        دع الفئة: غ64 = فئة_كتلة_حية(الحالة, الكتلة);
        لو (الفئة == 0) { أرجع 0; };
        دع السعة: غ64 = حجم_كتلة_فئة(الفئة) - 8;
        لو (الحجم <= السعة) { أرجع الكتلة; };
        دع الفئة_المطلوبة: غ64 = فئة_طلب(الحجم);
        لو (الفئة_المطلوبة == 0) { أرجع 0; };
        // The most recently carved block extends in place, unless a released
        // block of the target class can be reused instead: a vector that is
        // grown, released and built again then reuses its storage rather than
        // growing the heap each time.
        دع البداية: غ64 = الكتلة - 8;
        لو (البداية + حجم_كتلة_فئة(الفئة) == اقرأ_كلمة_مخصص(الحالة + كلمة_المخصص())
            && اقرأ_كلمة_مخصص(رأس_قائمة_فئة(الحالة, الفئة_المطلوبة)) == 0) {
            دع الفئة_الجديدة: غ64 = الفئة_المطلوبة;
            دع النهاية: غ64 = البداية + حجم_كتلة_فئة(الفئة_الجديدة);
            لو (النهاية < نهاية_كومة_مخصص() && اضمن_كومة_مخصص(النهاية)) {
                اكتب_كلمة_مخصص(الحالة + كلمة_المخصص(), النهاية);
                اكتب_رأس_مخصص(الكتلة, الفئة_الجديدة, وسم_كتلة_مخصصة());
                سجل_نمو_كتلة_مخصص(الفئة, الفئة_الجديدة);
                أرجع الكتلة;
            };
        };
        دع الجديدة: غ64 = خصص_كتلة_مخصص(الحجم);
        لو (الجديدة == 0) { أرجع 0; };
        انسخ_ذاكرة_مخصص(الجديدة, الكتلة, السعة);
        حرر_كتلة_مخصص(الكتلة);
        أرجع الجديدة;
    }
}

library/std/os/arguments.sn:
استورد os.error;

// Argument vectors belong to process startup, not to a kernel syscall.
// Validate a zero-based index before converting to an unsigned vector offset.
// The Windows provider supplies owned text; Linux requires the compiler's
// source-level external-data access to the process-lifetime argv symbol.
عرف موضع_وسيطة_نظام_صالح(الموضع: عدد, العدد: غير_موقع): منطقي {
    لو (الموضع < 0) { أرجع خطأ; };
    أرجع (الموضع مثل غير_موقع) < العدد;
}

لو (الهدف.المنصة == «windows») {
    استورد os.platform.windows.win32.process_control;
    استورد text.from_bytes;

    عرف خطأ_وسائط_ويندوز_للنظام(الخطأ: خطأ_عملية_ويندوز): خطأ_حد_نظام {
        طابق الخطأ مع
        | خطأ_عملية_ويندوز.وسيط_غير_صالح -> {
            أرجع خطأ_حد_نظام.وسيط_غير_صالح();
        }
        | خطأ_عملية_ويندوز.ترميز_غير_صالح -> {
            أرجع خطأ_حد_نظام.وسيط_غير_صالح();
        }
        | خطأ_عملية_ويندوز.مغلقة -> {
            أرجع خطأ_حد_نظام.مورد_مغلق();
        }
        | خطأ_عملية_ويندوز.حالة_انتظار_غير_متوقعة(_) -> {
            أرجع خطأ_حد_نظام.وسيط_غير_صالح();
        }
        | خطأ_عملية_ويندوز.نظام(الأصلي) -> {
            أرجع خطأ_حد_نظام.نظام(الأصلي);
        };
    }

    عام عرف عدد_وسائط_النظام(): نتيجة عدد, خطأ_حد_نظام {
        طابق عدد_وسائط_عملية_ويندوز() مع
        | نتيجة.نجح(العدد) -> { أرجع نتيجة.نجح(العدد); }
        | نتيجة.خطأ(الخطأ) -> {
            أرجع نتيجة.خطأ(خطأ_وسائط_ويندوز_للنظام(الخطأ));
        };
    }

    عام عرف وسيطة_النظام(الموضع: عدد): نتيجة نص, خطأ_حد_نظام {
        لو (الموضع < 0) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        طابق اقرأ_وسائط_عملية_ويندوز() مع
        | نتيجة.خطأ(الخطأ) -> {
            أرجع نتيجة.خطأ(خطأ_وسائط_ويندوز_للنظام(الخطأ));
        }
        | نتيجة.نجح(الوسائط) -> {
            لو (!موضع_وسيطة_نظام_صالح(الموضع, الطول(الوسائط) مثل غير_موقع)) {
                أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
            };
            // The argument vector is owned here; return an independent copy.
            دع الوسيطة: نص = انسخ_نص(&الوسائط[الموضع مثل غير_موقع]);
            أرجع نتيجة.نجح(الوسيطة);
        };
    }
}


// Linux and Darwin share the Unix process-startup argv contract.
لو ((الهدف.المنصة == «linux» && (الهدف.المعمارية == «x86_64» || الهدف.المعمارية == «aarch64»)) || الهدف.المنصة == «macos») {
    استورد os.platform.unix.process_startup;
    استورد text.from_bytes;

    عام عرف عدد_وسائط_النظام(): نتيجة عدد, خطأ_حد_نظام {
        طابق اقرأ_عدد_وسائط_إقلاع_يونكس() مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق()); }
        | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(القيمة مثل عدد); };
    }

    عام عرف وسيطة_النظام(الموضع: عدد): نتيجة نص, خطأ_حد_نظام {
        لو (الموضع < 0) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        طابق اقرأ_وسيطة_إقلاع_يونكس(الموضع مثل غير_موقع) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); }
        | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(من_بايتات(&القيمة)); };
    }
}

// WASI hosts supply arguments through args_sizes_get/args_get.
لو (الهدف.المنصة == «wasi») {
    استورد os.platform.wasi.preview1.file_descriptors;
    استورد os.platform.wasi.preview1.process_startup;
    استورد text.from_bytes;

    عام عرف عدد_وسائط_النظام(): نتيجة عدد, خطأ_حد_نظام {
        طابق اقرأ_وسائط_واسي() مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_واسي_للنظام(الخطأ)); }
        | نتيجة.نجح(الوسائط) -> { أرجع نتيجة.نجح(الطول(الوسائط) مثل عدد); };
    }

    عام عرف وسيطة_النظام(الموضع: عدد): نتيجة نص, خطأ_حد_نظام {
        لو (الموضع < 0) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        طابق اقرأ_وسائط_واسي() مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_واسي_للنظام(الخطأ)); }
        | نتيجة.نجح(الوسائط) -> {
            لو (!موضع_وسيطة_نظام_صالح(الموضع, الطول(الوسائط) مثل غير_موقع)) {
                أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
            };
            أرجع نتيجة.نجح(من_بايتات(&الوسائط[الموضع مثل غير_موقع]));
        };
    }
}

library/std/os/buffer.sn:
// OS-owned bounds validation for pointers borrowed by native platform calls.
// Check by subtraction so that offset + length cannot overflow.
عام عرف نطاق_بايتات_نظام_صالح(
    الحجم: عدد, الإزاحة: عدد, المطلوب: عدد
): منطقي {
    لو (الحجم < 0 || الإزاحة < 0 || المطلوب < 0) { أرجع خطأ; };
    لو (الإزاحة > الحجم) { أرجع خطأ; };
    أرجع المطلوب <= (الحجم - الإزاحة);
}

library/std/os/capability.sn:
// A capability describes the execution environment of the compilation
// target, not the host running SultanC. This module defines the result
// contract; the frontend must eventually select the target implementation
// and enforce its result. This module does NOT decide target capabilities.
عام نوع مرفق_نظام =
    | ملفات
    | استعراض_أدلة
    | تيارات_قياسية
    | متغيرات_بيئة
    | إنشاء_عمليات
    | إنهاء_عمليات
    | مقابس_شبكة
    | حل_أسماء_شبكة
    | ذاكرة_افتراضية
    | حماية_ذاكرة
    | قفل_ذاكرة
    | ساعة_نظام
    | ساعة_رتيبة
    | نوم
    | مكتبات_ديناميكية
;

عام نوع توفر_مرفق_نظام =
    | متاح
    | مشروط_بالمضيف
    | غير_مدعوم
    | متوقف_على_المترجم
;

عام نوع عقد_مرفق_نظام = {
    المرفق: مرفق_نظام,
    التوفر: توفر_مرفق_نظام
};

عام عرف أنشئ_عقد_مرفق_نظام(
    المرفق: مرفق_نظام,
    التوفر: توفر_مرفق_نظام
): عقد_مرفق_نظام {
    دع العقد: عقد_مرفق_نظام = { المرفق: المرفق, التوفر: التوفر };
    أرجع العقد;
}

// Conditional support is not unconditional support: a browser host import,
// WASI preopen or other host grant must be checked by the actual provider.
عام عرف مرفق_نظام_متاح_بلا_شرط(العقد: &عقد_مرفق_نظام): منطقي {
    طابق (*العقد).التوفر مع
    | توفر_مرفق_نظام.متاح -> { أرجع صواب; }
    | _ -> { أرجع خطأ; };
}

عام مرادف os_facility = مرفق_نظام;
عام مرادف os_facility_availability = توفر_مرفق_نظام;
عام مرادف os_facility_contract = عقد_مرفق_نظام;
عام مرادف make_os_facility_contract = أنشئ_عقد_مرفق_نظام;
عام مرادف os_facility_unconditionally_available = مرفق_نظام_متاح_بلا_شرط;
عام مرادف os_facility.filesystem = مرفق_نظام.ملفات;
عام مرادف os_facility.process_creation = مرفق_نظام.إنشاء_عمليات;
عام مرادف os_facility.socket_networking = مرفق_نظام.مقابس_شبكة;
عام مرادف os_facility.virtual_memory = مرفق_نظام.ذاكرة_افتراضية;
عام مرادف os_facility_availability.available = توفر_مرفق_نظام.متاح;
عام مرادف os_facility_availability.host_conditional = توفر_مرفق_نظام.مشروط_بالمضيف;
عام مرادف os_facility_availability.unsupported = توفر_مرفق_نظام.غير_مدعوم;
عام مرادف os_facility_availability.compiler_blocked = توفر_مرفق_نظام.متوقف_على_المترجم;

library/std/os/clock.sn:
استورد math.integer;
استورد os.error;

// Wall-clock timestamps and monotonic instants are distinct types: a system
// time may jump after clock correction; an elapsed interval needs a monotonic
// source. Neither constructor fetches time from the host.
عام نوع طابع_وقت_نظام = { النانوثواني: عدد };
عام نوع لحظة_رتيبة_نظام = { النانوثواني: عدد };

عام عرف أنشئ_طابع_وقت_نظام(النانوثواني: عدد): طابع_وقت_نظام {
    دع الطابع: طابع_وقت_نظام = { النانوثواني: النانوثواني };
    أرجع الطابع;
}

عام عرف أنشئ_لحظة_رتيبة_نظام(النانوثواني: عدد): لحظة_رتيبة_نظام {
    دع اللحظة: لحظة_رتيبة_نظام = { النانوثواني: النانوثواني };
    أرجع اللحظة;
}

// Returns none for reversed samples or signed overflow. Both readings must
// come from the same monotonic clock and boot/session epoch.
عام عرف مدة_بين_لحظتين_رتيبتين(
    السابقة: &لحظة_رتيبة_نظام,
    اللاحقة: &لحظة_رتيبة_نظام
): اختيار عدد {
    لو ((*اللاحقة).النانوثواني < (*السابقة).النانوثواني) {
        أرجع اختيار.لا_شيء();
    };
    أرجع طرح_عدد_متحقق((*اللاحقة).النانوثواني, (*السابقة).النانوثواني);
}

عام مرادف os_wall_clock_timestamp = طابع_وقت_نظام;
عام مرادف os_monotonic_instant = لحظة_رتيبة_نظام;
عام مرادف os_monotonic_elapsed_checked = مدة_بين_لحظتين_رتيبتين;


// Convert timespec64 only after checking signed nanosecond range.
لو (الهدف.المنصة == «linux» && (الهدف.المعمارية == «x86_64» || الهدف.المعمارية == «aarch64»)) {
    استورد os.platform.unix.linux.clocks;
    استورد os.platform.unix.linux.syscalls.operations;
    استورد os.platform.unix.linux.syscalls.selection;

    عرف وقت_نانو_لينكس(رتيب: منطقي): نتيجة عدد, خطأ_حد_نظام {
        طابق اقرأ_ساعة_لينكس(
            رقم_نداء_نواة_لينكس(عملية_نداء_نواة_لينكس.ساعة_نظام()), رتيب
        ) مع
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_ساعة_لينكس.مدة_غير_صالحة -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق()); }
            | خطأ_ساعة_لينكس.نظام(الأصلي) -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(الأصلي)); };
        }
        | نتيجة.نجح(القيمة) -> {
            لو (القيمة.الثواني < 0 || القيمة.الثواني > 9223372035) {
                أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
            };
            دع الكلي: غ64 = (القيمة.الثواني مثل غ64) * 1000000000;
            لو ((القيمة.النانو مثل غ64) > 9223372036854775807 - الكلي) {
                أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
            };
            أرجع نتيجة.نجح((الكلي + (القيمة.النانو مثل غ64)) مثل عدد);
        };
    }

    عام عرف اقرأ_وقت_نظام_النظام(): نتيجة طابع_وقت_نظام, خطأ_حد_نظام {
        طابق وقت_نانو_لينكس(خطأ) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النانو) -> { أرجع نتيجة.نجح(أنشئ_طابع_وقت_نظام(النانو)); };
    }

    عام عرف اقرأ_وقت_رتيب_النظام(): نتيجة لحظة_رتيبة_نظام, خطأ_حد_نظام {
        طابق وقت_نانو_لينكس(صواب) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النانو) -> { أرجع نتيجة.نجح(أنشئ_لحظة_رتيبة_نظام(النانو)); };
    }

    عام عرف نم_نانو_للنظام(المدة: عدد): نتيجة عدد, خطأ_حد_نظام {
        لو (المدة < 0) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        طابق نم_نانو_لينكس(
            رقم_نداء_نواة_لينكس(عملية_نداء_نواة_لينكس.نوم_نانو()),
            (المدة / 1000000000) مثل ص64, (المدة % 1000000000) مثل ص64
        ) مع
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_ساعة_لينكس.مدة_غير_صالحة -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); }
            | خطأ_ساعة_لينكس.نظام(الأصلي) -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(الأصلي)); };
        }
        | نتيجة.نجح(القيمة) -> { أرجع نتيجة.نجح(القيمة مثل عدد); };
    }
}

لو (الهدف.المنصة == «windows») {
    استورد os.platform.windows.win32.clocks;

    عام عرف اقرأ_وقت_نظام_النظام(): نتيجة طابع_وقت_نظام, خطأ_حد_نظام {
        طابق اقرأ_وقت_يونكس_نانو_ويندوز() مع
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_تحويل_وقت_ويندوز.خارج_النطاق -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق()); }
            | خطأ_تحويل_وقت_ويندوز.تردد_غير_صالح -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); }
            | خطأ_تحويل_وقت_ويندوز.نظام(الأصلي) -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(الأصلي)); };
        }
        | نتيجة.نجح(القيمة) -> {
            لو (القيمة > 9223372036854775807) { أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق()); };
            أرجع نتيجة.نجح(أنشئ_طابع_وقت_نظام(القيمة مثل عدد));
        };
    }

    عام عرف اقرأ_وقت_رتيب_النظام(): نتيجة لحظة_رتيبة_نظام, خطأ_حد_نظام {
        طابق اقرأ_وقت_رتيب_نانو_ويندوز() مع
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_تحويل_وقت_ويندوز.خارج_النطاق -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق()); }
            | خطأ_تحويل_وقت_ويندوز.تردد_غير_صالح -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); }
            | خطأ_تحويل_وقت_ويندوز.نظام(الأصلي) -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(الأصلي)); };
