            دع الفهرس: متغير غير_موقع = 0;
            بينما (الفهرس < الحجم) {
                (*المخزن)[(الإزاحة مثل غير_موقع) + الفهرس] := البايتات[الفهرس];
                الفهرس := الفهرس + 1;
            }
            أرجع نتيجة.نجح(الحجم مثل عدد);
        };
    }
}

// Linux and Darwin share the Unix process-startup envp contract.
لو ((الهدف.المنصة == «linux» && (الهدف.المعمارية == «x86_64» || الهدف.المعمارية == «aarch64»)) || الهدف.المنصة == «macos») {
    استورد os.platform.unix.process_startup;
    استورد text.from_bytes;

    // Match NAME=VALUE exactly. The startup provider returns owned bytes;
    // no mutable environment pointer escapes into safe STD interfaces.
    عرف ابحث_قيمة_بيئة_إقلاع_النظام(
        الاسم: &نص
    ): نتيجة متجه غ8, خطأ_حد_نظام {
        لو (!اسم_متغير_بيئة_نظام_صالح(الاسم)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        طابق ابحث_قيمة_بيئة_إقلاع_يونكس(الاسم) مع
        | نتيجة_بحث_بيئة_إقلاع_يونكس.موجود(القيمة) -> {
            أرجع نتيجة.نجح(القيمة);
        }
        | نتيجة_بحث_بيئة_إقلاع_يونكس.غير_موجود -> {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.غير_موجود());
        }
        | نتيجة_بحث_بيئة_إقلاع_يونكس.غير_صالح -> {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
        };
    }

    عام عرف طول_متغير_بيئة_نظام(الاسم: &نص): نتيجة عدد, خطأ_حد_نظام {
        طابق ابحث_قيمة_بيئة_إقلاع_النظام(الاسم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { أرجع نتيجة.نجح(الطول(القيمة) مثل عدد); };
    }

    عام عرف اقرأ_متغير_بيئة_نظام(
        الاسم: &نص, المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        طابق ابحث_قيمة_بيئة_إقلاع_النظام(الاسم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> {
            دع النص: نص = من_بايتات(&القيمة);
            أرجع انسخ_نص_بيئة_لنطاق(&النص, المخزن, الإزاحة, المطلوب);
        };
    }

    عام عرف اقرأ_دليل_مؤقت_النظام(
        المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        دع اسم_المؤقت: نص = «TMPDIR»;
        دع القيمة: متغير اختيار نص = اختيار.لا_شيء();
        طابق ابحث_قيمة_بيئة_إقلاع_النظام(&اسم_المؤقت) مع
        | نتيجة.نجح(البايتات) -> { القيمة := اختيار.بعض(من_بايتات(&البايتات)); }
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_حد_نظام.غير_موجود -> { }
            | _ -> { أرجع نتيجة.خطأ(الخطأ); };
        };
        طابق اختر_دليل_مؤقت_نظام_من_البيئة(القيمة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النص) -> {
            أرجع انسخ_نص_بيئة_لنطاق(&النص, المخزن, الإزاحة, المطلوب);
        };
    }
}

// WASI hosts supply the environment through environ_sizes_get/environ_get.
// WASI preview 1 has no working-directory call: paths are resolved against
// preopened directories, and "/" names the root they are mounted under (the
// convention wasi-libc uses for its initial working directory).
لو (الهدف.المنصة == «wasi») {
    استورد os.platform.wasi.preview1.file_descriptors;
    استورد os.platform.wasi.preview1.process_startup;
    استورد text.from_bytes;

    عرف ابحث_قيمة_بيئة_واسي_للنظام(الاسم: &نص): نتيجة متجه غ8, خطأ_حد_نظام {
        لو (!اسم_متغير_بيئة_نظام_صالح(الاسم)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        طابق ابحث_قيمة_بيئة_واسي(الاسم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_واسي_للنظام(الخطأ)); }
        | نتيجة.نجح(الموجود) -> {
            طابق الموجود مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.غير_موجود()); }
            | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(القيمة); };
        };
    }

    عام عرف طول_متغير_بيئة_نظام(الاسم: &نص): نتيجة عدد, خطأ_حد_نظام {
        طابق ابحث_قيمة_بيئة_واسي_للنظام(الاسم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { أرجع نتيجة.نجح(الطول(القيمة) مثل عدد); };
    }

    عام عرف اقرأ_متغير_بيئة_نظام(
        الاسم: &نص, المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        طابق ابحث_قيمة_بيئة_واسي_للنظام(الاسم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> {
            دع النص: نص = من_بايتات(&القيمة);
            أرجع انسخ_نص_بيئة_لنطاق(&النص, المخزن, الإزاحة, المطلوب);
        };
    }

    عام عرف اقرأ_دليل_عمل_النظام(
        المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        دع الجذر: نص = «/»;
        أرجع انسخ_نص_بيئة_لنطاق(&الجذر, المخزن, الإزاحة, المطلوب);
    }

    // TMPDIR when the host provides one (an absolute path); no invented default.
    عام عرف اختر_دليل_مؤقت_نظام_من_البيئة(
        قيمة_البيئة: اختيار نص
    ): نتيجة نص, خطأ_حد_نظام {
        طابق قيمة_البيئة مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_حد_نظام.غير_موجود()); }
        | اختيار.بعض(المسار) -> {
            لو (الطول(المسار) == 0 || المسار[0] != 47) {
                أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
            };
            أرجع نتيجة.نجح(المسار);
        };
    }

    عام عرف اقرأ_دليل_مؤقت_النظام(
        المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        دع اسم_المؤقت: نص = «TMPDIR»;
        دع القيمة: متغير اختيار نص = اختيار.لا_شيء();
        طابق ابحث_قيمة_بيئة_واسي_للنظام(&اسم_المؤقت) مع
        | نتيجة.نجح(البايتات) -> { القيمة := اختيار.بعض(من_بايتات(&البايتات)); }
        | نتيجة.خطأ(الخطأ) -> {
            طابق الخطأ مع
            | خطأ_حد_نظام.غير_موجود -> { }
            | _ -> { أرجع نتيجة.خطأ(الخطأ); };
        };
        طابق اختر_دليل_مؤقت_نظام_من_البيئة(القيمة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النص) -> {
            أرجع انسخ_نص_بيئة_لنطاق(&النص, المخزن, الإزاحة, المطلوب);
        };
    }
}

library/std/os/environment_validation.sn:
// Environment-name and value validation shared by the selected OS providers.
عام عرف اسم_متغير_بيئة_نظام_صالح(الاسم: &نص): منطقي {
    دع العدد: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    لو (العدد == 0) { أرجع خطأ; };
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < العدد) {
        دع البايت: غ8 = (*الاسم)[الموضع];
        لو (البايت == 0 || البايت == 0x3D) { أرجع خطأ; };
        الموضع := الموضع + 1;
    }
    أرجع صواب;
}

عام عرف قيمة_متغير_بيئة_نظام_صالحة(القيمة: &نص): منطقي {
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < (الطول(*القيمة) مثل غير_موقع)) {
        لو ((*القيمة)[الموضع] == 0) { أرجع خطأ; };
        الموضع := الموضع + 1;
    }
    أرجع صواب;
}

عام مرادف os_environment_name_valid = اسم_متغير_بيئة_نظام_صالح;
عام مرادف os_environment_value_valid = قيمة_متغير_بيئة_نظام_صالحة;

library/std/os/error.sn:
// A system error is a pair of the issuing ABI's error namespace and its
// unmodified native code. A Unix errno, a Win32 error and a Winsock error
// can have equal numbers without representing the same failure.
//
// Platform implementations must retrieve an error before another system
// operation can overwrite it. Classification is separate from this identity.
عام نوع مصدر_خطأ_نظام =
    | يونكس
    | وين32
    | وينسوك
    | واسي
    | واجهة_مضيف
;

عام نوع خطأ_نظام_أصلي = {
    المصدر: مصدر_خطأ_نظام,
    الرمز: عدد
};

عام عرف أنشئ_خطأ_نظام_أصلي(المصدر: مصدر_خطأ_نظام, الرمز: عدد): خطأ_نظام_أصلي {
    دع الخطأ: خطأ_نظام_أصلي = { المصدر: المصدر, الرمز: الرمز };
    أرجع الخطأ;
}

عام عرف نفس_خطأ_النظام_الأصلي(الأول: &خطأ_نظام_أصلي, الثاني: &خطأ_نظام_أصلي): منطقي {
    أرجع ((*الأول).المصدر == (*الثاني).المصدر)
        && ((*الأول).الرمز == (*الثاني).الرمز);
}

عام مرادف native_os_error_source = مصدر_خطأ_نظام;
عام مرادف native_os_error = خطأ_نظام_أصلي;
عام مرادف make_native_os_error = أنشئ_خطأ_نظام_أصلي;
عام مرادف same_native_os_error = نفس_خطأ_النظام_الأصلي;
عام مرادف native_os_error_source.unix = مصدر_خطأ_نظام.يونكس;
عام مرادف native_os_error_source.win32 = مصدر_خطأ_نظام.وين32;
عام مرادف native_os_error_source.winsock = مصدر_خطأ_نظام.وينسوك;
عام مرادف native_os_error_source.wasi = مصدر_خطأ_نظام.واسي;
عام مرادف native_os_error_source.host_interface = مصدر_خطأ_نظام.واجهة_مضيف;

// Portable classification is an annotation of an actual native error, never
// a replacement for its platform namespace and original code. Only the
// platform implementation can translate the issuing ABI's error values.
عام نوع صنف_خطأ_نظام =
    | غير_معروف
    | غير_موجود
    | موجود_مسبقا
    | وصول_مرفوض
    | وسيط_غير_صالح
    | مورد_مشغول
    | استنفاد_الموارد
    | عملية_ستحظر
    | عملية_انقطعت
    | انتهت_المهلة
    | اتصال_مرفوض
    | اتصال_انقطع
    | شبكة_غير_متاحة
    | غير_مدعوم
    | هو_دليل
    | ليس_دليلا
;

عام نوع خطأ_نظام = {
    الأصلي: خطأ_نظام_أصلي,
    الصنف: صنف_خطأ_نظام
};

عام عرف صنف_خطأ_نظام_أصليا(
    الأصلي: خطأ_نظام_أصلي,
    الصنف: صنف_خطأ_نظام
): خطأ_نظام {
    دع الخطأ: خطأ_نظام = { الأصلي: الأصلي, الصنف: الصنف };
    أرجع الخطأ;
}

عام عرف نفس_خطأ_النظام(الأول: &خطأ_نظام, الثاني: &خطأ_نظام): منطقي {
    أرجع نفس_خطأ_النظام_الأصلي(&(*الأول).الأصلي, &(*الثاني).الأصلي);
}

عام مرادف os_error_kind = صنف_خطأ_نظام;
عام مرادف os_error = خطأ_نظام;
عام مرادف classify_native_os_error = صنف_خطأ_نظام_أصليا;
عام مرادف same_os_error = نفس_خطأ_النظام;

// The inherited runtime ABI uses negative signed status values. They are not
// necessarily errno values: the native-error namespace is only known to the
// selected platform provider. Preserve the complete status without guessing.
عام نوع خطأ_حد_نظام =
    | غير_موجود
    | وسيط_غير_صالح
    | مورد_مغلق
    | قيمة_خارج_النطاق
    | اسم_شبكة_غير_موجود
    | رد_شبكة_غير_صالح
    | نظام بنوع خطأ_نظام_أصلي
    | فشل_تشغيل بنوع عدد
;

عام عرف نتيجة_حالة_تشغيل_نظام(الحالة: عدد): نتيجة عدد, خطأ_حد_نظام {
    لو (الحالة < 0) {
        أرجع نتيجة.خطأ(خطأ_حد_نظام.فشل_تشغيل(الحالة));
    };
    أرجع نتيجة.نجح(الحالة);
}

عام مرادف os_boundary_error = خطأ_حد_نظام;
عام مرادف os_runtime_status = نتيجة_حالة_تشغيل_نظام;

// This legacy classification value is portable only within the current
// runtime protocol. It is NOT an OS errno, a Win32 error, or a substitute for
// retrieving a native error at the issuing ABI boundary.
// The raw protocol is intentionally not remapped to a second enum here;
// the existing std.fs.error consumer remains the canonical interpreter.

// Existing std APIs return integer error codes. This is the sole lossy
// conversion at that older public boundary; std.os keeps the native source
// namespace and code in the typed variant above.
عام عرف رمز_خطأ_حد_النظام(الخطأ: خطأ_حد_نظام): عدد {
    طابق الخطأ مع
    | خطأ_حد_نظام.غير_موجود -> { أرجع -2; }
    | خطأ_حد_نظام.وسيط_غير_صالح -> { أرجع -22; }
    | خطأ_حد_نظام.مورد_مغلق -> { أرجع -9; }
    | خطأ_حد_نظام.قيمة_خارج_النطاق -> { أرجع -75; }
    | خطأ_حد_نظام.اسم_شبكة_غير_موجود -> { أرجع -2; }
    | خطأ_حد_نظام.رد_شبكة_غير_صالح -> { أرجع -71; }
    | خطأ_حد_نظام.نظام(الأصلي) -> {
        أرجع 0 - الأصلي.الرمز;
    }
    | خطأ_حد_نظام.فشل_تشغيل(الحالة) -> { أرجع الحالة; };
}

library/std/os/error_translation.sn:
استورد os.error;

// File-operation integer errors are the inherited STD boundary. The native
// OS error itself retains its origin in os.error. A negative integer alone
// cannot identify a Winsock error versus a Win32 error: do not apply this
// file-only classifier to socket errors.
لو (الهدف.المنصة == «linux» && (الهدف.المعمارية == «x86_64» || الهدف.المعمارية == «aarch64»)) {
    استورد os.platform.unix.linux.syscalls.kernel_result;
    عام عرف صنف_خطأ_ملفات_النظام(الحالة: عدد): صنف_خطأ_نظام {
        لو (الحالة >= 0) { أرجع صنف_خطأ_نظام.غير_معروف(); };
        أرجع صنف_خطأ_نواة_لينكس_أساسيا(0 - الحالة);
    }
}

لو (الهدف.المنصة == «windows») {
    استورد os.platform.windows.win32.error_translation;
    عام عرف صنف_خطأ_ملفات_النظام(الحالة: عدد): صنف_خطأ_نظام {
        لو (الحالة >= 0 || الحالة < -4294967295) {
            أرجع صنف_خطأ_نظام.غير_معروف();
        };
        أرجع صنف_خطأ_وين32((0 - الحالة) مثل غ32);
    }
}

لو (الهدف.المنصة == «macos») {
    استورد os.platform.unix.apple.darwin.error_translation;
    عام عرف صنف_خطأ_ملفات_النظام(الحالة: عدد): صنف_خطأ_نظام {
        لو (الحالة >= 0) { أرجع صنف_خطأ_نظام.غير_معروف(); };
        أرجع صنف_خطأ_داروين_أساسيا(0 - الحالة);
    }
}

لو (الهدف.المنصة == «wasi») {
    استورد os.platform.wasi.preview1.error_translation;
    عام عرف صنف_خطأ_ملفات_النظام(الحالة: عدد): صنف_خطأ_نظام {
        لو (الحالة >= 0) { أرجع صنف_خطأ_نظام.غير_معروف(); };
        أرجع صنف_خطأ_واسي_أساسيا(0 - الحالة);
    }
}

library/std/os/file.sn:
استورد os.buffer;
استورد os.error;
استورد os.path;

// Owned kernel file descriptors (Linux) and native HANDLEs (Windows) are
// stored as machine words, not signed runtime statuses. A close consumes the
// owner according to the selected platform's semantics.
عام نوع ملف_نظام = {
    القيمة: غ64,
    مفتوح: منطقي
};

عام نوع أصل_تحريك_ملف_نظام =
    | البداية
    | الحالي
    | النهاية
;

عرف أصل_تحريك_ملف_نظام_خام(الأصل: أصل_تحريك_ملف_نظام): عدد {
    طابق الأصل مع
    | أصل_تحريك_ملف_نظام.البداية -> { أرجع 0; }
    | أصل_تحريك_ملف_نظام.الحالي -> { أرجع 1; }
    | أصل_تحريك_ملف_نظام.النهاية -> { أرجع 2; };
}

لو (الهدف.المنصة == «linux» && (الهدف.المعمارية == «x86_64» || الهدف.المعمارية == «aarch64»)) {
    استورد os.platform.unix.linux.file_descriptors;
    استورد os.platform.unix.linux.syscalls.operations;
    استورد os.platform.unix.linux.syscalls.selection;

    عرف حول_خطأ_واصف_للنظام(الخطأ: خطأ_واصف_لينكس): خطأ_حد_نظام {
