library/std/os/path.sn:
استورد encoding.utf16;

// Native paths are not a single encoding: Unix passes opaque bytes, while
// Win32's W APIs consume UTF-16 code units. These constructors only prepare
// values for a future platform binding. They do not invoke an OS service.
عام نوع خطأ_مسار_نظام =
    | صفر_مدمج
    | ترميز_غير_صالح
;

// A text-based path is a restricted subset of Unix byte paths. It is not a
// substitute for the byte-based constructor (which can carry non-UTF-8 names).
عام عرف مسار_نظام_بلا_صفر_مدمج(المسار: &نص): منطقي {
    دع العدد: غير_موقع = الطول(*المسار) مثل غير_موقع;
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < العدد) {
        لو ((*المسار)[الفهرس] == 0) { أرجع خطأ; };
        الفهرس := الفهرس + 1;
    }
    أرجع صواب;
}

// A Unix pathname passed to a NUL-terminated native kernel ABI needs a terminator;
// an embedded NUL would otherwise silently select a different pathname.
// The returned vector owns the entire terminated byte sequence.
عام عرف بايتات_مسار_يونكس_صفرية(
    البايتات: &متجه غ8
): نتيجة متجه غ8, خطأ_مسار_نظام {
    دع الناتج: متغير متجه غ8 = [];
    دع الفهرس: متغير غير_موقع = 0;
    دع العدد: غير_موقع = الطول(*البايتات) مثل غير_موقع;
    بينما (الفهرس < العدد) {
        دع البايت: غ8 = (*البايتات)[الفهرس];
        لو (البايت == 0) {
            أرجع نتيجة.خطأ(خطأ_مسار_نظام.صفر_مدمج());
        };
        ألحق(الناتج, البايت);
        الفهرس := الفهرس + 1;
    }
    ألحق(الناتج, 0 مثل غ8);
    أرجع نتيجة.نجح(الناتج);
}

// Win32 W-path conversion shares the canonical std.encoding UTF-8/UTF-16
// converter. Conversion failures are never replaced by lossy code points.
// A resulting vector includes one UTF-16 NUL terminator for Win32 W APIs.
عام عرف وحدات_مسار_ويندوز_صفرية(
    المسار: &نص
): نتيجة متجه غ16, خطأ_مسار_نظام {
    لو (!مسار_نظام_بلا_صفر_مدمج(المسار)) {
        أرجع نتيجة.خطأ(خطأ_مسار_نظام.صفر_مدمج());
    };
    طابق نص_إلى_يوتيف16(المسار) مع
    | نتيجة.خطأ(_) -> {
        أرجع نتيجة.خطأ(خطأ_مسار_نظام.ترميز_غير_صالح());
    }
    | نتيجة.نجح(الوحدات) -> {
        دع الناتج: متغير متجه غ16 = الوحدات;
        ألحق(الناتج, 0 مثل غ16);
        أرجع نتيجة.نجح(الناتج);
    };
}

عام مرادف os_path_error = خطأ_مسار_نظام;
عام مرادف os_path_has_no_embedded_nul = مسار_نظام_بلا_صفر_مدمج;
عام مرادف unix_path_to_nul_terminated_bytes = بايتات_مسار_يونكس_صفرية;
عام مرادف windows_path_to_nul_terminated_utf16 = وحدات_مسار_ويندوز_صفرية;

// A text path supplies UTF-8 bytes on Unix; byte-only filesystem names can
// use the native Linux provider directly without converting through text.
عام عرف بايتات_مسار_نص_نظام(المسار: &نص): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < (الطول(*المسار) مثل غير_موقع)) {
        ألحق(الناتج, (*المسار)[الموضع]);
        الموضع := الموضع + 1;
    }
    أرجع الناتج;
}

library/std/os/platform/unix/apple/darwi:
استورد os.error;
استورد os.platform.unix.apple.darwin.file_descriptors;

// Darwin's POSIX clock_gettime(CLOCK_REALTIME=0) writes a timespec with
// two 64-bit signed longs on the supported arm64 macOS ABI. This is wall
// time; it cannot be substituted by mach_absolute_time's uptime epoch.
خارجي عرف clock_gettime(معرف_الساعة: ص32, الوقت: *متغير ص64): ص32;

عام عرف اقرأ_وقت_داروين_جداري_نانو(): نتيجة عدد, خطأ_حد_نظام {
    دع الحقول: متغير متجه ص64 = [0, 0];
    دع الحالة: ص32 = clock_gettime(0, &متغير الحقول[0]);
    لو (الحالة != 0) {
        أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(خطأ_داروين_الحالي()));
    };
    دع الثواني: ص64 = الحقول[0];
    دع النانو: ص64 = الحقول[1];
    لو (الثواني < 0 || الثواني > 9223372035 || النانو < 0 || النانو >= 1000000000) {
        أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
    };
    دع الكلي: غ64 = (الثواني مثل غ64) * 1000000000;
    لو ((النانو مثل غ64) > 9223372036854775807 - الكلي) {
        أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
    };
    أرجع نتيجة.نجح((الكلي + (النانو مثل غ64)) مثل عدد);
}

// Mach's supported monotonic clock API. Unlike POSIX clock_gettime, these
// declarations name Mach timing interfaces, not libc functions.
// mach_timebase_info_data_t contains two uint32_t fields.
خارجي عرف mach_absolute_time(): غ64;
خارجي عرف mach_timebase_info(المعلومات: *متغير غ32): ص32;

عام نوع خطأ_ساعة_ماخ =
    | فشل_نواة بنوع ص32
    | تردد_غير_صالح
    | خارج_النطاق
;

عام نوع قراءة_ساعة_ماخ = {
    الدقات: غ64,
    بسط_نانو_الثانية: غ32,
    مقام_نانو_الثانية: غ32
};

// Retain a rational conversion factor: ticks * numerator / denominator
// must be evaluated with overflow checks by consumers. mach_absolute_time
// is monotonic but does not include suspended-system sleep time.
عام عرف اقرأ_ساعة_ماخ_الرتيبة(): نتيجة قراءة_ساعة_ماخ, خطأ_ساعة_ماخ {
    دع البيانات: متغير متجه غ32 = [0, 0];
    دع الحالة: ص32 = mach_timebase_info(&متغير البيانات[0]);
    لو (الحالة != 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.فشل_نواة(الحالة));
    };
    لو (البيانات[1] == 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.تردد_غير_صالح());
    };
    دع القراءة: قراءة_ساعة_ماخ = {
        الدقات: mach_absolute_time(),
        بسط_نانو_الثانية: البيانات[0],
        مقام_نانو_الثانية: البيانات[1]
    };
    أرجع نتيجة.نجح(القراءة);
}

// mach_continuous_time includes time while the system is asleep, unlike
// mach_absolute_time. Both share mach_timebase_info's unit conversion.
خارجي عرف mach_continuous_time(): غ64;

// A large accumulated tick count cannot be multiplied directly by the
// numerator: split before multiplying. Both timebase fields are u32, so
// (ticks % denominator) * numerator fits in u64. Never return a wrapped
// duration if the whole-seconds contribution would overflow.
عام عرف حول_دقات_ماخ_إلى_نانو(
    الدقات: غ64, البسط: غ32, المقام: غ32
): نتيجة غ64, خطأ_ساعة_ماخ {
    لو (المقام == 0 || البسط == 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.تردد_غير_صالح());
    };
    دع القاسم: غ64 = المقام مثل غ64;
    دع المضاعف: غ64 = البسط مثل غ64;
    دع الكامل: غ64 = الدقات / القاسم;
    دع الباقي: غ64 = الدقات % القاسم;
    لو (الكامل > (18446744073709551615 / المضاعف)) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.خارج_النطاق());
    };
    دع الجزء: غ64 = (الباقي * المضاعف) / القاسم;
    دع الناتج: غ64 = الكامل * المضاعف;
    لو (الجزء > (18446744073709551615 - الناتج)) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.خارج_النطاق());
    };
    أرجع نتيجة.نجح(الناتج + الجزء);
}

عام عرف اقرأ_وقت_ماخ_رتيب_نانو(): نتيجة غ64, خطأ_ساعة_ماخ {
    طابق اقرأ_ساعة_ماخ_الرتيبة() مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القراءة) -> {
        أرجع حول_دقات_ماخ_إلى_نانو(
            القراءة.الدقات, القراءة.بسط_نانو_الثانية, القراءة.مقام_نانو_الثانية
        );
    };
}

عام عرف اقرأ_وقت_ماخ_مستمر_نانو(): نتيجة غ64, خطأ_ساعة_ماخ {
    دع البيانات: متغير متجه غ32 = [0, 0];
    دع الحالة: ص32 = mach_timebase_info(&متغير البيانات[0]);
    لو (الحالة != 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.فشل_نواة(الحالة));
    };
    أرجع حول_دقات_ماخ_إلى_نانو(
        mach_continuous_time(), البيانات[0], البيانات[1]
    );
}

// Native Mach absolute-deadline wait (mach/mach_time.h). The timebase ratio
// converts nanoseconds to ticks; rounding up must not shorten the wait.
// Mach's absolute clock does not count time spent suspended. This operation
// does not use POSIX nanosleep or a C runtime.
خارجي عرف mach_wait_until(الموعد: غ64): ص32;

عام عرف نم_نانو_ماخ(المدة_نانو: غ64): نتيجة عدد, خطأ_ساعة_ماخ {
    لو (المدة_نانو == 0) { أرجع نتيجة.نجح(0); };
    دع البيانات: متغير متجه غ32 = [0, 0];
    دع الحالة: ص32 = mach_timebase_info(&متغير البيانات[0]);
    لو (الحالة != 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.فشل_نواة(الحالة));
    };
    لو (البيانات[0] == 0 || البيانات[1] == 0) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.تردد_غير_صالح());
    };
    دع البسط: غ64 = البيانات[0] مثل غ64;
    دع المقام: غ64 = البيانات[1] مثل غ64;
    دع الجزء_الكامل: غ64 = المدة_نانو / البسط;
    دع الباقي: غ64 = المدة_نانو % البسط;
    لو (الجزء_الكامل > 18446744073709551615 / المقام) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.خارج_النطاق());
    };
    دع الدقات_الكاملة: غ64 = الجزء_الكامل * المقام;
    دع ناتج_الباقي: غ64 = الباقي * المقام;
    دع الدقات_الجزئية: متغير غ64 = ناتج_الباقي / البسط;
    لو ((ناتج_الباقي % البسط) != 0) {
        الدقات_الجزئية := الدقات_الجزئية + 1;
    };
    دع الآن: غ64 = mach_absolute_time();
    لو (الدقات_الجزئية > 18446744073709551615 - الدقات_الكاملة) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.خارج_النطاق());
    };
    دع الدقات: غ64 = الدقات_الكاملة + الدقات_الجزئية;
    لو (الدقات > 18446744073709551615 - الآن) {
        أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.خارج_النطاق());
    };
    دع الموعد: غ64 = الآن + الدقات;
    // KERN_ABORTED (14) denotes an interrupted Mach wait. Continue from
    // the original deadline rather than losing elapsed time or busy-spinning.
    بينما (mach_absolute_time() < الموعد) {
        دع الانتظار: ص32 = mach_wait_until(الموعد);
        لو (الانتظار != 0 && الانتظار != 14) {
            أرجع نتيجة.خطأ(خطأ_ساعة_ماخ.فشل_نواة(الانتظار));
        };
    }
    أرجع نتيجة.نجح(0);
}

استورد os.path;
استورد os.error;
استورد os.platform.unix.apple.darwin.file_descriptors;

// Darwin directory provider through libSystem (see file_descriptors.sn for
// why libSystem is the supported Darwin kernel interface). arm64 Darwin
// always uses the 64-bit inode ABI, so opendir/readdir carry no $INODE64
// suffix and struct dirent is: d_ino u64 @0, d_seekoff u64 @8,
// d_reclen u16 @16, d_namlen u16 @18, d_type u8 @20, d_name @21.
خارجي عرف opendir(المسار: *غ8): *متغير غ8;
خارجي عرف readdir(الدليل: *متغير غ8): *غ8;
خارجي عرف closedir(الدليل: *متغير غ8): ص32;
خارجي عرف mkdir(المسار: *غ8, الوضع: غ16): ص32;
خارجي عرف rmdir(المسار: *غ8): ص32;

عام نوع مدخل_دليل_داروين = { الاسم: متجه غ8, النوع: غ8 };

// Lists every entry except "." and ".."; the DIR stream is closed exactly once.
عام عرف اقرأ_مداخل_دليل_داروين(
    المسار: &متجه غ8
): نتيجة متجه مدخل_دليل_داروين, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        دع الدليل: *متغير غ8 = opendir(&الاسم[0]);
        لو (الدليل == الفارغ) {
            أرجع نتيجة.خطأ(خطأ_واصف_داروين.نظام(خطأ_داروين_الحالي()));
        };
        دع الناتج: متغير متجه مدخل_دليل_داروين = [];
        دع مستمر: متغير منطقي = صواب;
        بينما (مستمر) {
            // readdir reports end and failure both as NULL; errno separates them.
            اضبط_خطأ_داروين_صفرا();
            دع المدخل: *غ8 = readdir(الدليل);
            لو (المدخل == الفارغ) {
                دع الخطأ: خطأ_نظام_أصلي = خطأ_داروين_الحالي();
                دع الإغلاق: ص32 = closedir(الدليل);
                لو (الخطأ.الرمز != 0) {
                    أرجع نتيجة.خطأ(خطأ_واصف_داروين.نظام(الخطأ));
                };
                مستمر := خطأ;
            } وإلا {
                دع الطول_الأدنى: متغير غير_موقع = 0;
                دع الطول_الأعلى: متغير غير_موقع = 0;
                دع النوع: متغير غ8 = 0;
                غير_آمن {
                    الطول_الأدنى := المدخل[18] مثل غير_موقع;
                    الطول_الأعلى := المدخل[19] مثل غير_موقع;
                    النوع := المدخل[20];
                }
                دع طول_الاسم: غير_موقع = الطول_الأدنى + (الطول_الأعلى * 256);
                لو (طول_الاسم > 1023) {
                    دع الإغلاق: ص32 = closedir(الدليل);
                    أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح());
                };
                دع اسم_المدخل: متغير متجه غ8 = [];
                دع ف: متغير غير_موقع = 0;
                بينما (ف < طول_الاسم) {
                    دع البايت: متغير غ8 = 0;
                    غير_آمن { البايت := المدخل[21 + ف]; }
                    ألحق(اسم_المدخل, البايت);
                    ف := ف + 1;
                }
                دع خاص: منطقي = (طول_الاسم == 1 && اسم_المدخل[0] == 46)
                    || (طول_الاسم == 2 && اسم_المدخل[0] == 46 && اسم_المدخل[1] == 46);
                لو (!خاص) {
                    دع الناتج_المقروء: مدخل_دليل_داروين = { الاسم: اسم_المدخل, النوع: النوع };
                    ألحق(الناتج, الناتج_المقروء);
                };
            };
        }
        أرجع نتيجة.نجح(الناتج);
    };
}

عام عرف أنشئ_دليل_داروين(المسار: &متجه غ8, الوضع: غ16): نتيجة غ64, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        لو (mkdir(&الاسم[0], الوضع) < 0) {
            أرجع نتيجة.خطأ(خطأ_واصف_داروين.نظام(خطأ_داروين_الحالي()));
        };
        أرجع نتيجة.نجح(0);
    };
}

عام عرف أزل_دليل_داروين(المسار: &متجه غ8): نتيجة غ64, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        لو (rmdir(&الاسم[0]) < 0) {
            أرجع نتيجة.خطأ(خطأ_واصف_داروين.نظام(خطأ_داروين_الحالي()));
        };
        أرجع نتيجة.نجح(0);
    };
}

// حد ABI لمحمل المكتبات الديناميكية في النظام.
// الأسماء الإنجليزية هنا فقط لأنها أسماء رموز C خارجية فعلية.
// Darwin dladdr is provided by libSystem. This module holds only the
// platform C ABI and generic C-string extraction, not compiler policy.

عام نوع معلومات_عنوان_محمل_ديناميكي = {
    اسم_الملف: *غ8,
    قاعدة: *غ8,
    اسم_الرمز: *غ8,
    عنوان_الرمز: *غ8
};

خارجي عرف dladdr(العنوان: *متغير غ8, المعلومات: *متغير معلومات_عنوان_محمل_ديناميكي): ص32;

عام عرف ابحث_معلومات_عنوان_ديناميكي(
    العنوان: *متغير غ8,
    المعلومات: *متغير معلومات_عنوان_محمل_ديناميكي
): ص32 {
    أرجع dladdr(العنوان, المعلومات);
}

عام عرف انسخ_نص_سي_من_محمل_ديناميكي(المصدر: *غ8): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    دع فهرس_البايت: متغير غير_موقع = 0;
    غير_آمن {
        بينما (المصدر[فهرس_البايت] != 0) {
            ألحق(الناتج, المصدر[فهرس_البايت]);
            فهرس_البايت := فهرس_البايت + 1;
        }
    }
    أرجع الناتج;
}

استورد os.error;
استورد os.platform.unix.apple.darwin.file_descriptors;

// getentropy(2) is the libSystem (libsystem_kernel) entry point to the
// kernel CSPRNG, in the same role as the other Darwin system-call entry
// points. One call fills at most 256 bytes and either fills the whole
// request or fails with errno.
خارجي عرف getentropy(المخزن: *متغير غ8, الحجم: غ64): ص32;

عام عرف املأ_عشوائية_نواة_داروين(المخزن: &متغير متجه غ8): نتيجة غير_موقع, خطأ_نظام_أصلي {
    دع الحجم: غير_موقع = الطول(*المخزن) مثل غير_موقع;
    دع المكتمل: متغير غير_موقع = 0;
    بينما (المكتمل < الحجم) {
        دع الجزء: متغير غير_موقع = الحجم - المكتمل;
        لو (الجزء > 256) { الجزء := 256; };
        دع الرمز: ص32 = getentropy(&متغير (*المخزن)[المكتمل], الجزء مثل غ64);
        لو (الرمز != 0) { أرجع نتيجة.خطأ(خطأ_داروين_الحالي()); };
        المكتمل := المكتمل + الجزء;
    }
    أرجع نتيجة.نجح(الحجم);
}

استورد os.buffer;
استورد os.path;
استورد os.error;

// Darwin file-descriptor provider. On macOS the supported kernel interface is
// libSystem (libsystem_kernel); the raw syscall ABI is private and unstable,
// so these are the platform's system-call entry points, in the same role as
// the Win32 provider's kernel32 declarations. No libc stdio is used.
// Variadic entry points (open/fcntl) are only called with their fixed
// arguments: on Apple arm64 variadic arguments travel on the stack.
خارجي عرف __error(): *متغير ص32;
خارجي عرف open(المسار: *غ8, الأعلام: ص32): ص32;
خارجي عرف creat(المسار: *غ8, الوضع: غ16): ص32;
خارجي عرف read(الواصف: ص32, المخزن: *متغير غ8, العدد: غ64): ص64;
خارجي عرف write(الواصف: ص32, المخزن: *غ8, العدد: غ64): ص64;
خارجي عرف close(الواصف: ص32): ص32;
خارجي عرف lseek(الواصف: ص32, الإزاحة: ص64, الأصل: ص32): ص64;
خارجي عرف fsync(الواصف: ص32): ص32;
خارجي عرف fchmod(الواصف: ص32, الوضع: غ16): ص32;
خارجي عرف rename(الأصل: *غ8, الوجهة: *غ8): ص32;
خارجي عرف unlink(المسار: *غ8): ص32;
خارجي عرف stat(المسار: *غ8, المعلومات: *متغير غ8): ص32;

عام نوع خطأ_واصف_داروين =
    | مسار بنوع خطأ_مسار_نظام
    | نطاق_غير_صالح
    | كتابة_بلا_تقدم
    | واصف_مغلق
    | نظام بنوع خطأ_نظام_أصلي
;

عام نوع واصف_ملف_داروين = { القيمة: غ64, مفتوح: منطقي };

// The single Darwin mapping onto the portable std.os boundary error.
عام عرف خطأ_واصف_داروين_للنظام(الخطأ: خطأ_واصف_داروين): خطأ_حد_نظام {
    طابق الخطأ مع
    | خطأ_واصف_داروين.مسار(_) -> { أرجع خطأ_حد_نظام.وسيط_غير_صالح(); }
    | خطأ_واصف_داروين.نطاق_غير_صالح -> { أرجع خطأ_حد_نظام.وسيط_غير_صالح(); }
    | خطأ_واصف_داروين.كتابة_بلا_تقدم -> { أرجع خطأ_حد_نظام.قيمة_خارج_النطاق(); }
    | خطأ_واصف_داروين.واصف_مغلق -> { أرجع خطأ_حد_نظام.مورد_مغلق(); }
    | خطأ_واصف_داروين.نظام(الأصلي) -> { أرجع خطأ_حد_نظام.نظام(الأصلي); };
}

// errno must be captured immediately after the failing call.
عام عرف خطأ_داروين_الحالي(): خطأ_نظام_أصلي {
    دع المؤشر: *متغير ص32 = __error();
    دع الرمز: متغير ص32 = 0;
    لو (المؤشر != الفارغ) {
        غير_آمن { الرمز := المؤشر[0]; }
    };
    أرجع أنشئ_خطأ_نظام_أصلي(مصدر_خطأ_نظام.يونكس(), الرمز مثل عدد);
}

// Calls that report failure only through errno (readdir) clear it first.
عام عرف اضبط_خطأ_داروين_صفرا(): فراغ {
    دع المؤشر: *متغير ص32 = __error();
    لو (المؤشر != الفارغ) {
        غير_آمن { المؤشر[0] := 0; }
    };
}

عرف فشل_واصف_داروين(): خطأ_واصف_داروين {
    أرجع خطأ_واصف_داروين.نظام(خطأ_داروين_الحالي());
}

// O_RDONLY | O_CLOEXEC (0x1000000). Write creation uses creat(2), which is
// open(O_CREAT|O_WRONLY|O_TRUNC, mode) without variadic arguments.
عام عرف افتح_واصف_داروين(
    المسار: &متجه غ8, للكتابة: منطقي, الوضع: غ16
): نتيجة واصف_ملف_داروين, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        دع الناتج: متغير ص32 = -1;
        لو (للكتابة) {
            الناتج := creat(&الاسم[0], الوضع);
        } وإلا {
            الناتج := open(&الاسم[0], 0x1000000);
        };
        لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
        دع الواصف: واصف_ملف_داروين = { القيمة: الناتج مثل غ64, مفتوح: صواب };
        أرجع نتيجة.نجح(الواصف);
    };
}

عام عرف اقرأ_واصف_داروين(
    الواصف: &واصف_ملف_داروين, المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
): نتيجة غ64, خطأ_واصف_داروين {
    لو (!(*الواصف).مفتوح) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.واصف_مغلق()); };
    لو (!نطاق_بايتات_نظام_صالح(الطول(*المخزن), الإزاحة, المطلوب)) {
        أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح());
    };
    لو (المطلوب == 0) { أرجع نتيجة.نجح(0); };
    // Darwin rejects transfers above INT_MAX with EINVAL.
    دع الطلب: متغير عدد = المطلوب;
    لو (الطلب > 0x7fffffff) { الطلب := 0x7fffffff; };
    دع الناتج: ص64 = read(
        (*الواصف).القيمة مثل ص32, &متغير (*المخزن)[الإزاحة مثل غير_موقع], الطلب مثل غ64
    );
    لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    أرجع نتيجة.نجح(الناتج مثل غ64);
}

عام عرف اكتب_واصف_داروين(
    الواصف: &واصف_ملف_داروين, المحتوى: &متجه غ8, الإزاحة: عدد, المطلوب: عدد
): نتيجة غ64, خطأ_واصف_داروين {
    لو (!(*الواصف).مفتوح) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.واصف_مغلق()); };
    لو (!نطاق_بايتات_نظام_صالح(الطول(*المحتوى), الإزاحة, المطلوب)) {
        أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح());
    };
    لو (المطلوب == 0) { أرجع نتيجة.نجح(0); };
    دع الطلب: متغير عدد = المطلوب;
    لو (الطلب > 0x7fffffff) { الطلب := 0x7fffffff; };
    دع الناتج: ص64 = write(
        (*الواصف).القيمة مثل ص32, &(*المحتوى)[الإزاحة مثل غير_موقع], الطلب مثل غ64
    );
    لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    أرجع نتيجة.نجح(الناتج مثل غ64);
}

// close consumes the descriptor even when it reports EINTR; never retry it.
عام عرف أغلق_واصف_داروين(
    الواصف: &متغير واصف_ملف_داروين
): نتيجة غ64, خطأ_واصف_داروين {
    لو (!(*الواصف).مفتوح) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.واصف_مغلق()); };
    دع الناتج: ص32 = close((*الواصف).القيمة مثل ص32);
    (*الواصف).مفتوح := خطأ;
    لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    أرجع نتيجة.نجح(0);
}

عام عرف حرك_واصف_داروين(
    الواصف: &واصف_ملف_داروين, الإزاحة: ص64, الأصل: غ64
): نتيجة غ64, خطأ_واصف_داروين {
    لو (!(*الواصف).مفتوح) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.واصف_مغلق()); };
    لو (الأصل > 2) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح()); };
    دع الناتج: ص64 = lseek((*الواصف).القيمة مثل ص32, الإزاحة, الأصل مثل ص32);
    لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    أرجع نتيجة.نجح(الناتج مثل غ64);
}

عام عرف زامن_واصف_داروين(الواصف: &واصف_ملف_داروين): نتيجة غ64, خطأ_واصف_داروين {
    لو (!(*الواصف).مفتوح) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.واصف_مغلق()); };
    دع الناتج: ص32 = fsync((*الواصف).القيمة مثل ص32);
    لو (الناتج < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    أرجع نتيجة.نجح(0);
}

// Raw fd 0/1/2 are borrowed from process startup; never close them here.
عام عرف اقرأ_دخل_داروين(
    المخزن: &متغير متجه غ8, الإزاحة: عدد, المطلوب: عدد
): نتيجة غ64, خطأ_واصف_داروين {
    دع الدخل: واصف_ملف_داروين = { القيمة: 0, مفتوح: صواب };
    أرجع اقرأ_واصف_داروين(&الدخل, المخزن, الإزاحة, المطلوب);
}

عام عرف اكتب_تيار_داروين(
    الواصف: غ64, المحتوى: &متجه غ8, الإزاحة: عدد, المطلوب: عدد
): نتيجة غ64, خطأ_واصف_داروين {
    لو (الواصف != 1 && الواصف != 2) {
        أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح());
    };
    دع التيار: واصف_ملف_داروين = { القيمة: الواصف, مفتوح: صواب };
    أرجع اكتب_واصف_داروين(&التيار, المحتوى, الإزاحة, المطلوب);
}

// Complete executable output: create/truncate, write every byte (retrying
// EINTR without losing partial progress), set 0755 and close exactly once.
عام عرف اكتب_بايتات_تنفيذية_داروين(
    المسار: &متجه غ8, البايتات: &متجه غ8
): نتيجة غ64, خطأ_واصف_داروين {
    دع الملف: متغير واصف_ملف_داروين;
    طابق افتح_واصف_داروين(المسار, صواب, 493) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الواصف) -> { الملف := الواصف; };
    دع الكلي: غير_موقع = الطول(*البايتات) مثل غير_موقع;
    دع المكتوب: متغير غير_موقع = 0;
    بينما (المكتوب < الكلي) {
        دع الباقي: غير_موقع = الكلي - المكتوب;
        طابق اكتب_واصف_داروين(&الملف, البايتات, المكتوب مثل عدد, الباقي مثل عدد) مع
        | نتيجة.خطأ(الخطأ) -> {
            دع إعادة: متغير منطقي = خطأ;
            طابق الخطأ مع
            | خطأ_واصف_داروين.نظام(الأصلي) -> { إعادة := الأصلي.الرمز == 4; }
            | _ -> { };
            لو (!إعادة) {
                دع التنظيف: نتيجة غ64, خطأ_واصف_داروين = أغلق_واصف_داروين(&متغير الملف);
                أرجع نتيجة.خطأ(الخطأ);
            };
        }
        | نتيجة.نجح(العدد) -> {
            لو (العدد == 0) {
                دع التنظيف: نتيجة غ64, خطأ_واصف_داروين = أغلق_واصف_داروين(&متغير الملف);
                أرجع نتيجة.خطأ(خطأ_واصف_داروين.كتابة_بلا_تقدم());
            };
            المكتوب := المكتوب + (العدد مثل غير_موقع);
        };
    }
    // creat(2) keeps an existing file's mode; make the output executable.
    لو (fchmod(الملف.القيمة مثل ص32, 493) < 0) {
        دع خطأ_الوضع: خطأ_واصف_داروين = فشل_واصف_داروين();
        دع التنظيف: نتيجة غ64, خطأ_واصف_داروين = أغلق_واصف_داروين(&متغير الملف);
        أرجع نتيجة.خطأ(خطأ_الوضع);
    };
    طابق أغلق_واصف_داروين(&متغير الملف) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    أرجع نتيجة.نجح(الكلي مثل غ64);
}

عام عرف أعد_تسمية_داروين(
    الأصل: &متجه غ8, الوجهة: &متجه غ8
): نتيجة غ64, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(الأصل) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(مخزن_الأصل) -> {
        طابق بايتات_مسار_يونكس_صفرية(الوجهة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
        | نتيجة.نجح(مخزن_الوجهة) -> {
            دع أ: متجه غ8 = مخزن_الأصل;
            دع ب: متجه غ8 = مخزن_الوجهة;
            لو (rename(&أ[0], &ب[0]) < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
            أرجع نتيجة.نجح(0);
        };
    };
}

عام عرف احذف_ملف_داروين(المسار: &متجه غ8): نتيجة غ64, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        لو (unlink(&الاسم[0]) < 0) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
        أرجع نتيجة.نجح(0);
    };
}

// struct stat on Darwin arm64 (64-bit inode layout, 144 bytes):
// st_mode u16 @4, st_mtimespec {i64 sec, i64 nsec} @48, st_size i64 @96.
عام نوع معلومات_مسار_داروين = {
    الوضع: غ16,
    الحجم: غ64,
    التعديل_بالثواني: ص64,
    التعديل_بالنانو: ص64
};

عرف اقرأ_غ64_داروين(البايتات: &متجه غ8, البداية: غير_موقع): غ64 {
    دع القيمة: متغير غ64 = 0;
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < 8) {
        دع البايت: غ64 = (*البايتات)[البداية + الفهرس] مثل غ64;
        القيمة := القيمة | (البايت << (الفهرس * 8));
        الفهرس := الفهرس + 1;
    }
    أرجع القيمة;
}

عام عرف اقرأ_معلومات_مسار_داروين(
    المسار: &متجه غ8
): نتيجة معلومات_مسار_داروين, خطأ_واصف_داروين {
    طابق بايتات_مسار_يونكس_صفرية(المسار) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(خطأ_واصف_داروين.مسار(الخطأ)); }
    | نتيجة.نجح(البايتات) -> {
        دع الاسم: متجه غ8 = البايتات;
        دع المعلومات: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < 144) { ألحق(المعلومات, 0); ف := ف + 1; }
        لو (stat(&الاسم[0], &متغير المعلومات[0]) < 0) {
            أرجع نتيجة.خطأ(فشل_واصف_داروين());
        };
        دع الوضع_الأدنى: غ16 = المعلومات[4] مثل غ16;
        دع الوضع_الأعلى: غ16 = المعلومات[5] مثل غ16;
        دع الناتج: معلومات_مسار_داروين = {
            الوضع: الوضع_الأدنى | (الوضع_الأعلى << 8),
            الحجم: اقرأ_غ64_داروين(&المعلومات, 96),
            التعديل_بالثواني: اقرأ_غ64_داروين(&المعلومات, 48) مثل ص64,
            التعديل_بالنانو: اقرأ_غ64_داروين(&المعلومات, 56) مثل ص64
        };
        أرجع نتيجة.نجح(الناتج);
    };
}

خارجي عرف getcwd(المخزن: *متغير غ8, الحجم: غ64): *متغير غ8;

// Current working directory bytes, without the terminating NUL.
عام عرف اقرأ_دليل_عمل_داروين(السعة: غير_موقع): نتيجة متجه غ8, خطأ_واصف_داروين {
    لو (السعة == 0) { أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح()); };
    // PATH_MAX is 1024 on Darwin; one extra byte holds the NUL.
    دع الحجم: غير_موقع = 1025;
    دع المخزن: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحجم) { ألحق(المخزن, 0); ف := ف + 1; }
    دع الناتج: *متغير غ8 = getcwd(&متغير المخزن[0], الحجم مثل غ64);
    لو (الناتج == الفارغ) { أرجع نتيجة.خطأ(فشل_واصف_داروين()); };
    دع المسار: متغير متجه غ8 = [];
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < الحجم && المخزن[الموضع] != 0) {
        ألحق(المسار, المخزن[الموضع]);
        الموضع := الموضع + 1;
    }
    لو ((الطول(المسار) مثل غير_موقع) > السعة) {
        أرجع نتيجة.خطأ(خطأ_واصف_داروين.نطاق_غير_صالح());
    };
    أرجع نتيجة.نجح(المسار);
}

