// SO_NOSIGPIPE prevents a disconnected client from terminating an HTTP
// server with SIGPIPE.  A failed initialization closes its descriptor.
عام عرف أنشئ_مقبس_داروين(
    العائلة: ص32, النوع: ص32, البروتوكول: ص32
): نتيجة مقبس_داروين, خطأ_مقبس_داروين {
    دع الواصف: ص32 = socket(العائلة, النوع, البروتوكول);
    لو (الواصف < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    دع نعم: ص32 = 1;
    لو (setsockopt(الواصف, 0xffff, 0x1022, &نعم, 4) < 0) {
        دع الخطأ: خطأ_مقبس_داروين = فشل_مقبس_داروين();
        دع تجاهل: ص32 = close(الواصف);
        أرجع نتيجة.خطأ(الخطأ);
    };
    دع المقبس: مقبس_داروين = { القيمة: الواصف, مفتوح: صواب };
    أرجع نتيجة.نجح(المقبس);
}

عام عرف ضع_عنوان_مقبس_داروين(
    المقبس: &مقبس_داروين, العنوان: &متجه غ8, ربط: منطقي
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    دع الحجم: غير_موقع = الطول(*العنوان) مثل غير_موقع;
    لو ((الحجم != 16 && الحجم != 28) || (*العنوان)[0] != (الحجم مثل غ8)) {
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح());
    };
    دع الحالة: ص32;
    لو (ربط) { الحالة := bind((*المقبس).القيمة, &(*العنوان)[0], الحجم مثل غ32); }
    وإلا { الحالة := connect((*المقبس).القيمة, &(*العنوان)[0], الحجم مثل غ32); };
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف استمع_مقبس_داروين(
    المقبس: &مقبس_داروين, التراكم: ص32
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح || التراكم < 0) {
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح());
    };
    دع الحالة: ص32 = listen((*المقبس).القيمة, التراكم);
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف اقبل_مقبس_داروين(
    المستمع: &مقبس_داروين
): نتيجة مقبس_داروين, خطأ_مقبس_داروين {
    لو (!(*المستمع).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    // POSIX permits NULL,NULL when the peer address is not requested.
    دع الواصف: ص32 = accept((*المستمع).القيمة, الفارغ, الفارغ);
    لو (الواصف < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    دع نعم: ص32 = 1;
    لو (setsockopt(الواصف, 0xffff, 0x1022, &نعم, 4) < 0) {
        دع الخطأ: خطأ_مقبس_داروين = فشل_مقبس_داروين();
        دع تجاهل: ص32 = close(الواصف);
        أرجع نتيجة.خطأ(الخطأ);
    };
    دع الطفل: مقبس_داروين = { القيمة: الواصف, مفتوح: صواب };
    أرجع نتيجة.نجح(الطفل);
}

عام عرف أرسل_مقبس_داروين(
    المقبس: &مقبس_داروين, المحتوى: &متجه غ8, الإزاحة: عدد, العدد: عدد
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    لو (!نطاق_بايتات_نظام_صالح(الطول(*المحتوى), الإزاحة, العدد)) {
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح());
    };
    دع الطلب: متغير عدد = العدد;
    لو (الطلب > 0x7fffffff) { الطلب := 0x7fffffff; };
    لو (الطلب == 0) { أرجع نتيجة.نجح(0); };
    دع الحالة: ص64 = send(
        (*المقبس).القيمة, &(*المحتوى)[الإزاحة مثل غير_موقع], الطلب مثل غ64, 0
    );
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف استقبل_مقبس_داروين(
    المقبس: &مقبس_داروين, المخزن: &متغير متجه غ8, الإزاحة: عدد, العدد: عدد
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    لو (!نطاق_بايتات_نظام_صالح(الطول(*المخزن), الإزاحة, العدد)) {
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح());
    };
    دع الطلب: متغير عدد = العدد;
    لو (الطلب > 0x7fffffff) { الطلب := 0x7fffffff; };
    لو (الطلب == 0) { أرجع نتيجة.نجح(0); };
    دع الحالة: ص64 = recv(
        (*المقبس).القيمة, &متغير (*المخزن)[الإزاحة مثل غير_موقع], الطلب مثل غ64, 0
    );
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف أوقف_مقبس_داروين(
    المقبس: &مقبس_داروين, الاتجاه: ص32
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    لو (الاتجاه < 0 || الاتجاه > 2) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح()); };
    دع الحالة: ص32 = shutdown((*المقبس).القيمة, الاتجاه);
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف اضبط_خيار_عدد_مقبس_داروين(
    المقبس: &مقبس_داروين, المستوى: ص32, الخيار: ص32, القيمة: ص32
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    دع المعطى: ص32 = القيمة;
    دع الحالة: ص32 = setsockopt((*المقبس).القيمة, المستوى, الخيار, &المعطى, 4);
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(الحالة مثل عدد);
}

عام عرف أغلق_مقبس_داروين(
    المقبس: &متغير مقبس_داروين
): نتيجة عدد, خطأ_مقبس_داروين {
    لو (!(*المقبس).مفتوح) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.مغلق()); };
    دع الحالة: ص32 = close((*المقبس).القيمة);
    // POSIX close, including EINTR, must never be blindly retried:
    // the file descriptor may already have been reassigned.
    (*المقبس).مفتوح := خطأ;
    لو (الحالة < 0) { أرجع نتيجة.خطأ(فشل_مقبس_داروين()); };
    أرجع نتيجة.نجح(0);
}

// POSIX getaddrinfo reports EAI_* status directly, not errno (except EAI_SYSTEM).
// Return the std.net.dns compact owned IP encoding [family, len, 0, 0, IP...].
عام عرف حل_اسم_مضيف_داروين(
    المضيف: &نص, العائلة: عدد
): نتيجة متجه غ8, خطأ_مقبس_داروين {
    لو ((العائلة != 4 && العائلة != 6) || الطول(*المضيف) == 0) {
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح());
    };
    دع الاسم: متغير متجه غ8 = [];
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < (الطول(*المضيف) مثل غير_موقع)) {
        دع البايت: غ8 = (*المضيف)[الموضع];
        لو (البايت == 0) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح()); };
        ألحق(الاسم, البايت);
        الموضع := الموضع + 1;
    }
    ألحق(الاسم, 0);
    دع القائمة: متغير *معلومات_عنوان_داروين_أصلية = الفارغ;
    دع الحالة: ص32 = getaddrinfo(&الاسم[0], الفارغ, الفارغ, &متغير القائمة);
    لو (الحالة != 0) {
        // getaddrinfo() uses the EAI_* namespace, not errno. Never turn an
        // EAI value into a fake Unix errno. The std.os boundary currently
        // exposes a generic DNS failure but not individual EAI categories.
        أرجع نتيجة.خطأ(خطأ_مقبس_داروين.حل_اسم_فشل());
    };
    دع المطلوب: ص32;
    لو (العائلة == 4) { المطلوب := 2; } وإلا { المطلوب := 30; };
    دع الحالي: متغير *معلومات_عنوان_داروين_أصلية = القائمة;
    دع الناتج: متغير متجه غ8 = [];
    دع مستمر: متغير منطقي = صواب;
    غير_آمن {
        بينما (مستمر && الحالي != الفارغ) {
            لو ((*الحالي).العائلة == المطلوب && (*الحالي).العنوان != الفارغ) {
                دع بايتات_العنوان: *غ8 = (*الحالي).العنوان;
                دع الحد: متغير غير_موقع = 0;
                دع البداية: متغير غير_موقع = 0;
                لو (العائلة == 4 && (*الحالي).الطول >= 16) {
                    الحد := 4; البداية := 4;
                } وإلا لو (العائلة == 6 && (*الحالي).الطول >= 28) {
                    الحد := 16; البداية := 8;
                };
                لو (الحد > 0) {
                    ألحق(الناتج, العائلة مثل غ8);
                    ألحق(الناتج, الحد مثل غ8);
                    ألحق(الناتج, 0); ألحق(الناتج, 0);
                    دع ف: متغير غير_موقع = 0;
                    بينما (ف < الحد) {
                        ألحق(الناتج, بايتات_العنوان[البداية + ف]);
                        ف := ف + 1;
                    }
                    مستمر := خطأ;
                } وإلا { الحالي := (*الحالي).التالي; };
            } وإلا { الحالي := (*الحالي).التالي; };
        }
    }
    freeaddrinfo(القائمة);
    لو (الطول(الناتج) == 0) { أرجع نتيجة.خطأ(خطأ_مقبس_داروين.نطاق_غير_صالح()); };
    أرجع نتيجة.نجح(الناتج);
}

// Darwin address-range reservation for std's allocator (os/allocation.sn).
// libSystem's mmap/mprotect are the supported macOS kernel interface: Apple
// does not support direct system calls, so this is the system boundary, not a
// C-runtime allocator. Addresses cross it as u64 words (void * in the C ABI).
// These calls never allocate; the allocator itself depends on them.
خارجي عرف mmap(
    العنوان: غ64, الطول: غ64, الحماية: ص32, الأعلام: ص32, الواصف: ص32, الإزاحة: ص64
): غ64;
خارجي عرف mprotect(العنوان: غ64, الطول: غ64, الحماية: ص32): ص32;

// PROT_NONE (0) with MAP_PRIVATE | MAP_ANON (0x0002 | 0x1000) reserves
// addresses without committing memory. MAP_FAILED is the all-ones word.
عام عرف احجز_عناوين_داروين(الطول: غ64): غ64 {
    دع العنوان: غ64 = mmap(0 مثل غ64, الطول, 0 مثل ص32, 0x1002 مثل ص32, -1 مثل ص32, 0 مثل ص64);
    لو (العنوان == ~(0 مثل غ64)) { أرجع 0; };
    أرجع العنوان;
}

// PROT_READ | PROT_WRITE (3) commits a page range of the reservation.
عام عرف ثبت_عناوين_داروين(العنوان: غ64, الطول: غ64): منطقي {
    أرجع mprotect(العنوان, الطول, 3 مثل ص32) == 0;
}

// MADV_FREE (5) permits the kernel to discard pages when needed. The
// mapping remains accessible, but contents must not be relied on after free.
خارجي عرف madvise(العنوان: غ64, الطول: غ64, النصيحة: ص32): ص32;
عام عرف استرد_عناوين_داروين(العنوان: غ64, الطول: غ64): منطقي {
    أرجع madvise(العنوان, الطول, 5 مثل ص32) == 0;
}

library/std/os/platform/unix/bsd/socket_:
// Shared BSD-family network address layout for Darwin and FreeBSD.
// These native sockaddr structures carry an initial length byte, unlike
// Linux sockaddr; no POSIX libc functions are called by this module.
// The caller supplies the selected target's native AF_INET6 value: Darwin
// and FreeBSD deliberately do not share that constant. It also supplies
// the target's byte order, never the compiler host's byte order.
//
// Sources: Apple XNU bsd/netinet6/in6.h, FreeBSD sys/netinet/in.h and
// sys/netinet6/in6.h: sockaddr_in is 16 bytes, sockaddr_in6 is 28 bytes.

عام نوع خطأ_عنوان_مقبس_بي_إس_دي =
    | طول_عنوان_غير_صالح
    | عائلة_غير_صالحة
;

عرف ألحق_عدد_غ32_أصلي_بي_إس_دي(
    المخزن: &متغير متجه غ8, القيمة: غ32, صغير_النهاية: منطقي
): فراغ {
    لو (صغير_النهاية) {
        ألحق(*المخزن, (القيمة & 255) مثل غ8);
        ألحق(*المخزن, ((القيمة >> 8) & 255) مثل غ8);
        ألحق(*المخزن, ((القيمة >> 16) & 255) مثل غ8);
        ألحق(*المخزن, ((القيمة >> 24) & 255) مثل غ8);
    } وإلا {
        ألحق(*المخزن, ((القيمة >> 24) & 255) مثل غ8);
        ألحق(*المخزن, ((القيمة >> 16) & 255) مثل غ8);
        ألحق(*المخزن, ((القيمة >> 8) & 255) مثل غ8);
        ألحق(*المخزن, (القيمة & 255) مثل غ8);
    };
}

// BSD sin_len=16, AF_INET=2. sin_port and the four address bytes are in
// network byte order. sockaddr_in's eight remaining bytes are zero-filled.
عام عرف عنوان_مقبس_آيبي4_بي_إس_دي(
    العنوان: &متجه غ8, المنفذ: غ16
): نتيجة متجه غ8, خطأ_عنوان_مقبس_بي_إس_دي {
    لو (الطول(*العنوان) != 4) {
        أرجع نتيجة.خطأ(خطأ_عنوان_مقبس_بي_إس_دي.طول_عنوان_غير_صالح());
    };
    دع الناتج: متغير متجه غ8 = [
        16, 2,
        ((المنفذ >> 8) & 255) مثل غ8,
        (المنفذ & 255) مثل غ8
    ];
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < 4) {
        ألحق(الناتج, (*العنوان)[الفهرس]);
        الفهرس := الفهرس + 1;
    }
    دع الحشو: متغير غير_موقع = 0;
    بينما (الحشو < 8) {
        ألحق(الناتج, 0 مثل غ8);
        الحشو := الحشو + 1;
    }
    أرجع نتيجة.نجح(الناتج);
}

// BSD sockaddr_in6: [len, family, port(be16), flowinfo(be32),
// address(16 bytes), scope_id(u32 native)]. AF_INET6 differs across
// Darwin (30) and FreeBSD (28), so it is a selected-platform input.
عام عرف عنوان_مقبس_آيبي6_بي_إس_دي(
    العنوان: &متجه غ8, المنفذ: غ16,
    معلومات_التدفق: غ32, نطاق_الواجهة: غ32,
    عائلة_آيبي6: غ8, صغير_النهاية: منطقي
): نتيجة متجه غ8, خطأ_عنوان_مقبس_بي_إس_دي {
    لو (الطول(*العنوان) != 16) {
        أرجع نتيجة.خطأ(خطأ_عنوان_مقبس_بي_إس_دي.طول_عنوان_غير_صالح());
    };
    لو (عائلة_آيبي6 != 28 && عائلة_آيبي6 != 30) {
        أرجع نتيجة.خطأ(خطأ_عنوان_مقبس_بي_إس_دي.عائلة_غير_صالحة());
    };
    دع الناتج: متغير متجه غ8 = [
        28, عائلة_آيبي6,
        ((المنفذ >> 8) & 255) مثل غ8,
        (المنفذ & 255) مثل غ8,
        ((معلومات_التدفق >> 24) & 255) مثل غ8,
        ((معلومات_التدفق >> 16) & 255) مثل غ8,
        ((معلومات_التدفق >> 8) & 255) مثل غ8,
        (معلومات_التدفق & 255) مثل غ8
    ];
    دع الفهرس: متغير غير_موقع = 0;
    بينما (الفهرس < 16) {
        ألحق(الناتج, (*العنوان)[الفهرس]);
        الفهرس := الفهرس + 1;
    }
    ألحق_عدد_غ32_أصلي_بي_إس_دي(&متغير الناتج, نطاق_الواجهة, صغير_النهاية);
    أرجع نتيجة.نجح(الناتج);
}

library/std/os/platform/unix/linux/auxil:
استورد os.platform.unix.linux.file_descriptors;
استورد os.platform.unix.linux.syscalls.operations;
استورد os.platform.unix.linux.syscalls.selection;

// ELF auxiliary entries are 2 x 64-bit words on the supported ABIs.
// AT_PAGESZ=6, AT_NULL=0. This is kernel process-startup information,
// not a syscall; /proc/self/auxv is an optional procfs view of that data.
عام نوع خطأ_متجه_مساعد_لينكس =
    | بيانات_غير_صالحة
    | مدخل_غير_موجود
    | واصف بنوع خطأ_واصف_لينكس
;

// Decode a bounded little-endian word without unaligned native loads.
عرف اقرأ_كلمة_مساعدة_لينكس(المصدر: &متجه غ8, البداية: غير_موقع): غ64 {
    دع الناتج: متغير غ64 = 0;
    دع البايت: متغير غير_موقع = 0;
    بينما (البايت < 8) {
        الناتج := الناتج | (((*المصدر)[البداية + البايت] مثل غ64) << (8 * البايت));
        البايت := البايت + 1;
    }
    أرجع الناتج;
}

// Parse actual auxiliary-vector records; absence of AT_PAGESZ never produces
// a fabricated default. A truncated vector or one lacking AT_NULL is invalid.
عام عرف قيمة_متجه_مساعد_لينكس(
    المصدر: &متجه غ8, النوع_المطلوب: غ64
): نتيجة غ64, خطأ_متجه_مساعد_لينكس {
    دع الحجم: غير_موقع = الطول(*المصدر) مثل غير_موقع;
    لو ((الحجم % 16) != 0) {
        أرجع نتيجة.خطأ(خطأ_متجه_مساعد_لينكس.بيانات_غير_صالحة());
    };
    دع الموضع: متغير غير_موقع = 0;
    دع موجود: متغير منطقي = خطأ;
    دع القيمة: متغير غ64 = 0;
