    رقم_مقبس: غ64, النطاق: غ64, النوع: غ64, البروتوكول: غ64
): نتيجة واصف_ملف_لينكس, خطأ_مقبس_لينكس {
    // Every newly owned Linux socket is close-on-exec, including sockets
    // made before spawning a child. SOCK_CLOEXEC=0x80000 is set atomically
    // by the kernel. A caller may also request SOCK_NONBLOCK in النوع.
    دع الخام: غ64 = بدائي_نداء_نواة_خام(
        رقم_نداء_نواة_لينكس(عملية_نداء_نواة_لينكس.مقبس()), النطاق, النوع | (0x80000 مثل غ64), البروتوكول,
        0 مثل غ64, 0 مثل غ64, 0 مثل غ64
    );
    طابق نتيجة_مقبس_لينكس(الخام) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> {
        دع المقبس: واصف_ملف_لينكس = { القيمة: القيمة, مفتوح: صواب };
        أرجع نتيجة.نجح(المقبس);
