// The byte at a linear-memory address, read through its aligned word (an
// aligned word never crosses the end of memory when the byte is inside it).
عرف بايت_ذاكرة_واسي(العنوان: غ64): غ8 {
    دع الكلمة: غ64 = اقرأ_كلمة_ذاكرة_واسي(((العنوان / 4) * 4) مثل غ32) مثل غ64;
    دع الإزاحة: غ64 = (العنوان % 4) * 8;
    أرجع ((الكلمة >> الإزاحة) % 256) مثل غ8;
}

عرف اقرأ_سلاسل_جدول_واسي(
    المؤشرات: &متجه غ32,
    العدد: غير_موقع,
    حجم_المخزن: غير_موقع
): نتيجة متجه متجه غ8, خطأ_واصف_واسي {
    دع نهاية_الذاكرة: غ64 = (حجم_ذاكرة_واسي(0) مثل غ64) * 65536;
    دع المتبقي: متغير غ64 = حجم_المخزن مثل غ64;
    دع الناتج: متغير متجه متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        دع العنوان: متغير غ64 = (*المؤشرات)[ف] مثل غ64;
        دع السلسلة: متغير متجه غ8 = [];
        دع انتهت: متغير منطقي = خطأ;
        بينما (!انتهت) {
            // Every string, terminator included, lies in the host buffer.
            لو (المتبقي == 0 || العنوان >= نهاية_الذاكرة) {
                أرجع نتيجة.خطأ(خطأ_واصف_واسي.نطاق_غير_صالح());
            };
            المتبقي := المتبقي - 1;
            دع البايت: غ8 = بايت_ذاكرة_واسي(العنوان);
            لو (البايت == 0) {
                انتهت := صواب;
