    دع المؤشرات: متغير متجه غ32 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف <= (العدد[0] مثل غير_موقع)) { ألحق(المؤشرات, 0 مثل غ32); ف := ف + 1; }
    دع المخزن: متغير متجه غ8 = [];
    ف := 0;
    بينما (ف <= (الحجم[0] مثل غير_موقع)) { ألحق(المخزن, 0 مثل غ8); ف := ف + 1; }
    لو (بيئة) {
        الرمز := environ_get(&متغير المؤشرات[0], &متغير المخزن[0]);
    } وإلا {
        الرمز := args_get(&متغير المؤشرات[0], &متغير المخزن[0]);
    };
    لو (الرمز != 0) { أرجع نتيجة.خطأ(خطأ_رقم_واسي(الرمز)); };
    // The buffer stays owned (and unmoved) here while its strings are read.
    أرجع اقرأ_سلاسل_جدول_واسي(&المؤشرات, العدد[0] مثل غير_موقع, الحجم[0] مثل غير_موقع);
}

عام عرف اقرأ_وسائط_واسي(): نتيجة متجه متجه غ8, خطأ_واصف_واسي {
    أرجع اقرأ_سلاسل_إقلاع_واسي(خطأ);
