// macOS: libSystem's getpagesize/mmap/munmap/mprotect/mlock/munlock/madvise
// are the supported kernel interface (Apple supports no direct system calls).
// Failures are -1 with the reason in errno, captured right after the call.
لو (الهدف.المنصة == «macos») {
    استورد os.platform.unix.apple.darwin.file_descriptors;

    خارجي عرف getpagesize(): ص32;
    خارجي عرف mmap(
        العنوان: غ64, الطول: غ64, الحماية: ص32, الأعلام: ص32, الواصف: ص32, الإزاحة: ص64
    ): غ64;
    خارجي عرف mprotect(العنوان: غ64, الطول: غ64, الحماية: ص32): ص32;
    خارجي عرف madvise(العنوان: غ64, الطول: غ64, النصيحة: ص32): ص32;
    خارجي عرف munmap(العنوان: غ64, الطول: غ64): ص32;
    خارجي عرف mlock(العنوان: غ64, الطول: غ64): ص32;
    خارجي عرف munlock(العنوان: غ64, الطول: غ64): ص32;

    عرف نتيجة_نداء_ذاكرة_داروين(الحالة: ص32): نتيجة عدد, خطأ_حد_نظام {
        لو (الحالة == (-1 مثل ص32)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(خطأ_داروين_الحالي()));
        };
        أرجع نتيجة.نجح(0);
    }
    عرف منطقة_داروين_صالحة(المنطقة: &ربط_ذاكرة_نظام): منطقي {
        أرجع (*المنطقة).نشط && (*المنطقة).الطول > 0;
    }
    عام عرف حجم_صفحة_تشغيل_نظام(): نتيجة عدد, خطأ_حد_نظام {
        دع الحجم: ص32 = getpagesize();
        لو (الحجم <= (0 مثل ص32)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.قيمة_خارج_النطاق());
        };
        أرجع نتيجة.نجح(الحجم مثل عدد);
    }
    عام عرف اربط_ذاكرة_تشغيل_نظام(
        الطول: عدد, الحماية: عدد
    ): نتيجة ربط_ذاكرة_نظام, خطأ_حد_نظام {
        لو (الطول <= 0 || الحماية < 0 || الحماية > 7) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        // MAP_PRIVATE | MAP_ANON (0x0002 | 0x1000), fd=-1, offset=0. PROT_* bits
        // (read 1, write 2, exec 4) are the same as on Linux.
        دع العنوان: غ64 = mmap(
            0 مثل غ64, الطول مثل غ64, الحماية مثل ص32, 0x1002 مثل ص32, -1 مثل ص32, 0 مثل ص64
        );
        لو (العنوان == ~(0 مثل غ64)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.نظام(خطأ_داروين_الحالي()));
        };
        دع الربط: ربط_ذاكرة_نظام = { العنوان: العنوان, الطول: الطول مثل غ64, نشط: صواب };
        أرجع نتيجة.نجح(الربط);
    }
    عام عرف الغ_ربط_ذاكرة_تشغيل_نظام(
        المنطقة: &متغير ربط_ذاكرة_نظام
    ): نتيجة عدد, خطأ_حد_نظام {
        لو (!(*المنطقة).نشط) { أرجع نتيجة.خطأ(خطأ_حد_نظام.مورد_مغلق()); };
        لو ((*المنطقة).الطول == 0) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        دع النتيجة: نتيجة عدد, خطأ_حد_نظام = نتيجة_نداء_ذاكرة_داروين(
            munmap((*المنطقة).العنوان, (*المنطقة).الطول)
        );
        طابق النتيجة مع
        | نتيجة.نجح(_) -> { (*المنطقة).نشط := خطأ; }
        | نتيجة.خطأ(_) -> { };
        أرجع النتيجة;
    }
    عام عرف احم_ذاكرة_تشغيل_نظام(
        المنطقة: &ربط_ذاكرة_نظام, الحماية: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        لو (الحماية < 0 || الحماية > 7 || !منطقة_داروين_صالحة(المنطقة)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        أرجع نتيجة_نداء_ذاكرة_داروين(
            mprotect((*المنطقة).العنوان, (*المنطقة).الطول, الحماية مثل ص32)
        );
    }
    عام عرف اقفل_ذاكرة_تشغيل_نظام(
        المنطقة: &ربط_ذاكرة_نظام
    ): نتيجة عدد, خطأ_حد_نظام {
        لو (!منطقة_داروين_صالحة(المنطقة)) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        أرجع نتيجة_نداء_ذاكرة_داروين(mlock((*المنطقة).العنوان, (*المنطقة).الطول));
    }
    عام عرف الغ_قفل_ذاكرة_تشغيل_نظام(
        المنطقة: &ربط_ذاكرة_نظام
    ): نتيجة عدد, خطأ_حد_نظام {
        لو (!منطقة_داروين_صالحة(المنطقة)) { أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح()); };
        أرجع نتيجة_نداء_ذاكرة_داروين(munlock((*المنطقة).العنوان, (*المنطقة).الطول));
    }
    // POSIX_MADV_* / MADV_* 0..4 (normal, random, sequential, willneed,
    // dontneed) are the same numbers on Darwin and Linux.
    عام عرف انصح_ذاكرة_تشغيل_نظام(
        المنطقة: &ربط_ذاكرة_نظام, النصيحة: عدد
    ): نتيجة عدد, خطأ_حد_نظام {
        لو (النصيحة < 0 || النصيحة > 4 || !منطقة_داروين_صالحة(المنطقة)) {
            أرجع نتيجة.خطأ(خطأ_حد_نظام.وسيط_غير_صالح());
        };
        أرجع نتيجة_نداء_ذاكرة_داروين(
            madvise((*المنطقة).العنوان, (*المنطقة).الطول, النصيحة مثل ص32)
        );
    }
}

