// Splits LF/CRLF text into logical lines. A final line terminator does not
// synthesize an additional empty line; interior empty lines are preserved.
عام عرف أسطر_النص(القيمة: &نص): متجه نص {
    دع النص: نص = *القيمة;
    دع العدد: غير_موقع = الطول(النص) مثل غير_موقع;
    دع الناتج: متغير متجه نص = [];
    دع البداية: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        لو (النص[ف] == 0x0A) {
            دع النهاية: متغير غير_موقع = ف;
            لو (النهاية > البداية) {
                دع السابق: غير_موقع = النهاية - 1;
                لو (النص[السابق] == 0x0D) { النهاية := السابق; };
            };
            طابق مقطع_نص(&النص, البداية, النهاية - البداية) مع
            | اختيار.بعض(السطر) -> { ألحق(الناتج, السطر); }
            | اختيار.لا_شيء -> { };
            البداية := ف + 1;
        };
        ف := ف + 1;
    }
    لو (البداية < العدد) {
        طابق مقطع_نص(&النص, البداية, العدد - البداية) مع
        | اختيار.بعض(السطر) -> { ألحق(الناتج, السطر); }
        | اختيار.لا_شيء -> { };
    };
    أرجع الناتج;
}

عام عرف كرر_النص(القيمة: &نص, المرات: غير_موقع): نص {
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    دع العدد: غير_موقع = الطول(*القيمة) مثل غير_موقع;
    لو ((العدد == 0) || (المرات == 0)) { أرجع «»; };
    بينما (ف < المرات) {
        ألحق_نطاق_نص(&متغير البايتات, القيمة, 0, العدد);
        ف := ف + 1;
    }
    أرجع من_بايتات(&البايتات);
}

عام مرادف lines = أسطر_النص;
عام مرادف repeat_text = كرر_النص;

library/std/time/calendar.sn:
// Proleptic Gregorian calendar helpers for years 0000..9999.
عام نوع يوم_الأسبوع =
    | الأحد
    | الاثنين
    | الثلاثاء
    | الأربعاء
    | الخميس
    | الجمعة
    | السبت
;

عام نوع تاريخ_تقويمي = {
    السنة: عدد,
    الشهر: غير_موقع,
    اليوم: غير_موقع
};

عام عرف سنة_كبيسة(السنة: عدد): منطقي {
    لو ((السنة % 400) == 0) { أرجع صواب; };
    لو ((السنة % 100) == 0) { أرجع خطأ; };
    أرجع (السنة % 4) == 0;
}

عام عرف أيام_في_الشهر(السنة: عدد, الشهر: غير_موقع): غير_موقع {
    لو ((الشهر == 1) || (الشهر == 3) || (الشهر == 5) || (الشهر == 7)
        || (الشهر == 8) || (الشهر == 10) || (الشهر == 12)) { أرجع 31; };
    لو ((الشهر == 4) || (الشهر == 6) || (الشهر == 9) || (الشهر == 11)) { أرجع 30; };
    لو (الشهر == 2) {
        لو (سنة_كبيسة(السنة)) { أرجع 29; };
        أرجع 28;
    };
    أرجع 0;
}

عام عرف تاريخ_تقويمي_صالح(التاريخ: &تاريخ_تقويمي): منطقي {
    لو (((*التاريخ).السنة < 0) || ((*التاريخ).السنة > 9999)) { أرجع خطأ; };
    لو (((*التاريخ).الشهر < 1) || ((*التاريخ).الشهر > 12)) { أرجع خطأ; };
    دع الحد: غير_موقع = أيام_في_الشهر((*التاريخ).السنة, (*التاريخ).الشهر);
    أرجع ((*التاريخ).اليوم >= 1) && ((*التاريخ).اليوم <= الحد);
}

عام عرف أنشئ_تاريخا_تقويميا(السنة: عدد, الشهر: غير_موقع, اليوم: غير_موقع): اختيار تاريخ_تقويمي {
    دع الناتج: تاريخ_تقويمي = { السنة: السنة, الشهر: الشهر, اليوم: اليوم };
    لو (!تاريخ_تقويمي_صالح(&الناتج)) { أرجع اختيار.لا_شيء(); };
    أرجع اختيار.بعض(الناتج);
}

عرف أيام_قبل_السنة(السنة: عدد): عدد {
    // Number of days in Gregorian years [0000, السنة).
    أرجع (السنة * 365)
        + ((السنة + 3) / 4)
        - ((السنة + 99) / 100)
        + ((السنة + 399) / 400);
}

عرف أيام_قبل_الشهر(السنة: عدد, الشهر: غير_موقع): غير_موقع {
    دع الناتج: متغير غير_موقع = 0;
    دع ش: متغير غير_موقع = 1;
    بينما (ش < الشهر) {
        الناتج := الناتج + أيام_في_الشهر(السنة, ش);
        ش := ش + 1;
    }
    أرجع الناتج;
}

عام عرف ترتيب_اليوم_في_السنة(التاريخ: &تاريخ_تقويمي): اختيار غير_موقع {
    لو (!تاريخ_تقويمي_صالح(التاريخ)) { أرجع اختيار.لا_شيء(); };
    دع السابق: غير_موقع = أيام_قبل_الشهر((*التاريخ).السنة, (*التاريخ).الشهر);
    أرجع اختيار.بعض(السابق + (*التاريخ).اليوم);
}

عام عرف أيام_يونكس_من_التاريخ(التاريخ: &تاريخ_تقويمي): اختيار عدد {
    لو (!تاريخ_تقويمي_صالح(التاريخ)) { أرجع اختيار.لا_شيء(); };
    دع المطلقة: عدد = أيام_قبل_السنة((*التاريخ).السنة)
        + (أيام_قبل_الشهر((*التاريخ).السنة, (*التاريخ).الشهر) مثل عدد)
        + ((*التاريخ).اليوم مثل عدد) - 1;
    دع أصل_يونكس: عدد = أيام_قبل_السنة(1970);
    أرجع اختيار.بعض(المطلقة - أصل_يونكس);
}

عام عرف تاريخ_من_أيام_يونكس(الأيام: عدد): اختيار تاريخ_تقويمي {
    دع أصل_يونكس: عدد = أيام_قبل_السنة(1970);
    دع المطلقة: عدد = الأيام + أصل_يونكس;
    لو (المطلقة < 0) { أرجع اختيار.لا_شيء(); };
    دع نهاية_النطاق: عدد = أيام_قبل_السنة(10000);
    لو (المطلقة >= نهاية_النطاق) { أرجع اختيار.لا_شيء(); };

    دع الأدنى: متغير عدد = 0;
    دع الأعلى: متغير عدد = 10000;
    بينما ((الأدنى + 1) < الأعلى) {
        دع الوسط: عدد = (الأدنى + الأعلى) / 2;
        لو (أيام_قبل_السنة(الوسط) <= المطلقة) {
            الأدنى := الوسط;
        } وإلا {
            الأعلى := الوسط;
        };
    }

    دع السنة: عدد = الأدنى;
    دع المتبقي: متغير غير_موقع = (المطلقة - أيام_قبل_السنة(السنة)) مثل غير_موقع;
    دع الشهر: متغير غير_موقع = 1;
    بينما (الشهر <= 12) {
        دع أيام_الشهر: غير_موقع = أيام_في_الشهر(السنة, الشهر);
        لو (المتبقي < أيام_الشهر) {
            دع الناتج: تاريخ_تقويمي = {
                السنة: السنة,
                الشهر: الشهر,
                اليوم: المتبقي + 1
            };
            أرجع اختيار.بعض(الناتج);
        };
        المتبقي := المتبقي - أيام_الشهر;
        الشهر := الشهر + 1;
    }
    أرجع اختيار.لا_شيء();
}

عام عرف يوم_الأسبوع_للتاريخ(التاريخ: &تاريخ_تقويمي): اختيار يوم_الأسبوع {
    طابق أيام_يونكس_من_التاريخ(التاريخ) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأيام) -> {
        دع الرقم: متغير عدد = (الأيام + 4) % 7;
        لو (الرقم < 0) { الرقم := الرقم + 7; };
        لو (الرقم == 0) { أرجع اختيار.بعض(يوم_الأسبوع.الأحد()); };
        لو (الرقم == 1) { أرجع اختيار.بعض(يوم_الأسبوع.الاثنين()); };
        لو (الرقم == 2) { أرجع اختيار.بعض(يوم_الأسبوع.الثلاثاء()); };
        لو (الرقم == 3) { أرجع اختيار.بعض(يوم_الأسبوع.الأربعاء()); };
        لو (الرقم == 4) { أرجع اختيار.بعض(يوم_الأسبوع.الخميس()); };
        لو (الرقم == 5) { أرجع اختيار.بعض(يوم_الأسبوع.الجمعة()); };
        أرجع اختيار.بعض(يوم_الأسبوع.السبت());
    };
}

