library/std/tls/key_exchange.sn:
// Ephemeral (EC)DHE key shares for the TLS 1.3 client and server (RFC 8446
// 4.2.8): X25519 (RFC 7748) and the NIST curves secp256r1 and secp384r1
// (uncompressed SEC 1 points, 4.2.8.2). Private keys come from the system
// random source; the computations are constant time (crypto.x25519,
// crypto.ecdsa). A peer share of the wrong size, an invalid curve point or an
// all-zero X25519 result fails with illegal_parameter.

استورد crypto.ecdsa;
استورد crypto.words;
استورد crypto.x25519;
استورد tls.errors;
استورد tls.record;
استورد tls.wire;

عام نوع مشاركة_مفتاح_تي_إل_إس = {
    المجموعة: غير_موقع,
    الخاص: متجه غ8,
    العام: متجه غ8
};

عام عرف مجموعة_مدعومة_تي_إل_إس(المجموعة: غير_موقع): منطقي {
    أرجع المجموعة == مجموعة_إكس25519_تي_إل_إس()
        || المجموعة == مجموعة_بي256_تي_إل_إس()
        || المجموعة == مجموعة_بي384_تي_إل_إس();
}

عرف منحنى_مجموعة_تي_إل_إس(المجموعة: غير_موقع): منحنى_إهليلجي {
    لو (المجموعة == مجموعة_بي384_تي_إل_إس()) { أرجع منحنى_إهليلجي.منحنى_بي384(); };
    أرجع منحنى_إهليلجي.منحنى_بي256();
}

عرف حجم_مجموعة_تي_إل_إس(المجموعة: غير_موقع): غير_موقع {
    لو (المجموعة == مجموعة_بي384_تي_إل_إس()) { أرجع 48; };
    أرجع 32;
}

// A fresh key pair for المجموعة.
عام عرف أنشئ_مشاركة_مفتاح_تي_إل_إس(المجموعة: غير_موقع): نتيجة مشاركة_مفتاح_تي_إل_إس, عدد {
    لو (!مجموعة_مدعومة_تي_إل_إس(المجموعة)) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
    دع الحجم: غير_موقع = حجم_مجموعة_تي_إل_إس(المجموعة);
    // A random scalar outside [1, n) has probability below 2^-32 on these
    // curves; a few draws always suffice.
    دع المحاولة: متغير غير_موقع = 0;
    بينما (المحاولة < 8) {
        طابق بايتات_عشوائية_تي_إل_إس(الحجم) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الخاص) -> {
            لو (المجموعة == مجموعة_إكس25519_تي_إل_إس()) {
                دع العام: متجه غ8 = مفتاح_عام_إكس25519(&الخاص);
                دع المشاركة: مشاركة_مفتاح_تي_إل_إس = { المجموعة: المجموعة, الخاص: الخاص, العام: العام };
                أرجع نتيجة.نجح(المشاركة);
            };
            طابق مفتاح_عام_إي_سي_دي_إس_إيه(منحنى_مجموعة_تي_إل_إس(المجموعة), &الخاص) مع
            | اختيار.لا_شيء -> { }
            | اختيار.بعض(العام) -> {
                دع المشاركة: مشاركة_مفتاح_تي_إل_إس = { المجموعة: المجموعة, الخاص: الخاص, العام: العام };
                أرجع نتيجة.نجح(المشاركة);
            };
        };
        المحاولة := المحاولة + 1;
    }
    أرجع نتيجة.خطأ(خطأ_عشوائية_تي_إل_إس());
}

// The shared secret with the peer's share (the x-coordinate for the NIST
// curves, RFC 8446 7.4.2).
عام عرف سر_مشاركة_مفتاح_تي_إل_إس(المشاركة: &مشاركة_مفتاح_تي_إل_إس, النظير: &متجه غ8): نتيجة متجه غ8, عدد {
    دع المجموعة: غير_موقع = (*المشاركة).المجموعة;
    دع الحجم: غير_موقع = حجم_مجموعة_تي_إل_إس(المجموعة);
    لو (المجموعة == مجموعة_إكس25519_تي_إل_إس()) {
        لو ((الطول(*النظير) مثل غير_موقع) != 32) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        دع المشترك: متغير متجه غ8 = إكس25519(&(*المشاركة).الخاص, النظير);
        لو (سر_إكس25519_صفري(&المشترك)) {
            امسح_بايتات_تشفير(&متغير المشترك);
            أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
        };
        أرجع نتيجة.نجح(المشترك);
    };
    لو ((الطول(*النظير) مثل غير_موقع) != 2 * الحجم + 1) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    طابق اتفاق_إي_سي_دي_إتش(منحنى_مجموعة_تي_إل_إس(المجموعة), &(*المشاركة).الخاص, النظير) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); }
    | اختيار.بعض(المشترك) -> { أرجع نتيجة.نجح(المشترك); };
}

// Erases the private key.
عام عرف امسح_مشاركة_مفتاح_تي_إل_إس(المشاركة: &متغير مشاركة_مفتاح_تي_إل_إس): فراغ {
    امسح_بايتات_تشفير(&متغير (*المشاركة).الخاص);
}

library/std/tls/pkcs12.sn:
// PKCS#12 server identities (RFC 7292) and their private keys for the TLS
// server: PKCS#8 (RFC 5958) holding an RSA key (RFC 8017 A.1.2), an ECDSA
// P-256/P-384 key (RFC 5915, RFC 5480) or an Ed25519 key (RFC 8410).
//
// Supported protections: PBES2 with PBKDF2 (HMAC-SHA1/SHA-256/SHA-384/
// SHA-512) and AES-CBC (RFC 8018), the OpenSSL 3 default; and the legacy
// PKCS#12 PBE schemes pbeWithSHAAnd3-KeyTripleDES-CBC, pbeWithSHAAnd128BitRC2
// and pbeWithSHAAnd40BitRC2 with the RFC 7292 Appendix B key derivation,
// which LibreSSL and older OpenSSL produce. The MacData integrity check is
// verified whenever present, so a wrong password fails before any key is
// used. BER encodings (indefinite lengths, constructed strings), which
// Windows and Java write, are normalized to DER first (encoding.der).
// Previously only RSA keys and DER containers were accepted.

استورد crypto.aes;
استورد crypto.des;
استورد crypto.digest;
استورد crypto.ecdsa;
استورد crypto.ed25519;
استورد crypto.rc2;
استورد crypto.rsa;
استورد crypto.words;
استورد encoding.der;
استورد encoding.utf16;
استورد text.from_bytes;
استورد tls.errors;
استورد tls.x509;

// An ECDSA private scalar: big-endian bytes of the curve size.
عام نوع مفتاح_إي_سي_خاص_تي_إل_إس = {
    المنحنى: منحنى_إهليلجي,
    الخاص: متجه غ8
};

عام نوع مفتاح_خاص_تي_إل_إس =
    | مفتاح_خاص_آر_إس_إيه بنوع مفتاح_آر_إس_إيه_خاص
    | مفتاح_خاص_إي_سي بنوع مفتاح_إي_سي_خاص_تي_إل_إس
    // The 32-byte Ed25519 seed.
    | مفتاح_خاص_إد25519 بنوع متجه غ8
;

عام نوع هوية_محللة_تي_إل_إس = {
    المفتاح: مفتاح_خاص_تي_إل_إس,
    السلسلة: متجه متجه غ8
};

عرف معرف_بي_كي_سي_إس12(المصدر: &متجه غ8, العنصر: &عنصر_دي_إي_آر, النص: نص): منطقي {
    دع المتوقع: متجه غ8 = معرف_كائن_من_نص(النص);
    أرجع معرف_كائن_يساوي_دي_إي_آر(المصدر, العنصر, &المتوقع);
}

// The password as a NUL-terminated big-endian BMPString (RFC 7292 B.1).
عرف كلمة_مرور_بي_إم_بي_بي_كي_سي_إس12(كلمة_المرور: &متجه غ8): اختيار متجه غ8 {
    دع النص: نص = من_بايتات(كلمة_المرور);
    طابق نص_إلى_يوتيف16(&النص) مع
    | نتيجة.خطأ(_) -> { أرجع اختيار.لا_شيء(); }
    | نتيجة.نجح(الوحدات) -> {
        دع الناتج: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(الوحدات) مثل غير_موقع)) {
            دع الوحدة: غير_موقع = الوحدات[ف] مثل غير_موقع;
            ألحق(الناتج, (الوحدة >> 8) مثل غ8);
            ألحق(الناتج, (الوحدة & 0xFF) مثل غ8);
            ف := ف + 1;
        }
        ألحق(الناتج, 0 مثل غ8);
        ألحق(الناتج, 0 مثل غ8);
        أرجع اختيار.بعض(الناتج);
    };
}

عرف كرر_إلى_كتل_بي_كي_سي_إس12(البيانات: &متجه غ8, الكتلة: غير_موقع): متجه غ8 {
    دع الحجم: غير_موقع = الطول(*البيانات) مثل غير_موقع;
    دع الناتج: متغير متجه غ8 = [];
    لو (الحجم == 0) { أرجع الناتج; };
    دع الكلي: غير_موقع = الكتلة * ((الحجم + الكتلة - 1) / الكتلة);
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الكلي) {
        ألحق(الناتج, (*البيانات)[ف % الحجم]);
        ف := ف + 1;
    }
    أرجع الناتج;
}

// Key material derivation of RFC 7292 Appendix B.2 (ID 1 key, 2 IV, 3 MAC).
عام عرف اشتق_بي_كي_سي_إس12(
    الخوارزمية: خوارزمية_تجزئة,
    المعرف: غير_موقع,
    كلمة_المرور: &متجه غ8,
    الملح: &متجه غ8,
    التكرارات: غير_موقع,
    الطول_المطلوب: غير_موقع
): متجه غ8 {
    دع يو: غير_موقع = حجم_ملخص_تجزئة(الخوارزمية);
    دع في: غير_موقع = حجم_كتلة_تجزئة(الخوارزمية);
    دع دي: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < في) {
        ألحق(دي, المعرف مثل غ8);
        ف := ف + 1;
    }
    دع كتلة_آي: متغير متجه غ8 = كرر_إلى_كتل_بي_كي_سي_إس12(الملح, في);
    دع جزء_كلمة: متجه غ8 = كرر_إلى_كتل_بي_كي_سي_إس12(كلمة_المرور, في);
    ألحق_بايتات_تشفير(&متغير كتلة_آي, &جزء_كلمة);
    دع الناتج: متغير متجه غ8 = [];
    بينما ((الطول(الناتج) مثل غير_موقع) < الطول_المطلوب) {
        دع المدخل: متغير متجه غ8 = [];
        ألحق_بايتات_تشفير(&متغير المدخل, &دي);
        ألحق_بايتات_تشفير(&متغير المدخل, &كتلة_آي);
        دع أ: متغير متجه غ8 = جزئ_تشفير(الخوارزمية, &المدخل);
        دع ر: متغير غير_موقع = 1;
        بينما (ر < التكرارات) {
            أ := جزئ_تشفير(الخوارزمية, &أ);
            ر := ر + 1;
        }
        ف := 0;
        بينما (ف < يو && (الطول(الناتج) مثل غير_موقع) < الطول_المطلوب) {
