    طابق اقرأ_جذر_دي_إي_آر(البيانات) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
    | اختيار.بعض(الجذر) -> {
        طابق أبناء_بوسم_دي_إي_آر(البيانات, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
        | اختيار.بعض(الحقول) -> {
            لو ((الطول(الحقول) مثل غير_موقع) < 3) { أرجع نتيجة.خطأ(تالف); };
            لو (الحقول[2].الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر()) { أرجع نتيجة.خطأ(تالف); };
            دع الداخلي: متغير متجه غ8 = محتوى_دي_إي_آر(البيانات, &الحقول[2]);
            طابق أبناء_بوسم_دي_إي_آر(البيانات, &الحقول[1], وسم_تسلسل_دي_إي_آر()) مع
            | اختيار.لا_شيء -> { امسح_بايتات_تشفير(&متغير الداخلي); أرجع نتيجة.خطأ(تالف); }
            | اختيار.بعض(الخوارزمية) -> {
                دع العدد: غير_موقع = الطول(الخوارزمية) مثل غير_موقع;
                لو (العدد == 0) { امسح_بايتات_تشفير(&متغير الداخلي); أرجع نتيجة.خطأ(تالف); };
                دع الناتج: متغير نتيجة مفتاح_خاص_تي_إل_إس, عدد = نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس());
                لو (معرف_بي_كي_سي_إس12(البيانات, &الخوارزمية[0], «1.2.840.113549.1.1.1»)) {
                    طابق حلل_مفتاح_آر_إس_إيه_خاص_تي_إل_إس(&الداخلي) مع
                    | نتيجة.خطأ(الخطأ) -> { الناتج := نتيجة.خطأ(الخطأ); }
                    | نتيجة.نجح(المفتاح) -> { الناتج := نتيجة.نجح(مفتاح_خاص_تي_إل_إس.مفتاح_خاص_آر_إس_إيه(المفتاح)); };
                } وإلا لو (العدد == 2 && معرف_بي_كي_سي_إس12(البيانات, &الخوارزمية[0], «1.2.840.10045.2.1»)) {
                    لو (معرف_بي_كي_سي_إس12(البيانات, &الخوارزمية[1], «1.2.840.10045.3.1.7»)) {
                        الناتج := حلل_مفتاح_إي_سي_خاص_تي_إل_إس(&الداخلي, منحنى_إهليلجي.منحنى_بي256());
                    } وإلا لو (معرف_بي_كي_سي_إس12(البيانات, &الخوارزمية[1], «1.3.132.0.34»)) {
                        الناتج := حلل_مفتاح_إي_سي_خاص_تي_إل_إس(&الداخلي, منحنى_إهليلجي.منحنى_بي384());
                    };
                } وإلا لو (العدد == 1 && معرف_بي_كي_سي_إس12(البيانات, &الخوارزمية[0], «1.3.101.112»)) {
                    // CurvePrivateKey ::= OCTET STRING (RFC 8410 7).
                    طابق اقرأ_جذر_دي_إي_آر(&الداخلي) مع
                    | اختيار.لا_شيء -> { الناتج := نتيجة.خطأ(تالف); }
                    | اختيار.بعض(البذرة_المرمزة) -> {
                        دع البذرة: متغير متجه غ8 = محتوى_دي_إي_آر(&الداخلي, &البذرة_المرمزة);
                        لو (البذرة_المرمزة.الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر() || (الطول(البذرة) مثل غير_موقع) != 32) {
                            امسح_بايتات_تشفير(&متغير البذرة);
                            الناتج := نتيجة.خطأ(تالف);
                        } وإلا {
                            الناتج := نتيجة.نجح(مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إد25519(البذرة));
                        };
                    };
                };
                امسح_بايتات_تشفير(&متغير الداخلي);
                أرجع الناتج;
            };
        };
    };
}

// The value of an [0] IMPLICIT OCTET STRING: primitive (DER) or, in BER, a
// constructed element whose primitive OCTET STRING segments are joined.
عرف سلسلة_ضمنية_بي_كي_سي_إس12(المصدر: &متجه غ8, العنصر: &عنصر_دي_إي_آر): اختيار متجه غ8 {
    لو ((*العنصر).الوسم == وسم_سياق_بسيط_دي_إي_آر(0)) { أرجع اختيار.بعض(محتوى_دي_إي_آر(المصدر, العنصر)); };
    لو ((*العنصر).الوسم != وسم_سياق_مركب_دي_إي_آر(0)) { أرجع اختيار.لا_شيء(); };
    طابق أبناء_دي_إي_آر(المصدر, العنصر) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(المقاطع) -> {
        دع الناتج: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(المقاطع) مثل غير_موقع)) {
            لو (المقاطع[ف].الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر()) { أرجع اختيار.لا_شيء(); };
            دع الجزء: متجه غ8 = محتوى_دي_إي_آر(المصدر, &المقاطع[ف]);
            ألحق_بايتات_تشفير(&متغير الناتج, &الجزء);
            ف := ف + 1;
        }
        أرجع اختيار.بعض(الناتج);
    };
}

// Content of a ContentInfo of type id-data: the OCTET STRING inside [0].
عرف بيانات_معلومات_المحتوى_بي_كي_سي_إس12(المصدر: &متجه غ8, المعلومات: &متجه عنصر_دي_إي_آر): اختيار متجه غ8 {
    لو ((الطول(*المعلومات) مثل غير_موقع) != 2) { أرجع اختيار.لا_شيء(); };
    طابق أبناء_بوسم_دي_إي_آر(المصدر, &(*المعلومات)[1], وسم_سياق_مركب_دي_إي_آر(0)) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الغلاف) -> {
        لو ((الطول(الغلاف) مثل غير_موقع) != 1 || الغلاف[0].الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر()) { أرجع اختيار.لا_شيء(); };
        أرجع اختيار.بعض(محتوى_دي_إي_آر(المصدر, &الغلاف[0]));
    };
}

// Collects keys and certificates from one SafeContents.
عرف اجمع_حقائب_بي_كي_سي_إس12(
    المدخل_الخام: &متجه غ8,
    كلمة_المرور: &متجه غ8,
    كلمة_بي_إم_بي: &متجه غ8,
    المفاتيح: &متغير متجه مفتاح_خاص_تي_إل_إس,
    الشهادات: &متغير متجه متجه غ8
): نتيجة عدد, عدد {
    دع تالف: عدد = خطأ_ترميز_تي_إل_إس();
    // Decrypted SafeContents may be BER as well.
    دع الموحدة: متجه غ8;
    طابق حول_بي_إي_آر_إلى_دي_إي_آر(المدخل_الخام) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
    | اختيار.بعض(القيمة) -> { الموحدة := القيمة; };
    دع المحتويات: &متجه غ8 = &الموحدة;
    طابق اقرأ_جذر_دي_إي_آر(المحتويات) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
    | اختيار.بعض(الجذر) -> {
        طابق أبناء_بوسم_دي_إي_آر(المحتويات, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
        | اختيار.بعض(الحقائب) -> {
            دع ف: متغير غير_موقع = 0;
            بينما (ف < (الطول(الحقائب) مثل غير_موقع)) {
                طابق أبناء_بوسم_دي_إي_آر(المحتويات, &الحقائب[ف], وسم_تسلسل_دي_إي_آر()) مع
                | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                | اختيار.بعض(الحقيبة) -> {
                    لو ((الطول(الحقيبة) مثل غير_موقع) < 2) { أرجع نتيجة.خطأ(تالف); };
                    طابق أبناء_بوسم_دي_إي_آر(المحتويات, &الحقيبة[1], وسم_سياق_مركب_دي_إي_آر(0)) مع
                    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                    | اختيار.بعض(القيمة) -> {
                        لو ((الطول(القيمة) مثل غير_موقع) != 1) { أرجع نتيجة.خطأ(تالف); };
                        دع الترميز: متجه غ8 = ترميز_كامل_دي_إي_آر(المحتويات, &القيمة[0]);
                        لو (معرف_بي_كي_سي_إس12(المحتويات, &الحقيبة[0], «1.2.840.113549.1.12.10.1.1»)) {
                            طابق حلل_مفتاح_بي_كي_سي_إس8_تي_إل_إس(&الترميز) مع
                            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                            | نتيجة.نجح(المفتاح) -> { ألحق(*المفاتيح, المفتاح); };
                        } وإلا لو (معرف_بي_كي_سي_إس12(المحتويات, &الحقيبة[0], «1.2.840.113549.1.12.10.1.2»)) {
                            // EncryptedPrivateKeyInfo ::= SEQUENCE { algorithm, encryptedData }.
                            طابق أبناء_بوسم_دي_إي_آر(المحتويات, &القيمة[0], وسم_تسلسل_دي_إي_آر()) مع
                            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                            | اختيار.بعض(المشفر) -> {
                                لو ((الطول(المشفر) مثل غير_موقع) != 2 || المشفر[1].الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر()) { أرجع نتيجة.خطأ(تالف); };
                                دع البيانات: متجه غ8 = محتوى_دي_إي_آر(المحتويات, &المشفر[1]);
                                طابق فك_محمي_بي_كي_سي_إس12(المحتويات, &المشفر[0], &البيانات, كلمة_المرور, كلمة_بي_إم_بي) مع
                                | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                                | نتيجة.نجح(الصريح) -> {
                                    دع صريح_قابل: متغير متجه غ8 = الصريح;
                                    دع المحلل: نتيجة مفتاح_خاص_تي_إل_إس, عدد = حلل_مفتاح_بي_كي_سي_إس8_تي_إل_إس(&صريح_قابل);
                                    امسح_بايتات_تشفير(&متغير صريح_قابل);
                                    طابق المحلل مع
                                    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                                    | نتيجة.نجح(المفتاح) -> { ألحق(*المفاتيح, المفتاح); };
                                };
                            };
                        } وإلا لو (معرف_بي_كي_سي_إس12(المحتويات, &الحقيبة[0], «1.2.840.113549.1.12.10.1.3»)) {
                            // CertBag ::= SEQUENCE { certId, certValue [0] EXPLICIT }.
                            طابق أبناء_بوسم_دي_إي_آر(المحتويات, &القيمة[0], وسم_تسلسل_دي_إي_آر()) مع
                            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                            | اختيار.بعض(الشهادة) -> {
                                لو ((الطول(الشهادة) مثل غير_موقع) == 2 && معرف_بي_كي_سي_إس12(المحتويات, &الشهادة[0], «1.2.840.113549.1.9.22.1»)) {
                                    طابق أبناء_بوسم_دي_إي_آر(المحتويات, &الشهادة[1], وسم_سياق_مركب_دي_إي_آر(0)) مع
                                    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                                    | اختيار.بعض(الداخل) -> {
                                        لو ((الطول(الداخل) مثل غير_موقع) != 1 || الداخل[0].الوسم != وسم_سلسلة_ثمانيات_دي_إي_آر()) { أرجع نتيجة.خطأ(تالف); };
                                        ألحق(*الشهادات, محتوى_دي_إي_آر(المحتويات, &الداخل[0]));
                                    };
                                };
                            };
                        };
                    };
                };
                ف := ف + 1;
            }
            أرجع نتيجة.نجح(0);
        };
    };
}

// True when the certificate carries the public half of the private key.
عرف شهادة_تطابق_المفتاح_تي_إل_إس(الشهادة: &شهادة_إكس509, المفتاح: &مفتاح_خاص_تي_إل_إس): منطقي {
    طابق *المفتاح مع
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_آر_إس_إيه(الخاص) -> {
        طابق (*الشهادة).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_آر_إس_إيه_إكس509(العام) -> {
            أرجع بايتات_متساوية_بزمن_ثابت_تشفير(&العام.المعامل, &الخاص.العام.المعامل);
        }
        | _ -> { أرجع خطأ; };
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إي_سي(الخاص) -> {
        طابق (*الشهادة).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_إي_سي_إكس509(العام) -> {
            لو (العام.المنحنى != الخاص.المنحنى) { أرجع خطأ; };
            طابق مفتاح_عام_إي_سي_دي_إس_إيه(الخاص.المنحنى, &الخاص.الخاص) مع
            | اختيار.لا_شيء -> { أرجع خطأ; }
            | اختيار.بعض(النقطة) -> { أرجع بايتات_متساوية_بزمن_ثابت_تشفير(&النقطة, &العام.النقطة); };
        }
        | _ -> { أرجع خطأ; };
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إد25519(البذرة) -> {
        طابق (*الشهادة).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_إد25519_إكس509(العام) -> {
            طابق مفتاح_عام_إد25519(&البذرة) مع
            | اختيار.لا_شيء -> { أرجع خطأ; }
            | اختيار.بعض(المحسوب) -> { أرجع بايتات_متساوية_بزمن_ثابت_تشفير(&المحسوب, &العام); };
        }
        | _ -> { أرجع خطأ; };
    };
}

// Decodes a PKCS#12 container into one private key and its certificate chain
// (the certificate whose key matches first, the others after it).
عام عرف حلل_هوية_بي_كي_سي_إس12_تي_إل_إس(المدخل: &متجه غ8, كلمة_المرور: &متجه غ8): نتيجة هوية_محللة_تي_إل_إس, عدد {
    دع تالف: عدد = خطأ_ترميز_تي_إل_إس();
    دع الموحد: متجه غ8;
    طابق حول_بي_إي_آر_إلى_دي_إي_آر(المدخل) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
    | اختيار.بعض(القيمة) -> { الموحد := القيمة; };
    دع البيانات: &متجه غ8 = &الموحد;
    دع كلمة_بي_إم_بي: متجه غ8;
    طابق كلمة_مرور_بي_إم_بي_بي_كي_سي_إس12(كلمة_المرور) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_وسيط_تي_إل_إس()); }
    | اختيار.بعض(القيمة) -> { كلمة_بي_إم_بي := القيمة; };
    دع الآمنة_الخام: متجه غ8;
    طابق اقرأ_جذر_دي_إي_آر(البيانات) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
    | اختيار.بعض(الجذر) -> {
        طابق أبناء_بوسم_دي_إي_آر(البيانات, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
        | اختيار.بعض(الحقول) -> {
            دع العدد: غير_موقع = الطول(الحقول) مثل غير_موقع;
            لو (العدد < 2 || العدد > 3) { أرجع نتيجة.خطأ(تالف); };
            طابق عدد_صغير_دي_إي_آر(البيانات, &الحقول[0]) مع
            | اختيار.بعض(الإصدار) -> { لو (الإصدار != 3) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); }; }
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
            طابق أبناء_بوسم_دي_إي_آر(البيانات, &الحقول[1], وسم_تسلسل_دي_إي_آر()) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
            | اختيار.بعض(المعلومات) -> {
                لو ((الطول(المعلومات) مثل غير_موقع) == 0 || !معرف_بي_كي_سي_إس12(البيانات, &المعلومات[0], «1.2.840.113549.1.7.1»)) {
                    أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس());
                };
                طابق بيانات_معلومات_المحتوى_بي_كي_سي_إس12(البيانات, &المعلومات) مع
                | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(تالف); }
                | اختيار.بعض(القيمة) -> { الآمنة_الخام := القيمة; };
            };
            لو (العدد == 3) {
                // MacData ::= SEQUENCE { mac DigestInfo, macSalt, iterations DEFAULT 1 }.
