// HKDF-Expand-Label (RFC 8446 7.1).
عام عرف وسع_تسمية_تي_إل_إس(
    الخوارزمية: خوارزمية_تجزئة,
    السر: &متجه غ8,
    التسمية: نص,
    السياق: &متجه غ8,
    الطول_المطلوب: غير_موقع
): متجه غ8 {
    دع الكاملة: متغير متجه غ8 = بايتات_من_نص(«tls13 »);
    ألحق_بايتات_نص(&متغير الكاملة, التسمية);
    دع المعلومات: متغير متجه غ8 = [];
    ألحق_كبير16_تشفير(&متغير المعلومات, الطول_المطلوب);
    ألحق(المعلومات, (الطول(الكاملة) مثل غير_موقع) مثل غ8);
    ألحق_بايتات_تشفير(&متغير المعلومات, &الكاملة);
    ألحق(المعلومات, (الطول(*السياق) مثل غير_موقع) مثل غ8);
    ألحق_بايتات_تشفير(&متغير المعلومات, السياق);
    طابق هكدف_وسع_تشفير(الخوارزمية, السر, &المعلومات, الطول_المطلوب) مع
    | اختيار.بعض(القيمة) -> { أرجع القيمة; }
    | اختيار.لا_شيء -> {
        دع فارغ: متجه غ8 = [];
        أرجع فارغ;
    };
}

// Derive-Secret(Secret, Label, Messages) with the transcript already hashed.
عام عرف اشتق_سرا_تي_إل_إس(الخوارزمية: خوارزمية_تجزئة, السر: &متجه غ8, التسمية: نص, ملخص_النص: &متجه غ8): متجه غ8 {
