    أرجع اشتق_سرا_تي_إل_إس(الخوارزمية, السر, «derived», &ملخص_فارغ);
}

// Installs traffic keys derived from a traffic secret (RFC 8446 7.3).
عام عرف فعل_مفاتيح_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, للكتابة: منطقي, السر: &متجه غ8): فراغ {
    دع الحزمة: غير_موقع = (*الحالة).الحزمة;
    دع الخوارزمية: خوارزمية_تجزئة = تجزئة_الحزمة_تي_إل_إس(الحزمة);
    دع فارغ: متجه غ8 = [];
    دع المفتاح: متجه غ8 = وسع_تسمية_تي_إل_إس(الخوارزمية, السر, «key», &فارغ, حجم_مفتاح_الحزمة_تي_إل_إس(الحزمة));
    دع المتجه: متجه غ8 = وسع_تسمية_تي_إل_إس(الخوارزمية, السر, «iv», &فارغ, 12);
    دع المفاتيح: مفاتيح_اتجاه_تي_إل_إس = { مفعلة: صواب, المفتاح: المفتاح, المتجه: المتجه, السر: انسخ_بايتات(السر), التسلسل: 0 };
    لو (للكتابة) {
        (*الحالة).الكتابة := المفاتيح;
    } وإلا {
        (*الحالة).القراءة := المفاتيح;
    };
}

// application_traffic_secret_N+1 (RFC 8446 7.2).
عام عرف حدث_مفاتيح_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, للكتابة: منطقي): فراغ {
    دع الخوارزمية: خوارزمية_تجزئة = تجزئة_الحزمة_تي_إل_إس((*الحالة).الحزمة);
    دع فارغ: متجه غ8 = [];
    دع القديم: متغير متجه غ8 = [];
    // Take the old secret: it is erased below and replaced by the new keys.
    لو (للكتابة) {
        بدّل((*الحالة).الكتابة.السر, القديم);
    } وإلا {
        بدّل((*الحالة).القراءة.السر, القديم);
    };
    دع الجديد: متجه غ8 = وسع_تسمية_تي_إل_إس(الخوارزمية, &القديم, «traffic upd», &فارغ, حجم_ملخص_تجزئة(الخوارزمية));
    امسح_بايتات_تشفير(&متغير القديم);
    فعل_مفاتيح_تي_إل_إس(الحالة, للكتابة, &الجديد);
}

عرف نونس_سجل_تي_إل_إس(المتجه: &متجه غ8, التسلسل: غير_موقع): متجه غ8 {
    دع الناتج: متغير متجه غ8 = شريحة_بايتات_تشفير(المتجه, 0, 12);
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 8) {
        دع ب: غير_موقع = (التسلسل >> (56 - ف * 8)) & 0xFF;
        الناتج[4 + ف] := ((الناتج[4 + ف] مثل غير_موقع) ^ ب) مثل غ8;
        ف := ف + 1;
    }
    أرجع الناتج;
}

عرف اختم_بالحزمة_تي_إل_إس(الحزمة: غير_موقع, المفتاح: &متجه غ8, النونس: &متجه غ8, الإضافية: &متجه غ8, الصريح: &متجه غ8): متجه غ8 {
    لو (الحزمة == 0x1303) {
        أرجع اختم_تشاتشا20_بولي1305(المفتاح, النونس, الإضافية, الصريح);
    };
    طابق اختم_أيس_جي_سي_إم(المفتاح, النونس, الإضافية, الصريح) مع
    | اختيار.بعض(القيمة) -> { أرجع القيمة; }
    | اختيار.لا_شيء -> {
        دع فارغ: متجه غ8 = [];
        أرجع فارغ;
    };
}

عرف افتح_بالحزمة_تي_إل_إس(الحزمة: غير_موقع, المفتاح: &متجه غ8, النونس: &متجه غ8, الإضافية: &متجه غ8, المشفر: &متجه غ8): اختيار متجه غ8 {
    لو (الحزمة == 0x1303) {
        أرجع افتح_تشاتشا20_بولي1305(المفتاح, النونس, الإضافية, المشفر);
    };
    أرجع افتح_أيس_جي_سي_إم(المفتاح, النونس, الإضافية, المشفر);
}

عرف مقبس_نظام_تي_إل_إس(القيمة: عدد): مقبس_نظام {
    دع المقبس: مقبس_نظام = { القيمة: القيمة, مفتوح: صواب };
    أرجع المقبس;
}

// Writes all bytes to the socket.
عام عرف اكتب_بايتات_مقبس_تي_إل_إس(المقبس: عدد, البيانات: &متجه غ8): نتيجة عدد, عدد {
    دع مقبس: مقبس_نظام = مقبس_نظام_تي_إل_إس(المقبس);
    دع الحجم: عدد = الطول(*البيانات);
    دع المكتوب: متغير عدد = 0;
    بينما (المكتوب < الحجم) {
        طابق أرسل_مقبس_نظام(&مقبس, البيانات, المكتوب, الحجم - المكتوب) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(رمز_خطأ_حد_النظام(الخطأ)); }
        | نتيجة.نجح(العدد) -> {
            لو (العدد <= 0) { أرجع نتيجة.خطأ(خطأ_انقطاع_تي_إل_إس()); };
            المكتوب := المكتوب + العدد;
        };
    }
    أرجع نتيجة.نجح(الحجم);
}

// Sends one record of ≤ 2^14 bytes, protected when write keys are active.
عام عرف اكتب_سجل_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, النوع: غير_موقع, البيانات: &متجه غ8): نتيجة عدد, عدد {
    لو ((الطول(*البيانات) مثل غير_موقع) > 16384) { أرجع نتيجة.خطأ(خطأ_وسيط_تي_إل_إس()); };
    دع السجل: متغير متجه غ8 = [];
    لو (!(*الحالة).الكتابة.مفعلة) {
        ألحق(السجل, النوع مثل غ8);
        ألحق_كبير16_تشفير(&متغير السجل, 0x0303);
        ألحق_كبير16_تشفير(&متغير السجل, الطول(*البيانات) مثل غير_موقع);
        ألحق_بايتات_تشفير(&متغير السجل, البيانات);
    } وإلا {
        لو ((*الحالة).الكتابة.التسلسل >= 9223372036854775807) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        دع الداخلي: متغير متجه غ8 = [];
        ألحق_بايتات_تشفير(&متغير الداخلي, البيانات);
        ألحق(الداخلي, النوع مثل غ8);
        دع الرأس: متغير متجه غ8 = [];
        ألحق(الرأس, نوع_بيانات_تطبيق_تي_إل_إس() مثل غ8);
        ألحق_كبير16_تشفير(&متغير الرأس, 0x0303);
        ألحق_كبير16_تشفير(&متغير الرأس, (الطول(الداخلي) مثل غير_موقع) + 16);
        دع النونس: متجه غ8 = نونس_سجل_تي_إل_إس(&(*الحالة).الكتابة.المتجه, (*الحالة).الكتابة.التسلسل);
        دع المشفر: متجه غ8 = اختم_بالحزمة_تي_إل_إس((*الحالة).الحزمة, &(*الحالة).الكتابة.المفتاح, &النونس, &الرأس, &الداخلي);
        لو ((الطول(المشفر) مثل غير_موقع) == 0) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        (*الحالة).الكتابة.التسلسل := (*الحالة).الكتابة.التسلسل + 1;
        امسح_بايتات_تشفير(&متغير الداخلي);
        ألحق_بايتات_تشفير(&متغير السجل, &الرأس);
        ألحق_بايتات_تشفير(&متغير السجل, &المشفر);
    };
    أرجع اكتب_بايتات_مقبس_تي_إل_إس((*الحالة).المقبس, &السجل);
}

// Reads from the socket until at least المطلوب bytes are buffered.
عرف املأ_الوارد_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, المطلوب: غير_موقع): نتيجة عدد, عدد {
    دع مقبس: مقبس_نظام = مقبس_نظام_تي_إل_إس((*الحالة).المقبس);
    بينما ((الطول((*الحالة).وارد_خام) مثل غير_موقع) < المطلوب) {
        دع المخزن: متغير متجه غ8 = أصفار_تشفير(18437);
        طابق استقبل_مقبس_نظام(&مقبس, &متغير المخزن, 0, 18437) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(رمز_خطأ_حد_النظام(الخطأ)); }
        | نتيجة.نجح(العدد) -> {
            لو (العدد <= 0) { أرجع نتيجة.خطأ(خطأ_انقطاع_تي_إل_إس()); };
            دع ف: متغير غير_موقع = 0;
            بينما (ف < (العدد مثل غير_موقع)) {
                ألحق((*الحالة).وارد_خام, المخزن[ف]);
                ف := ف + 1;
            }
        };
    }
    أرجع نتيجة.نجح(0);
}

// Reads one record and removes its protection. change_cipher_spec records
// are dropped during the handshake; outside it they are a protocol error.
عام عرف اقرأ_سجل_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس): نتيجة سجل_تي_إل_إس, عدد {
    بينما (صواب) {
        طابق املأ_الوارد_تي_إل_إس(الحالة, 5) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        دع النوع: غير_موقع = (*الحالة).وارد_خام[0] مثل غير_موقع;
        دع الإصدار_الأعلى: غير_موقع = (*الحالة).وارد_خام[1] مثل غير_موقع;
        دع الطول_الحالي: غير_موقع = اقرأ_كبير16_تشفير(&(*الحالة).وارد_خام, 3);
        لو (الإصدار_الأعلى != 3) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
        لو (الطول_الحالي > 16640 || الطول_الحالي == 0) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
        طابق املأ_الوارد_تي_إل_إس(الحالة, 5 + الطول_الحالي) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        دع الرأس: متجه غ8 = شريحة_بايتات_تشفير(&(*الحالة).وارد_خام, 0, 5);
        دع الحمولة: متجه غ8 = شريحة_بايتات_تشفير(&(*الحالة).وارد_خام, 5, الطول_الحالي);
        دع الكلي: غير_موقع = الطول((*الحالة).وارد_خام) مثل غير_موقع;
        (*الحالة).وارد_خام := شريحة_بايتات_تشفير(&(*الحالة).وارد_خام, 5 + الطول_الحالي, الكلي - 5 - الطول_الحالي);

        لو (النوع == نوع_تغيير_التشفير_تي_إل_إس()) {
            لو ((*الحالة).المصافحة_مكتملة || الطول_الحالي != 1 || الحمولة[0] != 1) {
                أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
            };
        } وإلا لو (!(*الحالة).القراءة.مفعلة) {
            لو (الطول_الحالي > 16384) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
            لو (النوع != نوع_مصافحة_تي_إل_إس() && النوع != نوع_تنبيه_تي_إل_إس()) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
            دع السجل: سجل_تي_إل_إس = { النوع: النوع, البيانات: الحمولة };
            أرجع نتيجة.نجح(السجل);
        } وإلا {
            لو (النوع != نوع_بيانات_تطبيق_تي_إل_إس()) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
            دع النونس: متجه غ8 = نونس_سجل_تي_إل_إس(&(*الحالة).القراءة.المتجه, (*الحالة).القراءة.التسلسل);
            طابق افتح_بالحزمة_تي_إل_إس((*الحالة).الحزمة, &(*الحالة).القراءة.المفتاح, &النونس, &الرأس, &الحمولة) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_فك_السجل_تي_إل_إس()); }
            | اختيار.بعض(الداخلي) -> {
                (*الحالة).القراءة.التسلسل := (*الحالة).القراءة.التسلسل + 1;
                // TLSInnerPlaintext: content, type, zero padding.
                دع النهاية: متغير غير_موقع = الطول(الداخلي) مثل غير_موقع;
                بينما (النهاية > 0 && الداخلي[النهاية - 1] == 0) { النهاية := النهاية - 1; }
                لو (النهاية == 0) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
                دع النوع_الداخلي: غير_موقع = الداخلي[النهاية - 1] مثل غير_موقع;
                لو (النهاية - 1 > 16384) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
                لو (النوع_الداخلي != نوع_مصافحة_تي_إل_إس() && النوع_الداخلي != نوع_تنبيه_تي_إل_إس() && النوع_الداخلي != نوع_بيانات_تطبيق_تي_إل_إس()) {
                    أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
                };
                دع السجل: سجل_تي_إل_إس = { النوع: النوع_الداخلي, البيانات: شريحة_بايتات_تشفير(&الداخلي, 0, النهاية - 1) };
                أرجع نتيجة.نجح(السجل);
            };
        };
    }
    أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
}

// AlertDescription for a std.tls status (RFC 8446 6.2).
عام عرف تنبيه_لخطأ_تي_إل_إس(الخطأ: عدد): غير_موقع {
    لو (الخطأ == خطأ_ترميز_تي_إل_إس()) { أرجع 50; };
    لو (الخطأ == خطأ_غير_مدعوم_تي_إل_إس()) { أرجع 40; };
    لو (الخطأ == خطأ_شهادة_غير_موثوقة_تي_إل_إس()) { أرجع 48; };
    لو (الخطأ == خطأ_اسم_الشهادة_تي_إل_إس()) { أرجع 42; };
    لو (الخطأ == خطأ_صلاحية_الشهادة_تي_إل_إس()) { أرجع 45; };
    لو (الخطأ == خطأ_توقيع_تي_إل_إس()) { أرجع 51; };
    لو (الخطأ == خطأ_فك_السجل_تي_إل_إس()) { أرجع 20; };
    لو (الخطأ == خطأ_بروتوكول_تي_إل_إس()) { أرجع 47; };
    أرجع 80;
}

// Sends an alert record; failures are ignored because the connection is
// already being abandoned or closed.
عام عرف أرسل_تنبيها_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, الوصف: غير_موقع): فراغ {
    دع المستوى: غير_موقع = 2;
    لو (الوصف == 0) {
        // close_notify is a warning-level alert by convention.
        دع بيانات: متجه غ8 = [1, 0];
        دع تجاهل: نتيجة عدد, عدد = اكتب_سجل_تي_إل_إس(الحالة, نوع_تنبيه_تي_إل_إس(), &بيانات);
        أرجع;
    };
    دع البيانات: متغير متجه غ8 = [];
    ألحق(البيانات, المستوى مثل غ8);
    ألحق(البيانات, الوصف مثل غ8);
    دع تجاهل: نتيجة عدد, عدد = اكتب_سجل_تي_إل_إس(الحالة, نوع_تنبيه_تي_إل_إس(), &البيانات);
}

// Interprets a received alert record: close_notify yields 0, any other
// alert (all are fatal in TLS 1.3 except user_canceled) yields its status.
عام عرف عالج_تنبيها_مستلما_تي_إل_إس(البيانات: &متجه غ8): عدد {
    لو ((الطول(*البيانات) مثل غير_موقع) != 2) { أرجع خطأ_ترميز_تي_إل_إس(); };
    دع الوصف: غير_موقع = (*البيانات)[1] مثل غير_موقع;
    لو (الوصف == 0) { أرجع 0; };
    أرجع خطأ_تنبيه_مستلم_تي_إل_إس(الوصف);
}

// The next complete handshake message (header included). Messages may span
// records; application data or a closed stream is a protocol error here.
عام عرف اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس): نتيجة متجه غ8, عدد {
    بينما (صواب) {
        دع المتاح: غير_موقع = الطول((*الحالة).وارد_مصافحة) مثل غير_موقع;
        لو (المتاح >= 4) {
            دع الطول_المعلن: غير_موقع = اقرأ_كبير24_تشفير(&(*الحالة).وارد_مصافحة, 1);
            لو (الطول_المعلن > 262144) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
            لو (المتاح >= 4 + الطول_المعلن) {
                دع الرسالة: متجه غ8 = شريحة_بايتات_تشفير(&(*الحالة).وارد_مصافحة, 0, 4 + الطول_المعلن);
                (*الحالة).وارد_مصافحة := شريحة_بايتات_تشفير(&(*الحالة).وارد_مصافحة, 4 + الطول_المعلن, المتاح - 4 - الطول_المعلن);
                أرجع نتيجة.نجح(الرسالة);
            };
        };
        طابق اقرأ_سجل_تي_إل_إس(الحالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(السجل) -> {
            لو (السجل.النوع == نوع_تنبيه_تي_إل_إس()) {
                دع الحالة_الناتجة: عدد = عالج_تنبيها_مستلما_تي_إل_إس(&السجل.البيانات);
                لو (الحالة_الناتجة == 0) { أرجع نتيجة.خطأ(خطأ_انقطاع_تي_إل_إس()); };
                أرجع نتيجة.خطأ(الحالة_الناتجة);
            };
            لو (السجل.النوع != نوع_مصافحة_تي_إل_إس()) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
            لو ((الطول(السجل.البيانات) مثل غير_موقع) == 0) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
            ألحق_بايتات_تشفير(&متغير (*الحالة).وارد_مصافحة, &السجل.البيانات);
        };
    }
    أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
}

// Handshake messages must not span a key change (RFC 8446 5.1).
عام عرف لا_مصافحة_معلقة_تي_إل_إس(الحالة: &حالة_اتصال_تي_إل_إس): منطقي {
    أرجع (الطول((*الحالة).وارد_مصافحة) مثل غير_موقع) == 0;
}

// Sends one handshake message, split across records when it exceeds 2^14.
عام عرف اكتب_رسالة_مصافحة_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, الرسالة: &متجه غ8): نتيجة عدد, عدد {
    دع الحجم: غير_موقع = الطول(*الرسالة) مثل غير_موقع;
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < الحجم) {
        دع الجزء: متغير غير_موقع = الحجم - الموضع;
        لو (الجزء > 16384) { الجزء := 16384; };
        دع القطعة: متجه غ8 = شريحة_بايتات_تشفير(الرسالة, الموضع, الجزء);
        طابق اكتب_سجل_تي_إل_إس(الحالة, نوع_مصافحة_تي_إل_إس(), &القطعة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        الموضع := الموضع + الجزء;
    }
    أرجع نتيجة.نجح(الحجم مثل عدد);
}

// Wraps a handshake body with its type and 24-bit length.
عام عرف رسالة_مصافحة_تي_إل_إس(النوع: غير_موقع, الجسم: &متجه غ8): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    ألحق(الناتج, النوع مثل غ8);
    ألحق_كبير24_تشفير(&متغير الناتج, الطول(*الجسم) مثل غير_موقع);
    ألحق_بايتات_تشفير(&متغير الناتج, الجسم);
    أرجع الناتج;
}

// verify_data for a Finished message (RFC 8446 4.4.4).
عام عرف بيانات_الإنهاء_تي_إل_إس(الخوارزمية: خوارزمية_تجزئة, السر_الأساسي: &متجه غ8, ملخص_النص: &متجه غ8): متجه غ8 {
    دع فارغ: متجه غ8 = [];
    دع المفتاح: متغير متجه غ8 = وسع_تسمية_تي_إل_إس(الخوارزمية, السر_الأساسي, «finished», &فارغ, حجم_ملخص_تجزئة(الخوارزمية));
    دع الناتج: متجه غ8 = هماك_تشفير(الخوارزمية, &المفتاح, ملخص_النص);
    امسح_بايتات_تشفير(&متغير المفتاح);
    أرجع الناتج;
}

// The content signed by CertificateVerify (RFC 8446 4.4.3).
عام عرف محتوى_تحقق_الشهادة_تي_إل_إس(من_الخادم: منطقي, ملخص_النص: &متجه غ8): متجه غ8 {
    دع الناتج: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < 64) {
        ألحق_بايتات_نص(&متغير الناتج, « »);
        ف := ف + 1;
    }
    لو (من_الخادم) {
        ألحق_بايتات_نص(&متغير الناتج, «TLS 1.3, server CertificateVerify»);
    } وإلا {
        ألحق_بايتات_نص(&متغير الناتج, «TLS 1.3, client CertificateVerify»);
    };
    ألحق(الناتج, 0 مثل غ8);
    ألحق_بايتات_تشفير(&متغير الناتج, ملخص_النص);
    أرجع الناتج;
}

// Fresh bytes from the operating-system CSPRNG; there is no fallback.
عام عرف بايتات_عشوائية_تي_إل_إس(العدد: غير_موقع): نتيجة متجه غ8, عدد {
    دع المخزن: متغير متجه غ8 = أصفار_تشفير(العدد);
    طابق املأ_بايتات_عشوائية_النظام(&متغير المخزن) مع
    | نتيجة.خطأ(_) -> { أرجع نتيجة.خطأ(خطأ_عشوائية_تي_إل_إس()); }
    | نتيجة.نجح(_) -> { أرجع نتيجة.نجح(المخزن); };
}

// The legacy change_cipher_spec record sent once for middlebox
// compatibility (RFC 8446 D.4).
عام عرف أرسل_تغيير_تشفير_وهمي_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس): نتيجة عدد, عدد {
    دع السجل: متجه غ8 = [20, 3, 3, 0, 1, 1];
    أرجع اكتب_بايتات_مقبس_تي_إل_إس((*الحالة).المقبس, &السجل);
}

library/std/tls/server.sn:
// TLS 1.3 server handshake (RFC 8446 2, 4.1-4.4, 7.1), following the state
// sequence of Go crypto/tls handshake_server_tls13.go.
//
// The identity comes from a PKCS#12 container (std.tls.pkcs12). The server
// signs CertificateVerify with the scheme its key allows and the client
// offered (RFC 8446 4.2.3): RSASSA-PSS (rsa_pss_rsae_sha256/384/512) through
// crypto.rsa's constant-time CRT signer, ecdsa_secp256r1_sha256 or
// ecdsa_secp384r1_sha384 with deterministic constant-time ECDSA, or ed25519.
// The server selects TLS 1.3, its preferred cipher suite among
// ChaCha20-Poly1305, AES-128-GCM and AES-256-GCM, and its preferred group
// among X25519, secp256r1 and secp384r1 for which the client sent a share;
// when the client supports one of them without a share, one
// HelloRetryRequest asks for it. Previously only RSA keys and X25519 were
// accepted. PSKs are ignored (full handshake); early data, which requires a
// ticket this server never issues, is refused. With client verification
// enabled a CertificateRequest is sent and the client chain is validated for
// clientAuth against the configured client roots (or the system anchors).

استورد crypto.digest;
استورد crypto.ecdsa;
استورد crypto.ed25519;
استورد crypto.rsa;
استورد crypto.words;
استورد text.from_bytes;
استورد tls.client;
استورد tls.config;
استورد tls.errors;
استورد tls.key_exchange;
استورد tls.pkcs12;
استورد tls.record;
استورد tls.signature;
استورد tls.verify;
استورد tls.wire;
استورد tls.x509;

نوع ترحيب_عميل_تي_إل_إس = {
    معرف_الجلسة: متجه غ8,
    الحزم: متجه غير_موقع,
    الإصدارات: متجه غير_موقع,
    المجموعات: متجه غير_موقع,
    // Key shares of supported groups, in the client's order.
    مجموعات_المشاركات: متجه غير_موقع,
    مفاتيح_المشاركات: متجه متجه غ8,
    المخططات: متجه غير_موقع,
    بيانات_مبكرة: منطقي
};

عرف قائمة_أرقام_تي_إل_إس(البيانات: &متجه غ8, بايتات_الطول: غير_موقع): اختيار متجه غير_موقع {
    دع ق: متغير قارئ_تي_إل_إس = أنشئ_قارئ_تي_إل_إس(البيانات, 0);
    دع الكتلة: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير ق, بايتات_الطول);
    لو (!قارئ_منته_تي_إل_إس(&ق) || ((الطول(الكتلة) مثل غير_موقع) % 2) != 0) { أرجع اختيار.لا_شيء(); };
    دع الناتج: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(الكتلة) مثل غير_موقع)) {
        ألحق(الناتج, اقرأ_كبير16_تشفير(&الكتلة, ف));
        ف := ف + 2;
    }
    أرجع اختيار.بعض(الناتج);
}

عرف يحتوي_رقما_تي_إل_إس(القائمة: &متجه غير_موقع, القيمة: غير_موقع): منطقي {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*القائمة) مثل غير_موقع)) {
        لو ((*القائمة)[ف] == القيمة) { أرجع صواب; };
        ف := ف + 1;
    }
    أرجع خطأ;
}

عرف حلل_ترحيب_العميل_تي_إل_إس(الرسالة: &متجه غ8): نتيجة ترحيب_عميل_تي_إل_إس, عدد {
    لو ((*الرسالة)[0] != (رسالة_ترحيب_العميل_تي_إل_إس() مثل غ8)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    دع ق: متغير قارئ_تي_إل_إس = أنشئ_قارئ_تي_إل_إس(الرسالة, 4);
    دع تجاهل_الإصدار: غير_موقع = اقرأ_رقما_تي_إل_إس(&متغير ق, 2);
    دع تجاهل_العشوائي: متجه غ8 = اقرأ_بايتات_تي_إل_إس(&متغير ق, 32);
    دع معرف_الجلسة: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير ق, 1);
    دع كتلة_الحزم: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير ق, 2);
    دع الضغط: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير ق, 1);
    لو (!ق.صالح || (الطول(معرف_الجلسة) مثل غير_موقع) > 32 || ((الطول(كتلة_الحزم) مثل غير_موقع) % 2) != 0) {
        أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس());
    };
    // TLS 1.3 requires exactly the null compression method (4.1.2).
    لو ((الطول(الضغط) مثل غير_موقع) != 1 || الضغط[0] != 0) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    دع الحزم: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(كتلة_الحزم) مثل غير_موقع)) {
        ألحق(الحزم, اقرأ_كبير16_تشفير(&كتلة_الحزم, ف));
        ف := ف + 2;
    }
    دع الامتدادات: متجه امتداد_تي_إل_إس;
    طابق اقرأ_امتدادات_تي_إل_إس(&متغير ق) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); }
    | اختيار.بعض(القيمة) -> { الامتدادات := القيمة; };
    لو (!قارئ_منته_تي_إل_إس(&ق)) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
    دع فارغ_أرقام1: متجه غير_موقع = [];
    دع فارغ_أرقام2: متجه غير_موقع = [];
    دع فارغ_أرقام3: متجه غير_موقع = [];
    دع فارغ_أرقام4: متجه غير_موقع = [];
    دع فارغ_مفاتيح: متجه متجه غ8 = [];
    دع الترحيب: متغير ترحيب_عميل_تي_إل_إس = {
        معرف_الجلسة: معرف_الجلسة,
        الحزم: الحزم,
        الإصدارات: فارغ_أرقام1,
        المجموعات: فارغ_أرقام2,
        مجموعات_المشاركات: فارغ_أرقام4,
        مفاتيح_المشاركات: فارغ_مفاتيح,
        المخططات: فارغ_أرقام3,
        بيانات_مبكرة: خطأ
    };
    دع العدد: غير_موقع = الطول(الامتدادات) مثل غير_موقع;
    ف := 0;
    بينما (ف < العدد) {
        دع النوع: غير_موقع = الامتدادات[ف].النوع;
        دع البيانات: &متجه غ8 = &الامتدادات[ف].البيانات;
        لو (النوع == امتداد_الإصدارات_تي_إل_إس()) {
            طابق قائمة_أرقام_تي_إل_إس(البيانات, 1) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); }
            | اختيار.بعض(القيمة) -> { الترحيب.الإصدارات := القيمة; };
        } وإلا لو (النوع == امتداد_المجموعات_تي_إل_إس()) {
            طابق قائمة_أرقام_تي_إل_إس(البيانات, 2) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); }
            | اختيار.بعض(القيمة) -> { الترحيب.المجموعات := القيمة; };
        } وإلا لو (النوع == امتداد_خوارزميات_التوقيع_تي_إل_إس()) {
            طابق قائمة_أرقام_تي_إل_إس(البيانات, 2) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); }
            | اختيار.بعض(القيمة) -> { الترحيب.المخططات := القيمة; };
        } وإلا لو (النوع == امتداد_مشاركة_المفتاح_تي_إل_إس()) {
            دع م: متغير قارئ_تي_إل_إس = أنشئ_قارئ_تي_إل_إس(البيانات, 0);
            دع المشاركات: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير م, 2);
            لو (!قارئ_منته_تي_إل_إس(&م)) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
            دع ن: متغير قارئ_تي_إل_إس = أنشئ_قارئ_تي_إل_إس(&المشاركات, 0);
            دع المرئية: متغير متجه غير_موقع = [];
            بينما (متبقي_قارئ_تي_إل_إس(&ن) > 0) {
                دع المجموعة: غير_موقع = اقرأ_رقما_تي_إل_إس(&متغير ن, 2);
                دع المفتاح: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير ن, 2);
                لو (!ن.صالح || (الطول(المفتاح) مثل غير_موقع) == 0 || يحتوي_رقما_تي_إل_إس(&المرئية, المجموعة)) {
                    أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
                };
                ألحق(المرئية, المجموعة);
                لو (مجموعة_مدعومة_تي_إل_إس(المجموعة)) {
                    ألحق(الترحيب.مجموعات_المشاركات, المجموعة);
                    ألحق(الترحيب.مفاتيح_المشاركات, المفتاح);
                };
            }
        } وإلا لو (النوع == 42) {
            الترحيب.بيانات_مبكرة := صواب;
        } وإلا لو (النوع == امتداد_مفتاح_مشترك_مسبقا_تي_إل_إس()) {
            // pre_shared_key must be the last extension (4.2.11); it is ignored.
            لو (ف + 1 != العدد) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        };
        ف := ف + 1;
    }
    أرجع نتيجة.نجح(الترحيب);
}

عرف ابن_ترحيب_الخادم_تي_إل_إس(
    العشوائي: &متجه غ8,
    معرف_الجلسة: &متجه غ8,
    الحزمة: غير_موقع,
    مشاركة_المفتاح: &متجه غ8
): متجه غ8 {
    دع الجسم: متغير متجه غ8 = [];
    ألحق_كبير16_تشفير(&متغير الجسم, 0x0303);
    ألحق_بايتات_تشفير(&متغير الجسم, العشوائي);
    ألحق_متجها_تي_إل_إس(&متغير الجسم, 1, معرف_الجلسة);
    ألحق_كبير16_تشفير(&متغير الجسم, الحزمة);
    ألحق(الجسم, 0 مثل غ8);
    دع الامتدادات: متغير متجه غ8 = [];
    ألحق_كبير16_تشفير(&متغير الامتدادات, امتداد_الإصدارات_تي_إل_إس());
    ألحق_كبير16_تشفير(&متغير الامتدادات, 2);
    ألحق_كبير16_تشفير(&متغير الامتدادات, 0x0304);
    ألحق_كبير16_تشفير(&متغير الامتدادات, امتداد_مشاركة_المفتاح_تي_إل_إس());
    ألحق_متجها_تي_إل_إس(&متغير الامتدادات, 2, مشاركة_المفتاح);
    ألحق_متجها_تي_إل_إس(&متغير الجسم, 2, &الامتدادات);
    أرجع رسالة_مصافحة_تي_إل_إس(رسالة_ترحيب_الخادم_تي_إل_إس(), &الجسم);
}

// The first of the server's preferences that the client offered; 0 for none.
عرف اختر_من_تفضيل_تي_إل_إس(التفضيل: &متجه غير_موقع, العرض: &متجه غير_موقع): غير_موقع {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*التفضيل) مثل غير_موقع)) {
        لو (يحتوي_رقما_تي_إل_إس(العرض, (*التفضيل)[ف])) { أرجع (*التفضيل)[ف]; };
        ف := ف + 1;
    }
    أرجع 0;
}

// The index of the client's share for المجموعة, if it sent one.
عرف موضع_مشاركة_تي_إل_إس(الترحيب: &ترحيب_عميل_تي_إل_إس, المجموعة: غير_موقع): اختيار غير_موقع {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول((*الترحيب).مجموعات_المشاركات) مثل غير_موقع)) {
        لو ((*الترحيب).مجموعات_المشاركات[ف] == المجموعة) { أرجع اختيار.بعض(ف); };
        ف := ف + 1;
    }
    أرجع اختيار.لا_شيء();
}

// The server's preferred group among the client's shares; 0 for none.
عرف مجموعة_بمشاركة_تي_إل_إس(الترحيب: &ترحيب_عميل_تي_إل_إس): غير_موقع {
    دع التفضيل: متجه غير_موقع = المجموعات_المدعومة_تي_إل_إس();
    أرجع اختر_من_تفضيل_تي_إل_إس(&التفضيل, &(*الترحيب).مجموعات_المشاركات);
}

// The CertificateVerify scheme for the identity key among the client's
// signature_algorithms; 0 when none fits.
عرف مخطط_توقيع_الهوية_تي_إل_إس(المفتاح: &مفتاح_خاص_تي_إل_إس, المعروضة: &متجه غير_موقع): غير_موقع {
    طابق *المفتاح مع
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_آر_إس_إيه(_) -> {
        دع التفضيل: متجه غير_موقع = [0x0804, 0x0805, 0x0806];
        أرجع اختر_من_تفضيل_تي_إل_إس(&التفضيل, المعروضة);
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إي_سي(المفتاح_إي_سي) -> {
        دع المطلوب: متغير غير_موقع = مخطط_إي_سي_دي_إس_إيه_بي256_تي_إل_إس();
        طابق المفتاح_إي_سي.المنحنى مع
        | منحنى_إهليلجي.منحنى_بي256 -> { المطلوب := مخطط_إي_سي_دي_إس_إيه_بي256_تي_إل_إس(); }
        | منحنى_إهليلجي.منحنى_بي384 -> { المطلوب := مخطط_إي_سي_دي_إس_إيه_بي384_تي_إل_إس(); };
        لو (يحتوي_رقما_تي_إل_إس(المعروضة, المطلوب)) { أرجع المطلوب; };
        أرجع 0;
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إد25519(_) -> {
        لو (يحتوي_رقما_تي_إل_إس(المعروضة, مخطط_إد25519_تي_إل_إس())) { أرجع مخطط_إد25519_تي_إل_إس(); };
        أرجع 0;
    };
}

// Signs the CertificateVerify content with the identity key.
عرف وقع_تحقق_الشهادة_تي_إل_إس(المفتاح: &مفتاح_خاص_تي_إل_إس, المخطط: غير_موقع, المحتوى: &متجه غ8): نتيجة متجه غ8, عدد {
    طابق *المفتاح مع
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_آر_إس_إيه(المفتاح_آر_إس_إيه) -> {
        دع تجزئة_التوقيع: خوارزمية_تجزئة = تجزئة_مخطط_بي_إس_إس_تي_إل_إس(المخطط);
        دع ملخص_التوقيع: متجه غ8 = جزئ_تشفير(تجزئة_التوقيع, المحتوى);
        طابق بايتات_عشوائية_تي_إل_إس(حجم_ملخص_تجزئة(تجزئة_التوقيع)) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الملح) -> {
            طابق وقع_آر_إس_إيه_بي_إس_إس(&المفتاح_آر_إس_إيه, تجزئة_التوقيع, &ملخص_التوقيع, &الملح) مع
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_توقيع_تي_إل_إس()); }
            | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(القيمة); };
        };
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إي_سي(المفتاح_إي_سي) -> {
        دع التجزئة: متغير خوارزمية_تجزئة = خوارزمية_تجزئة.تجزئة_شا256();
        لو (المخطط == مخطط_إي_سي_دي_إس_إيه_بي384_تي_إل_إس()) { التجزئة := خوارزمية_تجزئة.تجزئة_شا384(); };
        دع الملخص: متجه غ8 = جزئ_تشفير(التجزئة, المحتوى);
        طابق وقع_إي_سي_دي_إس_إيه(المفتاح_إي_سي.المنحنى, التجزئة, &المفتاح_إي_سي.الخاص, &الملخص) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_توقيع_تي_إل_إس()); }
        | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(القيمة); };
    }
    | مفتاح_خاص_تي_إل_إس.مفتاح_خاص_إد25519(البذرة) -> {
        طابق وقع_إد25519(&البذرة, المحتوى) مع
        | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_توقيع_تي_إل_إس()); }
        | اختيار.بعض(القيمة) -> { أرجع نتيجة.نجح(القيمة); };
    };
}

عرف تجزئة_مخطط_بي_إس_إس_تي_إل_إس(المخطط: غير_موقع): خوارزمية_تجزئة {
    لو (المخطط == مخطط_بي_إس_إس_شا384_تي_إل_إس()) { أرجع خوارزمية_تجزئة.تجزئة_شا384(); };
    لو (المخطط == مخطط_بي_إس_إس_شا512_تي_إل_إس()) { أرجع خوارزمية_تجزئة.تجزئة_شا512(); };
    أرجع خوارزمية_تجزئة.تجزئة_شا256();
}

عرف نفذ_مصافحة_خادم_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, الإعداد: &إعداد_خادم_تي_إل_إس): نتيجة عدد, عدد {
    دع الهوية: هوية_محللة_تي_إل_إس;
    طابق حلل_هوية_بي_كي_سي_إس12_تي_إل_إس(&(*الإعداد).الهوية.بي_كي_سي12, &(*الإعداد).الهوية.كلمة_المرور) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { الهوية := القيمة; };

    دع الرسالة: متغير متجه غ8;
    طابق اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { الرسالة := القيمة; };
    دع الترحيب: متغير ترحيب_عميل_تي_إل_إس;
    طابق حلل_ترحيب_العميل_تي_إل_إس(&الرسالة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { الترحيب := القيمة; };
    لو (!يحتوي_رقما_تي_إل_إس(&الترحيب.الإصدارات, 0x0304)) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
    لو (الترحيب.بيانات_مبكرة) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
    دع تفضيل_الحزم: متجه غير_موقع = [0x1303, 0x1301, 0x1302];
    دع الحزمة: غير_موقع = اختر_من_تفضيل_تي_إل_إس(&تفضيل_الحزم, &الترحيب.الحزم);
    لو (الحزمة == 0) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
    دع المخطط: غير_موقع = مخطط_توقيع_الهوية_تي_إل_إس(&الهوية.المفتاح, &الترحيب.المخططات);
    لو (المخطط == 0) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
    (*الحالة).الحزمة := الحزمة;
    دع الخوارزمية: خوارزمية_تجزئة = تجزئة_الحزمة_تي_إل_إس(الحزمة);
    دع النص: متغير متجه غ8 = [];
    ألحق_بايتات_تشفير(&متغير النص, &الرسالة);
    دع أرسل_الوهمي: متغير منطقي = خطأ;
    دع وضع_التوافق: منطقي = (الطول(الترحيب.معرف_الجلسة) مثل غير_موقع) > 0;

    دع المجموعة: متغير غير_موقع = مجموعة_بمشاركة_تي_إل_إس(&الترحيب);
    لو (المجموعة == 0) {
        دع تفضيل_المجموعات: متجه غير_موقع = المجموعات_المدعومة_تي_إل_إس();
        المجموعة := اختر_من_تفضيل_تي_إل_إس(&تفضيل_المجموعات, &الترحيب.المجموعات);
        لو (المجموعة == 0) { أرجع نتيجة.خطأ(خطأ_غير_مدعوم_تي_إل_إس()); };
        // HelloRetryRequest for a share of the selected group (4.1.4).
        النص := بديل_ملخص_ترحيب_خادم_تي_إل_إس(الخوارزمية, &الرسالة);
        دع مشاركة_الإعادة: متغير متجه غ8 = [];
        ألحق_كبير16_تشفير(&متغير مشاركة_الإعادة, المجموعة);
        دع نص_الإعادة: متجه غ8 = بايتات_من_نص(«HelloRetryRequest»);
        دع عشوائي_الإعادة: متجه غ8 = جزئ_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), &نص_الإعادة);
        دع الإعادة: متجه غ8 = ابن_ترحيب_الخادم_تي_إل_إس(&عشوائي_الإعادة, &الترحيب.معرف_الجلسة, الحزمة, &مشاركة_الإعادة);
        طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &الإعادة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        ألحق_بايتات_تشفير(&متغير النص, &الإعادة);
        لو (وضع_التوافق) {
            طابق أرسل_تغيير_تشفير_وهمي_تي_إل_إس(الحالة) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(_) -> { };
            أرسل_الوهمي := صواب;
        };
        طابق اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { الرسالة := القيمة; };
        طابق حلل_ترحيب_العميل_تي_إل_إس(&الرسالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { الترحيب := القيمة; };
        // The second ClientHello must carry exactly the requested share.
        دع مشاركة_مطابقة: منطقي = (الطول(الترحيب.مجموعات_المشاركات) مثل غير_موقع) == 1
            && الترحيب.مجموعات_المشاركات[0] == المجموعة;
        لو (!مشاركة_مطابقة || !يحتوي_رقما_تي_إل_إس(&الترحيب.الحزم, الحزمة)
            || الترحيب.بيانات_مبكرة || !يحتوي_رقما_تي_إل_إس(&الترحيب.الإصدارات, 0x0304)) {
            أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
        };
        ألحق_بايتات_تشفير(&متغير النص, &الرسالة);
    };

    // ServerHello with a fresh share of the selected group.
    دع العشوائي: متجه غ8;
    طابق بايتات_عشوائية_تي_إل_إس(32) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { العشوائي := القيمة; };
    دع مشاركة_الخادم: متغير مشاركة_مفتاح_تي_إل_إس;
    طابق أنشئ_مشاركة_مفتاح_تي_إل_إس(المجموعة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { مشاركة_الخادم := القيمة; };
    دع موضع_النظير: غير_موقع;
    طابق موضع_مشاركة_تي_إل_إس(&الترحيب, المجموعة) مع
    | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); }
    | اختيار.بعض(القيمة) -> { موضع_النظير := القيمة; };
    دع المشترك: متغير متجه غ8;
    طابق سر_مشاركة_مفتاح_تي_إل_إس(&مشاركة_الخادم, &الترحيب.مفاتيح_المشاركات[موضع_النظير]) مع
    | نتيجة.خطأ(الخطأ) -> { امسح_مشاركة_مفتاح_تي_إل_إس(&متغير مشاركة_الخادم); أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { المشترك := القيمة; };
    امسح_مشاركة_مفتاح_تي_إل_إس(&متغير مشاركة_الخادم);
    دع المشاركة: متغير متجه غ8 = [];
    ألحق_كبير16_تشفير(&متغير المشاركة, المجموعة);
    ألحق_متجها_تي_إل_إس(&متغير المشاركة, 2, &مشاركة_الخادم.العام);
    دع ترحيب_الخادم: متجه غ8 = ابن_ترحيب_الخادم_تي_إل_إس(&العشوائي, &الترحيب.معرف_الجلسة, الحزمة, &المشاركة);
    لو (!لا_مصافحة_معلقة_تي_إل_إس(الحالة)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &ترحيب_الخادم) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    ألحق_بايتات_تشفير(&متغير النص, &ترحيب_الخادم);
    لو (وضع_التوافق && !أرسل_الوهمي) {
        طابق أرسل_تغيير_تشفير_وهمي_تي_إل_إس(الحالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
    };

    // Key schedule (7.1) and the server's encrypted flight.
    دع طول_الملخص: غير_موقع = حجم_ملخص_تجزئة(الخوارزمية);
    دع أصفار: متجه غ8 = أصفار_تشفير(طول_الملخص);
    دع لا_ملح: متجه غ8 = [];
    دع المبكر: متجه غ8 = هكدف_استخرج_تشفير(الخوارزمية, &لا_ملح, &أصفار);
    دع مشتق1: متجه غ8 = سر_مشتق_تالي_تي_إل_إس(الخوارزمية, &المبكر);
    دع سر_المصافحة: متغير متجه غ8 = هكدف_استخرج_تشفير(الخوارزمية, &مشتق1, &المشترك);
    امسح_بايتات_تشفير(&متغير المشترك);
    دع ملخص_الترحيب: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
    دع عميل_مصافحة: متغير متجه غ8 = اشتق_سرا_تي_إل_إس(الخوارزمية, &سر_المصافحة, «c hs traffic», &ملخص_الترحيب);
    دع خادم_مصافحة: متغير متجه غ8 = اشتق_سرا_تي_إل_إس(الخوارزمية, &سر_المصافحة, «s hs traffic», &ملخص_الترحيب);
    فعل_مفاتيح_تي_إل_إس(الحالة, صواب, &خادم_مصافحة);
    فعل_مفاتيح_تي_إل_إس(الحالة, خطأ, &عميل_مصافحة);

    دع جسم_الامتدادات: متجه غ8 = [0, 0];
    دع الامتدادات_المشفرة: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_امتدادات_مشفرة_تي_إل_إس(), &جسم_الامتدادات);
    طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &الامتدادات_المشفرة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    ألحق_بايتات_تشفير(&متغير النص, &الامتدادات_المشفرة);

    دع اطلب_شهادة: منطقي = (*الإعداد).تحقق_العميل;
    لو (اطلب_شهادة) {
        // CertificateRequest: empty context, signature_algorithms (4.3.2).
        دع جسم_الطلب: متغير متجه غ8 = [0];
        دع المخططات: متجه غير_موقع = [0x0807, 0x0403, 0x0503, 0x0804, 0x0805, 0x0806];
        دع القائمة: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(المخططات) مثل غير_موقع)) {
            ألحق_كبير16_تشفير(&متغير القائمة, المخططات[ف]);
            ف := ف + 1;
        }
        دع بيانات_التواقيع: متغير متجه غ8 = [];
        ألحق_متجها_تي_إل_إس(&متغير بيانات_التواقيع, 2, &القائمة);
        دع امتدادات_الطلب: متغير متجه غ8 = [];
        ألحق_كبير16_تشفير(&متغير امتدادات_الطلب, امتداد_خوارزميات_التوقيع_تي_إل_إس());
        ألحق_متجها_تي_إل_إس(&متغير امتدادات_الطلب, 2, &بيانات_التواقيع);
        ألحق_متجها_تي_إل_إس(&متغير جسم_الطلب, 2, &امتدادات_الطلب);
        دع رسالة_الطلب: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_طلب_شهادة_تي_إل_إس(), &جسم_الطلب);
        طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &رسالة_الطلب) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        ألحق_بايتات_تشفير(&متغير النص, &رسالة_الطلب);
    };

    // Certificate: empty context, then each certificate without extensions.
    دع القائمة_المرمزة: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(الهوية.السلسلة) مثل غير_موقع)) {
        ألحق_متجها_تي_إل_إس(&متغير القائمة_المرمزة, 3, &الهوية.السلسلة[ف]);
        ألحق_كبير16_تشفير(&متغير القائمة_المرمزة, 0);
        ف := ف + 1;
    }
    دع جسم_الشهادة: متغير متجه غ8 = [0];
    ألحق_متجها_تي_إل_إس(&متغير جسم_الشهادة, 3, &القائمة_المرمزة);
    دع رسالة_الشهادة: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_شهادة_تي_إل_إس(), &جسم_الشهادة);
    طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &رسالة_الشهادة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    ألحق_بايتات_تشفير(&متغير النص, &رسالة_الشهادة);

    // CertificateVerify with the identity key (4.4.3).
    دع ملخص_حتى_الشهادة: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
    دع المحتوى: متجه غ8 = محتوى_تحقق_الشهادة_تي_إل_إس(صواب, &ملخص_حتى_الشهادة);
    دع التوقيع: متجه غ8;
    طابق وقع_تحقق_الشهادة_تي_إل_إس(&الهوية.المفتاح, المخطط, &المحتوى) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { التوقيع := القيمة; };
    دع جسم_التحقق: متغير متجه غ8 = [];
    ألحق_كبير16_تشفير(&متغير جسم_التحقق, المخطط);
    ألحق_متجها_تي_إل_إس(&متغير جسم_التحقق, 2, &التوقيع);
    دع رسالة_التحقق: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_تحقق_شهادة_تي_إل_إس(), &جسم_التحقق);
    طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &رسالة_التحقق) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    ألحق_بايتات_تشفير(&متغير النص, &رسالة_التحقق);

    // Server Finished.
    دع ملخص_حتى_التحقق: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
    دع بيانات_الخادم: متجه غ8 = بيانات_الإنهاء_تي_إل_إس(الخوارزمية, &خادم_مصافحة, &ملخص_حتى_التحقق);
    دع إنهاء_الخادم: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_إنهاء_تي_إل_إس(), &بيانات_الخادم);
    طابق اكتب_رسالة_مصافحة_تي_إل_إس(الحالة, &إنهاء_الخادم) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(_) -> { };
    ألحق_بايتات_تشفير(&متغير النص, &إنهاء_الخادم);

    دع مشتق2: متجه غ8 = سر_مشتق_تالي_تي_إل_إس(الخوارزمية, &سر_المصافحة);
    دع السر_الرئيس: متغير متجه غ8 = هكدف_استخرج_تشفير(الخوارزمية, &مشتق2, &أصفار);
    دع ملخص_حتى_الإنهاء: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
    دع عميل_تطبيق: متغير متجه غ8 = اشتق_سرا_تي_إل_إس(الخوارزمية, &السر_الرئيس, «c ap traffic», &ملخص_حتى_الإنهاء);
    دع خادم_تطبيق: متغير متجه غ8 = اشتق_سرا_تي_إل_إس(الخوارزمية, &السر_الرئيس, «s ap traffic», &ملخص_حتى_الإنهاء);
    فعل_مفاتيح_تي_إل_إس(الحالة, صواب, &خادم_تطبيق);

    // Client flight: optional Certificate/CertificateVerify, then Finished.
    دع رسالة_العميل: متغير متجه غ8;
    طابق اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { رسالة_العميل := القيمة; };
    لو (اطلب_شهادة) {
        لو (رسالة_العميل[0] != (رسالة_شهادة_تي_إل_إس() مثل غ8)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        دع لا_سياق: متجه غ8 = [];
        دع شهادات_العميل: متجه شهادة_إكس509;
        طابق حلل_رسالة_شهادة_تي_إل_إس(&رسالة_العميل, &لا_سياق) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { شهادات_العميل := القيمة; };
        // An empty list is certificate_required (116).
        لو ((الطول(شهادات_العميل) مثل غير_موقع) == 0) { أرجع نتيجة.خطأ(خطأ_شهادة_غير_موثوقة_تي_إل_إس()); };
        ألحق_بايتات_تشفير(&متغير النص, &رسالة_العميل);
        طابق وقت_الآن_بالثواني_تي_إل_إس() مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الآن) -> {
            طابق جذور_ثقة_محللة_تي_إل_إس(&(*الإعداد).جذور_ثقة_العميل) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(الجذور) -> {
                دع لا_اسم: متجه غ8 = [];
                دع الرمز: عدد = رمز_نتيجة_التحقق_تي_إل_إس(تحقق_سلسلة_شهادات_تي_إل_إس(&شهادات_العميل, &الجذور, &لا_اسم, الآن, غرض_تحقق_تي_إل_إس.غرض_عميل()));
                لو (الرمز != 0) { أرجع نتيجة.خطأ(الرمز); };
            };
        };
        طابق اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { رسالة_العميل := القيمة; };
        لو (رسالة_العميل[0] != (رسالة_تحقق_شهادة_تي_إل_إس() مثل غ8)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        طابق حلل_تحقق_الشهادة_تي_إل_إس(&رسالة_العميل) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(التحقق_المستلم) -> {
            دع ملخص_العميل_حتى_الشهادة: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
            دع محتوى_العميل: متجه غ8 = محتوى_تحقق_الشهادة_تي_إل_إس(خطأ, &ملخص_العميل_حتى_الشهادة);
            لو (!تحقق_توقيع_مصافحة_تي_إل_إس(&شهادات_العميل[0].المفتاح, التحقق_المستلم.النوع, &محتوى_العميل, &التحقق_المستلم.البيانات)) {
                أرجع نتيجة.خطأ(خطأ_توقيع_تي_إل_إس());
            };
        };
        ألحق_بايتات_تشفير(&متغير النص, &رسالة_العميل);
        طابق اقرأ_رسالة_مصافحة_تي_إل_إس(الحالة) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> { رسالة_العميل := القيمة; };
    };
    لو (رسالة_العميل[0] != (رسالة_إنهاء_تي_إل_إس() مثل غ8)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    دع ملخص_إنهاء_العميل: متجه غ8 = جزئ_تشفير(الخوارزمية, &النص);
    دع المتوقع: متجه غ8 = بيانات_الإنهاء_تي_إل_إس(الخوارزمية, &عميل_مصافحة, &ملخص_إنهاء_العميل);
    دع المستلم: متجه غ8 = شريحة_بايتات_تشفير(&رسالة_العميل, 4, (الطول(رسالة_العميل) مثل غير_موقع) - 4);
    لو (!بايتات_متساوية_بزمن_ثابت_تشفير(&المتوقع, &المستلم)) { أرجع نتيجة.خطأ(خطأ_توقيع_تي_إل_إس()); };
    لو (!لا_مصافحة_معلقة_تي_إل_إس(الحالة)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
    فعل_مفاتيح_تي_إل_إس(الحالة, خطأ, &عميل_تطبيق);
    (*الحالة).المصافحة_مكتملة := صواب;
    امسح_بايتات_تشفير(&متغير سر_المصافحة);
    امسح_بايتات_تشفير(&متغير عميل_مصافحة);
    امسح_بايتات_تشفير(&متغير خادم_مصافحة);
    امسح_بايتات_تشفير(&متغير السر_الرئيس);
    امسح_بايتات_تشفير(&متغير عميل_تطبيق);
    امسح_بايتات_تشفير(&متغير خادم_تطبيق);
    أرجع نتيجة.نجح(0);
}

عرف بديل_ملخص_ترحيب_خادم_تي_إل_إس(الخوارزمية: خوارزمية_تجزئة, الترحيب_الأول: &متجه غ8): متجه غ8 {
    دع الملخص: متجه غ8 = جزئ_تشفير(الخوارزمية, الترحيب_الأول);
    أرجع رسالة_مصافحة_تي_إل_إس(رسالة_ملخص_الرسالة_تي_إل_إس(), &الملخص);
}

// Runs the server handshake on a fresh connection state. On failure the
// matching alert is sent and the state keeps the error.
عام عرف صافح_كخادم_تي_إل_إس(الحالة: &متغير حالة_اتصال_تي_إل_إس, الإعداد: &إعداد_خادم_تي_إل_إس): نتيجة عدد, عدد {
    طابق نفذ_مصافحة_خادم_تي_إل_إس(الحالة, الإعداد) مع
    | نتيجة.نجح(_) -> { أرجع نتيجة.نجح(0); }
    | نتيجة.خطأ(الخطأ) -> {
        لو (الخطأ <= -2001 && الخطأ > -3000 && الخطأ != خطأ_انقطاع_تي_إل_إس()) {
            أرسل_تنبيها_تي_إل_إس(الحالة, تنبيه_لخطأ_تي_إل_إس(الخطأ));
        };
        (*الحالة).خطأ_دائم := الخطأ;
        أرجع نتيجة.خطأ(الخطأ);
    };
}

library/std/tls/signature.sn:
// CertificateVerify signing and checking (RFC 8446 4.4.3). Only the schemes
// std.tls advertises are accepted; the scheme must match the key type and,
// for ECDSA, the key's curve. RSA keys use RSASSA-PSS (rsa_pss_rsae_*);
// PKCS#1 v1.5 is never valid in CertificateVerify. Ed25519 signs the content
// itself (ed25519, 0x0807).

استورد crypto.digest;
استورد crypto.ecdsa;
استورد crypto.ed25519;
استورد crypto.rsa;
استورد tls.wire;
استورد tls.x509;

عام عرف تحقق_توقيع_مصافحة_تي_إل_إس(
    المفتاح: &مفتاح_عام_إكس509,
    المخطط: غير_موقع,
    المحتوى: &متجه غ8,
    التوقيع: &متجه غ8
): منطقي {
    طابق *المفتاح مع
    | مفتاح_عام_إكس509.مفتاح_إي_سي_إكس509(المفتاح_إي_سي) -> {
        لو (المخطط == مخطط_إي_سي_دي_إس_إيه_بي256_تي_إل_إس()) {
            طابق المفتاح_إي_سي.المنحنى مع
            | منحنى_إهليلجي.منحنى_بي256 -> {
                دع الملخص: متجه غ8 = جزئ_تشفير(خوارزمية_تجزئة.تجزئة_شا256(), المحتوى);
                أرجع تحقق_إي_سي_دي_إس_إيه(منحنى_إهليلجي.منحنى_بي256(), &المفتاح_إي_سي.النقطة, &الملخص, التوقيع);
            }
            | _ -> { أرجع خطأ; };
        };
        لو (المخطط == مخطط_إي_سي_دي_إس_إيه_بي384_تي_إل_إس()) {
            طابق المفتاح_إي_سي.المنحنى مع
            | منحنى_إهليلجي.منحنى_بي384 -> {
                دع الملخص: متجه غ8 = جزئ_تشفير(خوارزمية_تجزئة.تجزئة_شا384(), المحتوى);
                أرجع تحقق_إي_سي_دي_إس_إيه(منحنى_إهليلجي.منحنى_بي384(), &المفتاح_إي_سي.النقطة, &الملخص, التوقيع);
            }
            | _ -> { أرجع خطأ; };
        };
        أرجع خطأ;
    }
    | مفتاح_عام_إكس509.مفتاح_آر_إس_إيه_إكس509(المفتاح_آر_إس_إيه) -> {
        دع التجزئة: متغير خوارزمية_تجزئة = خوارزمية_تجزئة.تجزئة_شا256();
        لو (المخطط == مخطط_بي_إس_إس_شا256_تي_إل_إس()) {
            التجزئة := خوارزمية_تجزئة.تجزئة_شا256();
        } وإلا لو (المخطط == مخطط_بي_إس_إس_شا384_تي_إل_إس()) {
            التجزئة := خوارزمية_تجزئة.تجزئة_شا384();
        } وإلا لو (المخطط == مخطط_بي_إس_إس_شا512_تي_إل_إس()) {
            التجزئة := خوارزمية_تجزئة.تجزئة_شا512();
        } وإلا {
            أرجع خطأ;
        };
        دع الملخص: متجه غ8 = جزئ_تشفير(التجزئة, المحتوى);
        أرجع تحقق_آر_إس_إيه_بي_إس_إس(&المفتاح_آر_إس_إيه, التجزئة, &الملخص, التوقيع);
    }
    | مفتاح_عام_إكس509.مفتاح_إد25519_إكس509(العام) -> {
        لو (المخطط != مخطط_إد25519_تي_إل_إس()) { أرجع خطأ; };
        أرجع تحقق_إد25519(&العام, المحتوى, التوقيع);
    }
    | مفتاح_عام_إكس509.مفتاح_غير_مدعوم_إكس509 -> { أرجع خطأ; };
}

library/std/tls/stream.sn:
استورد net.tcp;
استورد os.socket;
استورد tls.client;
استورد tls.config;
استورد tls.errors;
استورد tls.record;
استورد tls.server;
استورد tls.wire;

// TLS streams over a TCP connection, implemented entirely in std (record
// layer, key schedule and handshakes in std.tls, primitives in std.crypto).
// There is no runtime or C provider. A stream owns its socket from the
// moment it is wrapped. The handshake runs on the first explicit
// صافح_تدفق_تي_إل_إس, read or write; a failed handshake or record leaves a
// sticky error and sends the matching alert. Reads return 0 after the
// peer's close_notify; a connection that ends without it is reported as
// خطأ_انقطاع_تي_إل_إس (truncation, RFC 8446 6.1).
//
// The std reader/writer contracts pass streams by shared reference, while
// TLS must advance sequence numbers and buffers on every call: each call
// copies the boxed connection state out, works on it, and stores it back
// into the box (*(*التدفق) := ...), the box being the stream's heap cell.

نوع دور_تدفق_تي_إل_إس =
    | دور_عميل بنوع إعداد_عميل_تي_إل_إس
    | دور_خادم بنوع إعداد_خادم_تي_إل_إس
;

نوع حالة_تدفق_تي_إل_إس = {
    الاتصال: حالة_اتصال_تي_إل_إس,
    الدور: دور_تدفق_تي_إل_إس
};

// The box holds mutable state: stream operations update it through a shared
// stream reference, which the reader and writer callback shapes require.
عام نوع تدفق_تي_إل_إس = صندوق متغير حالة_تدفق_تي_إل_إس;

// Takes the stream state out of its box for one operation, leaving an inert
// state (no socket, no buffers) in its place; احفظ_حالة_تي_إل_إس stores it
// back on every exit path.
عرف حالة_تي_إل_إس(التدفق: &تدفق_تي_إل_إس): حالة_تدفق_تي_إل_إس {
    دع جذور_فارغة: متجه شهادة_تي_إل_إس = [];
    دع الإعداد_الخامل: إعداد_عميل_تي_إل_إس = {
        تحقق_النظير: خطأ,
        اسم_الخادم: اختيار.لا_شيء(),
        جذور_الثقة: جذور_فارغة
    };
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = {
        الاتصال: أنشئ_حالة_اتصال_تي_إل_إس(-1, خطأ),
        الدور: دور_تدفق_تي_إل_إس.دور_عميل(الإعداد_الخامل)
    };
    بدّل( **التدفق, الحالة);
    أرجع الحالة;
}

عرف احفظ_حالة_تي_إل_إس(التدفق: &تدفق_تي_إل_إس, الحالة: حالة_تدفق_تي_إل_إس): فراغ {
    *(*التدفق) := الحالة;
}

عرف أنشئ_تدفق_تي_إل_إس(المقبس: عدد, الدور: دور_تدفق_تي_إل_إس, خادم: منطقي): تدفق_تي_إل_إس {
    // The stream is a box of mutable state (تدفق_تي_إل_إس), so the boxed value is mutable.
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = {
        الاتصال: أنشئ_حالة_اتصال_تي_إل_إس(المقبس, خادم),
        الدور: الدور
    };
    دع التدفق: تدفق_تي_إل_إس = صندوق الحالة;
    أرجع التدفق;
}

عام عرف غلف_عميل_تي_إل_إس(التدفق: تدفق_تي_سي_بي, الإعداد: &إعداد_عميل_تي_إل_إس): نتيجة تدفق_تي_إل_إس, عدد {
    دع المقبس: عدد = سلم_مقبس_تدفق_تي_سي_بي(التدفق);
    دع الدور: دور_تدفق_تي_إل_إس = دور_تدفق_تي_إل_إس.دور_عميل(انسخ_إعداد_عميل_تي_إل_إس(الإعداد));
    أرجع نتيجة.نجح(أنشئ_تدفق_تي_إل_إس(المقبس, الدور, خطأ));
}

عام عرف غلف_خادم_تي_إل_إس(التدفق: تدفق_تي_سي_بي, الإعداد: &إعداد_خادم_تي_إل_إس): نتيجة تدفق_تي_إل_إس, عدد {
    دع المقبس: عدد = سلم_مقبس_تدفق_تي_سي_بي(التدفق);
    دع الدور: دور_تدفق_تي_إل_إس = دور_تدفق_تي_إل_إس.دور_خادم(انسخ_إعداد_خادم_تي_إل_إس(الإعداد));
    أرجع نتيجة.نجح(أنشئ_تدفق_تي_إل_إس(المقبس, الدور, صواب));
}

// Runs the handshake once; later calls report the outcome again.
عرف صافح_حالة_تي_إل_إس(الحالة: &متغير حالة_تدفق_تي_إل_إس): نتيجة عدد, عدد {
    لو ((*الحالة).الاتصال.خطأ_دائم != 0) { أرجع نتيجة.خطأ((*الحالة).الاتصال.خطأ_دائم); };
    لو ((*الحالة).الاتصال.مغلقة) { أرجع نتيجة.خطأ(خطأ_تدفق_مغلق_تي_إل_إس()); };
    لو ((*الحالة).الاتصال.المصافحة_مكتملة) { أرجع نتيجة.نجح(0); };
    طابق (*الحالة).الدور مع
    | دور_تدفق_تي_إل_إس.دور_عميل(الإعداد) -> {
        أرجع صافح_كعميل_تي_إل_إس(&متغير (*الحالة).الاتصال, &الإعداد);
    }
    | دور_تدفق_تي_إل_إس.دور_خادم(الإعداد) -> {
        أرجع صافح_كخادم_تي_إل_إس(&متغير (*الحالة).الاتصال, &الإعداد);
    };
}

عام عرف صافح_تدفق_تي_إل_إس(التدفق: &تدفق_تي_إل_إس): نتيجة عدد, عدد {
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = حالة_تي_إل_إس(التدفق);
    دع الناتج: نتيجة عدد, عدد = صافح_حالة_تي_إل_إس(&متغير الحالة);
    احفظ_حالة_تي_إل_إس(التدفق, الحالة);
    أرجع الناتج;
}

// Records a fatal failure: the alert goes out once and the error sticks.
عرف أفشل_اتصال_تي_إل_إس(الاتصال: &متغير حالة_اتصال_تي_إل_إس, الخطأ: عدد): عدد {
    لو (الخطأ <= -2001 && الخطأ > -3000 && الخطأ != خطأ_انقطاع_تي_إل_إس()) {
        أرسل_تنبيها_تي_إل_إس(الاتصال, تنبيه_لخطأ_تي_إل_إس(الخطأ));
    };
    (*الاتصال).خطأ_دائم := الخطأ;
    أرجع الخطأ;
}

// Post-handshake handshake messages (RFC 8446 4.6): NewSessionTicket is
// ignored by clients (no resumption) and KeyUpdate rotates the keys.
عرف عالج_رسائل_ما_بعد_المصافحة_تي_إل_إس(الاتصال: &متغير حالة_اتصال_تي_إل_إس): نتيجة عدد, عدد {
    بينما (صواب) {
        دع المتاح: غير_موقع = الطول((*الاتصال).وارد_مصافحة) مثل غير_موقع;
        لو (المتاح < 4) { أرجع نتيجة.نجح(0); };
        دع الطول_المعلن: غير_موقع = ((*الاتصال).وارد_مصافحة[1] مثل غير_موقع) * 65536
            + ((*الاتصال).وارد_مصافحة[2] مثل غير_موقع) * 256
            + ((*الاتصال).وارد_مصافحة[3] مثل غير_موقع);
        لو (الطول_المعلن > 65536) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
        لو (المتاح < 4 + الطول_المعلن) { أرجع نتيجة.نجح(0); };
        دع النوع: غير_موقع = (*الاتصال).وارد_مصافحة[0] مثل غير_موقع;
        دع طلب_تحديث: متغير غير_موقع = 2;
        لو (النوع == رسالة_تحديث_المفتاح_تي_إل_إس()) {
            لو (الطول_المعلن != 1) { أرجع نتيجة.خطأ(خطأ_ترميز_تي_إل_إس()); };
            طلب_تحديث := (*الاتصال).وارد_مصافحة[4] مثل غير_موقع;
            لو (طلب_تحديث > 1) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
        } وإلا لو (النوع != رسالة_تذكرة_جلسة_تي_إل_إس() || (*الاتصال).خادم) {
            أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
        };
        دع الباقي: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 4 + الطول_المعلن;
        بينما (ف < المتاح) {
            ألحق(الباقي, (*الاتصال).وارد_مصافحة[ف]);
            ف := ف + 1;
        }
        (*الاتصال).وارد_مصافحة := الباقي;
        لو (طلب_تحديث < 2) {
            // KeyUpdate must end its record (5.1): no buffered remainder.
            لو (!لا_مصافحة_معلقة_تي_إل_إس(الاتصال)) { أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس()); };
            حدث_مفاتيح_تي_إل_إس(الاتصال, خطأ);
            لو (طلب_تحديث == 1) {
                دع الجسم: متجه غ8 = [0];
                دع الرد: متجه غ8 = رسالة_مصافحة_تي_إل_إس(رسالة_تحديث_المفتاح_تي_إل_إس(), &الجسم);
                طابق اكتب_رسالة_مصافحة_تي_إل_إس(الاتصال, &الرد) مع
                | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                | نتيجة.نجح(_) -> { };
                حدث_مفاتيح_تي_إل_إس(الاتصال, صواب);
            };
        };
    }
    أرجع نتيجة.نجح(0);
}

// Delivers buffered application data, reading records as needed.
عرف اقرأ_تطبيق_تي_إل_إس(
    الاتصال: &متغير حالة_اتصال_تي_إل_إس,
    المخزن: &متغير متجه غ8,
    الإزاحة: عدد,
    العدد: عدد
): نتيجة عدد, عدد {
    بينما (صواب) {
        دع المتاح: غير_موقع = (الطول((*الاتصال).وارد_تطبيق) مثل غير_موقع) - (*الاتصال).موضع_التطبيق;
        لو (المتاح > 0) {
            دع المنسوخ: متغير غير_موقع = العدد مثل غير_موقع;
            لو (المنسوخ > المتاح) { المنسوخ := المتاح; };
            دع ف: متغير غير_موقع = 0;
            بينما (ف < المنسوخ) {
                (*المخزن)[(الإزاحة مثل غير_موقع) + ف] := (*الاتصال).وارد_تطبيق[(*الاتصال).موضع_التطبيق + ف];
                ف := ف + 1;
            }
            (*الاتصال).موضع_التطبيق := (*الاتصال).موضع_التطبيق + المنسوخ;
            لو ((*الاتصال).موضع_التطبيق == (الطول((*الاتصال).وارد_تطبيق) مثل غير_موقع)) {
                دع فارغ: متجه غ8 = [];
                (*الاتصال).وارد_تطبيق := فارغ;
                (*الاتصال).موضع_التطبيق := 0;
            };
            أرجع نتيجة.نجح(المنسوخ مثل عدد);
        };
        لو ((*الاتصال).نهاية_مستلمة) { أرجع نتيجة.نجح(0); };
        طابق اقرأ_سجل_تي_إل_إس(الاتصال) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح({ النوع: نوع_السجل, البيانات: البيانات }) -> {
            لو (نوع_السجل == نوع_بيانات_تطبيق_تي_إل_إس()) {
                (*الاتصال).وارد_تطبيق := البيانات;
                (*الاتصال).موضع_التطبيق := 0;
            } وإلا لو (نوع_السجل == نوع_تنبيه_تي_إل_إس()) {
                دع الحالة: عدد = عالج_تنبيها_مستلما_تي_إل_إس(&البيانات);
                لو (الحالة == 0) {
                    (*الاتصال).نهاية_مستلمة := صواب;
                    أرجع نتيجة.نجح(0);
                };
                أرجع نتيجة.خطأ(الحالة);
            } وإلا {
                ألحق_بايتات_سجل_مصافحة_تي_إل_إس(الاتصال, &البيانات);
                طابق عالج_رسائل_ما_بعد_المصافحة_تي_إل_إس(الاتصال) مع
                | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                | نتيجة.نجح(_) -> { };
            };
        };
    }
    أرجع نتيجة.خطأ(خطأ_بروتوكول_تي_إل_إس());
}

عرف ألحق_بايتات_سجل_مصافحة_تي_إل_إس(الاتصال: &متغير حالة_اتصال_تي_إل_إس, البيانات: &متجه غ8): فراغ {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*البيانات) مثل غير_موقع)) {
        ألحق((*الاتصال).وارد_مصافحة, (*البيانات)[ف]);
        ف := ف + 1;
    }
}

عرف نطاق_مخزن_صالح_تي_إل_إس(الحجم: عدد, الإزاحة: عدد, العدد: عدد): منطقي {
    لو (الإزاحة < 0 || العدد < 0 || الإزاحة > الحجم) { أرجع خطأ; };
    أرجع العدد <= الحجم - الإزاحة;
}

عام عرف اقرأ_تدفق_تي_إل_إس(
    التدفق: &تدفق_تي_إل_إس,
    المخزن: &متغير متجه غ8,
    الإزاحة: عدد,
    العدد: عدد
): نتيجة عدد, عدد {
    لو (!نطاق_مخزن_صالح_تي_إل_إس(الطول(*المخزن), الإزاحة, العدد)) { أرجع نتيجة.خطأ(خطأ_وسيط_تي_إل_إس()); };
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = حالة_تي_إل_إس(التدفق);
    طابق صافح_حالة_تي_إل_إس(&متغير الحالة) مع
    | نتيجة.خطأ(الخطأ) -> {
        احفظ_حالة_تي_إل_إس(التدفق, الحالة);
        أرجع نتيجة.خطأ(الخطأ);
    }
    | نتيجة.نجح(_) -> { };
    لو (العدد == 0) {
        احفظ_حالة_تي_إل_إس(التدفق, الحالة);
        أرجع نتيجة.نجح(0);
    };
    دع الناتج: نتيجة عدد, عدد = اقرأ_تطبيق_تي_إل_إس(&متغير الحالة.الاتصال, المخزن, الإزاحة, العدد);
    طابق الناتج مع
    | نتيجة.خطأ(الخطأ) -> {
        دع الرمز: عدد = أفشل_اتصال_تي_إل_إس(&متغير الحالة.الاتصال, الخطأ);
        احفظ_حالة_تي_إل_إس(التدفق, الحالة);
        أرجع نتيجة.خطأ(الرمز);
    }
    | نتيجة.نجح(المقروء) -> {
        احفظ_حالة_تي_إل_إس(التدفق, الحالة);
        أرجع نتيجة.نجح(المقروء);
    };
}

عام عرف اكتب_تدفق_تي_إل_إس(
    التدفق: &تدفق_تي_إل_إس,
    المحتوى: &متجه غ8,
    الإزاحة: عدد,
    العدد: عدد
): نتيجة عدد, عدد {
    لو (!نطاق_مخزن_صالح_تي_إل_إس(الطول(*المحتوى), الإزاحة, العدد)) { أرجع نتيجة.خطأ(خطأ_وسيط_تي_إل_إس()); };
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = حالة_تي_إل_إس(التدفق);
    طابق صافح_حالة_تي_إل_إس(&متغير الحالة) مع
    | نتيجة.خطأ(الخطأ) -> {
        احفظ_حالة_تي_إل_إس(التدفق, الحالة);
        أرجع نتيجة.خطأ(الخطأ);
    }
    | نتيجة.نجح(_) -> { };
    دع المكتوب: متغير غير_موقع = 0;
    دع الكلي: غير_موقع = العدد مثل غير_موقع;
    بينما (المكتوب < الكلي) {
        دع الجزء: متغير غير_موقع = الكلي - المكتوب;
        لو (الجزء > 16384) { الجزء := 16384; };
        دع القطعة: متغير متجه غ8 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < الجزء) {
            ألحق(القطعة, (*المحتوى)[(الإزاحة مثل غير_موقع) + المكتوب + ف]);
            ف := ف + 1;
        }
        طابق اكتب_سجل_تي_إل_إس(&متغير الحالة.الاتصال, نوع_بيانات_تطبيق_تي_إل_إس(), &القطعة) مع
        | نتيجة.خطأ(الخطأ) -> {
            دع الرمز: عدد = أفشل_اتصال_تي_إل_إس(&متغير الحالة.الاتصال, الخطأ);
            احفظ_حالة_تي_إل_إس(التدفق, الحالة);
            أرجع نتيجة.خطأ(الرمز);
        }
        | نتيجة.نجح(_) -> { };
        المكتوب := المكتوب + الجزء;
    }
    احفظ_حالة_تي_إل_إس(التدفق, الحالة);
    أرجع نتيجة.نجح(العدد);
}

// Sends close_notify after a completed handshake, then closes the socket.
عام عرف أغلق_تدفق_تي_إل_إس(التدفق: تدفق_تي_إل_إس): نتيجة عدد, عدد {
    // Moving the state out of the owned box consumes the box.
    دع الحالة: متغير حالة_تدفق_تي_إل_إس = *التدفق;
    لو (الحالة.الاتصال.المصافحة_مكتملة && الحالة.الاتصال.خطأ_دائم == 0 && !الحالة.الاتصال.مغلقة) {
        أرسل_تنبيها_تي_إل_إس(&متغير الحالة.الاتصال, 0);
    };
    دع المقبس: متغير مقبس_نظام = { القيمة: الحالة.الاتصال.المقبس, مفتوح: صواب };
    طابق أغلق_مقبس_نظام(&متغير المقبس) مع
    | نتيجة.خطأ(_) -> { أرجع نتيجة.خطأ(خطأ_انقطاع_تي_إل_إس()); }
    | نتيجة.نجح(_) -> { };
    أرجع نتيجة.نجح(0);
}

عام عرف اتصل_عميل_تي_إل_إس(التدفق: تدفق_تي_سي_بي, الإعداد: &إعداد_عميل_تي_إل_إس): نتيجة تدفق_تي_إل_إس, عدد {
    طابق غلف_عميل_تي_إل_إس(التدفق, الإعداد) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الآمن) -> {
        طابق صافح_تدفق_تي_إل_إس(&الآمن) مع
        | نتيجة.خطأ(الخطأ) -> { دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_إل_إس(الآمن); أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { أرجع نتيجة.نجح(الآمن); };
    };
}

عام عرف اقبل_خادم_تي_إل_إس(التدفق: تدفق_تي_سي_بي, الإعداد: &إعداد_خادم_تي_إل_إس): نتيجة تدفق_تي_إل_إس, عدد {
    طابق غلف_خادم_تي_إل_إس(التدفق, الإعداد) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الآمن) -> {
        طابق صافح_تدفق_تي_إل_إس(&الآمن) مع
        | نتيجة.خطأ(الخطأ) -> { دع تجاهل: نتيجة عدد, عدد = أغلق_تدفق_تي_إل_إس(الآمن); أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { أرجع نتيجة.نجح(الآمن); };
    };
}

عام نوع tls_stream = تدفق_تي_إل_إس;
عام مرادف tls_wrap_client = غلف_عميل_تي_إل_إس;
عام مرادف tls_wrap_server = غلف_خادم_تي_إل_إس;
عام مرادف tls_handshake = صافح_تدفق_تي_إل_إس;
عام مرادف tls_read = اقرأ_تدفق_تي_إل_إس;
عام مرادف tls_write = اكتب_تدفق_تي_إل_إس;
عام مرادف tls_close = أغلق_تدفق_تي_إل_إس;
عام مرادف tls_client_connect = اتصل_عميل_تي_إل_إس;
عام مرادف tls_server_accept = اقبل_خادم_تي_إل_إس;

library/std/tls/trust.sn:
// System trust anchors for TLS peer verification.
//
// The bundle locations are those Go crypto/x509 searches on Linux
// (root_linux.go); the first readable bundle is used, and SSL_CERT_FILE,
// when set, replaces the search as in Go and OpenSSL. On macOS the
// Apple-maintained PEM bundle /etc/ssl/cert.pem is read; keychain trust
// settings are not consulted. Windows (CryptoAPI system stores) and WASI
// (no host store) have no system anchors here: a connection there must be
// configured with explicit roots, otherwise verification fails with
// خطأ_مخزن_الثقة_تي_إل_إس. Certificates that do not parse are skipped.

استورد encoding.pem;
استورد env.environment;
استورد fs.read_file;
استورد tls.errors;
استورد tls.x509;

لو (الهدف.المنصة == «linux») {
    عرف مسارات_جذور_النظام_تي_إل_إس(): متجه نص {
        دع المسارات: متجه نص = [
            «/etc/ssl/certs/ca-certificates.crt»,
            «/etc/pki/tls/certs/ca-bundle.crt»,
            «/etc/ssl/ca-bundle.pem»,
            «/etc/pki/tls/cacert.pem»,
            «/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem»,
            «/etc/ssl/cert.pem»
        ];
        أرجع المسارات;
    }
}

لو (الهدف.المنصة == «macos») {
    عرف مسارات_جذور_النظام_تي_إل_إس(): متجه نص {
        دع المسارات: متجه نص = [«/etc/ssl/cert.pem»];
        أرجع المسارات;
    }
}

لو (الهدف.المنصة == «windows» || الهدف.المنصة == «wasi») {
    عرف مسارات_جذور_النظام_تي_إل_إس(): متجه نص {
        دع المسارات: متجه نص = [];
        أرجع المسارات;
    }
}

// Parses every CERTIFICATE block of a PEM bundle.
عام عرف شهادات_من_حزمة_بي_إي_إم_تي_إل_إس(البيانات: &متجه غ8): متجه شهادة_إكس509 {
    دع الكتل: متجه متجه غ8 = كتل_بي_إي_إم_بوصف(البيانات, «CERTIFICATE»);
    دع الشهادات: متغير متجه شهادة_إكس509 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(الكتل) مثل غير_موقع)) {
        طابق حلل_شهادة_إكس509(&الكتل[ف]) مع
        | اختيار.لا_شيء -> { }
        | اختيار.بعض(الشهادة) -> { ألحق(الشهادات, الشهادة); };
        ف := ف + 1;
    }
    أرجع الشهادات;
}

عرف اقرأ_حزمة_جذور_تي_إل_إس(المسار: &نص): اختيار متجه شهادة_إكس509 {
    طابق اقرأ_بايتات_ملف(المسار) مع
    | نتيجة.خطأ(_) -> { أرجع اختيار.لا_شيء(); }
    | نتيجة.نجح(البيانات) -> {
        دع الشهادات: متجه شهادة_إكس509 = شهادات_من_حزمة_بي_إي_إم_تي_إل_إس(&البيانات);
        لو ((الطول(الشهادات) مثل غير_موقع) == 0) { أرجع اختيار.لا_شيء(); };
        أرجع اختيار.بعض(الشهادات);
    };
}

// The platform trust anchors, or خطأ_مخزن_الثقة_تي_إل_إس when none can be read.
عام عرف جذور_النظام_تي_إل_إس(): نتيجة متجه شهادة_إكس509, عدد {
    دع اسم_المتغير: نص = «SSL_CERT_FILE»;
    طابق متغير_بيئة(&اسم_المتغير) مع
    | نتيجة.نجح(القيمة) -> {
        طابق القيمة مع
        | اختيار.بعض(المسار) -> {
            طابق اقرأ_حزمة_جذور_تي_إل_إس(&المسار) مع
            | اختيار.بعض(الشهادات) -> { أرجع نتيجة.نجح(الشهادات); }
            | اختيار.لا_شيء -> { أرجع نتيجة.خطأ(خطأ_مخزن_الثقة_تي_إل_إس()); };
        }
        | اختيار.لا_شيء -> { };
    }
    | نتيجة.خطأ(_) -> { };
    دع المسارات: متجه نص = مسارات_جذور_النظام_تي_إل_إس();
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(المسارات) مثل غير_موقع)) {
        طابق اقرأ_حزمة_جذور_تي_إل_إس(&المسارات[ف]) مع
        | اختيار.بعض(الشهادات) -> { أرجع نتيجة.نجح(الشهادات); }
        | اختيار.لا_شيء -> { };
        ف := ف + 1;
    }
    أرجع نتيجة.خطأ(خطأ_مخزن_الثقة_تي_إل_إس());
}

عام مرادف tls_system_roots = جذور_النظام_تي_إل_إس;
عام مرادف tls_certificates_from_pem = شهادات_من_حزمة_بي_إي_إم_تي_إل_إس;

library/std/tls/verify.sn:
استورد text.from_bytes;
// Certificate path building and validation for TLS (RFC 5280 section 6,
// profiled as Go crypto/x509 and webpki do for the Web PKI) and server
// identity checks (RFC 6125 / RFC 9525).
//
// A path is built depth-first from the leaf through the peer-supplied
// intermediates to a trust anchor, matching issuer and subject names
// byte-for-byte and verifying every signature. Each certificate must be
// within its validity period, free of unhandled critical extensions, and
// (when it issues) a CA with keyCertSign and a satisfied path length. The
// extended key usage must permit the requested purpose along the whole path,
// and DNS/IP name constraints are enforced. There is no fallback: any
// failure rejects the peer.

استورد chars.ascii;
استورد crypto.words;
استورد tls.x509;

عام نوع غرض_تحقق_تي_إل_إس =
    | غرض_خادم
    | غرض_عميل
;

عام نوع نتيجة_تحقق_شهادة_تي_إل_إس =
    | سلسلة_موثوقة
    | لا_مسار_موثوق
    | شهادة_منتهية
    | اسم_غير_مطابق
    | شهادة_تالفة
;

عرف بايت_تحقق(النص: نص): غ8 {
    أرجع النص[0];
}

عرف تسميات_تحقق(الاسم: &متجه غ8): متجه متجه غ8 {
    دع نقطة: غ8 = بايت_تحقق(«.»);
    دع التسميات: متغير متجه متجه غ8 = [];
    دع الحالية: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*الاسم) مثل غير_موقع)) {
        دع ب: غ8 = (*الاسم)[ف];
        لو (ب == نقطة) {
            ألحق(التسميات, الحالية);
            دع فارغة: متجه غ8 = [];
            الحالية := فارغة;
        } وإلا {
            ألحق(الحالية, إلى_صغير_أسكي(ب));
        };
        ف := ف + 1;
    }
    ألحق(التسميات, الحالية);
    أرجع التسميات;
}

// A host name usable as a reference identifier: ASCII letters, digits,
// hyphens and dots, non-empty labels, at most 253 bytes, one optional
// trailing dot removed by the caller.
عرف اسم_مضيف_صالح_تحقق(الاسم: &متجه غ8): منطقي {
    دع الحجم: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    لو (الحجم == 0 || الحجم > 253) { أرجع خطأ; };
    دع شرطة: غ8 = بايت_تحقق(«-»);
    دع نقطة: غ8 = بايت_تحقق(«.»);
    دع طول_التسمية: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحجم) {
        دع ب: غ8 = (*الاسم)[ف];
        لو (ب == نقطة) {
            لو (طول_التسمية == 0) { أرجع خطأ; };
            طول_التسمية := 0;
        } وإلا {
            دع حرف_صالح: منطقي = حرف_أو_رقم_أسكي(ب) || ب == شرطة;
            لو (!حرف_صالح) { أرجع خطأ; };
            طول_التسمية := طول_التسمية + 1;
            لو (طول_التسمية > 63) { أرجع خطأ; };
        };
        ف := ف + 1;
    }
    أرجع طول_التسمية > 0;
}

// RFC 6125 6.4.3 as profiled by RFC 9525 / Go: the wildcard may only be
// the complete left-most label and matches exactly one label; the pattern
// must keep at least two further labels.
عرف اسم_يطابق_نمطا_تحقق(النمط: &متجه غ8, الاسم: &متجه غ8): منطقي {
    دع نجمة: غ8 = بايت_تحقق(«*»);
    دع أ: متجه متجه غ8 = تسميات_تحقق(النمط);
    دع ب: متجه متجه غ8 = تسميات_تحقق(الاسم);
    دع عدد_أ: غير_موقع = الطول(أ) مثل غير_موقع;
    لو (عدد_أ != (الطول(ب) مثل غير_موقع)) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < عدد_أ) {
        دع بري: منطقي = ف == 0 && (الطول(أ[0]) مثل غير_موقع) == 1 && أ[0][0] == نجمة;
        لو (بري) {
            لو (عدد_أ < 3 || (الطول(ب[0]) مثل غير_موقع) == 0) { أرجع خطأ; };
        } وإلا {
            لو ((الطول(أ[ف]) مثل غير_موقع) == 0) { أرجع خطأ; };
            لو (!متساويان_تحقق(&أ[ف], &ب[ف])) { أرجع خطأ; };
        };
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف متساويان_تحقق(أ: &متجه غ8, ب: &متجه غ8): منطقي {
    دع الحجم: غير_موقع = الطول(*أ) مثل غير_موقع;
    لو (الحجم != (الطول(*ب) مثل غير_موقع)) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحجم) {
        لو ((*أ)[ف] != (*ب)[ف]) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

// IPv4 dotted-quad or IPv6 text as 4 or 16 address bytes; none for a DNS name.
عام عرف عنوان_آي_بي_مضيف_تي_إل_إس(الاسم: &متجه غ8): اختيار متجه غ8 {
    دع نقطة: غ8 = بايت_تحقق(«.»);
    دع نقطتان: غ8 = بايت_تحقق(«:»);
    دع الحجم: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    دع فيه_نقطتان: متغير منطقي = خطأ;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحجم) {
        لو ((*الاسم)[ف] == نقطتان) { فيه_نقطتان := صواب; };
        ف := ف + 1;
    }
    لو (فيه_نقطتان) { أرجع عنوان_آي_بي6_من_نص_تحقق(الاسم); };
    // IPv4: exactly four decimal octets without leading zeros.
    دع الناتج: متغير متجه غ8 = [];
    دع القيمة: متغير غير_موقع = 0;
    دع الأرقام: متغير غير_موقع = 0;
    ف := 0;
    بينما (ف < الحجم) {
        دع ب: غ8 = (*الاسم)[ف];
        لو (ب == نقطة) {
            لو (الأرقام == 0) { أرجع اختيار.لا_شيء(); };
            ألحق(الناتج, القيمة مثل غ8);
            القيمة := 0;
            الأرقام := 0;
        } وإلا لو (رقم_عشري(ب)) {
            لو (الأرقام > 0 && القيمة == 0) { أرجع اختيار.لا_شيء(); };
            القيمة := القيمة * 10 + (قيمة_رقم_أسكي(ب) مثل غير_موقع);
            الأرقام := الأرقام + 1;
            لو (القيمة > 255) { أرجع اختيار.لا_شيء(); };
        } وإلا {
            أرجع اختيار.لا_شيء();
        };
        ف := ف + 1;
    }
    لو (الأرقام == 0) { أرجع اختيار.لا_شيء(); };
    ألحق(الناتج, القيمة مثل غ8);
    لو ((الطول(الناتج) مثل غير_موقع) != 4) { أرجع اختيار.لا_شيء(); };
    أرجع اختيار.بعض(الناتج);
}

// IPv6 text (RFC 4291 2.2 forms 1 and 2; an embedded IPv4 tail is refused).
عرف عنوان_آي_بي6_من_نص_تحقق(الاسم: &متجه غ8): اختيار متجه غ8 {
    دع نقطتان: غ8 = بايت_تحقق(«:»);
    دع الحجم: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    دع القبل: متغير متجه غير_موقع = [];
    دع البعد: متغير متجه غير_موقع = [];
    دع بعد_الضغط: متغير منطقي = خطأ;
    دع القيمة: متغير غير_موقع = 0;
    دع الأرقام: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    لو (الحجم >= 2 && (*الاسم)[0] == نقطتان && (*الاسم)[1] == نقطتان) {
        بعد_الضغط := صواب;
        ف := 2;
    } وإلا لو (الحجم >= 1 && (*الاسم)[0] == نقطتان) {
        أرجع اختيار.لا_شيء();
    };
    بينما (ف < الحجم) {
        لو ((*الاسم)[ف] == نقطتان) {
            لو (الأرقام == 0) {
                لو (بعد_الضغط) { أرجع اختيار.لا_شيء(); };
                بعد_الضغط := صواب;
            } وإلا {
                لو (بعد_الضغط) { ألحق(البعد, القيمة); } وإلا { ألحق(القبل, القيمة); };
                لو (ف + 1 < الحجم && (*الاسم)[ف + 1] == نقطتان) {
                    لو (بعد_الضغط) { أرجع اختيار.لا_شيء(); };
                    بعد_الضغط := صواب;
                    ف := ف + 1;
                } وإلا لو (ف + 1 == الحجم) {
                    أرجع اختيار.لا_شيء();
                };
            };
            القيمة := 0;
            الأرقام := 0;
        } وإلا {
            دع ر: عدد = قيمة_سداسية((*الاسم)[ف]);
            لو (ر < 0) { أرجع اختيار.لا_شيء(); };
            القيمة := القيمة * 16 + (ر مثل غير_موقع);
            الأرقام := الأرقام + 1;
            لو (الأرقام > 4) { أرجع اختيار.لا_شيء(); };
        };
        ف := ف + 1;
    }
    لو (الأرقام > 0) {
        لو (بعد_الضغط) { ألحق(البعد, القيمة); } وإلا { ألحق(القبل, القيمة); };
    };
    دع المجموع: غير_موقع = (الطول(القبل) مثل غير_موقع) + (الطول(البعد) مثل غير_موقع);
    لو ((!بعد_الضغط && المجموع != 8) || (بعد_الضغط && المجموع > 7)) { أرجع اختيار.لا_شيء(); };
    دع الناتج: متغير متجه غ8 = [];
    ف := 0;
    بينما (ف < (الطول(القبل) مثل غير_موقع)) {
        ألحق(الناتج, (القبل[ف] >> 8) مثل غ8);
        ألحق(الناتج, (القبل[ف] & 0xFF) مثل غ8);
        ف := ف + 1;
    }
    ف := المجموع;
    بينما (ف < 8) {
        ألحق(الناتج, 0 مثل غ8);
        ألحق(الناتج, 0 مثل غ8);
        ف := ف + 1;
    }
    ف := 0;
    بينما (ف < (الطول(البعد) مثل غير_موقع)) {
        ألحق(الناتج, (البعد[ف] >> 8) مثل غ8);
        ألحق(الناتج, (البعد[ف] & 0xFF) مثل غ8);
        ف := ف + 1;
    }
    أرجع اختيار.بعض(الناتج);
}

عرف بلا_نقطة_ختامية_تحقق(الاسم: &متجه غ8): متجه غ8 {
    دع نقطة: غ8 = بايت_تحقق(«.»);
    دع الحجم: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    لو (الحجم > 0 && (*الاسم)[الحجم - 1] == نقطة) {
        أرجع شريحة_بايتات_تشفير(الاسم, 0, الحجم - 1);
    };
    أرجع انسخ_بايتات(الاسم);
}

// Server identity (RFC 9525 6.3): a DNS reference identity matches a SAN
// dNSName, an IP literal matches a SAN iPAddress. The subject common name is
// never consulted.
عام عرف شهادة_تطابق_المضيف_تي_إل_إس(الشهادة: &شهادة_إكس509, المضيف: &متجه غ8): منطقي {
    طابق عنوان_آي_بي_مضيف_تي_إل_إس(المضيف) مع
    | اختيار.بعض(العنوان) -> {
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول((*الشهادة).عناوين_آي_بي) مثل غير_موقع)) {
            لو (متساويان_تحقق(&(*الشهادة).عناوين_آي_بي[ف], &العنوان)) { أرجع صواب; };
            ف := ف + 1;
        }
        أرجع خطأ;
    }
    | اختيار.لا_شيء -> { };
    دع الاسم: متجه غ8 = بلا_نقطة_ختامية_تحقق(المضيف);
    لو (!اسم_مضيف_صالح_تحقق(&الاسم)) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول((*الشهادة).أسماء_النطاق) مثل غير_موقع)) {
        دع النمط: متجه غ8 = بلا_نقطة_ختامية_تحقق(&(*الشهادة).أسماء_النطاق[ف]);
        لو (اسم_يطابق_نمطا_تحقق(&النمط, &الاسم)) { أرجع صواب; };
        ف := ف + 1;
    }
    أرجع خطأ;
}

// dNSName constraint matching (RFC 5280 4.2.1.10): the name equals the
// constraint or ends with "." followed by it; a leading "." in the
// constraint requires at least one further label.
عرف اسم_ضمن_قيد_تحقق(الاسم: &متجه غ8, القيد: &متجه غ8): منطقي {
    دع نقطة: غ8 = بايت_تحقق(«.»);
    دع حجم_القيد: غير_موقع = الطول(*القيد) مثل غير_موقع;
    لو (حجم_القيد == 0) { أرجع صواب; };
    دع حجم_الاسم: غير_موقع = الطول(*الاسم) مثل غير_موقع;
    لو (حجم_الاسم < حجم_القيد) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < حجم_القيد) {
        دع س: غ8 = إلى_صغير_أسكي((*الاسم)[حجم_الاسم - حجم_القيد + ف]);
        دع ص: غ8 = إلى_صغير_أسكي((*القيد)[ف]);
        لو (س != ص) { أرجع خطأ; };
        ف := ف + 1;
    }
    لو ((*القيد)[0] == نقطة) { أرجع حجم_الاسم > حجم_القيد; };
    لو (حجم_الاسم == حجم_القيد) { أرجع صواب; };
    أرجع (*الاسم)[حجم_الاسم - حجم_القيد - 1] == نقطة;
}

عرف عنوان_ضمن_قيد_تحقق(العنوان: &متجه غ8, القيد: &قيد_اسم_إكس509): منطقي {
    دع الحجم: غير_موقع = الطول(*العنوان) مثل غير_موقع;
    لو (الحجم != (الطول((*القيد).القيمة) مثل غير_موقع)) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحجم) {
        دع قناع: غير_موقع = (*القيد).القناع[ف] مثل غير_موقع;
        لو ((((*العنوان)[ف] مثل غير_موقع) & قناع) != (((*القيد).القيمة[ف] مثل غير_موقع) & قناع)) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

// The leaf names must satisfy the constraints of one CA in the path.
عرف أسماء_تحترم_القيود_تحقق(الورقة: &شهادة_إكس509, السلطة: &شهادة_إكس509): منطقي {
    دع عدد_المسموحة: غير_موقع = الطول((*السلطة).قيود_مسموحة) مثل غير_موقع;
    دع عدد_المستبعدة: غير_موقع = الطول((*السلطة).قيود_مستبعدة) مثل غير_موقع;
    لو (عدد_المسموحة == 0 && عدد_المستبعدة == 0) { أرجع صواب; };
    دع فيه_نطاق_مسموح: متغير منطقي = خطأ;
    دع فيه_عنوان_مسموح: متغير منطقي = خطأ;
    دع م: متغير غير_موقع = 0;
    بينما (م < عدد_المسموحة) {
        لو ((*السلطة).قيود_مسموحة[م].نطاق) { فيه_نطاق_مسموح := صواب; } وإلا { فيه_عنوان_مسموح := صواب; };
        م := م + 1;
    }
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول((*الورقة).أسماء_النطاق) مثل غير_موقع)) {
        دع الاسم: متجه غ8 = بلا_نقطة_ختامية_تحقق(&(*الورقة).أسماء_النطاق[ف]);
        م := 0;
        بينما (م < عدد_المستبعدة) {
            لو ((*السلطة).قيود_مستبعدة[م].نطاق && اسم_ضمن_قيد_تحقق(&الاسم, &(*السلطة).قيود_مستبعدة[م].القيمة)) { أرجع خطأ; };
            م := م + 1;
        }
        لو (فيه_نطاق_مسموح) {
            دع مسموح: متغير منطقي = خطأ;
            م := 0;
            بينما (م < عدد_المسموحة) {
                لو ((*السلطة).قيود_مسموحة[م].نطاق && اسم_ضمن_قيد_تحقق(&الاسم, &(*السلطة).قيود_مسموحة[م].القيمة)) { مسموح := صواب; };
                م := م + 1;
            }
            لو (!مسموح) { أرجع خطأ; };
        };
        ف := ف + 1;
    }
    ف := 0;
    بينما (ف < (الطول((*الورقة).عناوين_آي_بي) مثل غير_موقع)) {
        دع العنوان: &متجه غ8 = &(*الورقة).عناوين_آي_بي[ف];
        م := 0;
        بينما (م < عدد_المستبعدة) {
            لو (!(*السلطة).قيود_مستبعدة[م].نطاق && عنوان_ضمن_قيد_تحقق(العنوان, &(*السلطة).قيود_مستبعدة[م])) { أرجع خطأ; };
            م := م + 1;
        }
        لو (فيه_عنوان_مسموح) {
            دع مسموح: متغير منطقي = خطأ;
            م := 0;
            بينما (م < عدد_المسموحة) {
                لو (!(*السلطة).قيود_مسموحة[م].نطاق && عنوان_ضمن_قيد_تحقق(العنوان, &(*السلطة).قيود_مسموحة[م])) { مسموح := صواب; };
                م := م + 1;
            }
            لو (!مسموح) { أرجع خطأ; };
        };
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف صالحة_زمنيا_تحقق(الشهادة: &شهادة_إكس509, الآن: عدد): منطقي {
    أرجع الآن >= (*الشهادة).ليس_قبل && الآن <= (*الشهادة).ليس_بعد;
}

عرف تسمح_بالغرض_تحقق(الشهادة: &شهادة_إكس509, الغرض: غرض_تحقق_تي_إل_إس): منطقي {
    لو (!(*الشهادة).له_استخدام_ممتد) { أرجع صواب; };
    طابق الغرض مع
    | غرض_تحقق_تي_إل_إس.غرض_خادم -> { أرجع (*الشهادة).استخدام_خادم; }
    | غرض_تحقق_تي_إل_إس.غرض_عميل -> { أرجع (*الشهادة).استخدام_عميل; };
}

// Checks for a certificate used to issue another one at path depth
// العمق (the number of non-self-issued intermediates below it).
عرف سلطة_صالحة_تحقق(الشهادة: &شهادة_إكس509, العمق: عدد): منطقي {
    لو ((*الشهادة).الإصدار == 3) {
        لو (!(*الشهادة).له_قيود_أساسية || !(*الشهادة).سلطة) { أرجع خطأ; };
    } وإلا {
        // v1/v2 certificates cannot assert CA status (Go and webpki refuse them).
        أرجع خطأ;
    };
    لو ((*الشهادة).له_استخدام_المفتاح && ((*الشهادة).استخدام_المفتاح & استخدام_توقيع_شهادات_إكس509()) == 0) { أرجع خطأ; };
    لو ((*الشهادة).حد_المسار >= 0 && العمق > (*الشهادة).حد_المسار) { أرجع خطأ; };
    أرجع صواب;
}

// Depth-first search for an issuer chain ending at an anchor. المسار holds
// the indices of the intermediates already on the path (cycle guard).
عرف ابحث_عن_مسار_تحقق(
    الحالية: &شهادة_إكس509,
    الورقة: &شهادة_إكس509,
    الوسيطة: &متجه شهادة_إكس509,
    الجذور: &متجه شهادة_إكس509,
    المسار: &متغير متجه غير_موقع,
    الآن: عدد,
    الغرض: غرض_تحقق_تي_إل_إس,
    العمق: عدد
): منطقي {
    لو (العمق > 8) { أرجع خطأ; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*الجذور) مثل غير_موقع)) {
        دع الجذر: &شهادة_إكس509 = &(*الجذور)[ف];
        لو (متساويان_تحقق(&(*الجذر).الموضوع, &(*الحالية).المصدر)
            && سلطة_صالحة_تحقق(الجذر, العمق)
            && صالحة_زمنيا_تحقق(الجذر, الآن)
            && !(*الجذر).امتداد_حرج_غير_معالج
            && تسمح_بالغرض_تحقق(الجذر, الغرض)
            && أسماء_تحترم_القيود_تحقق(الورقة, الجذر)
            && تحقق_توقيع_شهادة_إكس509(الحالية, الجذر)) {
            أرجع صواب;
        };
        ف := ف + 1;
    }
    ف := 0;
    بينما (ف < (الطول(*الوسيطة) مثل غير_موقع)) {
        دع مستعملة: متغير منطقي = خطأ;
        دع م: متغير غير_موقع = 0;
        بينما (م < (الطول(*المسار) مثل غير_موقع)) {
            لو ((*المسار)[م] == ف) { مستعملة := صواب; };
            م := م + 1;
        }
        دع المرشح: &شهادة_إكس509 = &(*الوسيطة)[ف];
        لو (!مستعملة
            && متساويان_تحقق(&(*المرشح).الموضوع, &(*الحالية).المصدر)
            && سلطة_صالحة_تحقق(المرشح, العمق)
            && صالحة_زمنيا_تحقق(المرشح, الآن)
            && !(*المرشح).امتداد_حرج_غير_معالج
            && تسمح_بالغرض_تحقق(المرشح, الغرض)
            && أسماء_تحترم_القيود_تحقق(الورقة, المرشح)
            && تحقق_توقيع_شهادة_إكس509(الحالية, المرشح)) {
            ألحق(*المسار, ف);
            لو (ابحث_عن_مسار_تحقق(المرشح, الورقة, الوسيطة, الجذور, المسار, الآن, الغرض, العمق + 1)) {
                أرجع صواب;
            };
        };
        ف := ف + 1;
    }
    أرجع خطأ;
}

// Validates the peer chain (leaf first, then whatever intermediates the peer
// sent, in any order) against the trust anchors at time الآن (Unix seconds).
// When المضيف is non-empty the leaf must also identify that host.
عام عرف تحقق_سلسلة_شهادات_تي_إل_إس(
    السلسلة: &متجه شهادة_إكس509,
    الجذور: &متجه شهادة_إكس509,
    المضيف: &متجه غ8,
    الآن: عدد,
    الغرض: غرض_تحقق_تي_إل_إس
): نتيجة_تحقق_شهادة_تي_إل_إس {
    لو ((الطول(*السلسلة) مثل غير_موقع) == 0) { أرجع نتيجة_تحقق_شهادة_تي_إل_إس.شهادة_تالفة(); };
    دع الورقة: &شهادة_إكس509 = &(*السلسلة)[0];
    لو ((*الورقة).امتداد_حرج_غير_معالج) { أرجع نتيجة_تحقق_شهادة_تي_إل_إس.شهادة_تالفة(); };
    لو (!صالحة_زمنيا_تحقق(الورقة, الآن)) { أرجع نتيجة_تحقق_شهادة_تي_إل_إس.شهادة_منتهية(); };
    لو (!تسمح_بالغرض_تحقق(الورقة, الغرض)) { أرجع نتيجة_تحقق_شهادة_تي_إل_إس.لا_مسار_موثوق(); };
    لو ((الطول(*المضيف) مثل غير_موقع) > 0 && !شهادة_تطابق_المضيف_تي_إل_إس(الورقة, المضيف)) {
        أرجع نتيجة_تحقق_شهادة_تي_إل_إس.اسم_غير_مطابق();
    };
    // A leaf that is itself a configured anchor is trusted directly.
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*الجذور) مثل غير_موقع)) {
        لو (متساويان_تحقق(&(*الجذور)[ف].الخام, &(*الورقة).الخام)) { أرجع نتيجة_تحقق_شهادة_تي_إل_إس.سلسلة_موثوقة(); };
        ف := ف + 1;
    }
    // Intermediates are the borrowed chain itself; the leaf (index 0) starts
    // on the path so it is never chosen as an intermediate.
    دع المسار: متغير متجه غير_موقع = [];
    ألحق(المسار, 0);
    لو (ابحث_عن_مسار_تحقق(الورقة, الورقة, السلسلة, الجذور, &متغير المسار, الآن, الغرض, 0)) {
        أرجع نتيجة_تحقق_شهادة_تي_إل_إس.سلسلة_موثوقة();
    };
    أرجع نتيجة_تحقق_شهادة_تي_إل_إس.لا_مسار_موثوق();
}

عام مرادف tls_verify_certificate_chain = تحقق_سلسلة_شهادات_تي_إل_إس;
عام مرادف tls_certificate_matches_host = شهادة_تطابق_المضيف_تي_إل_إس;

library/std/tls/wire.sn:
استورد text.from_bytes;
// Bounds-checked reading of TLS presentation-language structures
// (RFC 8446 3): fixed-width big-endian integers and opaque vectors with
// 8-, 16- or 24-bit length prefixes. A read past the end marks the reader
// invalid instead of trapping; parsers check صالح and that every byte was
// consumed, and report decode_error otherwise.

استورد crypto.words;

عام نوع قارئ_تي_إل_إس = {
    البيانات: متجه غ8,
    الموضع: غير_موقع,
    صالح: منطقي
};

عام عرف أنشئ_قارئ_تي_إل_إس(البيانات: &متجه غ8, البداية: غير_موقع): قارئ_تي_إل_إس {
    دع القارئ: قارئ_تي_إل_إس = { البيانات: انسخ_بايتات(البيانات), الموضع: البداية, صالح: صواب };
    أرجع القارئ;
}

عام عرف متبقي_قارئ_تي_إل_إس(القارئ: &قارئ_تي_إل_إس): غير_موقع {
    دع الحجم: غير_موقع = الطول((*القارئ).البيانات) مثل غير_موقع;
    لو ((*القارئ).الموضع >= الحجم) { أرجع 0; };
    أرجع الحجم - (*القارئ).الموضع;
}

عام عرف قارئ_منته_تي_إل_إس(القارئ: &قارئ_تي_إل_إس): منطقي {
    أرجع (*القارئ).صالح && متبقي_قارئ_تي_إل_إس(القارئ) == 0;
}

عرف يكفي_قارئ_تي_إل_إس(القارئ: &متغير قارئ_تي_إل_إس, العدد: غير_موقع): منطقي {
    لو (!(*القارئ).صالح || متبقي_قارئ_تي_إل_إس(القارئ) < العدد) {
        (*القارئ).صالح := خطأ;
        أرجع خطأ;
    };
    أرجع صواب;
}

عام عرف اقرأ_رقما_تي_إل_إس(القارئ: &متغير قارئ_تي_إل_إس, البايتات: غير_موقع): غير_موقع {
    لو (!يكفي_قارئ_تي_إل_إس(القارئ, البايتات)) { أرجع 0; };
    دع القيمة: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < البايتات) {
        القيمة := (القيمة << 8) | ((*القارئ).البيانات[(*القارئ).الموضع + ف] مثل غير_موقع);
        ف := ف + 1;
    }
    (*القارئ).الموضع := (*القارئ).الموضع + البايتات;
    أرجع القيمة;
}

عام عرف اقرأ_بايتات_تي_إل_إس(القارئ: &متغير قارئ_تي_إل_إس, العدد: غير_موقع): متجه غ8 {
    لو (!يكفي_قارئ_تي_إل_إس(القارئ, العدد)) {
        دع فارغ: متجه غ8 = [];
        أرجع فارغ;
    };
    دع الناتج: متجه غ8 = شريحة_بايتات_تشفير(&(*القارئ).البيانات, (*القارئ).الموضع, العدد);
    (*القارئ).الموضع := (*القارئ).الموضع + العدد;
    أرجع الناتج;
}

// opaque field<min..max> with a length prefix of بايتات_الطول bytes.
عام عرف اقرأ_متجها_تي_إل_إس(القارئ: &متغير قارئ_تي_إل_إس, بايتات_الطول: غير_موقع): متجه غ8 {
    دع الحجم: غير_موقع = اقرأ_رقما_تي_إل_إس(القارئ, بايتات_الطول);
    أرجع اقرأ_بايتات_تي_إل_إس(القارئ, الحجم);
}

// Appends opaque data with a length prefix of بايتات_الطول bytes.
عام عرف ألحق_متجها_تي_إل_إس(الهدف: &متغير متجه غ8, بايتات_الطول: غير_موقع, البيانات: &متجه غ8): فراغ {
    دع الحجم: غير_موقع = الطول(*البيانات) مثل غير_موقع;
    لو (بايتات_الطول == 1) {
        ألحق(*الهدف, (الحجم & 0xFF) مثل غ8);
    } وإلا لو (بايتات_الطول == 2) {
        ألحق_كبير16_تشفير(الهدف, الحجم);
    } وإلا {
        ألحق_كبير24_تشفير(الهدف, الحجم);
    };
    ألحق_بايتات_تشفير(الهدف, البيانات);
}

// One extension: type, then opaque data<0..2^16-1>.
عام نوع امتداد_تي_إل_إس = {
    النوع: غير_موقع,
    البيانات: متجه غ8
};

// Extension list<0..2^16-1>; none when malformed or a type repeats
// (RFC 8446 4.2: duplicate extensions are a protocol error).
عام عرف اقرأ_امتدادات_تي_إل_إس(القارئ: &متغير قارئ_تي_إل_إس): اختيار متجه امتداد_تي_إل_إس {
    دع الكتلة: متجه غ8 = اقرأ_متجها_تي_إل_إس(القارئ, 2);
    لو (!(*القارئ).صالح) { أرجع اختيار.لا_شيء(); };
    دع الداخلي: متغير قارئ_تي_إل_إس = أنشئ_قارئ_تي_إل_إس(&الكتلة, 0);
    دع الامتدادات: متغير متجه امتداد_تي_إل_إس = [];
    بينما (متبقي_قارئ_تي_إل_إس(&الداخلي) > 0) {
        دع النوع: غير_موقع = اقرأ_رقما_تي_إل_إس(&متغير الداخلي, 2);
        دع البيانات: متجه غ8 = اقرأ_متجها_تي_إل_إس(&متغير الداخلي, 2);
        لو (!الداخلي.صالح) { أرجع اختيار.لا_شيء(); };
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(الامتدادات) مثل غير_موقع)) {
            لو (الامتدادات[ف].النوع == النوع) { أرجع اختيار.لا_شيء(); };
            ف := ف + 1;
        }
        دع الامتداد: امتداد_تي_إل_إس = { النوع: النوع, البيانات: البيانات };
        ألحق(الامتدادات, الامتداد);
    }
    أرجع اختيار.بعض(الامتدادات);
}

