// KeyUsage named bits (RFC 5280 4.2.1.3).
عام عرف استخدام_توقيع_رقمي_إكس509(): غير_موقع { أرجع 1; }
عام عرف استخدام_توقيع_شهادات_إكس509(): غير_موقع { أرجع 32; }

عرف معرف_إكس509(النص: نص): متجه غ8 {
    أرجع معرف_كائن_من_نص(النص);
}

عرف معرف_يساوي_إكس509(المصدر: &متجه غ8, العنصر: &عنصر_دي_إي_آر, النص: نص): منطقي {
    دع المتوقع: متجه غ8 = معرف_إكس509(النص);
    أرجع معرف_كائن_يساوي_دي_إي_آر(المصدر, العنصر, &المتوقع);
}

// Hash named by an AlgorithmIdentifier whose parameters are NULL or absent.
عرف تجزئة_من_معرف_إكس509(المصدر: &متجه غ8, المعرف: &عنصر_دي_إي_آر): اختيار خوارزمية_تجزئة {
    طابق أبناء_بوسم_دي_إي_آر(المصدر, المعرف, وسم_تسلسل_دي_إي_آر()) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأبناء) -> {
        دع العدد: غير_موقع = الطول(الأبناء) مثل غير_موقع;
        لو (العدد == 0 || العدد > 2) { أرجع اختيار.لا_شيء(); };
        لو (العدد == 2 && (الأبناء[1].الوسم != وسم_فارغ_دي_إي_آر() || الأبناء[1].الطول != 0)) { أرجع اختيار.لا_شيء(); };
        لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «2.16.840.1.101.3.4.2.1»)) { أرجع اختيار.بعض(خوارزمية_تجزئة.تجزئة_شا256()); };
        لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «2.16.840.1.101.3.4.2.2»)) { أرجع اختيار.بعض(خوارزمية_تجزئة.تجزئة_شا384()); };
        لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «2.16.840.1.101.3.4.2.3»)) { أرجع اختيار.بعض(خوارزمية_تجزئة.تجزئة_شا512()); };
        أرجع اختيار.لا_شيء();
    };
}

// RSASSA-PSS-params (RFC 4055 3.1) restricted to MGF1 with the same SHA-2
// digest, salt length equal to the digest length and trailer field 1.
عرف تجزئة_بي_إس_إس_إكس509(المصدر: &متجه غ8, المعاملات: &عنصر_دي_إي_آر): اختيار خوارزمية_تجزئة {
    دع التجزئة: متغير اختيار خوارزمية_تجزئة = اختيار.لا_شيء();
    دع تجزئة_القناع: متغير اختيار خوارزمية_تجزئة = اختيار.لا_شيء();
    دع الملح: متغير غير_موقع = 20;
    طابق أبناء_بوسم_دي_إي_آر(المصدر, المعاملات, وسم_تسلسل_دي_إي_آر()) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأبناء) -> {
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(الأبناء) مثل غير_موقع)) {
            دع الوسم: غير_موقع = الأبناء[ف].الوسم;
            طابق أبناء_دي_إي_آر(المصدر, &الأبناء[ف]) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(الداخل) -> {
                لو ((الطول(الداخل) مثل غير_موقع) != 1) { أرجع اختيار.لا_شيء(); };
                لو (الوسم == وسم_سياق_مركب_دي_إي_آر(0)) {
                    التجزئة := تجزئة_من_معرف_إكس509(المصدر, &الداخل[0]);
                } وإلا لو (الوسم == وسم_سياق_مركب_دي_إي_آر(1)) {
                    طابق أبناء_بوسم_دي_إي_آر(المصدر, &الداخل[0], وسم_تسلسل_دي_إي_آر()) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(القناع) -> {
                        لو ((الطول(القناع) مثل غير_موقع) != 2) { أرجع اختيار.لا_شيء(); };
                        لو (!معرف_يساوي_إكس509(المصدر, &القناع[0], «1.2.840.113549.1.1.8»)) { أرجع اختيار.لا_شيء(); };
                        تجزئة_القناع := تجزئة_من_معرف_إكس509(المصدر, &القناع[1]);
                    };
                } وإلا لو (الوسم == وسم_سياق_مركب_دي_إي_آر(2)) {
                    طابق عدد_صغير_دي_إي_آر(المصدر, &الداخل[0]) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(القيمة) -> { الملح := القيمة; };
                } وإلا لو (الوسم == وسم_سياق_مركب_دي_إي_آر(3)) {
                    طابق عدد_صغير_دي_إي_آر(المصدر, &الداخل[0]) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(القيمة) -> { لو (القيمة != 1) { أرجع اختيار.لا_شيء(); }; };
                } وإلا {
                    أرجع اختيار.لا_شيء();
                };
            };
            ف := ف + 1;
        }
    };
    طابق التجزئة مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأولى) -> {
        طابق تجزئة_القناع مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(الثانية) -> {
            لو (الأولى != الثانية || الملح != حجم_ملخص_تجزئة(الأولى)) { أرجع اختيار.لا_شيء(); };
            أرجع اختيار.بعض(الأولى);
        };
    };
}

// Signature AlgorithmIdentifier (RFC 5280 4.1.1.2; RFC 4055; RFC 5758).
// SHA-1 and MD5 based algorithms are unsupported and therefore rejected.
عرف خوارزمية_توقيع_من_معرف_إكس509(المصدر: &متجه غ8, المعرف: &عنصر_دي_إي_آر): خوارزمية_توقيع_إكس509 {
    طابق أبناء_بوسم_دي_إي_آر(المصدر, المعرف, وسم_تسلسل_دي_إي_آر()) مع
    | اختيار.لا_شيء -> { أرجع خوارزمية_توقيع_إكس509.توقيع_غير_مدعوم_إكس509(); }
    | اختيار.بعض(الأبناء) -> {
        دع العدد: غير_موقع = الطول(الأبناء) مثل غير_موقع;
        لو (العدد == 0 || العدد > 2) { أرجع خوارزمية_توقيع_إكس509.توقيع_غير_مدعوم_إكس509(); };
        دع بلا_معاملات: منطقي = العدد == 1;
        دع معاملات_فارغة: منطقي = بلا_معاملات || (الأبناء[1].الوسم == وسم_فارغ_دي_إي_آر() && الأبناء[1].الطول == 0);
        لو (معاملات_فارغة) {
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.113549.1.1.11»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_بي_كي_سي_إس1_إكس509(خوارزمية_تجزئة.تجزئة_شا256()); };
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.113549.1.1.12»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_بي_كي_سي_إس1_إكس509(خوارزمية_تجزئة.تجزئة_شا384()); };
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.113549.1.1.13»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_بي_كي_سي_إس1_إكس509(خوارزمية_تجزئة.تجزئة_شا512()); };
        };
        لو (بلا_معاملات) {
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.10045.4.3.2»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_إي_سي_دي_إس_إيه_إكس509(خوارزمية_تجزئة.تجزئة_شا256()); };
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.10045.4.3.3»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_إي_سي_دي_إس_إيه_إكس509(خوارزمية_تجزئة.تجزئة_شا384()); };
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.10045.4.3.4»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_إي_سي_دي_إس_إيه_إكس509(خوارزمية_تجزئة.تجزئة_شا512()); };
            // id-Ed25519 with absent parameters (RFC 8410 3).
            لو (معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.3.101.112»)) { أرجع خوارزمية_توقيع_إكس509.توقيع_إد25519_إكس509(); };
        };
        لو (العدد == 2 && معرف_يساوي_إكس509(المصدر, &الأبناء[0], «1.2.840.113549.1.1.10»)) {
            طابق تجزئة_بي_إس_إس_إكس509(المصدر, &الأبناء[1]) مع
            | اختيار.بعض(التجزئة) -> { أرجع خوارزمية_توقيع_إكس509.توقيع_بي_إس_إس_إكس509(التجزئة); }
            | اختيار.لا_شيء -> { };
        };
        أرجع خوارزمية_توقيع_إكس509.توقيع_غير_مدعوم_إكس509();
    };
}

// SubjectPublicKeyInfo (RFC 5280 4.1.2.7; RFC 3279 2.3.1; RFC 5480 2).
عام عرف حلل_مفتاح_عام_إكس509(المصدر: &متجه غ8, المعلومات: &عنصر_دي_إي_آر): اختيار مفتاح_عام_إكس509 {
    طابق أبناء_بوسم_دي_إي_آر(المصدر, المعلومات, وسم_تسلسل_دي_إي_آر()) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأبناء) -> {
        لو ((الطول(الأبناء) مثل غير_موقع) != 2) { أرجع اختيار.لا_شيء(); };
        دع المفتاح_الخام: متجه غ8;
        طابق سلسلة_بتات_كاملة_دي_إي_آر(المصدر, &الأبناء[1]) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(القيمة) -> { المفتاح_الخام := القيمة; };
        طابق أبناء_بوسم_دي_إي_آر(المصدر, &الأبناء[0], وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(الخوارزمية) -> {
            دع العدد: غير_موقع = الطول(الخوارزمية) مثل غير_موقع;
            لو (العدد == 0) { أرجع اختيار.لا_شيء(); };
            لو (معرف_يساوي_إكس509(المصدر, &الخوارزمية[0], «1.2.840.113549.1.1.1»)) {
                طابق اقرأ_جذر_دي_إي_آر(&المفتاح_الخام) مع
                | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                | اختيار.بعض(الجذر) -> {
                    طابق أبناء_بوسم_دي_إي_آر(&المفتاح_الخام, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(الأجزاء) -> {
                        لو ((الطول(الأجزاء) مثل غير_موقع) != 2) { أرجع اختيار.لا_شيء(); };
                        طابق عدد_صحيح_موجب_دي_إي_آر(&المفتاح_الخام, &الأجزاء[0]) مع
                        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                        | اختيار.بعض(المعامل) -> {
                            طابق عدد_صحيح_موجب_دي_إي_آر(&المفتاح_الخام, &الأجزاء[1]) مع
                            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                            | اختيار.بعض(الأس) -> {
                                دع العام: مفتاح_آر_إس_إيه_عام = أنشئ_مفتاح_آر_إس_إيه_عام(&المعامل, &الأس);
                                أرجع اختيار.بعض(مفتاح_عام_إكس509.مفتاح_آر_إس_إيه_إكس509(العام));
                            };
                        };
                    };
                };
            };
            لو (العدد == 2 && معرف_يساوي_إكس509(المصدر, &الخوارزمية[0], «1.2.840.10045.2.1»)) {
                دع المنحنى: منحنى_إهليلجي;
                لو (معرف_يساوي_إكس509(المصدر, &الخوارزمية[1], «1.2.840.10045.3.1.7»)) {
                    المنحنى := منحنى_إهليلجي.منحنى_بي256();
                } وإلا لو (معرف_يساوي_إكس509(المصدر, &الخوارزمية[1], «1.3.132.0.34»)) {
