                } وإلا {
                    أرجع اختيار.بعض(مفتاح_عام_إكس509.مفتاح_غير_مدعوم_إكس509());
                };
                دع المفتاح: مفتاح_إي_سي_عام_إكس509 = { المنحنى: المنحنى, النقطة: المفتاح_الخام };
                أرجع اختيار.بعض(مفتاح_عام_إكس509.مفتاح_إي_سي_إكس509(المفتاح));
            };
            لو (العدد == 1 && معرف_يساوي_إكس509(المصدر, &الخوارزمية[0], «1.3.101.112»)) {
                لو ((الطول(المفتاح_الخام) مثل غير_موقع) != 32) { أرجع اختيار.لا_شيء(); };
                أرجع اختيار.بعض(مفتاح_عام_إكس509.مفتاح_إد25519_إكس509(المفتاح_الخام));
            };
            أرجع اختيار.بعض(مفتاح_عام_إكس509.مفتاح_غير_مدعوم_إكس509());
        };
    };
}

// Reads a GeneralSubtree base for name constraints; none for a form that
// these constraints do not implement (the certificate is then unusable).
عرف قيد_من_اسم_عام_إكس509(المصدر: &متجه غ8, الشجرة: &عنصر_دي_إي_آر): اختيار قيد_اسم_إكس509 {
    طابق أبناء_بوسم_دي_إي_آر(المصدر, الشجرة, وسم_تسلسل_دي_إي_آر()) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الأجزاء) -> {
        // minimum must be 0 (absent) and maximum absent (RFC 5280 4.2.1.10).
        لو ((الطول(الأجزاء) مثل غير_موقع) != 1) { أرجع اختيار.لا_شيء(); };
        دع الأساس: &عنصر_دي_إي_آر = &الأجزاء[0];
        دع فارغ: متجه غ8 = [];
        لو ((*الأساس).الوسم == وسم_سياق_بسيط_دي_إي_آر(2)) {
            دع القيد: قيد_اسم_إكس509 = { نطاق: صواب, القيمة: محتوى_دي_إي_آر(المصدر, الأساس), القناع: فارغ };
            أرجع اختيار.بعض(القيد);
        };
        لو ((*الأساس).الوسم == وسم_سياق_بسيط_دي_إي_آر(7)) {
            دع المحتوى: متجه غ8 = محتوى_دي_إي_آر(المصدر, الأساس);
            دع الحجم: غير_موقع = الطول(المحتوى) مثل غير_موقع;
            لو (الحجم != 8 && الحجم != 32) { أرجع اختيار.لا_شيء(); };
            دع النصف: غير_موقع = الحجم / 2;
            دع القيد: قيد_اسم_إكس509 = {
                نطاق: خطأ,
                القيمة: شريحة_بايتات_تشفير(&المحتوى, 0, النصف),
                القناع: شريحة_بايتات_تشفير(&المحتوى, النصف, النصف)
            };
            أرجع اختيار.بعض(القيد);
        };
        أرجع اختيار.لا_شيء();
    };
}

// Fills the extension-derived fields; false when the extensions are
// malformed or duplicated.
عرف حلل_امتدادات_إكس509(المصدر: &متجه غ8, الحاوية: &عنصر_دي_إي_آر, الشهادة: &متغير شهادة_إكس509): منطقي {
    طابق أبناء_دي_إي_آر(المصدر, الحاوية) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(الغلاف) -> {
        لو ((الطول(الغلاف) مثل غير_موقع) != 1) { أرجع خطأ; };
