        | اختيار.لا_شيء -> { أرجع خطأ; }
        | اختيار.بعض(الامتدادات) -> {
            لو ((الطول(الامتدادات) مثل غير_موقع) == 0) { أرجع خطأ; };
            دع رأيت_أساسية: متغير منطقي = خطأ;
            دع رأيت_استخدام: متغير منطقي = خطأ;
            دع رأيت_ممتد: متغير منطقي = خطأ;
            دع رأيت_بديل: متغير منطقي = خطأ;
            دع رأيت_قيود: متغير منطقي = خطأ;
            دع ف: متغير غير_موقع = 0;
            بينما (ف < (الطول(الامتدادات) مثل غير_موقع)) {
                طابق أبناء_بوسم_دي_إي_آر(المصدر, &الامتدادات[ف], وسم_تسلسل_دي_إي_آر()) مع
                | اختيار.لا_شيء -> { أرجع خطأ; }
                | اختيار.بعض(الأجزاء) -> {
                    دع العدد: غير_موقع = الطول(الأجزاء) مثل غير_موقع;
                    لو (العدد < 2 || العدد > 3) { أرجع خطأ; };
