                        لو (معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.19») || معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.15»)
                            || معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.37») || معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.17»)
                            || معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.30»)) {
                            أرجع خطأ;
                        };
                    }
                    | اختيار.بعض(الجذر) -> {
                        لو (معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.19»)) {
                            // basicConstraints
