                                    طابق منطقي_دي_إي_آر(&القيمة, &الحقول[م]) مع
                                    | اختيار.لا_شيء -> { أرجع خطأ; }
                                    | اختيار.بعض(سلطة) -> { (*الشهادة).سلطة := سلطة; };
                                    م := م + 1;
                                };
                                لو (م < (الطول(الحقول) مثل غير_موقع)) {
                                    طابق عدد_صغير_دي_إي_آر(&القيمة, &الحقول[م]) مع
                                    | اختيار.لا_شيء -> { أرجع خطأ; }
                                    | اختيار.بعض(الحد) -> { (*الشهادة).حد_المسار := الحد مثل عدد; };
                                    م := م + 1;
                                };
                                لو (م != (الطول(الحقول) مثل غير_موقع)) { أرجع خطأ; };
