                        } وإلا لو (معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.15»)) {
                            // keyUsage
                            لو (رأيت_استخدام) { أرجع خطأ; };
                            رأيت_استخدام := صواب;
                            معالج := صواب;
                            طابق بتات_مسماة_دي_إي_آر(&القيمة, &الجذر) مع
                            | اختيار.لا_شيء -> { أرجع خطأ; }
                            | اختيار.بعض(البتات) -> {
                                (*الشهادة).له_استخدام_المفتاح := صواب;
                                (*الشهادة).استخدام_المفتاح := البتات;
