                            معالج := صواب;
                            طابق أبناء_بوسم_دي_إي_آر(&القيمة, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
                            | اختيار.لا_شيء -> { أرجع خطأ; }
                            | اختيار.بعض(المعرفات) -> {
                                (*الشهادة).له_استخدام_ممتد := صواب;
                                دع م: متغير غير_موقع = 0;
                                بينما (م < (الطول(المعرفات) مثل غير_موقع)) {
                                    لو (معرف_يساوي_إكس509(&القيمة, &المعرفات[م], «2.5.29.37.0»)) {
                                        (*الشهادة).استخدام_خادم := صواب;
                                        (*الشهادة).استخدام_عميل := صواب;
                                    };
                                    لو (معرف_يساوي_إكس509(&القيمة, &المعرفات[م], «1.3.6.1.5.5.7.3.1»)) { (*الشهادة).استخدام_خادم := صواب; };
                                    لو (معرف_يساوي_إكس509(&القيمة, &المعرفات[م], «1.3.6.1.5.5.7.3.2»)) { (*الشهادة).استخدام_عميل := صواب; };
                                    م := م + 1;
                                }
                            };
                        } وإلا لو (معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.17»)) {
                            // subjectAltName: dNSName [2] and iPAddress [7]
                            لو (رأيت_بديل) { أرجع خطأ; };
                            رأيت_بديل := صواب;
                            معالج := صواب;
                            طابق أبناء_بوسم_دي_إي_آر(&القيمة, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
                            | اختيار.لا_شيء -> { أرجع خطأ; }
                            | اختيار.بعض(الأسماء) -> {
                                دع م: متغير غير_موقع = 0;
                                بينما (م < (الطول(الأسماء) مثل غير_موقع)) {
                                    لو (الأسماء[م].الوسم == وسم_سياق_بسيط_دي_إي_آر(2)) {
                                        ألحق((*الشهادة).أسماء_النطاق, محتوى_دي_إي_آر(&القيمة, &الأسماء[م]));
                                    } وإلا لو (الأسماء[م].الوسم == وسم_سياق_بسيط_دي_إي_آر(7)) {
                                        ألحق((*الشهادة).عناوين_آي_بي, محتوى_دي_إي_آر(&القيمة, &الأسماء[م]));
                                    };
                                    م := م + 1;
                                }
                            };
                        } وإلا لو (معرف_يساوي_إكس509(المصدر, المعرف, «2.5.29.30»)) {
                            // nameConstraints with dNSName and iPAddress subtrees
                            لو (رأيت_قيود) { أرجع خطأ; };
                            رأيت_قيود := صواب;
                            معالج := صواب;
                            طابق أبناء_بوسم_دي_إي_آر(&القيمة, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
                            | اختيار.لا_شيء -> { أرجع خطأ; }
                            | اختيار.بعض(الأشجار) -> {
                                دع م: متغير غير_موقع = 0;
                                بينما (م < (الطول(الأشجار) مثل غير_موقع)) {
                                    دع مستبعدة: منطقي = الأشجار[م].الوسم == وسم_سياق_مركب_دي_إي_آر(1);
                                    لو (!مستبعدة && الأشجار[م].الوسم != وسم_سياق_مركب_دي_إي_آر(0)) { أرجع خطأ; };
