                                    | اختيار.لا_شيء -> { أرجع خطأ; }
                                    | اختيار.بعض(البنود) -> {
                                        دع ن: متغير غير_موقع = 0;
                                        بينما (ن < (الطول(البنود) مثل غير_موقع)) {
                                            طابق قيد_من_اسم_عام_إكس509(&القيمة, &البنود[ن]) مع
                                            | اختيار.لا_شيء -> { معالج := خطأ; }
                                            | اختيار.بعض(القيد) -> {
                                                لو (مستبعدة) { ألحق((*الشهادة).قيود_مستبعدة, القيد); }
                                                وإلا { ألحق((*الشهادة).قيود_مسموحة, القيد); };
