                };
                ف := ف + 1;
            }
            أرجع صواب;
        };
    };
}

// Parses one DER certificate; none when it is not a well-formed X.509 v1-v3
// certificate.
عام عرف حلل_شهادة_إكس509(الخام: &متجه غ8): اختيار شهادة_إكس509 {
    طابق اقرأ_جذر_دي_إي_آر(الخام) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الجذر) -> {
        طابق أبناء_بوسم_دي_إي_آر(الخام, &الجذر, وسم_تسلسل_دي_إي_آر()) مع
        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
        | اختيار.بعض(الأقسام) -> {
            لو ((الطول(الأقسام) مثل غير_موقع) != 3) { أرجع اختيار.لا_شيء(); };
            دع التوقيع: متجه غ8;
            طابق سلسلة_بتات_كاملة_دي_إي_آر(الخام, &الأقسام[2]) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(القيمة) -> { التوقيع := القيمة; };
            دع الخوارزمية: خوارزمية_توقيع_إكس509 = خوارزمية_توقيع_من_معرف_إكس509(الخام, &الأقسام[1]);
            دع معرف_الخارج: متجه غ8 = ترميز_كامل_دي_إي_آر(الخام, &الأقسام[1]);
            طابق أبناء_بوسم_دي_إي_آر(الخام, &الأقسام[0], وسم_تسلسل_دي_إي_آر()) مع
            | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
            | اختيار.بعض(الحقول) -> {
                دع العدد: غير_موقع = الطول(الحقول) مثل غير_موقع;
                دع م: متغير غير_موقع = 0;
                دع الإصدار: متغير غير_موقع = 0;
                لو (العدد > 0 && الحقول[0].الوسم == وسم_سياق_مركب_دي_إي_آر(0)) {
                    طابق أبناء_دي_إي_آر(الخام, &الحقول[0]) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(الداخل) -> {
                        لو ((الطول(الداخل) مثل غير_موقع) != 1) { أرجع اختيار.لا_شيء(); };
                        طابق عدد_صغير_دي_إي_آر(الخام, &الداخل[0]) مع
                        | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                        | اختيار.بعض(القيمة) -> { الإصدار := القيمة; };
                    };
                    م := 1;
                };
                لو (الإصدار > 2 || العدد < م + 6) { أرجع اختيار.لا_شيء(); };
                // serialNumber (م), signature (م+1), issuer, validity, subject, spki
                لو (الحقول[م].الوسم != وسم_عدد_صحيح_دي_إي_آر()) { أرجع اختيار.لا_شيء(); };
                دع معرف_الداخل: متجه غ8 = ترميز_كامل_دي_إي_آر(الخام, &الحقول[م + 1]);
                لو (!بايتات_متساوية_بزمن_ثابت_تشفير(&معرف_الداخل, &معرف_الخارج)) { أرجع اختيار.لا_شيء(); };
                لو (الحقول[م + 2].الوسم != وسم_تسلسل_دي_إي_آر() || الحقول[م + 4].الوسم != وسم_تسلسل_دي_إي_آر()) { أرجع اختيار.لا_شيء(); };
                دع المصدر_الخام: متجه غ8 = ترميز_كامل_دي_إي_آر(الخام, &الحقول[م + 2]);
                دع الموضوع_الخام: متجه غ8 = ترميز_كامل_دي_إي_آر(الخام, &الحقول[م + 4]);
                دع ليس_قبل: متغير عدد = 0;
                دع ليس_بعد: متغير عدد = 0;
                طابق أبناء_بوسم_دي_إي_آر(الخام, &الحقول[م + 3], وسم_تسلسل_دي_إي_آر()) مع
                | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                | اختيار.بعض(المدة) -> {
                    لو ((الطول(المدة) مثل غير_موقع) != 2) { أرجع اختيار.لا_شيء(); };
                    طابق وقت_دي_إي_آر(الخام, &المدة[0]) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(القيمة) -> { ليس_قبل := القيمة; };
                    طابق وقت_دي_إي_آر(الخام, &المدة[1]) مع
                    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                    | اختيار.بعض(القيمة) -> { ليس_بعد := القيمة; };
                };
                دع المفتاح: مفتاح_عام_إكس509;
                طابق حلل_مفتاح_عام_إكس509(الخام, &الحقول[م + 5]) مع
                | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
                | اختيار.بعض(القيمة) -> { المفتاح := القيمة; };
                دع أسماء: متجه متجه غ8 = [];
                دع عناوين: متجه متجه غ8 = [];
                دع مسموحة: متجه قيد_اسم_إكس509 = [];
                دع مستبعدة: متجه قيد_اسم_إكس509 = [];
                دع الشهادة: متغير شهادة_إكس509 = {
                    الخام: انسخ_بايتات(الخام),
                    الجزء_الموقع: ترميز_كامل_دي_إي_آر(الخام, &الأقسام[0]),
                    خوارزمية_التوقيع: الخوارزمية,
                    التوقيع: التوقيع,
                    المصدر: المصدر_الخام,
                    الموضوع: الموضوع_الخام,
                    ليس_قبل: ليس_قبل,
                    ليس_بعد: ليس_بعد,
                    المفتاح: المفتاح,
                    الإصدار: الإصدار + 1,
                    له_قيود_أساسية: خطأ,
                    سلطة: خطأ,
                    حد_المسار: -1,
                    له_استخدام_المفتاح: خطأ,
                    استخدام_المفتاح: 0,
                    له_استخدام_ممتد: خطأ,
                    استخدام_خادم: خطأ,
                    استخدام_عميل: خطأ,
                    أسماء_النطاق: أسماء,
                    عناوين_آي_بي: عناوين,
                    قيود_مسموحة: مسموحة,
                    قيود_مستبعدة: مستبعدة,
                    امتداد_حرج_غير_معالج: خطأ
                };
                // Optional issuerUniqueID [1], subjectUniqueID [2], extensions [3].
                دع ك: متغير غير_موقع = م + 6;
                بينما (ك < العدد) {
                    دع الوسم: غير_موقع = الحقول[ك].الوسم;
                    لو (الوسم == وسم_سياق_مركب_دي_إي_آر(3)) {
                        لو (الإصدار != 2) { أرجع اختيار.لا_شيء(); };
                        لو (!حلل_امتدادات_إكس509(الخام, &الحقول[ك], &متغير الشهادة)) { أرجع اختيار.لا_شيء(); };
                    } وإلا لو (الوسم != 0x81 && الوسم != 0x82 && الوسم != 0xA1 && الوسم != 0xA2) {
                        أرجع اختيار.لا_شيء();
                    };
                    ك := ك + 1;
                }
                أرجع اختيار.بعض(الشهادة);
            };
        };
    };
}

// Verifies that المصدر_المرشح's key signed الشهادة. SHA-1/MD5 and unknown
// algorithms never verify; key types must match the signature algorithm.
عام عرف تحقق_توقيع_شهادة_إكس509(الشهادة: &شهادة_إكس509, المصدر_المرشح: &شهادة_إكس509): منطقي {
    طابق (*الشهادة).خوارزمية_التوقيع مع
    | خوارزمية_توقيع_إكس509.توقيع_غير_مدعوم_إكس509 -> { أرجع خطأ; }
    | خوارزمية_توقيع_إكس509.توقيع_بي_كي_سي_إس1_إكس509(التجزئة) -> {
        دع الملخص: متجه غ8 = جزئ_تشفير(التجزئة, &(*الشهادة).الجزء_الموقع);
        طابق (*المصدر_المرشح).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_آر_إس_إيه_إكس509(العام) -> {
            أرجع تحقق_آر_إس_إيه_بي_كي_سي_إس1(&العام, التجزئة, &الملخص, &(*الشهادة).التوقيع);
        }
        | _ -> { أرجع خطأ; };
    }
    | خوارزمية_توقيع_إكس509.توقيع_بي_إس_إس_إكس509(التجزئة) -> {
        دع الملخص: متجه غ8 = جزئ_تشفير(التجزئة, &(*الشهادة).الجزء_الموقع);
        طابق (*المصدر_المرشح).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_آر_إس_إيه_إكس509(العام) -> {
            أرجع تحقق_آر_إس_إيه_بي_إس_إس(&العام, التجزئة, &الملخص, &(*الشهادة).التوقيع);
        }
        | _ -> { أرجع خطأ; };
    }
    | خوارزمية_توقيع_إكس509.توقيع_إي_سي_دي_إس_إيه_إكس509(التجزئة) -> {
        دع الملخص: متجه غ8 = جزئ_تشفير(التجزئة, &(*الشهادة).الجزء_الموقع);
        طابق (*المصدر_المرشح).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_إي_سي_إكس509(المفتاح) -> {
            أرجع تحقق_إي_سي_دي_إس_إيه(المفتاح.المنحنى, &المفتاح.النقطة, &الملخص, &(*الشهادة).التوقيع);
        }
        | _ -> { أرجع خطأ; };
    }
    | خوارزمية_توقيع_إكس509.توقيع_إد25519_إكس509 -> {
        طابق (*المصدر_المرشح).المفتاح مع
        | مفتاح_عام_إكس509.مفتاح_إد25519_إكس509(العام) -> {
            أرجع تحقق_إد25519(&العام, &(*الشهادة).الجزء_الموقع, &(*الشهادة).التوقيع);
        }
        | _ -> { أرجع خطأ; };
    };
}

عام مرادف x509_certificate = شهادة_إكس509;
عام مرادف x509_parse_certificate = حلل_شهادة_إكس509;

library/std/toml/parser.sn:
استورد text.from_bytes;
استورد text.compare;
استورد encoding.utf8;

// Generic TOML document model. Package semantics belong to package_manifest.sn.
// Tables/arrays are arena-indexed so recursive TOML values do not require a
// recursive value layout in the language type system.
عام نوع قيمة_تومل =
    | سلسلة بنوع نص
    | منطق بنوع منطقي
    | عدد بنوع نص
    | تاريخ_وقت بنوع نص
    | مصفوفة بنوع غير_موقع
    | جدول بنوع غير_موقع
;

عام نوع مدخل_جدول_تومل = {
    المفتاح: نص,
    القيمة: قيمة_تومل,
    الإزاحة: غير_موقع
};

عام نوع جدول_تومل = {
    المداخل: متجه مدخل_جدول_تومل,
    معلن: منطقي,
    مغلق: منطقي
};

عام نوع مصفوفة_تومل = {
    القيم: متجه قيمة_تومل
};

عام نوع وثيقة_تومل = {
    الجذر: غير_موقع,
    الجداول: متجه جدول_تومل,
    المصفوفات: متجه مصفوفة_تومل
};

عام نوع صنف_خطأ_تومل =
    | نهاية_غير_متوقعة
    | رمز_غير_متوقع
    | مفتاح_غير_صالح
    | قيمة_غير_صالحة
    | هروب_غير_صالح
    | يونيكود_غير_صالح
    | مفتاح_مكرر
    | جدول_مكرر
    | تعارض_نوع
    | جدول_ضمني_مغلق
    | نص_لاحق
;

عام نوع خطأ_تومل = {
    الصنف: صنف_خطأ_تومل,
    الإزاحة: غير_موقع
};

// Independent copies of document values for the owning query results.
عام عرف انسخ_قيمة_تومل(القيمة: &قيمة_تومل): قيمة_تومل {
    طابق *القيمة مع
    | قيمة_تومل.سلسلة(النص) -> { أرجع قيمة_تومل.سلسلة(انسخ_نص(&النص)); }
    | قيمة_تومل.منطق(المنطق) -> { أرجع قيمة_تومل.منطق(المنطق); }
    | قيمة_تومل.عدد(النص) -> { أرجع قيمة_تومل.عدد(انسخ_نص(&النص)); }
    | قيمة_تومل.تاريخ_وقت(النص) -> { أرجع قيمة_تومل.تاريخ_وقت(انسخ_نص(&النص)); }
    | قيمة_تومل.مصفوفة(الفهرس) -> { أرجع قيمة_تومل.مصفوفة(الفهرس); }
    | قيمة_تومل.جدول(الفهرس) -> { أرجع قيمة_تومل.جدول(الفهرس); };
}

عرف انسخ_قيم_تومل(القيم: &متجه قيمة_تومل): متجه قيمة_تومل {
    دع الناتج: متغير متجه قيمة_تومل = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*القيم) مثل غير_موقع)) {
        ألحق(الناتج, انسخ_قيمة_تومل(&(*القيم)[ف]));
        ف := ف + 1;
    }
    أرجع الناتج;
}

عرف انسخ_مداخل_جدول_تومل(المداخل: &متجه مدخل_جدول_تومل): متجه مدخل_جدول_تومل {
    دع الناتج: متغير متجه مدخل_جدول_تومل = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*المداخل) مثل غير_موقع)) {
        دع المدخل: مدخل_جدول_تومل = {
            المفتاح: انسخ_نص(&(*المداخل)[ف].المفتاح),
            القيمة: انسخ_قيمة_تومل(&(*المداخل)[ف].القيمة),
            الإزاحة: (*المداخل)[ف].الإزاحة
        };
        ألحق(الناتج, المدخل);
        ف := ف + 1;
    }
    أرجع الناتج;
}

نوع محلل_تومل = {
    النص: نص,
    الموضع: غير_موقع,
    الجدول_الحالي: غير_موقع,
    الجذر: غير_موقع,
    الجداول: متجه جدول_تومل,
    المصفوفات: متجه مصفوفة_تومل
};

عرف خطأ_تومل_عند(الصنف: صنف_خطأ_تومل, الموضع: غير_موقع): خطأ_تومل {
    دع الخطأ: خطأ_تومل = { الصنف: الصنف, الإزاحة: الموضع };
    أرجع الخطأ;
}

عرف جدول_تومل_جديد(معلن: منطقي, مغلق: منطقي): جدول_تومل {
    دع المداخل: متجه مدخل_جدول_تومل = [];
    دع الجدول: جدول_تومل = { المداخل: المداخل, معلن: معلن, مغلق: مغلق };
    أرجع الجدول;
}

عرف مصفوفة_تومل_جديدة(): مصفوفة_تومل {
    دع القيم: متجه قيمة_تومل = [];
    دع المصفوفة: مصفوفة_تومل = { القيم: القيم };
    أرجع المصفوفة;
}

عرف أضف_جدول_تومل(المحلل: &متغير محلل_تومل, معلن: منطقي, مغلق: منطقي): غير_موقع {
    دع الفهرس: غير_موقع = الطول((*المحلل).الجداول) مثل غير_موقع;
    ألحق((*المحلل).الجداول, جدول_تومل_جديد(معلن, مغلق));
    أرجع الفهرس;
}

عرف أضف_مصفوفة_تومل(المحلل: &متغير محلل_تومل): غير_موقع {
    دع الفهرس: غير_موقع = الطول((*المحلل).المصفوفات) مثل غير_موقع;
    ألحق((*المحلل).المصفوفات, مصفوفة_تومل_جديدة());
    أرجع الفهرس;
}

عرف موضع_مدخل_تومل(الجدول: &جدول_تومل, المفتاح: &نص): اختيار غير_موقع {
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول((*الجدول).المداخل) مثل غير_موقع)) {
        لو (نصان_متساويان(&(*الجدول).المداخل[ف].المفتاح, المفتاح)) {
            أرجع اختيار.بعض(ف);
        };
        ف := ف + 1;
    }
    أرجع اختيار.لا_شيء();
}

عرف قيمة_مدخل_تومل_داخلية(
    المحلل: &محلل_تومل,
    فهرس_الجدول: غير_موقع,
    المفتاح: &نص
): اختيار قيمة_تومل {
    لو (فهرس_الجدول >= (الطول((*المحلل).الجداول) مثل غير_موقع)) {
        أرجع اختيار.لا_شيء();
    };
    دع الجدول: &جدول_تومل = &(*المحلل).الجداول[فهرس_الجدول];
    طابق موضع_مدخل_تومل(الجدول, المفتاح) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الموضع) -> {
        أرجع اختيار.بعض(انسخ_قيمة_تومل(&(*الجدول).المداخل[الموضع].القيمة));
    };
}

عرف أضف_مدخل_تومل(
    المحلل: &متغير محلل_تومل,
    فهرس_الجدول: غير_موقع,
    المفتاح: نص,
    القيمة: قيمة_تومل,
    الإزاحة: غير_موقع
): منطقي {
    لو (فهرس_الجدول >= (الطول((*المحلل).الجداول) مثل غير_موقع)) { أرجع خطأ; };
    طابق موضع_مدخل_تومل(&(*المحلل).الجداول[فهرس_الجدول], &المفتاح) مع
    | اختيار.بعض(_) -> { أرجع خطأ; }
    | اختيار.لا_شيء -> { };
    دع المدخل: مدخل_جدول_تومل = { المفتاح: المفتاح, القيمة: القيمة, الإزاحة: الإزاحة };
    ألحق((*المحلل).الجداول[فهرس_الجدول].المداخل, المدخل);
    أرجع صواب;
}

عرف اضبط_جدول_معلنا(
    المحلل: &متغير محلل_تومل,
    الفهرس: غير_موقع
): منطقي {
    لو (الفهرس >= (الطول((*المحلل).الجداول) مثل غير_موقع)) { أرجع خطأ; };
    لو ((*المحلل).الجداول[الفهرس].مغلق || (*المحلل).الجداول[الفهرس].معلن) { أرجع خطأ; };
    (*المحلل).الجداول[الفهرس].معلن := صواب;
    أرجع صواب;
}

عرف أغلق_جدول_تومل(المحلل: &متغير محلل_تومل, الفهرس: غير_موقع): فراغ {
    لو (الفهرس < (الطول((*المحلل).الجداول) مثل غير_موقع)) {
        (*المحلل).الجداول[الفهرس].مغلق := صواب;
    };
}

عرف ألحق_مصفوفة_تومل(
    المحلل: &متغير محلل_تومل,
    الفهرس: غير_موقع,
    القيمة: قيمة_تومل
): منطقي {
    لو (الفهرس >= (الطول((*المحلل).المصفوفات) مثل غير_موقع)) { أرجع خطأ; };
    ألحق((*المحلل).المصفوفات[الفهرس].القيم, القيمة);
    أرجع صواب;
}

عرف في_نهاية_تومل(المحلل: &محلل_تومل): منطقي {
    أرجع (*المحلل).الموضع >= (الطول((*المحلل).النص) مثل غير_موقع);
}

عرف بايت_تومل_عند(المحلل: &محلل_تومل, الموضع: غير_موقع): غ8 {
    أرجع (*المحلل).النص[الموضع];
}

عرف بايت_تومل_الحالي(المحلل: &محلل_تومل): اختيار غ8 {
    لو (في_نهاية_تومل(المحلل)) { أرجع اختيار.لا_شيء(); };
    أرجع اختيار.بعض(بايت_تومل_عند(المحلل, (*المحلل).الموضع));
}

عرف تقدم_تومل(المحلل: &متغير محلل_تومل): فراغ {
    لو ((*المحلل).الموضع < (الطول((*المحلل).النص) مثل غير_موقع)) {
        (*المحلل).الموضع := (*المحلل).الموضع + 1;
    };
}

عرف تجاوز_مسافة_تومل(المحلل: &متغير محلل_تومل): فراغ {
    دع مستمر: متغير منطقي = صواب;
    بينما (!في_نهاية_تومل(المحلل) && مستمر) {
        دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
        لو ((ب == 0x20) || (ب == 0x09)) { تقدم_تومل(المحلل); }
        وإلا { مستمر := خطأ; };
    }
}

عرف تجاوز_تعليق_تومل(المحلل: &متغير محلل_تومل): فراغ {
    لو (في_نهاية_تومل(المحلل)) { أرجع; };
    لو (بايت_تومل_عند(المحلل, (*المحلل).الموضع) != 0x23) { أرجع; };
    بينما (!في_نهاية_تومل(المحلل)) {
        دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
        لو ((ب == 0x0A) || (ب == 0x0D)) { أرجع; };
        تقدم_تومل(المحلل);
    }
}

عرف تجاوز_نهاية_سطر_تومل(المحلل: &متغير محلل_تومل): منطقي {
    لو (في_نهاية_تومل(المحلل)) { أرجع صواب; };
    دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
    لو (ب == 0x0A) { تقدم_تومل(المحلل); أرجع صواب; };
    لو (ب == 0x0D) {
        تقدم_تومل(المحلل);
        لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x0A)) {
            تقدم_تومل(المحلل);
            أرجع صواب;
        };
        أرجع خطأ;
    };
    أرجع خطأ;
}

عرف تجاوز_فراغ_وتعليقات_مصفوفة(المحلل: &متغير محلل_تومل): منطقي {
    دع مستمر: متغير منطقي = صواب;
    بينما (مستمر) {
        تجاوز_مسافة_تومل(المحلل);
        لو (في_نهاية_تومل(المحلل)) { أرجع صواب; };
        دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
        لو (ب == 0x23) {
            تجاوز_تعليق_تومل(المحلل);
        } وإلا لو ((ب == 0x0A) || (ب == 0x0D)) {
            لو (!تجاوز_نهاية_سطر_تومل(المحلل)) { أرجع خطأ; };
        } وإلا {
            مستمر := خطأ;
        };
    }
    أرجع صواب;
}

عرف يطابق_تومل_عند(المحلل: &محلل_تومل, الموضع: غير_موقع, النص: نص): منطقي {
    دع الهدف: نص = النص;
    لو ((الموضع + (الطول(الهدف) مثل غير_موقع)) > (الطول((*المحلل).النص) مثل غير_موقع)) {
        أرجع خطأ;
    };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(الهدف) مثل غير_موقع)) {
        لو (بايت_تومل_عند(المحلل, الموضع + ف) != الهدف[ف]) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف قيمة_سداسية_تومل(البايت: غ8): اختيار غ32 {
    لو ((البايت >= 0x30) && (البايت <= 0x39)) { أرجع اختيار.بعض((البايت - 0x30) مثل غ32); };
    لو ((البايت >= 0x41) && (البايت <= 0x46)) { أرجع اختيار.بعض(((البايت - 0x41) مثل غ32) + 10); };
    لو ((البايت >= 0x61) && (البايت <= 0x66)) { أرجع اختيار.بعض(((البايت - 0x61) مثل غ32) + 10); };
    أرجع اختيار.لا_شيء();
}

عرف اقرأ_يونيكود_تومل(
    المحلل: &متغير محلل_تومل,
    العدد: غير_موقع
): نتيجة غ32, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    لو ((البداية + العدد) > (الطول((*المحلل).النص) مثل غير_موقع)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.يونيكود_غير_صالح(), البداية));
    };
    دع القيمة: متغير غ32 = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        طابق قيمة_سداسية_تومل(بايت_تومل_عند(المحلل, البداية + ف)) مع
        | اختيار.لا_شيء -> {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.يونيكود_غير_صالح(), البداية + ف));
        }
        | اختيار.بعض(الرقم) -> { القيمة := (القيمة << 4) | الرقم; };
        ف := ف + 1;
    }
    (*المحلل).الموضع := البداية + العدد;
    أرجع نتيجة.نجح(القيمة);
}

عرف ألحق_سلم_تومل(البايتات: &متغير متجه غ8, القيمة: غ32): منطقي {
    لو (!صالح_كسلم_يونيكود(القيمة)) { أرجع خطأ; };
    دع الحالية: متغير متجه غ8 = [];
    بدّل((*البايتات), الحالية);
    طابق ألحق_محرف_يوتيف8(الحالية, القيمة) مع
    | نتيجة_ترميز_يوتيف8.قيمة_غير_صالحة -> { أرجع خطأ; }
    | نتيجة_ترميز_يوتيف8.مشفر(الناتج) -> { *البايتات := الناتج; أرجع صواب; };
}

عرف حلل_سلسلة_أساسية_تومل(
    المحلل: &متغير محلل_تومل,
    متعددة: منطقي
): نتيجة نص, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    لو (متعددة) {
        لو (!يطابق_تومل_عند(المحلل, البداية, «"""»)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), البداية));
        };
        (*المحلل).الموضع := البداية + 3;
        لو (!في_نهاية_تومل(المحلل)) {
            دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
            لو ((ب == 0x0A) || (ب == 0x0D)) { تجاوز_نهاية_سطر_تومل(المحلل); };
        };
    } وإلا {
        لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, البداية) != 0x22)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), البداية));
        };
        تقدم_تومل(المحلل);
    };

    دع الناتج: متغير متجه غ8 = [];
    بينما (!في_نهاية_تومل(المحلل)) {
        دع الموضع: غير_موقع = (*المحلل).الموضع;
        لو (متعددة && يطابق_تومل_عند(المحلل, الموضع, «"""»)) {
            دع عدد_الاقتباسات: متغير غير_موقع = 3;
            بينما (((الموضع + عدد_الاقتباسات) < (الطول((*المحلل).النص) مثل غير_موقع))
                && (بايت_تومل_عند(المحلل, الموضع + عدد_الاقتباسات) == 0x22)) {
                عدد_الاقتباسات := عدد_الاقتباسات + 1;
            }
            لو (عدد_الاقتباسات > 5) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), الموضع));
            };
            دع داخلية: متغير غير_موقع = عدد_الاقتباسات - 3;
            بينما (داخلية > 0) { ألحق(الناتج, 0x22); داخلية := داخلية - 1; }
            (*المحلل).الموضع := الموضع + عدد_الاقتباسات;
            أرجع نتيجة.نجح(من_بايتات(&الناتج));
        };
        دع ب: غ8 = بايت_تومل_عند(المحلل, الموضع);
        لو (!متعددة && (ب == 0x22)) {
            تقدم_تومل(المحلل);
            أرجع نتيجة.نجح(من_بايتات(&الناتج));
        };
        لو (!متعددة && ((ب == 0x0A) || (ب == 0x0D))) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), الموضع));
        };
        لو (((ب < 0x20) && (ب != 0x09) && (ب != 0x0A) && (ب != 0x0D)) || (ب == 0x7F)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), الموضع));
        };
        لو (ب != 0x5C) {
            ألحق(الناتج, ب);
            تقدم_تومل(المحلل);
        } وإلا {
            تقدم_تومل(المحلل);
            لو (في_نهاية_تومل(المحلل)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
            };
            دع هـ: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
            لو (متعددة && ((هـ == 0x0A) || (هـ == 0x0D))) {
                لو (!تجاوز_نهاية_سطر_تومل(المحلل)) {
                    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.هروب_غير_صالح(), (*المحلل).الموضع));
                };
                دع مستمر: متغير منطقي = صواب;
                بينما (!في_نهاية_تومل(المحلل) && مستمر) {
                    دع فاصل: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
                    لو ((فاصل == 0x20) || (فاصل == 0x09) || (فاصل == 0x0A) || (فاصل == 0x0D)) {
                        لو ((فاصل == 0x0A) || (فاصل == 0x0D)) { تجاوز_نهاية_سطر_تومل(المحلل); }
                        وإلا { تقدم_تومل(المحلل); };
                    } وإلا { مستمر := خطأ; };
                }
            } وإلا {
                تقدم_تومل(المحلل);
                لو (هـ == 0x22) { ألحق(الناتج, 0x22); }
                وإلا لو (هـ == 0x5C) { ألحق(الناتج, 0x5C); }
                وإلا لو (هـ == 0x62) { ألحق(الناتج, 0x08); }
                وإلا لو (هـ == 0x74) { ألحق(الناتج, 0x09); }
                وإلا لو (هـ == 0x6E) { ألحق(الناتج, 0x0A); }
                وإلا لو (هـ == 0x66) { ألحق(الناتج, 0x0C); }
                وإلا لو (هـ == 0x72) { ألحق(الناتج, 0x0D); }
                وإلا لو ((هـ == 0x75) || (هـ == 0x55)) {
                    دع أرقام: متغير غير_موقع = 4;
                    لو (هـ == 0x55) { أرقام := 8; };
                    طابق اقرأ_يونيكود_تومل(المحلل, أرقام) مع
                    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                    | نتيجة.نجح(السلم) -> {
                        لو (!ألحق_سلم_تومل(&متغير الناتج, السلم)) {
                            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.يونيكود_غير_صالح(), الموضع));
                        };
                    };
                } وإلا {
                    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.هروب_غير_صالح(), الموضع));
                };
            };
        };
    }
    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
}

