عرف بايت_مفتاح_عار_تومل(ب: غ8): منطقي {
    أرجع ((ب >= 0x41) && (ب <= 0x5A))
        || ((ب >= 0x61) && (ب <= 0x7A))
        || ((ب >= 0x30) && (ب <= 0x39))
        || (ب == 0x5F)
        || (ب == 0x2D);
}

عرف حلل_مفتاح_واحد_تومل(المحلل: &متغير محلل_تومل): نتيجة نص, خطأ_تومل {
    لو (في_نهاية_تومل(المحلل)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
    };
    دع ب: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
    لو (ب == 0x22) { أرجع حلل_سلسلة_أساسية_تومل(المحلل, خطأ); };
    لو (ب == 0x27) { أرجع حلل_سلسلة_حرفية_تومل(المحلل, خطأ); };
    دع الناتج: متغير متجه غ8 = [];
    بينما (!في_نهاية_تومل(المحلل) && بايت_مفتاح_عار_تومل(بايت_تومل_عند(المحلل, (*المحلل).الموضع))) {
        ألحق(الناتج, بايت_تومل_عند(المحلل, (*المحلل).الموضع));
        تقدم_تومل(المحلل);
    }
    لو ((الطول(الناتج) مثل غير_موقع) == 0) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_غير_صالح(), (*المحلل).الموضع));
    };
    أرجع نتيجة.نجح(من_بايتات(&الناتج));
}

عرف حلل_مسار_مفتاح_تومل(المحلل: &متغير محلل_تومل): نتيجة متجه نص, خطأ_تومل {
    دع الأجزاء: متغير متجه نص = [];
    دع مستمر: متغير منطقي = صواب;
    بينما (مستمر) {
        تجاوز_مسافة_تومل(المحلل);
        طابق حلل_مفتاح_واحد_تومل(المحلل) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الجزء) -> { ألحق(الأجزاء, الجزء); };
        تجاوز_مسافة_تومل(المحلل);
        لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x2E)) {
            تقدم_تومل(المحلل);
        } وإلا {
            مستمر := خطأ;
        };
    }
    لو ((الطول(الأجزاء) مثل غير_موقع) == 0) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_غير_صالح(), (*المحلل).الموضع));
    };
    أرجع نتيجة.نجح(الأجزاء);
}

عرف آخر_جدول_في_مصفوفة_تومل(
    المحلل: &محلل_تومل,
    فهرس_المصفوفة: غير_موقع
): اختيار غير_موقع {
    لو (فهرس_المصفوفة >= (الطول((*المحلل).المصفوفات) مثل غير_موقع)) { أرجع اختيار.لا_شيء(); };
    دع مرجع_القيم: &متجه قيمة_تومل = &(*المحلل).المصفوفات[فهرس_المصفوفة].القيم;
    دع القيم: متجه قيمة_تومل = *مرجع_القيم;
    لو ((الطول(القيم) مثل غير_موقع) == 0) { أرجع اختيار.لا_شيء(); };
    دع الأخير: غير_موقع = (الطول(القيم) مثل غير_موقع) - 1;
    طابق القيم[الأخير] مع
    | قيمة_تومل.جدول(الجدول) -> { أرجع اختيار.بعض(الجدول); }
    | _ -> { أرجع اختيار.لا_شيء(); };
}

عرف حل_جدول_مسار_تومل(
    المحلل: &متغير محلل_تومل,
    البداية: غير_موقع,
    الأجزاء: &متجه نص,
    العدد: غير_موقع,
    أنشئ: منطقي,
    مغلق: منطقي
): نتيجة غير_موقع, خطأ_تومل {
    دع الحالي: متغير غير_موقع = البداية;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        دع مرجع_المفتاح: &نص = &(*الأجزاء)[ف];
        دع المفتاح: نص = انسخ_نص(مرجع_المفتاح);
        طابق قيمة_مدخل_تومل_داخلية(المحلل, الحالي, &المفتاح) مع
        | اختيار.لا_شيء -> {
            لو (!أنشئ) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_غير_صالح(), (*المحلل).الموضع));
            };
            لو ((*المحلل).الجداول[الحالي].مغلق) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.جدول_ضمني_مغلق(), (*المحلل).الموضع));
            };
            دع الجديد: غير_موقع = أضف_جدول_تومل(المحلل, خطأ, مغلق);
            لو (!أضف_مدخل_تومل(المحلل, الحالي, المفتاح, قيمة_تومل.جدول(الجديد), (*المحلل).الموضع)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_مكرر(), (*المحلل).الموضع));
            };
            الحالي := الجديد;
        }
        | اختيار.بعض(القيمة) -> {
            طابق القيمة مع
            | قيمة_تومل.جدول(الجدول) -> { الحالي := الجدول; }
            | قيمة_تومل.مصفوفة(المصفوفة) -> {
                طابق آخر_جدول_في_مصفوفة_تومل(المحلل, المصفوفة) مع
                | اختيار.بعض(الجدول) -> { الحالي := الجدول; }
                | اختيار.لا_شيء -> {
                    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.تعارض_نوع(), (*المحلل).الموضع));
                };
            }
            | _ -> {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.تعارض_نوع(), (*المحلل).الموضع));
            };
        };
        ف := ف + 1;
    }
    أرجع نتيجة.نجح(الحالي);
}


عرف حلل_مصفوفة_تومل(المحلل: &متغير محلل_تومل): نتيجة قيمة_تومل, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, البداية) != 0x5B)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), البداية));
    };
    تقدم_تومل(المحلل);
    دع الفهرس: غير_موقع = أضف_مصفوفة_تومل(المحلل);
    لو (!تجاوز_فراغ_وتعليقات_مصفوفة(المحلل)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
    };
    لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x5D)) {
        تقدم_تومل(المحلل);
        أرجع نتيجة.نجح(قيمة_تومل.مصفوفة(الفهرس));
    };
    دع يتوقع_قيمة: متغير منطقي = صواب;
    بينما (!في_نهاية_تومل(المحلل)) {
        لو (!يتوقع_قيمة) {
            دع فاصل: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
            لو (فاصل == 0x5D) {
                تقدم_تومل(المحلل);
                أرجع نتيجة.نجح(قيمة_تومل.مصفوفة(الفهرس));
            };
            لو (فاصل != 0x2C) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
            };
            تقدم_تومل(المحلل);
            يتوقع_قيمة := صواب;
            لو (!تجاوز_فراغ_وتعليقات_مصفوفة(المحلل)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
            };
            لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x5D)) {
                تقدم_تومل(المحلل);
                أرجع نتيجة.نجح(قيمة_تومل.مصفوفة(الفهرس));
            };
        };
        طابق حلل_قيمة_تومل(المحلل) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> {
            لو (!ألحق_مصفوفة_تومل(المحلل, الفهرس, القيمة)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.تعارض_نوع(), (*المحلل).الموضع));
            };
        };
        يتوقع_قيمة := خطأ;
        لو (!تجاوز_فراغ_وتعليقات_مصفوفة(المحلل)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
        };
    }
    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
}

عرف حلل_جدول_ضمني_تومل(المحلل: &متغير محلل_تومل): نتيجة قيمة_تومل, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, البداية) != 0x7B)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), البداية));
    };
    تقدم_تومل(المحلل);
    دع الفهرس: غير_موقع = أضف_جدول_تومل(المحلل, صواب, خطأ);
    تجاوز_مسافة_تومل(المحلل);
    لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x7D)) {
        تقدم_تومل(المحلل);
        أغلق_جدول_تومل(المحلل, الفهرس);
        أرجع نتيجة.نجح(قيمة_تومل.جدول(الفهرس));
    };
    بينما (!في_نهاية_تومل(المحلل)) {
        طابق حلل_مسار_مفتاح_تومل(المحلل) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الأجزاء) -> {
            تجاوز_مسافة_تومل(المحلل);
            لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, (*المحلل).الموضع) != 0x3D)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
            };
            تقدم_تومل(المحلل);
            تجاوز_مسافة_تومل(المحلل);
            طابق حلل_قيمة_تومل(المحلل) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(القيمة) -> {
                دع العدد: غير_موقع = الطول(الأجزاء) مثل غير_موقع;
                دع المالك: متغير غير_موقع = الفهرس;
                لو (العدد > 1) {
                    طابق حل_جدول_مسار_تومل(المحلل, الفهرس, &الأجزاء, العدد - 1, صواب, صواب) مع
                    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                    | نتيجة.نجح(الجدول) -> { المالك := الجدول; };
                };
                دع موضع_المفتاح: غير_موقع = العدد - 1;
                دع مرجع_المفتاح: &نص = &الأجزاء[موضع_المفتاح];
                دع المفتاح: نص = انسخ_نص(مرجع_المفتاح);
                لو (!أضف_مدخل_تومل(المحلل, المالك, المفتاح, القيمة, (*المحلل).الموضع)) {
                    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_مكرر(), (*المحلل).الموضع));
                };
            };
        };
        تجاوز_مسافة_تومل(المحلل);
        لو (في_نهاية_تومل(المحلل)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
        };
        دع فاصل: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
        لو (فاصل == 0x7D) {
            تقدم_تومل(المحلل);
            أغلق_جدول_تومل(المحلل, الفهرس);
            أرجع نتيجة.نجح(قيمة_تومل.جدول(الفهرس));
        };
        لو (فاصل != 0x2C) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
        };
        تقدم_تومل(المحلل);
        تجاوز_مسافة_تومل(المحلل);
    }
    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
}

عرف بايت_قيمة_عارية_تومل(ب: غ8): منطقي {
    أرجع (ب != 0x20) && (ب != 0x09) && (ب != 0x0A) && (ب != 0x0D)
        && (ب != 0x23) && (ب != 0x2C) && (ب != 0x5D) && (ب != 0x7D);
}

عرف بايت_رقم_تومل(البايت: غ8, الأساس: غير_موقع): منطقي {
    لو ((البايت >= 0x30) && (البايت <= 0x39)) {
        أرجع (((البايت - 0x30) مثل غير_موقع) < الأساس);
    };
    لو (الأساس == 16) {
        لو ((البايت >= 0x41) && (البايت <= 0x46)) { أرجع صواب; };
        لو ((البايت >= 0x61) && (البايت <= 0x66)) { أرجع صواب; };
    };
    أرجع خطأ;
}

عرف قيمة_رقم_تومل(البايت: غ8): غير_موقع {
    لو ((البايت >= 0x30) && (البايت <= 0x39)) { أرجع (البايت - 0x30) مثل غير_موقع; };
    لو ((البايت >= 0x41) && (البايت <= 0x46)) { أرجع ((البايت - 0x41) مثل غير_موقع) + 10; };
    أرجع ((البايت - 0x61) مثل غير_موقع) + 10;
}

عرف تحقق_تسلسل_أرقام_تومل(
    النص: &نص,
    البداية: غير_موقع,
    النهاية: غير_موقع,
    الأساس: غير_موقع
): منطقي {
    لو (البداية >= النهاية) { أرجع خطأ; };
    دع رأى_رقما: متغير منطقي = خطأ;
    دع السابق_رقم: متغير منطقي = خطأ;
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) {
        دع ب: غ8 = (*النص)[ف];
        لو (بايت_رقم_تومل(ب, الأساس)) {
            رأى_رقما := صواب;
            السابق_رقم := صواب;
        } وإلا لو (ب == 0x5F) {
            دع التالي: غير_موقع = ف + 1;
            لو (!السابق_رقم || (التالي >= النهاية)) {
                أرجع خطأ;
            };
            لو (!بايت_رقم_تومل((*النص)[التالي], الأساس)) {
                أرجع خطأ;
            };
            السابق_رقم := خطأ;
        } وإلا {
            أرجع خطأ;
        };
        ف := ف + 1;
    }
    أرجع رأى_رقما && السابق_رقم;
}

عرف عدد_أرقام_تومل_دون_فواصل(
    النص: &نص,
    البداية: غير_موقع,
    النهاية: غير_موقع
): غير_موقع {
    دع العدد: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) {
        لو ((*النص)[ف] != 0x5F) { العدد := العدد + 1; };
        ف := ف + 1;
    }
    أرجع العدد;
}

عرف تحقق_جزء_عشري_تومل(
    النص: &نص,
    البداية: غير_موقع,
    النهاية: غير_موقع,
    يسمح_بأصفار_بادئة: منطقي
): منطقي {
    لو (!تحقق_تسلسل_أرقام_تومل(النص, البداية, النهاية, 10)) { أرجع خطأ; };
    لو (!يسمح_بأصفار_بادئة) {
        دع العدد: غير_موقع = عدد_أرقام_تومل_دون_فواصل(النص, البداية, النهاية);
        لو ((العدد > 1) && ((*النص)[البداية] == 0x30)) { أرجع خطأ; };
    };
    أرجع صواب;
}

عرف صحيح_تومل_ضمن_ص64(
    النص: &نص,
    البداية: غير_موقع,
    النهاية: غير_موقع,
    الأساس: غير_موقع,
    سالب: منطقي
): منطقي {
    دع الحد_الموجب: غ64 = (~(0 مثل غ64)) >> 1;
    دع الحد: متغير غ64 = الحد_الموجب;
    لو (سالب) { الحد := الحد_الموجب + 1; };
    دع القيمة: متغير غ64 = 0;
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) {
        دع ب: غ8 = (*النص)[ف];
        لو (ب != 0x5F) {
            دع الرقم: غ64 = قيمة_رقم_تومل(ب) مثل غ64;
            دع القاعدة: غ64 = الأساس مثل غ64;
            لو (القيمة > ((الحد - الرقم) / القاعدة)) { أرجع خطأ; };
            القيمة := (القيمة * القاعدة) + الرقم;
        };
        ف := ف + 1;
    }
    أرجع صواب;
}

نوع تصنيف_رقم_تومل =
    | غير_صالح
    | صحيح
    | عائم
;

عرف صنف_رقم_تومل(النص: &نص): تصنيف_رقم_تومل {
    دع العدد: غير_موقع = الطول(*النص) مثل غير_موقع;
    لو (العدد == 0) { أرجع تصنيف_رقم_تومل.غير_صالح(); };

    دع البداية: متغير غير_موقع = 0;
    دع سالب: متغير منطقي = خطأ;
    دع له_إشارة: متغير منطقي = خطأ;
    لو (((*النص)[0] == 0x2B) || ((*النص)[0] == 0x2D)) {
        له_إشارة := صواب;
        سالب := (*النص)[0] == 0x2D;
        البداية := 1;
        لو (البداية >= العدد) { أرجع تصنيف_رقم_تومل.غير_صالح(); };
    };

    دع الباقي: متغير متجه غ8 = [];
    دع ر: متغير غير_موقع = البداية;
    بينما (ر < العدد) { ألحق(الباقي, (*النص)[ر]); ر := ر + 1; }
    دع نص_الباقي: نص = من_بايتات(&الباقي);
    دع نان: نص = «nan»;
    دع لانهاية: نص = «inf»;
    لو (نصان_متساويان(&نص_الباقي, &نان) || نصان_متساويان(&نص_الباقي, &لانهاية)) {
        أرجع تصنيف_رقم_تومل.عائم();
    };

    لو (!له_إشارة && ((البداية + 2) <= العدد) && ((*النص)[البداية] == 0x30)) {
        دع موضع_النوع: غير_موقع = البداية + 1;
        دع النوع: غ8 = (*النص)[موضع_النوع];
        دع الأساس: متغير غير_موقع = 0;
        لو (النوع == 0x78) { الأساس := 16; }
        وإلا لو (النوع == 0x6F) { الأساس := 8; }
        وإلا لو (النوع == 0x62) { الأساس := 2; };
        لو (الأساس != 0) {
            دع بداية_الأرقام: غير_موقع = البداية + 2;
            لو (!تحقق_تسلسل_أرقام_تومل(النص, بداية_الأرقام, العدد, الأساس)) {
                أرجع تصنيف_رقم_تومل.غير_صالح();
            };
            لو (!صحيح_تومل_ضمن_ص64(النص, بداية_الأرقام, العدد, الأساس, خطأ)) {
                أرجع تصنيف_رقم_تومل.غير_صالح();
            };
            أرجع تصنيف_رقم_تومل.صحيح();
        };
    };

    دع نهاية_الصحيح: متغير غير_موقع = البداية;
    بينما ((نهاية_الصحيح < العدد) && ((*النص)[نهاية_الصحيح] != 0x2E)
        && ((*النص)[نهاية_الصحيح] != 0x65) && ((*النص)[نهاية_الصحيح] != 0x45)) {
        نهاية_الصحيح := نهاية_الصحيح + 1;
    }
    لو (!تحقق_جزء_عشري_تومل(النص, البداية, نهاية_الصحيح, خطأ)) {
        أرجع تصنيف_رقم_تومل.غير_صالح();
    };
    لو (نهاية_الصحيح == العدد) {
        لو (!صحيح_تومل_ضمن_ص64(النص, البداية, العدد, 10, سالب)) {
            أرجع تصنيف_رقم_تومل.غير_صالح();
        };
        أرجع تصنيف_رقم_تومل.صحيح();
    };

    دع الموضع: متغير غير_موقع = نهاية_الصحيح;
    دع له_كسر: متغير منطقي = خطأ;
    دع له_أس: متغير منطقي = خطأ;
    لو ((*النص)[الموضع] == 0x2E) {
        له_كسر := صواب;
        الموضع := الموضع + 1;
        دع نهاية_الكسر: متغير غير_موقع = الموضع;
        بينما ((نهاية_الكسر < العدد) && ((*النص)[نهاية_الكسر] != 0x65) && ((*النص)[نهاية_الكسر] != 0x45)) {
            نهاية_الكسر := نهاية_الكسر + 1;
        }
        لو (!تحقق_تسلسل_أرقام_تومل(النص, الموضع, نهاية_الكسر, 10)) {
            أرجع تصنيف_رقم_تومل.غير_صالح();
        };
        الموضع := نهاية_الكسر;
    };
    لو ((الموضع < العدد) && (((*النص)[الموضع] == 0x65) || ((*النص)[الموضع] == 0x45))) {
        له_أس := صواب;
        الموضع := الموضع + 1;
        لو ((الموضع < العدد) && (((*النص)[الموضع] == 0x2B) || ((*النص)[الموضع] == 0x2D))) {
            الموضع := الموضع + 1;
        };
        لو (!تحقق_تسلسل_أرقام_تومل(النص, الموضع, العدد, 10)) {
            أرجع تصنيف_رقم_تومل.غير_صالح();
        };
        الموضع := العدد;
    };
    لو ((الموضع != العدد) || (!له_كسر && !له_أس)) {
        أرجع تصنيف_رقم_تومل.غير_صالح();
    };
    أرجع تصنيف_رقم_تومل.عائم();
}

عرف قيمة_أرقام_ثابتة_تومل(
    النص: &نص,
    البداية: غير_موقع,
    العدد: غير_موقع
): اختيار غير_موقع {
    لو ((البداية + العدد) > (الطول(*النص) مثل غير_موقع)) { أرجع اختيار.لا_شيء(); };
    دع القيمة: متغير غير_موقع = 0;
    دع ف: متغير غير_موقع = 0;
    بينما (ف < العدد) {
        دع الموضع: غير_موقع = البداية + ف;
        دع ب: غ8 = (*النص)[الموضع];
        لو ((ب < 0x30) || (ب > 0x39)) { أرجع اختيار.لا_شيء(); };
        القيمة := (القيمة * 10) + ((ب - 0x30) مثل غير_موقع);
        ف := ف + 1;
    }
    أرجع اختيار.بعض(القيمة);
}

عرف سنة_كبيسة_تومل(السنة: غير_موقع): منطقي {
    لو ((السنة % 400) == 0) { أرجع صواب; };
    لو ((السنة % 100) == 0) { أرجع خطأ; };
    أرجع (السنة % 4) == 0;
}

عرف أيام_شهر_تومل(السنة: غير_موقع, الشهر: غير_موقع): غير_موقع {
    لو ((الشهر == 1) || (الشهر == 3) || (الشهر == 5) || (الشهر == 7)
        || (الشهر == 8) || (الشهر == 10) || (الشهر == 12)) { أرجع 31; };
    لو ((الشهر == 4) || (الشهر == 6) || (الشهر == 9) || (الشهر == 11)) { أرجع 30; };
    لو (الشهر == 2) {
        لو (سنة_كبيسة_تومل(السنة)) { أرجع 29; };
        أرجع 28;
    };
    أرجع 0;
}

عرف تحقق_تاريخ_تومل_عند(النص: &نص, البداية: غير_موقع): منطقي {
    لو ((البداية + 10) > (الطول(*النص) مثل غير_موقع)) { أرجع خطأ; };
    دع موضع_فاصل_السنة: غير_موقع = البداية + 4;
    دع موضع_فاصل_الشهر: غير_موقع = البداية + 7;
    لو (((*النص)[موضع_فاصل_السنة] != 0x2D) || ((*النص)[موضع_فاصل_الشهر] != 0x2D)) { أرجع خطأ; };
    دع السنة: غير_موقع;
    دع الشهر: غير_موقع;
    دع اليوم: غير_موقع;
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية, 4) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { السنة := القيمة; };
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية + 5, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { الشهر := القيمة; };
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية + 8, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { اليوم := القيمة; };
    دع الحد: غير_موقع = أيام_شهر_تومل(السنة, الشهر);
    أرجع (الحد != 0) && (اليوم >= 1) && (اليوم <= الحد);
}

عرف تحقق_وقت_تومل(
    النص: &نص,
    البداية: غير_موقع,
    النهاية: غير_موقع,
    يسمح_بمنطقة: منطقي
): منطقي {
    لو ((البداية + 8) > النهاية) { أرجع خطأ; };
    دع موضع_فاصل_الساعة: غير_موقع = البداية + 2;
    دع موضع_فاصل_الدقيقة: غير_موقع = البداية + 5;
    لو (((*النص)[موضع_فاصل_الساعة] != 0x3A) || ((*النص)[موضع_فاصل_الدقيقة] != 0x3A)) { أرجع خطأ; };
    دع الساعة: غير_موقع;
    دع الدقيقة: غير_موقع;
    دع الثانية: غير_موقع;
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { الساعة := القيمة; };
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية + 3, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { الدقيقة := القيمة; };
    طابق قيمة_أرقام_ثابتة_تومل(النص, البداية + 6, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { الثانية := القيمة; };
    لو ((الساعة > 23) || (الدقيقة > 59) || (الثانية > 60)) { أرجع خطأ; };

    دع الموضع: متغير غير_موقع = البداية + 8;
    لو ((الموضع < النهاية) && ((*النص)[الموضع] == 0x2E)) {
        الموضع := الموضع + 1;
        دع بداية_الكسر: غير_موقع = الموضع;
        بينما ((الموضع < النهاية) && ((*النص)[الموضع] >= 0x30) && ((*النص)[الموضع] <= 0x39)) {
            الموضع := الموضع + 1;
        }
        لو (الموضع == بداية_الكسر) { أرجع خطأ; };
    };
    لو (الموضع == النهاية) { أرجع صواب; };
    لو (!يسمح_بمنطقة) { أرجع خطأ; };
    لو (((*النص)[الموضع] == 0x5A) || ((*النص)[الموضع] == 0x7A)) {
        أرجع (الموضع + 1) == النهاية;
    };
    لو (((*النص)[الموضع] != 0x2B) && ((*النص)[الموضع] != 0x2D)) { أرجع خطأ; };
    لو ((الموضع + 6) != النهاية) { أرجع خطأ; };
    دع موضع_فاصل_المنطقة: غير_موقع = الموضع + 3;
    لو ((*النص)[موضع_فاصل_المنطقة] != 0x3A) { أرجع خطأ; };
    دع ساعة_المنطقة: غير_موقع;
    دع دقيقة_المنطقة: غير_موقع;
    طابق قيمة_أرقام_ثابتة_تومل(النص, الموضع + 1, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { ساعة_المنطقة := القيمة; };
    طابق قيمة_أرقام_ثابتة_تومل(النص, الموضع + 4, 2) مع
    | اختيار.لا_شيء -> { أرجع خطأ; }
    | اختيار.بعض(القيمة) -> { دقيقة_المنطقة := القيمة; };
    أرجع (ساعة_المنطقة <= 23) && (دقيقة_المنطقة <= 59);
}

عرف قيمة_تاريخ_وقت_صالحة_تومل(النص: &نص): منطقي {
    دع العدد: غير_موقع = الطول(*النص) مثل غير_موقع;
    لو ((العدد >= 10) && تحقق_تاريخ_تومل_عند(النص, 0)) {
        لو (العدد == 10) { أرجع صواب; };
        دع الفاصل: غ8 = (*النص)[10];
        لو ((الفاصل != 0x54) && (الفاصل != 0x74) && (الفاصل != 0x20)) { أرجع خطأ; };
        أرجع تحقق_وقت_تومل(النص, 11, العدد, صواب);
    };
    أرجع تحقق_وقت_تومل(النص, 0, العدد, خطأ);
}

عرف حلل_قيمة_عارية_تومل(المحلل: &متغير محلل_تومل): نتيجة قيمة_تومل, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    دع البايتات: متغير متجه غ8 = [];
    بينما (!في_نهاية_تومل(المحلل) && بايت_قيمة_عارية_تومل(بايت_تومل_عند(المحلل, (*المحلل).الموضع))) {
        ألحق(البايتات, بايت_تومل_عند(المحلل, (*المحلل).الموضع));
        تقدم_تومل(المحلل);
    }
    // RFC3339 date-times may use one space instead of T. Keep that one space
    // inside the scalar only when it separates a date from a time token.
    لو (!في_نهاية_تومل(المحلل) && (بايت_تومل_عند(المحلل, (*المحلل).الموضع) == 0x20)) {
        دع حفظ: غير_موقع = (*المحلل).الموضع;
        دع الحالي: نص = من_بايتات(&البايتات);
        لو ((الطول(الحالي) مثل غير_موقع) == 10 && تحقق_تاريخ_تومل_عند(&الحالي, 0)) {
            (*المحلل).الموضع := حفظ + 1;
            لو (!في_نهاية_تومل(المحلل)) {
                دع التالي: غ8 = بايت_تومل_عند(المحلل, (*المحلل).الموضع);
                لو ((التالي >= 0x30) && (التالي <= 0x39)) {
                    ألحق(البايتات, 0x20);
                    بينما (!في_نهاية_تومل(المحلل) && بايت_قيمة_عارية_تومل(بايت_تومل_عند(المحلل, (*المحلل).الموضع))) {
                        ألحق(البايتات, بايت_تومل_عند(المحلل, (*المحلل).الموضع));
                        تقدم_تومل(المحلل);
                    }
                } وإلا {
                    (*المحلل).الموضع := حفظ;
                };
            };
        };
    };
    دع النص: نص = من_بايتات(&البايتات);
    دع صواب_نص: نص = «true»;
    دع خطأ_نص: نص = «false»;
    لو (نصان_متساويان(&النص, &صواب_نص)) { أرجع نتيجة.نجح(قيمة_تومل.منطق(صواب)); };
    لو (نصان_متساويان(&النص, &خطأ_نص)) { أرجع نتيجة.نجح(قيمة_تومل.منطق(خطأ)); };
    لو (قيمة_تاريخ_وقت_صالحة_تومل(&النص)) { أرجع نتيجة.نجح(قيمة_تومل.تاريخ_وقت(النص)); };
    طابق صنف_رقم_تومل(&النص) مع
    | تصنيف_رقم_تومل.صحيح -> { أرجع نتيجة.نجح(قيمة_تومل.عدد(النص)); }
    | تصنيف_رقم_تومل.عائم -> { أرجع نتيجة.نجح(قيمة_تومل.عدد(النص)); }
    | تصنيف_رقم_تومل.غير_صالح -> { };
    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.قيمة_غير_صالحة(), البداية));
}

عرف حلل_قيمة_تومل(المحلل: &متغير محلل_تومل): نتيجة قيمة_تومل, خطأ_تومل {
    تجاوز_مسافة_تومل(المحلل);
    لو (في_نهاية_تومل(المحلل)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نهاية_غير_متوقعة(), (*المحلل).الموضع));
    };
    دع الموضع: غير_موقع = (*المحلل).الموضع;
    دع ب: غ8 = بايت_تومل_عند(المحلل, الموضع);
    لو (ب == 0x22) {
        لو (يطابق_تومل_عند(المحلل, الموضع, «"""»)) {
            طابق حلل_سلسلة_أساسية_تومل(المحلل, صواب) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(النص) -> { أرجع نتيجة.نجح(قيمة_تومل.سلسلة(النص)); };
        };
        طابق حلل_سلسلة_أساسية_تومل(المحلل, خطأ) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النص) -> { أرجع نتيجة.نجح(قيمة_تومل.سلسلة(النص)); };
    };
    لو (ب == 0x27) {
        لو (يطابق_تومل_عند(المحلل, الموضع, «'''»)) {
            طابق حلل_سلسلة_حرفية_تومل(المحلل, صواب) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(النص) -> { أرجع نتيجة.نجح(قيمة_تومل.سلسلة(النص)); };
        };
        طابق حلل_سلسلة_حرفية_تومل(المحلل, خطأ) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(النص) -> { أرجع نتيجة.نجح(قيمة_تومل.سلسلة(النص)); };
    };
    لو (ب == 0x5B) { أرجع حلل_مصفوفة_تومل(المحلل); };
    لو (ب == 0x7B) { أرجع حلل_جدول_ضمني_تومل(المحلل); };
    أرجع حلل_قيمة_عارية_تومل(المحلل);
}

عرف حلل_تعيين_تومل(المحلل: &متغير محلل_تومل): نتيجة منطقي, خطأ_تومل {
    طابق حلل_مسار_مفتاح_تومل(المحلل) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(الأجزاء) -> {
        تجاوز_مسافة_تومل(المحلل);
        لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, (*المحلل).الموضع) != 0x3D)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
        };
        تقدم_تومل(المحلل);
        تجاوز_مسافة_تومل(المحلل);
        طابق حلل_قيمة_تومل(المحلل) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(القيمة) -> {
            دع العدد: غير_موقع = الطول(الأجزاء) مثل غير_موقع;
            دع المالك: متغير غير_موقع = (*المحلل).الجدول_الحالي;
            لو (العدد > 1) {
                طابق حل_جدول_مسار_تومل(
                    المحلل, المالك, &الأجزاء, العدد - 1, صواب, صواب
                ) مع
                | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                | نتيجة.نجح(الجدول) -> { المالك := الجدول; };
            };
            دع موضع_المفتاح: غير_موقع = العدد - 1;
            دع مرجع_المفتاح: &نص = &الأجزاء[موضع_المفتاح];
            دع المفتاح: نص = انسخ_نص(مرجع_المفتاح);
            لو (!أضف_مدخل_تومل(المحلل, المالك, المفتاح, القيمة, (*المحلل).الموضع)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_مكرر(), (*المحلل).الموضع));
            };
        };
    };
    أرجع نتيجة.نجح(صواب);
}

عرف حلل_رأس_جدول_تومل(المحلل: &متغير محلل_تومل): نتيجة منطقي, خطأ_تومل {
    دع البداية: غير_موقع = (*المحلل).الموضع;
    لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, البداية) != 0x5B)) {
        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), البداية));
    };
    دع مصفوفة_جداول: منطقي = يطابق_تومل_عند(المحلل, البداية, «[[»);
    لو (مصفوفة_جداول) { (*المحلل).الموضع := البداية + 2; }
    وإلا { (*المحلل).الموضع := البداية + 1; };
    تجاوز_مسافة_تومل(المحلل);
    دع الأجزاء: متجه نص;
    طابق حلل_مسار_مفتاح_تومل(المحلل) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(القيمة) -> { الأجزاء := القيمة; };
    تجاوز_مسافة_تومل(المحلل);
    لو (مصفوفة_جداول) {
        لو (!يطابق_تومل_عند(المحلل, (*المحلل).الموضع, «]]»)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
        };
        (*المحلل).الموضع := (*المحلل).الموضع + 2;
        دع العدد: غير_موقع = الطول(الأجزاء) مثل غير_موقع;
        دع الأب: متغير غير_موقع = (*المحلل).الجذر;
        لو (العدد > 1) {
            طابق حل_جدول_مسار_تومل(المحلل, الأب, &الأجزاء, العدد - 1, صواب, خطأ) مع
            | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
            | نتيجة.نجح(الجدول) -> { الأب := الجدول; };
        };
        دع موضع_المفتاح: غير_موقع = العدد - 1;
        دع مرجع_المفتاح: &نص = &الأجزاء[موضع_المفتاح];
        دع المفتاح: نص = انسخ_نص(مرجع_المفتاح);
        دع فهرس_المصفوفة: متغير غير_موقع = 0;
        طابق قيمة_مدخل_تومل_داخلية(المحلل, الأب, &المفتاح) مع
        | اختيار.لا_شيء -> {
            فهرس_المصفوفة := أضف_مصفوفة_تومل(المحلل);
            لو (!أضف_مدخل_تومل(المحلل, الأب, المفتاح, قيمة_تومل.مصفوفة(فهرس_المصفوفة), البداية)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.مفتاح_مكرر(), البداية));
            };
        }
        | اختيار.بعض(القيمة) -> {
            طابق القيمة مع
            | قيمة_تومل.مصفوفة(الفهرس) -> { فهرس_المصفوفة := الفهرس; }
            | _ -> { أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.تعارض_نوع(), البداية)); };
        };
        دع الجدول: غير_موقع = أضف_جدول_تومل(المحلل, صواب, خطأ);
        لو (!ألحق_مصفوفة_تومل(المحلل, فهرس_المصفوفة, قيمة_تومل.جدول(الجدول))) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.تعارض_نوع(), البداية));
        };
        (*المحلل).الجدول_الحالي := الجدول;
    } وإلا {
        لو (في_نهاية_تومل(المحلل) || (بايت_تومل_عند(المحلل, (*المحلل).الموضع) != 0x5D)) {
            أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), (*المحلل).الموضع));
        };
        تقدم_تومل(المحلل);
        طابق حل_جدول_مسار_تومل(
            المحلل, (*المحلل).الجذر, &الأجزاء, الطول(الأجزاء) مثل غير_موقع, صواب, خطأ
        ) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(الجدول) -> {
            لو (!اضبط_جدول_معلنا(المحلل, الجدول)) {
                أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.جدول_مكرر(), البداية));
            };
            (*المحلل).الجدول_الحالي := الجدول;
        };
    };
    أرجع نتيجة.نجح(صواب);
}

عام عرف حلل_تومل(النص: &نص): نتيجة وثيقة_تومل, خطأ_تومل {
    دع الجداول: متجه جدول_تومل = [];
    دع المصفوفات: متجه مصفوفة_تومل = [];
    دع المحلل: متغير محلل_تومل = {
        النص: انسخ_نص(النص),
        الموضع: 0,
        الجدول_الحالي: 0,
        الجذر: 0,
        الجداول: الجداول,
        المصفوفات: المصفوفات
    };
    دع الجذر: غير_موقع = أضف_جدول_تومل(&متغير المحلل, صواب, خطأ);
    المحلل.الجذر := الجذر;
    المحلل.الجدول_الحالي := الجذر;

    بينما (!في_نهاية_تومل(&المحلل)) {
        تجاوز_مسافة_تومل(&متغير المحلل);
        لو (في_نهاية_تومل(&المحلل)) { } وإلا {
            دع ب: غ8 = بايت_تومل_عند(&المحلل, المحلل.الموضع);
            لو (ب == 0x23) {
                تجاوز_تعليق_تومل(&متغير المحلل);
            } وإلا لو ((ب == 0x0A) || (ب == 0x0D)) {
                لو (!تجاوز_نهاية_سطر_تومل(&متغير المحلل)) {
                    أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), المحلل.الموضع));
                };
            } وإلا {
                لو (ب == 0x5B) {
                    طابق حلل_رأس_جدول_تومل(&متغير المحلل) مع
                    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                    | نتيجة.نجح(_) -> { };
                } وإلا {
                    طابق حلل_تعيين_تومل(&متغير المحلل) مع
                    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
                    | نتيجة.نجح(_) -> { };
                };
                تجاوز_مسافة_تومل(&متغير المحلل);
                تجاوز_تعليق_تومل(&متغير المحلل);
                لو (!في_نهاية_تومل(&المحلل)) {
                    دع نهاية: غ8 = بايت_تومل_عند(&المحلل, المحلل.الموضع);
                    لو ((نهاية != 0x0A) && (نهاية != 0x0D)) {
                        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.نص_لاحق(), المحلل.الموضع));
                    };
                    لو (!تجاوز_نهاية_سطر_تومل(&متغير المحلل)) {
                        أرجع نتيجة.خطأ(خطأ_تومل_عند(صنف_خطأ_تومل.رمز_غير_متوقع(), المحلل.الموضع));
                    };
                };
            };
        };
    }

    دع الجذر_النهائي: غير_موقع = المحلل.الجذر;
    دع الجداول_النهائية: متغير متجه جدول_تومل = [];
    دع المصفوفات_النهائية: متغير متجه مصفوفة_تومل = [];
    بدّل(المحلل.الجداول, الجداول_النهائية);
    بدّل(المحلل.المصفوفات, المصفوفات_النهائية);
    دع الوثيقة: وثيقة_تومل = {
        الجذر: الجذر_النهائي,
        الجداول: الجداول_النهائية,
        المصفوفات: المصفوفات_النهائية
    };
    أرجع نتيجة.نجح(الوثيقة);
}

عام عرف قيمة_مفتاح_تومل(
    الوثيقة: &وثيقة_تومل,
    فهرس_الجدول: غير_موقع,
    المفتاح: &نص
): اختيار قيمة_تومل {
    لو (فهرس_الجدول >= (الطول((*الوثيقة).الجداول) مثل غير_موقع)) { أرجع اختيار.لا_شيء(); };
    دع الجدول: &جدول_تومل = &(*الوثيقة).الجداول[فهرس_الجدول];
    طابق موضع_مدخل_تومل(الجدول, المفتاح) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(الموضع) -> {
        أرجع اختيار.بعض(انسخ_قيمة_تومل(&(*الجدول).المداخل[الموضع].القيمة));
    };
}

عام عرف جدول_مفتاح_تومل(
    الوثيقة: &وثيقة_تومل,
    فهرس_الجدول: غير_موقع,
    المفتاح: &نص
): اختيار غير_موقع {
    طابق قيمة_مفتاح_تومل(الوثيقة, فهرس_الجدول, المفتاح) مع
    | اختيار.لا_شيء -> { أرجع اختيار.لا_شيء(); }
    | اختيار.بعض(القيمة) -> {
        طابق القيمة مع
        | قيمة_تومل.جدول(الجدول) -> { أرجع اختيار.بعض(الجدول); }
        | _ -> { أرجع اختيار.لا_شيء(); };
    };
}

عام عرف مداخل_جدول_تومل(الوثيقة: &وثيقة_تومل, الفهرس: غير_موقع): متجه مدخل_جدول_تومل {
    لو (الفهرس >= (الطول((*الوثيقة).الجداول) مثل غير_موقع)) {
        دع فارغة: متجه مدخل_جدول_تومل = [];
        أرجع فارغة;
    };
    أرجع انسخ_مداخل_جدول_تومل(&(*الوثيقة).الجداول[الفهرس].المداخل);
}

عام عرف قيم_مصفوفة_تومل(الوثيقة: &وثيقة_تومل, الفهرس: غير_موقع): متجه قيمة_تومل {
    لو (الفهرس >= (الطول((*الوثيقة).المصفوفات) مثل غير_موقع)) {
        دع فارغة: متجه قيمة_تومل = [];
        أرجع فارغة;
    };
    أرجع انسخ_قيم_تومل(&(*الوثيقة).المصفوفات[الفهرس].القيم);
}

// English spellings reference the canonical Arabic TOML declarations.
عام مرادف parse_toml = حلل_تومل;
عام مرادف toml_value_at = قيمة_مفتاح_تومل;
عام مرادف toml_table_at = جدول_مفتاح_تومل;
عام مرادف toml_document = وثيقة_تومل;
عام مرادف toml_value = قيمة_تومل;
عام مرادف toml_error = خطأ_تومل;

library/std/unicode/algorithms/canonical:
// Canonical combining-class reordering (UAX #15).
// The caller supplies canonical combining classes from the SAME versioned UCD
// as the code points. Neither the classes nor their source are guessed here.
// A class of zero is a starter and cannot be moved across by this algorithm.
// Equal nonzero classes retain their original order.
عام عرف رتب_دمج_يونيكود(
    القيم: &متغير متجه غ32,
    درجات_الدمج: &متغير متجه غ8
): منطقي {
    دع العدد: غير_موقع = الطول(*القيم) مثل غير_موقع;
    لو (العدد != (الطول(*درجات_الدمج) مثل غير_موقع)) {
        أرجع خطأ;
    };

    دع الفهرس: متغير غير_موقع = 1;
    بينما (الفهرس < العدد) {
        دع الموضع: متغير غير_موقع = الفهرس;
        بينما (
            (الموضع > 0)
            && ((*درجات_الدمج)[الموضع] != 0)
            && ((*درجات_الدمج)[الموضع - 1] > (*درجات_الدمج)[الموضع])
        ) {
            دع القيمة_السابقة: غ32 = (*القيم)[الموضع - 1];
            (*القيم)[الموضع - 1] := (*القيم)[الموضع];
            (*القيم)[الموضع] := القيمة_السابقة;
            دع الدرجة_السابقة: غ8 = (*درجات_الدمج)[الموضع - 1];
            (*درجات_الدمج)[الموضع - 1] := (*درجات_الدمج)[الموضع];
            (*درجات_الدمج)[الموضع] := الدرجة_السابقة;
            الموضع := الموضع - 1;
        }
        الفهرس := الفهرس + 1;
    }
    أرجع صواب;
}

library/std/unicode/algorithms/case_cont:
// Unicode SpecialCasing.txt Final_Sigma context (default, locale-independent).
// The supplied classifications must come from the SAME versioned UCD.
// The caller must select this context for U+03A3; this operation does not
// implement Turkish or Lithuanian locale-specific casing.
عام عرف سيغما_نهائية_في_نص(
    ذو_حالة: &متجه منطقي,
    متجاهل_للحالة: &متجه منطقي,
    الموضع: غير_موقع
): اختيار منطقي {
    دع العدد: غير_موقع = الطول(*ذو_حالة) مثل غير_موقع;
    لو (العدد != (الطول(*متجاهل_للحالة) مثل غير_موقع) || الموضع >= العدد) {
        أرجع اختيار.لا_شيء();
    };

    // Final_Sigma requires a preceding Cased character, ignoring Case_Ignorable.
    دع السابق: متغير غير_موقع = الموضع;
    دع وجد_السابق: متغير منطقي = خطأ;
    دع استمر: متغير منطقي = صواب;
    بينما (السابق > 0 && استمر) {
        السابق := السابق - 1;
        لو ((*متجاهل_للحالة)[السابق]) {
            // Ignore for the purpose of this context.
        } وإلا {
            وجد_السابق := (*ذو_حالة)[السابق];
            استمر := خطأ;
        };
    }
    لو (!وجد_السابق) { أرجع اختيار.بعض(خطأ); };

    // There must be NO following Cased character after Case_Ignorable*.
    دع التالي: متغير غير_موقع = الموضع + 1;
    بينما (التالي < العدد) {
        لو (!(*متجاهل_للحالة)[التالي]) {
            أرجع اختيار.بعض(!(*ذو_حالة)[التالي]);
        };
        التالي := التالي + 1;
    }
    أرجع اختيار.بعض(صواب);
}

library/std/unicode/algorithms/hangul.sn:
// Algorithmic Hangul canonical decomposition and composition (UAX #15).
// This algorithm is independent of the versioned Unicode Character Database.
// The UCD's other decomposition mappings and composition exclusions are
// intentionally NOT approximated by these Hangul-only operations.

عام عرف فك_مقطع_هانغول(القيمة: غ32): متجه غ32 {
    دع الناتج: متغير متجه غ32 = [];
    لو ((القيمة < 0xAC00) || (القيمة >= 0xD7A4)) {
        أرجع الناتج;
    };

    دع فهرس_المقطع: غ32 = القيمة - 0xAC00;
    دع فهرس_البداية: غ32 = فهرس_المقطع / 588;
    دع فهرس_الحركة: غ32 = (فهرس_المقطع % 588) / 28;
    دع فهرس_الختام: غ32 = فهرس_المقطع % 28;

    ألحق(الناتج, 0x1100 + فهرس_البداية);
    ألحق(الناتج, 0x1161 + فهرس_الحركة);
    لو (فهرس_الختام != 0) {
        ألحق(الناتج, 0x11A7 + فهرس_الختام);
    };
    أرجع الناتج;
}

عام عرف ركب_مقطعي_هانغول(الأول: غ32, الثاني: غ32): اختيار غ32 {
    لو (
        (الأول >= 0x1100) && (الأول < 0x1113)
        && (الثاني >= 0x1161) && (الثاني < 0x1176)
    ) {
        دع فهرس_البداية: غ32 = الأول - 0x1100;
        دع فهرس_الحركة: غ32 = الثاني - 0x1161;
        أرجع اختيار.بعض(0xAC00 + (فهرس_البداية * 588) + (فهرس_الحركة * 28));
    };

    لو (
        (الأول >= 0xAC00) && (الأول < 0xD7A4)
        && (((الأول - 0xAC00) % 28) == 0)
        && (الثاني >= 0x11A8) && (الثاني < 0x11C3)
    ) {
        أرجع اختيار.بعض(الأول + (الثاني - 0x11A7));
    };
    أرجع اختيار.لا_شيء();
}

library/std/unicode/algorithms/lookup.sn:
// Single sorted-table lookup owner for Unicode 18 data.
// Triples are inclusive (first, last, value); properties are sorted
// (property ID, first, last). No decoding, heap allocation or linear scan.
عام عرف قيمة_نطاق_مرتب(
    العناصر: &متجه غ32,
    القيمة: غ32,
    الافتراضي: غ32
): غ32 {
    دع نهاية: متغير غير_موقع = (الطول(*العناصر) مثل غير_موقع) / 3;
    دع بداية: متغير غير_موقع = 0;
    بينما (بداية < نهاية) {
        دع وسط: غير_موقع = بداية + (نهاية - بداية) / 2;
        دع موضع: غير_موقع = وسط * 3;
        لو (القيمة < (*العناصر)[موضع]) {
            نهاية := وسط;
        } وإلا لو (القيمة > (*العناصر)[موضع + 1]) {
            بداية := وسط + 1;
        } وإلا {
            أرجع (*العناصر)[موضع + 2];
        };
    }
    أرجع الافتراضي;
}

عام عرف خاصية_نطاق_مرتبة(
    العناصر: &متجه غ32,
    الخاصية: غ32,
    القيمة: غ32
): منطقي {
    دع بداية: متغير غير_موقع = 0;
    دع نهاية: متغير غير_موقع = (الطول(*العناصر) مثل غير_موقع) / 3;
    بينما (بداية < نهاية) {
        دع وسط: غير_موقع = بداية + (نهاية - بداية) / 2;
        دع موضع: غير_موقع = وسط * 3;
        دع معرف: غ32 = (*العناصر)[موضع];
        لو (الخاصية < معرف || (الخاصية == معرف && القيمة < (*العناصر)[موضع + 1])) {
            نهاية := وسط;
        } وإلا لو (الخاصية > معرف || القيمة > (*العناصر)[موضع + 2]) {
            بداية := وسط + 1;
        } وإلا {
            أرجع صواب;
        };
    }
    أرجع خطأ;
}

// Mapping keys are sorted; offsets and lengths index one shared scalar pool.
عام عرف تسلسل_تحويل_يونيكود(
    القيمة: غ32,
    المفاتيح: &متجه غ32,
    البدايات: &متجه غ32,
    الأطوال: &متجه غ32,
    القيم: &متجه غ32
): متجه غ32 {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = الطول(*المفاتيح) مثل غير_موقع;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + (النهاية - البداية) / 2;
        لو ((*المفاتيح)[الوسط] < القيمة) {
            البداية := الوسط + 1;
        } وإلا {
            النهاية := الوسط;
        };
    }
    دع الناتج: متغير متجه غ32 = [];
    لو (البداية < (الطول(*المفاتيح) مثل غير_موقع) && (*المفاتيح)[البداية] == القيمة) {
        دع موضع: متغير غير_موقع = (*البدايات)[البداية] مثل غير_موقع;
        دع النهاية_الفعلية: غير_موقع = موضع + ((*الأطوال)[البداية] مثل غير_موقع);
        بينما (موضع < النهاية_الفعلية) {
            ألحق(الناتج, (*القيم)[موضع]);
            موضع := موضع + 1;
        }
    } وإلا {
        ألحق(الناتج, القيمة);
    };
    أرجع الناتج;
}

// Simple mappings contain at most one mapped scalar. Read the shared numeric
// pool directly instead of constructing an allocation-backed result vector.
// Unknown keys preserve their input scalar, as required by simple casing.
عام عرف محرف_تحويل_بسيط_يونيكود(
    القيمة: غ32,
    المفاتيح: &متجه غ32,
    البدايات: &متجه غ32,
    الأطوال: &متجه غ32,
    القيم: &متجه غ32
): غ32 {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = الطول(*المفاتيح) مثل غير_موقع;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + (النهاية - البداية) / 2;
        لو ((*المفاتيح)[الوسط] < القيمة) {
            البداية := الوسط + 1;
        } وإلا {
            النهاية := الوسط;
        };
    }
    لو (البداية < (الطول(*المفاتيح) مثل غير_موقع)
        && (*المفاتيح)[البداية] == القيمة
        && (*الأطوال)[البداية] == 1) {
        أرجع (*القيم)[(*البدايات)[البداية] مثل غير_موقع];
    };
    أرجع القيمة;
}

library/std/unicode/algorithms/normaliza:
استورد unicode.algorithms.hangul;

// Unicode UAX #15 canonical composition of an ALREADY fully decomposed,
// canonically ordered sequence. No compatibility/canonical decomposition is
// attempted here. Non-Hangul pairs must come from the same versioned UCD,
// after applying Full_Composition_Exclusion (derived composition data).
// Composition pairs use one compact numeric table: (starter, combining,
// composite), sorted lexicographically by the first two scalar values.
// This is also the format used by unicode.data.normalization; there is no
// parallel record-based copy of the same Unicode information.
عرف ركب_مزدوجا_من_بيانات(
    الأزواج: &متجه غ32,
    الأول: غ32,
    الثاني: غ32
): اختيار غ32 {
    دع البداية: متغير غير_موقع = 0;
    دع النهاية: متغير غير_موقع = (الطول(*الأزواج) مثل غير_موقع) / 3;
    بينما (البداية < النهاية) {
        دع الوسط: غير_موقع = البداية + ((النهاية - البداية) / 2);
        دع موضع: غير_موقع = الوسط * 3;
        دع القيمة_الأولى: غ32 = (*الأزواج)[موضع];
        دع القيمة_الثانية: غ32 = (*الأزواج)[موضع + 1];
        لو (القيمة_الأولى < الأول
            || (القيمة_الأولى == الأول && القيمة_الثانية < الثاني)) {
            البداية := الوسط + 1;
        } وإلا {
            النهاية := الوسط;
        };
    }
    لو (البداية < ((الطول(*الأزواج) مثل غير_موقع) / 3)) {
        دع موضع: غير_موقع = البداية * 3;
        لو ((*الأزواج)[موضع] == الأول && (*الأزواج)[موضع + 1] == الثاني) {
            أرجع اختيار.بعض((*الأزواج)[موضع + 2]);
        };
    };
    أرجع اختيار.لا_شيء();
}

// Return لا_شيء on mismatched input, instead of silently assuming CCC=0.
// The caller must supply already decomposed scalars and their UCD CCC values.
عام عرف ركب_المفكك_قانونيا(
    الرموز: &متجه غ32,
    درجات_الدمج: &متجه غ8,
    الأزواج: &متجه غ32
): اختيار متجه غ32 {
    دع العدد: غير_موقع = الطول(*الرموز) مثل غير_موقع;
    لو (العدد != (الطول(*درجات_الدمج) مثل غير_موقع)) {
        أرجع اختيار.لا_شيء();
    };
    دع الناتج: متغير متجه غ32 = [];
    لو (العدد == 0) { أرجع اختيار.بعض(الناتج); };

    ألحق(الناتج, (*الرموز)[0]);
    دع موضع_البداية: متغير غير_موقع = 0;
    دع آخر_درجة: متغير غ8 = (*درجات_الدمج)[0];
    دع الموضع: متغير غير_موقع = 1;
    بينما (الموضع < العدد) {
        دع الرمز: غ32 = (*الرموز)[الموضع];
        دع الدرجة: غ8 = (*درجات_الدمج)[الموضع];
        دع تركيب: متغير اختيار غ32 = اختيار.لا_شيء();

        // UAX #15 blocked rule: a preceding CCC must be strictly smaller
        // than this CCC, except a previous starter (CCC=0).
        لو (آخر_درجة == 0 || آخر_درجة < الدرجة) {
            طابق ركب_مقطعي_هانغول((*الناتج)[موضع_البداية], الرمز) مع
            | اختيار.بعض(المركب) -> { تركيب := اختيار.بعض(المركب); }
            | اختيار.لا_شيء -> {
                تركيب := ركب_مزدوجا_من_بيانات(
                    الأزواج, (*الناتج)[موضع_البداية], الرمز
                );
            };
        };

        طابق تركيب مع
        | اختيار.بعض(المركب) -> {
            (*الناتج)[موضع_البداية] := المركب;
            // Last CCC is intentionally unchanged after composition.
        }
        | اختيار.لا_شيء -> {
            لو (الدرجة == 0) {
                موضع_البداية := الطول(الناتج) مثل غير_موقع;
            };
            ألحق(الناتج, الرمز);
            آخر_درجة := الدرجة;
        };
        الموضع := الموضع + 1;
    }
    أرجع اختيار.بعض(الناتج);
}

library/std/unicode/algorithms/segmentat:
// Unicode 18.0 UAX #29 extended grapheme boundary rules GB1..GB999.
// This algorithm consumes classified scalar values from a single UCD version.
// It does not attempt to derive Unicode properties from character ranges.
// The data owner must supply Grapheme_Cluster_Break, Extended_Pictographic,
// and Indic_Conjunct_Break from the same Unicode database.

عام نوع صنف_فصل_عنقود =
    | عادي
    | إرجاع_عربة
    | سطر_جديد
    | تحكم
    | هانغول_بادئ
    | هانغول_وسط
    | هانغول_ختام
    | هانغول_مقطع_مفتوح
    | هانغول_مقطع_مغلق
    | امتداد
    | رابط_صفري
    | علامة_متباعدة
    | تقديم
    | مؤشر_إقليمي
;

عام نوع صنف_وصل_هندي =
    | لا_شيء
    | وصل
    | امتداد
    | صامت
;

عرف تحكم_عنقود(الصنف: صنف_فصل_عنقود): منطقي {
    طابق الصنف مع
    | صنف_فصل_عنقود.إرجاع_عربة -> { أرجع صواب; }
    | صنف_فصل_عنقود.سطر_جديد -> { أرجع صواب; }
    | صنف_فصل_عنقود.تحكم -> { أرجع صواب; }
    | _ -> { أرجع خطأ; };
}

// A true result means a grapheme boundary exists immediately before الموضع.
// Invalid property-array lengths or an out-of-bounds index return لا_شيء.
عام عرف حد_عنقود_موسع_مصنف(
    الأصناف: &متجه صنف_فصل_عنقود,
    تصويرية_موسعة: &متجه منطقي,
    وصل_هندي: &متجه صنف_وصل_هندي,
    الموضع: غير_موقع
): اختيار منطقي {
    دع الطول_الكلي: غير_موقع = الطول(*الأصناف) مثل غير_موقع;
    لو ((الطول(*تصويرية_موسعة) مثل غير_موقع) != الطول_الكلي
        || (الطول(*وصل_هندي) مثل غير_موقع) != الطول_الكلي
        || الموضع > الطول_الكلي) {
        أرجع اختيار.لا_شيء();
    };
    // GB1/GB2: the empty text has no grapheme boundaries.
    لو (الطول_الكلي == 0) { أرجع اختيار.بعض(خطأ); };
    لو (الموضع == 0 || الموضع == الطول_الكلي) {
        أرجع اختيار.بعض(صواب);
    };

    دع السابق: صنف_فصل_عنقود = (*الأصناف)[الموضع - 1];
    دع التالي: صنف_فصل_عنقود = (*الأصناف)[الموضع];

    // GB3, GB4, GB5: CR/LF and control boundaries.
    طابق السابق مع
    | صنف_فصل_عنقود.إرجاع_عربة -> {
        طابق التالي مع
        | صنف_فصل_عنقود.سطر_جديد -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | _ -> { };
    لو (تحكم_عنقود(السابق) || تحكم_عنقود(التالي)) {
        أرجع اختيار.بعض(صواب);
    };

    // GB6, GB7, GB8: conjoining Hangul syllables.
    طابق السابق مع
    | صنف_فصل_عنقود.هانغول_بادئ -> {
        طابق التالي مع
        | صنف_فصل_عنقود.هانغول_بادئ -> { أرجع اختيار.بعض(خطأ); }
        | صنف_فصل_عنقود.هانغول_وسط -> { أرجع اختيار.بعض(خطأ); }
        | صنف_فصل_عنقود.هانغول_مقطع_مفتوح -> { أرجع اختيار.بعض(خطأ); }
        | صنف_فصل_عنقود.هانغول_مقطع_مغلق -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | صنف_فصل_عنقود.هانغول_وسط -> {
        طابق التالي مع
        | صنف_فصل_عنقود.هانغول_وسط -> { أرجع اختيار.بعض(خطأ); }
        | صنف_فصل_عنقود.هانغول_ختام -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | صنف_فصل_عنقود.هانغول_مقطع_مفتوح -> {
        طابق التالي مع
        | صنف_فصل_عنقود.هانغول_وسط -> { أرجع اختيار.بعض(خطأ); }
        | صنف_فصل_عنقود.هانغول_ختام -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | صنف_فصل_عنقود.هانغول_ختام -> {
        طابق التالي مع
        | صنف_فصل_عنقود.هانغول_ختام -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | صنف_فصل_عنقود.هانغول_مقطع_مغلق -> {
        طابق التالي مع
        | صنف_فصل_عنقود.هانغول_ختام -> { أرجع اختيار.بعض(خطأ); }
        | _ -> { };
    }
    | _ -> { };

    // GB9, GB9a, GB9b: Extend, ZWJ, SpacingMark and Prepend.
    طابق التالي مع
    | صنف_فصل_عنقود.امتداد -> { أرجع اختيار.بعض(خطأ); }
    | صنف_فصل_عنقود.رابط_صفري -> { أرجع اختيار.بعض(خطأ); }
    | صنف_فصل_عنقود.علامة_متباعدة -> { أرجع اختيار.بعض(خطأ); }
    | _ -> { };
    طابق السابق مع
    | صنف_فصل_عنقود.تقديم -> { أرجع اختيار.بعض(خطأ); }
    | _ -> { };

    // GB9c (revised in Unicode 18.0):
    // InCB=Linker InCB=Extend* × InCB=Consonant.
    طابق (*وصل_هندي)[الموضع] مع
    | صنف_وصل_هندي.صامت -> {
        دع البحث: متغير غير_موقع = الموضع;
        دع تابع: متغير منطقي = صواب;
        بينما (البحث > 0 && تابع) {
            دع السابق_الهندي: صنف_وصل_هندي = (*وصل_هندي)[البحث - 1];
            طابق السابق_الهندي مع
            | صنف_وصل_هندي.امتداد -> { البحث := البحث - 1; }
            | صنف_وصل_هندي.وصل -> { أرجع اختيار.بعض(خطأ); }
            | _ -> { تابع := خطأ; };
        }
    }
    | _ -> { };

    // GB11: Extended_Pictographic Extend* ZWJ × Extended_Pictographic.
    لو ((*تصويرية_موسعة)[الموضع]) {
        طابق السابق مع
        | صنف_فصل_عنقود.رابط_صفري -> {
            دع البحث: متغير غير_موقع = الموضع - 1;
            دع تابع: متغير منطقي = صواب;
            بينما (البحث > 0 && تابع) {
                طابق (*الأصناف)[البحث - 1] مع
                | صنف_فصل_عنقود.امتداد -> { البحث := البحث - 1; }
                | _ -> { تابع := خطأ; };
            }
            لو (البحث > 0 && (*تصويرية_موسعة)[البحث - 1]) {
                أرجع اختيار.بعض(خطأ);
            };
        }
        | _ -> { };
    };

    // GB12/GB13: odd count of preceding regional indicators.
    طابق السابق مع
    | صنف_فصل_عنقود.مؤشر_إقليمي -> {
        طابق التالي مع
        | صنف_فصل_عنقود.مؤشر_إقليمي -> {
            دع البحث: متغير غير_موقع = الموضع;
            دع العدد: متغير غير_موقع = 0;
            دع تابع: متغير منطقي = صواب;
            بينما (البحث > 0 && تابع) {
                طابق (*الأصناف)[البحث - 1] مع
                | صنف_فصل_عنقود.مؤشر_إقليمي -> {
                    العدد := العدد + 1;
                    البحث := البحث - 1;
                }
                | _ -> { تابع := خطأ; };
            }
            لو ((العدد % 2) == 1) { أرجع اختيار.بعض(خطأ); };
        }
        | _ -> { };
    }
    | _ -> { };

    // GB999: break in every other position.
    أرجع اختيار.بعض(صواب);
}

library/std/unicode/algorithms/text_offs:
استورد encoding.utf8;
استورد text.from_bytes;

// Keep UTF-8 byte offsets separate from Unicode scalar indexes. UAX #29
// operates on Unicode scalars; callers can map its boundaries to byte offsets.
عام نوع نص_سلالم_يونيكود = {
    القيم: متجه غ32,
    بدايات_البايتات: متجه غير_موقع
};
عام نوع خطأ_تحويل_يونيكود =
    | يوتيف8_غير_صالح بنوع غير_موقع
    | سلم_غير_صالح بنوع غير_موقع
;

عام عرف فك_نص_إلى_سلالم_يونيكود(النص: &نص): نتيجة نص_سلالم_يونيكود, خطأ_تحويل_يونيكود {
    دع القيم: متغير متجه غ32 = [];
    دع البدايات: متغير متجه غير_موقع = [];
    دع الموضع: متغير غير_موقع = 0;
    بينما (الموضع < (الطول(*النص) مثل غير_موقع)) {
        دع المحرف: فك_يوتيف8 = فك_محرف_يوتيف8(النص, الموضع);
        لو (!المحرف.صالح || المحرف.العرض == 0) {
            أرجع نتيجة.خطأ(خطأ_تحويل_يونيكود.يوتيف8_غير_صالح(الموضع));
        };
        ألحق(البدايات, الموضع);
        ألحق(القيم, المحرف.القيمة);
        الموضع := الموضع + المحرف.العرض;
    }
    ألحق(البدايات, الموضع);
    دع الناتج: نص_سلالم_يونيكود = { القيم: القيم, بدايات_البايتات: البدايات };
    أرجع نتيجة.نجح(الناتج);
}

عام عرف حدود_بايتات_من_سلالم(
    المراجع: &نص_سلالم_يونيكود,
    الحدود: &متجه غير_موقع
): متجه غير_موقع {
    دع الناتج: متغير متجه غير_موقع = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*الحدود) مثل غير_موقع)) {
        ألحق(الناتج, (*المراجع).بدايات_البايتات[(*الحدود)[ف]]);
        ف := ف + 1;
    }
    أرجع الناتج;
}

// UTF-8 encoding is performed only after scalar-level transformations.
عام عرف حول_سلالم_إلى_نص_يونيكود(القيم: &متجه غ32): نتيجة نص, خطأ_تحويل_يونيكود {
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(*القيم) مثل غير_موقع)) {
        طابق ألحق_محرف_يوتيف8(البايتات, (*القيم)[ف]) مع
        | نتيجة_ترميز_يوتيف8.مشفر(الناتج) -> { البايتات := الناتج; }
        | نتيجة_ترميز_يوتيف8.قيمة_غير_صالحة -> {
            أرجع نتيجة.خطأ(خطأ_تحويل_يونيكود.سلم_غير_صالح(ف));
        };
        ف := ف + 1;
    }
    أرجع نتيجة.نجح(من_بايتات(&البايتات));
}

library/std/unicode/case_folding.sn:
استورد unicode.algorithms.text_offsets;
استورد unicode.algorithms.lookup;
استورد unicode.data.case_folding;

عام عرف طي_حالة_الأحرف_يونيكود(القيمة: غ32): متجه غ32 {
    أرجع تسلسل_تحويل_يونيكود(القيمة, &طي_حالة_كامل_مفاتيح,
        &طي_حالة_كامل_بدايات, &طي_حالة_كامل_أطوال, &طي_حالة_كامل_قيم);
}
عام عرف طي_حالة_بسيط_يونيكود(القيمة: غ32): غ32 {
    أرجع محرف_تحويل_بسيط_يونيكود(القيمة, &طي_حالة_بسيط_مفاتيح,
        &طي_حالة_بسيط_بدايات, &طي_حالة_بسيط_أطوال, &طي_حالة_بسيط_قيم);
}

عام عرف طي_حالة_نص_يونيكود(النص: &نص): نتيجة نص, خطأ_تحويل_يونيكود {
    طابق فك_نص_إلى_سلالم_يونيكود(النص) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(المراجع) -> {
        دع الناتج: متغير متجه غ32 = [];
        دع ف: متغير غير_موقع = 0;
        بينما (ف < (الطول(المراجع.القيم) مثل غير_موقع)) {
            دع المطابقة: متجه غ32 = طي_حالة_الأحرف_يونيكود(المراجع.القيم[ف]);
            دع ج: متغير غير_موقع = 0;
            بينما (ج < (الطول(المطابقة) مثل غير_موقع)) {
                ألحق(الناتج, المطابقة[ج]);
                ج := ج + 1;
            }
            ف := ف + 1;
        }
        أرجع حول_سلالم_إلى_نص_يونيكود(&الناتج);
    };
}

