        ف := ف + 1;
    }
    أرجع نتيجة.نجح(صواب);
}

عرف انسخ_نطاق_إصدار(النص: &نص, البداية: غير_موقع, النهاية: غير_موقع): نص {
    دع المصدر: نص = *النص;
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) { ألحق(البايتات, المصدر[ف]); ف := ف + 1; }
    أرجع من_بايتات(&البايتات);
}

عام عرف حلل_إصدارا_دلاليا(النص: &نص): نتيجة إصدار_دلالي, صنف_خطأ_إصدار_دلالي {
    دع المصدر: نص = *النص;
    دع العدد: غير_موقع = الطول(المصدر) مثل غير_موقع;
    لو (العدد == 0) { أرجع نتيجة.خطأ(صنف_خطأ_إصدار_دلالي.فارغ()); };

    دع الرئيسي: متغير غير_موقع = 0;
    دع الثانوي: متغير غير_موقع = 0;
    دع التصحيح: متغير غير_موقع = 0;
    دع الموضع: متغير غير_موقع = 0;

    طابق اقرأ_رقم_إصدار(&المصدر, الموضع) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(المقروء) -> { الرئيسي := المقروء.القيمة; الموضع := المقروء.التالي; };
    لو ((الموضع >= العدد) || (المصدر[الموضع] != 0x2E)) {
        أرجع نتيجة.خطأ(صنف_خطأ_إصدار_دلالي.مكون_مفقود(الموضع));
    };
    الموضع := الموضع + 1;

    طابق اقرأ_رقم_إصدار(&المصدر, الموضع) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(المقروء) -> { الثانوي := المقروء.القيمة; الموضع := المقروء.التالي; };
    لو ((الموضع >= العدد) || (المصدر[الموضع] != 0x2E)) {
        أرجع نتيجة.خطأ(صنف_خطأ_إصدار_دلالي.مكون_مفقود(الموضع));
    };
    الموضع := الموضع + 1;

    طابق اقرأ_رقم_إصدار(&المصدر, الموضع) مع
    | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
    | نتيجة.نجح(المقروء) -> { التصحيح := المقروء.القيمة; الموضع := المقروء.التالي; };

    دع قبل: متغير نص = «»;
    دع بناء: متغير نص = «»;
    لو ((الموضع < العدد) && (المصدر[الموضع] == 0x2D)) {
        دع بداية_قبل: غير_موقع = الموضع + 1;
        دع نهاية_قبل: متغير غير_موقع = بداية_قبل;
        بينما ((نهاية_قبل < العدد) && (المصدر[نهاية_قبل] != 0x2B)) { نهاية_قبل := نهاية_قبل + 1; }
        طابق تحقق_معرفات_إصدار(&المصدر, بداية_قبل, نهاية_قبل, صواب) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        قبل := انسخ_نطاق_إصدار(&المصدر, بداية_قبل, نهاية_قبل);
        الموضع := نهاية_قبل;
    };

    لو ((الموضع < العدد) && (المصدر[الموضع] == 0x2B)) {
        دع بداية_البناء: غير_موقع = الموضع + 1;
        طابق تحقق_معرفات_إصدار(&المصدر, بداية_البناء, العدد, خطأ) مع
        | نتيجة.خطأ(الخطأ) -> { أرجع نتيجة.خطأ(الخطأ); }
        | نتيجة.نجح(_) -> { };
        بناء := انسخ_نطاق_إصدار(&المصدر, بداية_البناء, العدد);
        الموضع := العدد;
    };

    لو (الموضع != العدد) {
        أرجع نتيجة.خطأ(صنف_خطأ_إصدار_دلالي.محرف_غير_صالح(الموضع));
    };

    دع الناتج: إصدار_دلالي = {
        الرئيسي: الرئيسي,
        الثانوي: الثانوي,
        التصحيح: التصحيح,
        قبل_الإصدار: قبل,
        البناء: بناء
    };
    أرجع نتيجة.نجح(الناتج);
}

عرف معرف_رقمي_إصدار(النص: &نص, البداية: غير_موقع, النهاية: غير_موقع): منطقي {
    دع المصدر: نص = *النص;
    دع ف: متغير غير_موقع = البداية;
    بينما (ف < النهاية) {
        لو (!رقم_أسكي_للإصدار(المصدر[ف])) { أرجع خطأ; };
        ف := ف + 1;
    }
    أرجع صواب;
}

عرف قارن_معرف_إصدار(
    أ: &نص, بداية_أ: غير_موقع, نهاية_أ: غير_موقع,
    ب: &نص, بداية_ب: غير_موقع, نهاية_ب: غير_موقع
): عدد {
    دع رقمي_أ: منطقي = معرف_رقمي_إصدار(أ, بداية_أ, نهاية_أ);
    دع رقمي_ب: منطقي = معرف_رقمي_إصدار(ب, بداية_ب, نهاية_ب);
    لو (رقمي_أ && !رقمي_ب) { أرجع -1; };
    لو (!رقمي_أ && رقمي_ب) { أرجع 1; };
    دع طول_أ: غير_موقع = نهاية_أ - بداية_أ;
    دع طول_ب: غير_موقع = نهاية_ب - بداية_ب;
    لو (رقمي_أ && رقمي_ب) {
        لو (طول_أ < طول_ب) { أرجع -1; };
        لو (طول_أ > طول_ب) { أرجع 1; };
    };
    دع نص_أ: نص = *أ;
    دع نص_ب: نص = *ب;
    دع الحد: متغير غير_موقع = طول_أ;
    لو (طول_ب < الحد) { الحد := طول_ب; };
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحد) {
        دع موضع_أ: غير_موقع = بداية_أ + ف;
        دع موضع_ب: غير_موقع = بداية_ب + ف;
        لو (نص_أ[موضع_أ] < نص_ب[موضع_ب]) { أرجع -1; };
        لو (نص_أ[موضع_أ] > نص_ب[موضع_ب]) { أرجع 1; };
        ف := ف + 1;
    }
    لو (طول_أ < طول_ب) { أرجع -1; };
    لو (طول_أ > طول_ب) { أرجع 1; };
    أرجع 0;
}

عرف قارن_قبل_الإصدار(أ: &نص, ب: &نص): عدد {
    دع نص_أ: نص = *أ;
    دع نص_ب: نص = *ب;
    دع طول_أ: غير_موقع = الطول(نص_أ) مثل غير_موقع;
    دع طول_ب: غير_موقع = الطول(نص_ب) مثل غير_موقع;
    لو ((طول_أ == 0) && (طول_ب == 0)) { أرجع 0; };
    لو (طول_أ == 0) { أرجع 1; };
    لو (طول_ب == 0) { أرجع -1; };

    دع بداية_أ: متغير غير_موقع = 0;
    دع بداية_ب: متغير غير_موقع = 0;
    بينما (صواب) {
        دع نهاية_أ: متغير غير_موقع = بداية_أ;
        بينما ((نهاية_أ < طول_أ) && (نص_أ[نهاية_أ] != 0x2E)) { نهاية_أ := نهاية_أ + 1; }
        دع نهاية_ب: متغير غير_موقع = بداية_ب;
        بينما ((نهاية_ب < طول_ب) && (نص_ب[نهاية_ب] != 0x2E)) { نهاية_ب := نهاية_ب + 1; }
        دع المقارنة: عدد = قارن_معرف_إصدار(&نص_أ, بداية_أ, نهاية_أ, &نص_ب, بداية_ب, نهاية_ب);
        لو (المقارنة != 0) { أرجع المقارنة; };
        دع انتهى_أ: منطقي = نهاية_أ == طول_أ;
        دع انتهى_ب: منطقي = نهاية_ب == طول_ب;
        لو (انتهى_أ && انتهى_ب) { أرجع 0; };
        لو (انتهى_أ) { أرجع -1; };
        لو (انتهى_ب) { أرجع 1; };
        بداية_أ := نهاية_أ + 1;
        بداية_ب := نهاية_ب + 1;
    }
    أرجع 0;
}

عام عرف قارن_إصدارين_دلاليين(أ: &إصدار_دلالي, ب: &إصدار_دلالي): عدد {
    دع س: إصدار_دلالي = *أ;
    دع ص: إصدار_دلالي = *ب;
    لو (س.الرئيسي < ص.الرئيسي) { أرجع -1; };
    لو (س.الرئيسي > ص.الرئيسي) { أرجع 1; };
    لو (س.الثانوي < ص.الثانوي) { أرجع -1; };
    لو (س.الثانوي > ص.الثانوي) { أرجع 1; };
    لو (س.التصحيح < ص.التصحيح) { أرجع -1; };
    لو (س.التصحيح > ص.التصحيح) { أرجع 1; };
    أرجع قارن_قبل_الإصدار(&س.قبل_الإصدار, &ص.قبل_الإصدار);
}

عام عرف إصداران_دلاليان_متكافئان(أ: &إصدار_دلالي, ب: &إصدار_دلالي): منطقي {
    أرجع قارن_إصدارين_دلاليين(أ, ب) == 0;
}

عام عرف نص_إصدار_دلالي(القيمة: &إصدار_دلالي): نص {
    دع إصدار: إصدار_دلالي = *القيمة;
    دع الرئيسي: نص = uint_to_text(إصدار.الرئيسي);
    دع الثانوي: نص = uint_to_text(إصدار.الثانوي);
    دع التصحيح: نص = uint_to_text(إصدار.التصحيح);
    دع البايتات: متغير متجه غ8 = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < (الطول(الرئيسي) مثل غير_موقع)) { ألحق(البايتات, الرئيسي[ف]); ف := ف + 1; }
    ألحق(البايتات, 0x2E);
    ف := 0;
    بينما (ف < (الطول(الثانوي) مثل غير_موقع)) { ألحق(البايتات, الثانوي[ف]); ف := ف + 1; }
    ألحق(البايتات, 0x2E);
    ف := 0;
    بينما (ف < (الطول(التصحيح) مثل غير_موقع)) { ألحق(البايتات, التصحيح[ف]); ف := ف + 1; }
    لو ((الطول(إصدار.قبل_الإصدار) مثل غير_موقع) > 0) {
        ألحق(البايتات, 0x2D);
        ف := 0;
        بينما (ف < (الطول(إصدار.قبل_الإصدار) مثل غير_موقع)) { ألحق(البايتات, إصدار.قبل_الإصدار[ف]); ف := ف + 1; }
    };
    لو ((الطول(إصدار.البناء) مثل غير_موقع) > 0) {
        ألحق(البايتات, 0x2B);
        ف := 0;
        بينما (ف < (الطول(إصدار.البناء) مثل غير_موقع)) { ألحق(البايتات, إصدار.البناء[ف]); ف := ف + 1; }
    };
    أرجع من_بايتات(&البايتات);
}

